    /** Formatter PT-BR canônico para tipos de local do Atlas. */
    private static String formatLocationTypePt(String raw){
        String t=raw==null?"":raw.trim().toLowerCase(Locale.US);
        if(t.equals("city"))return "cidade";
        if(t.equals("town"))return "vila";
        if(t.equals("village"))return "aldeia";
        if(t.equals("port"))return "porto";
        if(t.equals("ruin")||t.equals("ruins"))return "ruínas";
        if(t.equals("dungeon"))return "dungeon";
        if(t.equals("fortress")||t.equals("keep")||t.equals("castle"))return "fortaleza";
        if(t.equals("hills"))return "região de colinas";
        if(t.equals("trade_route"))return "rota comercial";
        if(t.equals("road"))return "estrada";
        if(t.equals("temple"))return "templo";
        if(t.equals("cave"))return "caverna";
        if(t.equals("point_of_interest"))return "ponto de interesse";
        return t.length()==0?"ponto de interesse":t.replace('_',' ');
    }
