            DatabaseMigrationGuard.beforeOpen(this);db=new AppDb(this);db.setActiveMapProfile(activeWorldProfile());DatabaseMigrationGuard.afterOpen(this,db);uiResponsivenessMonitor=new UiResponsivenessMonitor(this);uiResponsivenessMonitor.start();charonLatencyTelemetry=new CharonLatencyTelemetry(this);ensureWorldRagIsolationMigration();db.disableBrokenTokenPdfSources();secrets=new SecureSecretStore(this,prefs);secrets.migratePlaintext("gemini_key");secrets.migratePlaintext("gemini_paid_key");migrateLegacyModels();applyTheme();
            safety=new CampaignSafetyManager(this,db);libraryConnections=new LibraryConnectionManager(this);portableBackup=new PortableBackupManager(this,db,libraryConnections);maintenance=new AppMaintenanceManager(this,safety,portableBackup);CrashRecoveryHandler.install(this,db,safety);String safetyMessage="Braseiro pronto. Verificações de segurança continuam em segundo plano.";
            String audioRecoveryNotice=prefs.getString(PREF_AUDIO_RECOVERY_NOTICE,"");if(audioRecoveryNotice.length()>0){safetyMessage=safetyMessage+"\n"+audioRecoveryNotice;prefs.edit().remove(PREF_AUDIO_RECOVERY_NOTICE).apply();}
            gemini=new GeminiService(this);drive=new DriveService(this);manualFolderScanner=new SafFolderScanner(this);localManualIndexer=new LocalManualIndexer(this,db,drive);tokenPdfLibrary=new TokenPdfLibrary(this);mapPackageManager=new MapPackageManager(this,db);accountManager=AccountManager.get(this);ensureNpcSourceManualCatalog();if(!prefs.getBoolean("npc_token_folder_47_migrated",false)){String old=prefs.getString("token_folder","");SharedPreferences.Editor tokenMigration=prefs.edit().putBoolean("npc_token_folder_47_migrated",true);if(old.length()==0||DEFAULT_TOKEN_FOLDER.equals(old))tokenMigration.putString("token_folder",DEFAULT_TOKEN_IMAGE_FOLDER);tokenMigration.apply();}
