ceneStateEngine=new SceneStateEngine(db);environmentalDirector=new EnvironmentalDirector(db);travelRulesEngine=new TravelRulesEngine(db);taskQueue=new ResilientTaskQueue(this,db);mythicOracle=new MythicOracle(this);
