    private void warmManualSearchIndexAsync(){
        if(db==null)return;
        if(db.isManualSearchIndexReady()){AppExecutors.io().execute(new Runnable(){public void run(){EssentialRulesCache.warm(db);}});return;}
        AppExecutors.io().execute(new Runnable(){public void run(){
            final JSONObject result=db.rebuildManualSearchIndexIfNeeded();
            ui.post(new Runnable(){public void run(){
                if("ready".equals(result.optString("status"))){AppExecutors.io().execute(new Runnable(){public void run(){EssentialRulesCache.warm(db);}});setBackgroundStatus("Busca local pronta: "+result.optInt("pages",0)+" páginas acessíveis sem nova indexação dos PDFs.");}
                else setBackgroundStatus("A busca local continuará pelo núcleo de regras enquanto o índice invertido é reparado: "+result.optString("error","erro desconhecido"));
            }});
        }});
    }

    private void runLivingWorldCatchUpAsync(){
        if(livingWorldCatchUpEngine==null)return;AppExecutors.io().execute(new Runnable(){public void run(){try{final JSONObject preview=livingWorldCatchUpEngine.preview(System.currentTimeMillis());if(preview.optInt("game_hours",0)>0&&safety!=null)safety.beforeDestructiveChange("sincronização offline do Mundo Vivo");final boolean ok=livingWorldCatchUpEngine.commit(preview);if(ok&&preview.optInt("game_hours",0)>0)ui.post(new Runnable(){public void run(){screenCache.clear();setStatus("Mundo Vivo sincronizado offline: "+preview.optInt("game_hours")+" hora(s) de campanha.");}});}catch(final Exception e){AppLog.e("MainActivity","Falha na sincronização offline do Mundo Vivo.",e);}}});
    }

    private void runWorldSixAsync(){
        if(worldSixCoordinator==null)return;AppExecutors.io().execute(new Runnable(){public void run(){try{final JSONObject result=worldSixCoordinator.tick();ui.post(new Runnable(){public void run(){if(result.optString("error").length()>0)setBackgroundStatus("Mundo 6.0: "+result.optString("error"));}});}catch(Exception e){AppLog.e("WorldSix","Falha ao atualizar o mundo emergente.",e);}}});
    }

    private void showStartupFailure(Throwable fatal){
        try{
            LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(24),dp(32),dp(24),dp(32));root.setBackgroundColor(Color.rgb(18,12,10));
            TextView title=new TextView(this);title.setText("Braseiro iniciou em modo de recuperação");title.setTextColor(Color.rgb(255,190,72));title.setTextSize(23);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);root.addView(title);
            TextView body=new TextView(this);String detail=fatal==null?"Falha desconhecida":fatal.getClass().getSimpleName()+": "+String.valueOf(fatal.getMessage());body.setText("O aplicativo não será fechado. Feche esta tela, abra novamente e, se o erro persistir, envie o diagnóstico abaixo.\n\n"+detail);body.setTextColor(Color.WHITE);body.setTextSize(15);body.setPadding(0,dp(18),0,dp(18));root.addView(body);
            Button retry=new Button(this);retry.setText("TENTAR ABRIR NOVAMENTE");retry.setOnClickListener(new View.OnClickListener(){public void onClick(View v){recreate();}});root.addView(retry,new LinearLayout.LayoutParams(-1,dp(58)));
            setContentView(root);writeStartupCrash(fatal);
        }catch(Throwable ignored){TextView fallback=new TextView(this);fallback.setText("Braseiro: falha de inicialização. Reinicie o aplicativo.");fallback.setTextColor(Color.WHITE);fallback.setBackgroundColor(Color.BLACK);fallback.setPadding(30,60,30,30);setContentView(fallback);}
    }
    private void writeStartupCrash(Throwable fatal){AppLog.e("Startup","Falha de inicialização registrada.",fatal);try{File f=new File(getFilesDir(),"startup_crash.txt");FileOutputStream out=new FileOutputStream(f,false);String text=new Date()+"\n"+(fatal==null?"erro desconhecido":android.util.Log.getStackTraceString(fatal));out.write(text.getBytes("UTF-8"));out.close();}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}}

    @Override
    protected void onSaveInstanceState(Bundle outState){
        if(outState!=null){
            outState.putString(STATE_CURRENT_SCREEN,currentScreen==null?"Aventura":currentScreen);
            if(narratorInput!=null)outState.putString(STATE_NARRATOR_DRAFT,narratorInput.getText()==null?"":narratorInput.getText().toString());
            else if(pendingRestoredNarratorDraft!=null&&pendingRestoredNarratorDraft.length()>0)outState.putString(STATE_NARRATOR_DRAFT,pendingRestoredNarratorDraft);
        }
        super.onSaveInstanceState(outState);
    }

    @Override
    public void onConfigurationChanged(Configuration newConfig){
        super.onConfigurationChanged(newConfig);
        // O Braseiro é phone-first e permanece em retrato. Mudanças de rotação/tamanho
        // não recriam a Activity, não reinicializam o Mestre e não disparam manutenção.
        if(shellRoot!=null){
            applySystemBarInsets(shellRoot);
            shellRoot.requestLayout();
            shellRoot.invalidate();
        }
        if(mapView!=null){mapView.requestLayout();mapView.invalidate();}
        if(sceneHexMiniMapView!=null){sceneHexMiniMapView.requestLayout();sceneHexMiniMapView.invalidate();}
        AppLog.i("Orientation","Configuração de tela aplicada sem recriar a campanha. orientation="+newConfig.orientation);
    }

    private boolean isKnownScreen(String screen){
        if(screen==null)return false;
        return "Aventura".equals(screen)||"Campanha".equals(screen)||"Kingmaker".equals(screen)||"Mestre IA".equals(screen)||"Combate".equals(screen)||"Companhia".equals(screen)||"Mundo Vivo".equals(screen)||"Guildas".equals(screen)||"Mapa".equals(screen)||"Dados".equals(screen)||"Heróis".equals(screen)||"Diário".equals(screen)||"Manuais".equals(screen)||"Tokens".equals(screen)||"Áudio".equals(screen)||"Config".equals(screen);
    }

    protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);handleIncomingIntent(intent);}

    private void ensureInitialSnapshotAsync(){
        if(safety==null||safety.snapshotFileCount()>0)return;
        AppExecutors.io().execute(new Runnable(){public void run(){try{final File created=safety.ensureInitialSnapshot();if(created!=null)ui.post(new Runnable(){public void run(){setStatus("Banco íntegro • primeiro snapshot criado em segundo plano.");}});}catch(final Exception e){ui.post(new Runnable(){public void run(){setStatus("Banco íntegro, mas o snapshot inicial falhou: "+String.valueOf(e.getMessage()));}});}}});
    }

    public void onTrimMemory(int level){
        super.onTrimMemory(level);
        if(level>=android.content.ComponentCallbacks2.TRIM_MEMORY_RUNNING_LOW||level==android.content.ComponentCallbacks2.TRIM_MEMORY_UI_HIDDEN){screenCache.clear();screenCacheTime.clear();if(mapView!=null)mapView.trimTileCache();}
        if(level>=android.content.ComponentCallbacks2.TRIM_MEMORY_RUNNING_CRITICAL){if(!"Mapa".equals(currentScreen)&&mapView!=null){mapView.releaseResources();mapView=null;}if(!"Mestre IA".equals(currentScreen)&&sceneHexMiniMapView!=null){sceneHexMiniMapView.releaseResources();sceneHexMiniMapView=null;}}
    }
    public void onLowMemory(){super.onLowMemory();screenCache.clear();screenCacheTime.clear();if(mapView!=null)mapView.trimTileCache();}

    protected void onStop(){super.onStop();if(maintenance!=null&&!isChangingConfigurations())maintenance.onBackground();}

    protected void onDestroy(){if(uiResponsivenessMonitor!=null)uiResponsivenessMonitor.stop();
        if(localTableServer!=null)localTableServer.stop();
        if(activeCharonRequest!=null){activeCharonRequest.cancel();activeCharonRequest=null;}
        if(maintenance!=null)maintenance.stop();
        if(isFinishing()){if(narrativeAudio!=null)narrativeAudio.stopAll();try{stopService(new Intent(this,AudioPlaybackService.class));}catch(Exception e){AppLog.w("MainActivity","Falha ao encerrar serviço de áudio.",e);}}
        if(nativeTts!=null){nativeTts.stop();nativeTts.shutdown();}
        if(narrativeAudio!=null)narrativeAudio.shutdown();
        if(smartAudio!=null)smartAudio.shutdown();
        if(audioDiagnostics!=null)audioDiagnostics.shutdown();
        if(audio!=null)audio.shutdown();
        if(taskQueue!=null)taskQueue.shutdown();
        if(mapView!=null)mapView.releaseResources();if(sceneHexMiniMapView!=null)sceneHexMiniMapView.releaseResources();AppLog.i("MainActivity","Activity destruída. finishing="+isFinishing());super.onDestroy();
    }
    private boolean isBraseiroKokoroPackage(String pkg){return SHERPA_KOKORO_ENGINE_PACKAGE.equals(pkg)||SHERPA_KOKORO_ENGINE_DEBUG_PACKAGE.equals(pkg);}
    private String installedBraseiroKokoroPackage(LinkedHashMap<String,String> raw){if(raw.containsKey(SHERPA_KOKORO_ENGINE_DEBUG_PACKAGE))return SHERPA_KOKORO_ENGINE_DEBUG_PACKAGE;if(raw.containsKey(SHERPA_KOKORO_ENGINE_PACKAGE))return SHERPA_KOKORO_ENGINE_PACKAGE;return "";}
    private boolean isLegacyDbNextGenIdentity(String value){String x=value==null?"":value.trim().toLowerCase(Locale.ROOT);return LEGACY_BRASEIRO_KOKORO_PACKAGE.equals(x)||x.contains("db next-gen")||x.contains("db nextgen")||x.equals("db next gen");}
    private LinkedHashMap<String,String> rawInstalledNativeTtsEngines(){
        LinkedHashMap<String,String> found=new LinkedHashMap<String,String>();
        try{if(nativeTts!=null)for(TextToSpeech.EngineInfo info:nativeTts.getEngines()){if(info==null||info.name==null||info.name.trim().isEmpty())continue;found.put(info.name,info.label==null||info.label.trim().isEmpty()?info.name:info.label);}}catch(Throwable error){AppLog.w("NativeTts","Falha ao consultar engines pelo TextToSpeech.",error);}
        try{Intent intent=new Intent("android.intent.action.TTS_SERVICE");List<android.content.pm.ResolveInfo> services=getPackageManager().queryIntentServices(intent,0);if(services!=null)for(android.content.pm.ResolveInfo resolve:services){if(resolve==null||resolve.serviceInfo==null)continue;String pkg=resolve.serviceInfo.packageName==null?"":resolve.serviceInfo.packageName.trim();if(pkg.isEmpty())continue;CharSequence label=resolve.loadLabel(getPackageManager());found.put(pkg,label==null||label.toString().trim().isEmpty()?pkg:label.toString());}}catch(Throwable error){AppLog.w("NativeTts","Falha ao descobrir serviços TTS instalados.",error);}
        String[] known={SHERPA_KOKORO_ENGINE_PACKAGE,SHERPA_KOKORO_ENGINE_DEBUG_PACKAGE,"com.google.android.tts","com.samsung.SMT"};for(String pkg:known)try{android.content.pm.ApplicationInfo app=getPackageManager().getApplicationInfo(pkg,0);CharSequence label=getPackageManager().getApplicationLabel(app);if(!found.containsKey(pkg))found.put(pkg,label==null?pkg:label.toString());}catch(Throwable ignored){}
        return found;
    }
    private LinkedHashMap<String,String> discoverNativeTtsEngines(){
        LinkedHashMap<String,String> raw=rawInstalledNativeTtsEngines();LinkedHashMap<String,String> shown=new LinkedHashMap<String,String>();String kokoro=installedBraseiroKokoroPackage(raw);
        for(Map.Entry<String,String> e:raw.entrySet()){String pkg=e.getKey(),label=e.getValue()==null?pkg:e.getValue();if(LEGACY_BRASEIRO_KOKORO_PACKAGE.equals(pkg)||isLegacyDbNextGenIdentity(label)||isBraseiroKokoroPackage(pkg))continue;shown.put(pkg,label);}
        if(!kokoro.isEmpty())shown.put(kokoro,BRASEIRO_KOKORO_LABEL);
        return shown;
    }
    private String preferredBraseiroKokoroPackage(){return installedBraseiroKokoroPackage(rawInstalledNativeTtsEngines());}
    private void migrateLegacyNativeTtsPreferences(){if(prefs==null)return;String saved=prefs.getString("native_tts_engine_package","").trim();String target=preferredBraseiroKokoroPackage();boolean migrate=isLegacyDbNextGenIdentity(saved)||isBraseiroKokoroPackage(saved);if(migrate&&!target.isEmpty()&&!target.equals(saved)){String oldVoice=prefs.getString("native_tts_voice_"+saved,"");if(oldVoice.isEmpty())oldVoice=prefs.getString("native_tts_voice_"+LEGACY_BRASEIRO_KOKORO_PACKAGE,"");SharedPreferences.Editor edit=prefs.edit().putString("native_tts_engine_package",target);if(!oldVoice.isEmpty())edit.putString("native_tts_voice_"+target,oldVoice);edit.apply();}else if(isLegacyDbNextGenIdentity(saved)&&target.isEmpty()){prefs.edit().remove("native_tts_engine_package").apply();}}
    private boolean isInstalledNativeTtsEngine(String pkg){return pkg==null||pkg.trim().isEmpty()||discoverNativeTtsEngines().containsKey(pkg.trim());}
    private boolean isNativeNeuralProfile(){return isBraseiroKokoroPackage(nativeTtsEnginePackage);}
    private String nativeVoicePreferenceKey(){return "native_tts_voice_"+(nativeTtsEnginePackage==null||nativeTtsEnginePackage.isEmpty()?"android_default":nativeTtsEnginePackage);}
    private float nativeNeuralRate(){return prefs==null?1.0f:Math.max(.65f,Math.min(1.5f,prefs.getFloat("native_tts_neural_rate",1.0f)));}
    private String friendlyNativeVoiceLabel(Voice v){if(v==null)return "";String name=v.getName()==null?"":v.getName();Locale l=v.getLocale();return name+(l==null?"":" • "+l.toLanguageTag())+(v.isNetworkConnectionRequired()?" • rede":" • local");}
    private Bundle nativeSpeechParams(String utteranceId,float volume){Bundle params=new Bundle();params.putString(TextToSpeech.Engine.KEY_PARAM_UTTERANCE_ID,utteranceId);params.putFloat(TextToSpeech.Engine.KEY_PARAM_VOLUME,Math.max(0f,Math.min(1f,volume)));return params;}
    private List<Voice> availableNativeTtsVoices(){ArrayList<Voice> out=new ArrayList<Voice>();try{Set<Voice> voices=nativeTts==null?null:nativeTts.getVoices();if(voices!=null)for(Voice v:voices)if(v!=null&&v.getName()!=null&&!v.getName().trim().isEmpty()&&!"NOT_SET_VOICE".equalsIgnoreCase(v.getName()))out.add(v);}catch(Throwable error){AppLog.w("NativeTts","Falha ao ler TextToSpeech.voices.",error);}Collections.sort(out,new Comparator<Voice>(){public int compare(Voice a,Voice b){String aa=a==null?"":a.getName(),bb=b==null?"":b.getName();return aa.compareToIgnoreCase(bb);}});return out;}
    private void selectNativeTtsVoice(String voiceName){try{String requested=voiceName==null?"":voiceName.trim();if(nativeTts==null){toast("O motor TTS ainda não foi inicializado.");return;}if(requested.isEmpty()){nativeTtsVoiceName="";if(prefs!=null)prefs.edit().putString(nativeVoicePreferenceKey(),"").apply();toast("Voz automática do motor selecionada.");return;}Voice chosen=null;for(Voice v:availableNativeTtsVoices())if(requested.equals(v.getName())){chosen=v;break;}if(chosen==null){toast("Voz TTS não disponível no motor selecionado.");return;}int result=nativeTts.setVoice(chosen);if(result==TextToSpeech.ERROR){toast("O motor TTS recusou a voz selecionada.");return;}nativeTtsVoiceName=chosen.getName();if(prefs!=null)prefs.edit().putString(nativeVoicePreferenceKey(),nativeTtsVoiceName).apply();toast("Voz TTS selecionada: "+nativeTtsVoiceName);}catch(Throwable error){AppLog.w("NativeTts","Falha segura ao selecionar Voice real.",error);toast("Falha ao selecionar voz TTS. Atualize motores/vozes e tente novamente.");}}
    private synchronized void switchNativeTtsEngine(String packageName){String requested=packageName==null?"":packageName.trim();if(isLegacyDbNextGenIdentity(requested))requested=preferredBraseiroKokoroPackage();if(!isInstalledNativeTtsEngine(requested)){toast("Motor TTS não instalado: "+requested);return;}if(requested.equals(nativeTtsEnginePackage)&&nativeTts!=null){if(prefs!=null)prefs.edit().putString("native_tts_engine_package",requested).apply();return;}cancelNarrationAudio();if(prefs!=null)prefs.edit().putString("native_tts_engine_package",requested).apply();nativeTtsEnginePackage=requested;nativeTtsReady=false;nativeTtsLanguageReady=false;nativeTtsInitAttempts=0;try{if(nativeTts!=null)nativeTts.shutdown();}catch(Throwable ignored){}nativeTts=null;ensureNativeTtsInitialized();}

    private synchronized void ensureNativeTtsInitialized(){
        long now=System.currentTimeMillis();
        if(nativeTts!=null&&(nativeTtsReady||now-nativeTtsLastInitAt<3500L))return;
        if(nativeTtsInitAttempts>=3&&now-nativeTtsLastInitAt<30000L)return;
        nativeTtsLastInitAt=now;nativeTtsInitAttempts++;migrateLegacyNativeTtsPreferences();
        String requested=prefs==null?"":prefs.getString("native_tts_engine_package","").trim();if(!isInstalledNativeTtsEngine(requested)){requested="";if(prefs!=null)prefs.edit().remove("native_tts_engine_package").apply();}nativeTtsEnginePackage=requested;
        try{if(nativeTts!=null){try{nativeTts.shutdown();}catch(Throwable ignored){}}nativeTtsReady=false;nativeTtsLanguageReady=false;nativeTts=requested.isEmpty()?new TextToSpeech(this,this):new TextToSpeech(this,this,requested);}
        catch(Throwable error){nativeTts=null;nativeTtsReady=false;nativeTtsLanguageReady=false;AppLog.e("NativeTts","Não foi possível criar o mecanismo de voz Android.",error);}
    }

    public void onInit(int status){
        nativeTtsReady=status==TextToSpeech.SUCCESS;nativeTtsLanguageReady=false;
        if(!nativeTtsReady){setStatus("A voz do Android não pôde ser iniciada. Uma nova tentativa será feita sem travar o app.");final int attempt=nativeTtsInitAttempts;if(attempt<3&&ui!=null)ui.postDelayed(new Runnable(){public void run(){ensureNativeTtsInitialized();}},1800L);return;}
        LinkedHashMap<String,String> engines=discoverNativeTtsEngines();nativeTtsEngineLabel=isNativeNeuralProfile()?BRASEIRO_KOKORO_LABEL:(nativeTtsEnginePackage.isEmpty()?"Padrão do Android":(engines.containsKey(nativeTtsEnginePackage)?engines.get(nativeTtsEnginePackage):nativeTtsEnginePackage));
        Locale[] locales=isNativeNeuralProfile()?new Locale[]{new Locale("pt","BR"),new Locale("pt","PT"),new Locale("pt"),Locale.getDefault()}:new Locale[]{new Locale("pt","BR"),new Locale("pt")};
        int languageResult=TextToSpeech.LANG_NOT_SUPPORTED;for(Locale locale:locales){try{languageResult=nativeTts.setLanguage(locale);}catch(Throwable error){continue;}if(languageResult!=TextToSpeech.LANG_MISSING_DATA&&languageResult!=TextToSpeech.LANG_NOT_SUPPORTED){nativeTtsLanguageReady=true;break;}}
        if(!nativeTtsLanguageReady){setStatus("O motor TTS selecionado não oferece português. Escolha outra voz/motor nas configurações.");return;}
        configureNativeTtsVoice();nativeTtsInitAttempts=0;
        nativeTts.setOnUtteranceProgressListener(new UtteranceProgressListener(){
            public void onStart(final String id){ui.post(new Runnable(){public void run(){String sentence;synchronized(nativeVoiceSentenceByUtterance){sentence=nativeVoiceSentenceByUtterance.get(id);if(sentence!=null)nativeVoiceStartedUtterances.add(id);}if(sentence==null)return;if(narrativeAudio!=null)narrativeAudio.onNativeUtteranceStart(id,sentence,Build.VERSION.SDK_INT>=26);setStatus((isNativeNeuralProfile()?"Braseiro Kokoro PT-BR":"Voz do Android")+" narrando • áudio inteligente sincronizado.");}});}
            public void onRangeStart(final String id,final int start,final int end,final int frame){ui.post(new Runnable(){public void run(){String sentence;synchronized(nativeVoiceSentenceByUtterance){sentence=nativeVoiceSentenceByUtterance.get(id);}if(sentence==null)return;if(narrativeAudio!=null)narrativeAudio.onNativeRange(id,sentence,start,end);}});}
            public void onDone(final String id){ui.post(new Runnable(){public void run(){String completed;synchronized(nativeVoiceSentenceByUtterance){completed=nativeVoiceSentenceByUtterance.remove(id);nativeVoiceStartedUtterances.remove(id);if(completed!=null)nativeVoicePendingChunks=Math.max(0,nativeNarrationQueue.size()-nativeNarrationQueueIndex-1);}if(completed==null)return;if(narrativeAudio!=null)narrativeAudio.onUtteranceDone(id);nativeNarrationQueueIndex++;if(nativeNarrationQueueIndex>=nativeNarrationQueue.size())finishNativeNarration();else if(isNativeNeuralProfile())speakNextNativeNarrationChunk();else{long pause=narrativePauseMs(nativeChapterStartIndexes.contains(nativeNarrationQueueIndex));ui.postDelayed(new Runnable(){public void run(){speakNextNativeNarrationChunk();}},pause);}}});}
            public void onError(final String id){handleNativeTtsError(id,-1);}public void onError(final String id,final int code){handleNativeTtsError(id,code);}
        });
        final String pending=pendingRequestedNativeNarration;pendingRequestedNativeNarration="";if(pending.trim().length()>0)ui.postDelayed(new Runnable(){public void run(){speakNativeNarrationWithSfx(pending);}},80L);
    }
    private void handleNativeTtsError(final String id,final int code){ui.post(new Runnable(){public void run(){String failed;synchronized(nativeVoiceSentenceByUtterance){failed=nativeVoiceSentenceByUtterance.remove(id);nativeVoiceStartedUtterances.remove(id);}if(failed==null)return;if(narrativeAudio!=null)narrativeAudio.onUtteranceDone(id);if(isNativeNeuralProfile()){failCoordinatedAudioSession("neural-tts-error");nativeNarrationQueue.clear();audio.setExternalVoiceActive(false);if(narrativeAudio!=null)narrativeAudio.cancelNarration();resumeBackgroundWorkAfterNarration();setStatus("Braseiro Kokoro falhou no bloco "+(nativeNarrationQueueIndex+1)+(code>=0?" ("+code+")":"")+"; nenhum trecho foi pulado silenciosamente.");return;}nativeNarrationQueueIndex++;if(nativeNarrationQueueIndex>=nativeNarrationQueue.size())finishNativeNarration();else{long pause=narrativePauseMs(nativeChapterStartIndexes.contains(nativeNarrationQueueIndex));ui.postDelayed(new Runnable(){public void run(){speakNextNativeNarrationChunk();}},pause);}}});}

    private void configureNativeTtsVoice(){
        if(nativeTts==null)return;try{nativeNeuralSpeechRate=nativeNeuralRate();String key=nativeVoicePreferenceKey();boolean explicit=prefs!=null&&prefs.contains(key);String saved=prefs==null?"":prefs.getString(key,"").trim();nativeTtsVoiceName=saved;Voice selected=null;if(!nativeTtsVoiceName.isEmpty())for(Voice v:availableNativeTtsVoices())if(nativeTtsVoiceName.equals(v.getName())){selected=v;break;}if(selected==null&&!explicit){Voice current=nativeTts.getVoice();if(current!=null&&availableNativeTtsVoices().contains(current))selected=current;}if(selected==null&&!explicit){int bestScore=Integer.MIN_VALUE;for(Voice candidate:availableNativeTtsVoices()){if(candidate==null||candidate.getLocale()==null)continue;Locale locale=candidate.getLocale();if(!"pt".equalsIgnoreCase(locale.getLanguage()))continue;int score=0;if("BR".equalsIgnoreCase(locale.getCountry()))score+=10000;score+=Math.max(0,candidate.getQuality())*10;if(candidate.getQuality()>=Voice.QUALITY_HIGH)score+=1500;if(!candidate.isNetworkConnectionRequired())score+=80;if(candidate.getLatency()<=Voice.LATENCY_NORMAL)score+=120;if(score>bestScore){selected=candidate;bestScore=score;}}}if(selected!=null){if(nativeTts.setVoice(selected)!=TextToSpeech.ERROR){nativeTtsVoiceName=selected.getName();if(prefs!=null)prefs.edit().putString(key,nativeTtsVoiceName).apply();}}else if(explicit&&saved.isEmpty()){nativeTtsVoiceName="";}if(!isNativeNeuralProfile()){nativeTts.setSpeechRate(NarrationPlaybackPolicy.ANDROID_SPEECH_RATE);nativeTts.setPitch(NarrationPlaybackPolicy.ANDROID_PITCH);}AppLog.i("NativeTts","Motor="+nativeTtsEngineLabel+" voz="+nativeTtsVoiceName+" neural="+isNativeNeuralProfile());}catch(Throwable error){AppLog.w("NativeTts","A seleção da voz instalada falhou; mantendo a voz real atual do motor.",error);Voice current=nativeTts==null?null:nativeTts.getVoice();if(current!=null)nativeTtsVoiceName=current.getName();}
    }

    private float narrativeSpeechRate(){
        float base=NarrationPlaybackPolicy.ANDROID_SPEECH_RATE;JSONObject plan=lastAudioPlan==null?new JSONObject():lastAudioPlan;String delivery=plan.optString("delivery","normal").trim().toLowerCase(Locale.ROOT);int intensity=Math.max(0,Math.min(5,plan.optInt("intensity",1)));
        if("baixo".equals(delivery))return Math.max(0.72f,base*0.90f);
        if("calmo".equals(delivery))return Math.max(0.76f,base*0.94f);
        if("urgente".equals(delivery))return Math.min(1.28f,base*(1.03f+0.012f*intensity));
        return base;
    }
    private long narrativePauseMs(boolean chapter){
        JSONObject plan=lastAudioPlan==null?new JSONObject():lastAudioPlan;String profile=plan.optString("pause_profile","normal").trim().toLowerCase(Locale.ROOT);
        if("curto".equals(profile)||"curta".equals(profile))return chapter?260L:80L;
        if("longo".equals(profile)||"longa".equals(profile))return chapter?720L:260L;
        return chapter?420L:120L;
    }
    private void applyNativeNarrativeDelivery(){if(nativeTts==null)return;try{if(isNativeNeuralProfile())nativeTts.setSpeechRate(nativeNeuralRate());else{nativeTts.setSpeechRate(narrativeSpeechRate());nativeTts.setPitch(NarrationPlaybackPolicy.ANDROID_PITCH);}}catch(Throwable error){AppLog.w("NativeTts","Falha ao aplicar direção narrativa de voz; mantendo o padrão.",error);}}

    private String startAudioServiceSafely(){
        // O serviço legado é encerrado uma única vez na criação da Activity. Fazer
        // stopService a cada PLAY executava trabalho de Binder na UI e causava ANR.
        return "";
    }

    /**
     * Lê a chave Gemini exclusivamente do armazenamento cifrado.
     * O método havia sido removido por engano na refatoração do áudio 3.7.0,
     * embora oito fluxos da Activity ainda dependessem dele.
     */
    private String geminiKey(){
        return secrets==null?"":secrets.get("gemini_key");
    }
    private String geminiPaidKey(){
        return secrets==null?"":secrets.get("gemini_paid_key");
    }

    /** Grava as duas chaves como uma única alteração lógica e restaura o estado anterior em qualquer falha. */
    private boolean saveGeminiSecretsAtomically(String primary,String paid){
        if(secrets==null)return false;
        String oldPrimary=geminiKey(),oldPaid=geminiPaidKey();
        if(!secrets.put("gemini_key",primary))return false;
        if(secrets.put("gemini_paid_key",paid))return true;
        boolean rollbackPrimary=secrets.put("gemini_key",oldPrimary);
        boolean rollbackPaid=secrets.put("gemini_paid_key",oldPaid);
        AppLog.e("SecureSecretStore","A chave alternativa falhou; o estado anterior foi restaurado="+(rollbackPrimary&&rollbackPaid),null);
        return false;
    }

    /**
     * Migra apenas preferências legadas e idempotentes.
     * Não toca no banco da campanha, nos mapas, nos manuais ou na biblioteca de áudio.
     */
    private void migrateLegacyModels(){
        String textModel=prefs.getString("text_model","").trim().toLowerCase(Locale.US);
        String imageModel=prefs.getString("image_model","").trim().toLowerCase(Locale.US);
        SharedPreferences.Editor edit=null;

        if(textModel.startsWith("gemini-2.0")
                ||textModel.startsWith("gemini-2.5")
                ||textModel.length()==0){
            edit=prefs.edit();
            edit.putString("text_model","gemini-3.5-flash-lite");
        }

        // 6.2.8: havia uma preferência oculta narrator_text_model que podia ignorar o
        // modelo escolhido na tela de Configurações. O Narrador passa a obedecer exclusivamente
        // text_model; removemos o valor legado para que upgrades preservem a escolha visível.
        if(prefs.contains("narrator_text_model")){
            if(edit==null)edit=prefs.edit();
            edit.remove("narrator_text_model");
        }

        if(imageModel.startsWith("gemini-2.0")
                ||imageModel.startsWith("gemini-2.5")
                ||imageModel.length()==0){
            if(edit==null)edit=prefs.edit();
            edit.putString("image_model","gemini-3.1-flash-image");
        }

        if(!prefs.contains("sfx_multilayer_migrated")){
            if(edit==null)edit=prefs.edit();
            edit.putInt("sfx_global_gap_seconds",3)
                    .putBoolean("sfx_multilayer_migrated",true);
        }

        // 6.0.1 — temas passam a ser independentes por mundo.
        if(!prefs.contains("theme_mode_pf2")){
            if(edit==null)edit=prefs.edit();
            edit.putString("theme_mode_pf2",prefs.getString("theme_mode","pathfinder"));
        }

        if(edit!=null)edit.apply();
    }

