    private boolean manualBelongsToWorld(JSONObject manual,String world){
        if(manual==null)return false;
        String lower=manual.optString("title","").toLowerCase(Locale.US);
        if(isForeignSystemManualTitle(lower))return false;
        return !lower.contains("dungeons & dragons")&&!lower.contains("d&d 5e")&&!lower.contains("rules cyclopedia")&&!lower.startsWith("mystara_");
    }
    private boolean isForeignSystemManualTitle(String lower){String value=lower==null?"":lower.toLowerCase(Locale.US);return value.contains("traveller")||value.contains("mongoose traveller")||value.contains("high guard")||value.contains("robot handbook")||value.contains("central supply catalogue")||value.contains("mgt2");}
    
    private List<JSONObject> filterManualsForWorld(List<JSONObject> input){return filterManualsForWorld(input,activeWorldProfile());}
    private List<JSONObject> filterManualsForWorld(List<JSONObject> input,String world){ArrayList<JSONObject> out=new ArrayList<JSONObject>();if(input!=null)for(JSONObject m:input)if(manualBelongsToWorld(m,world))out.add(m);return out;}
    private String attachedManualPrefKey(String world){return "attached_manual_id_pf2";}
    private long attachedManualId(String world){try{return Long.parseLong(prefs.getString(attachedManualPrefKey(world),"-1"));}catch(Exception e){return -1L;}}
    private JSONObject attachedManual(String world){long id=attachedManualId(world);if(id<0)return new JSONObject();JSONObject m=findManualById(id);if(!manualBelongsToWorld(m,world)||m.optInt("enabled",1)!=1){prefs.edit().remove(attachedManualPrefKey(world)).apply();return new JSONObject();}return m;}
    private String manualDisplayTitle(JSONObject manual){return manual==null?"":manual.optString("title","");}
    private void ensureWorldRagIsolationMigration(){
        SharedPreferences.Editor edit=prefs.edit();
        if(!prefs.getBoolean("rag_world_isolation_v1",false)){
            edit.remove("rag_store_name").remove("rag_key_fingerprint").remove("last_manual_context").remove("last_rag_citations").remove("attached_manual_id_dnd").remove("attached_manual_id_mystara").putBoolean("rag_world_isolation_v1",true);
            db.resetRagLibrary();
        }
        if(!prefs.getBoolean("manual_local_index_v1",false)){
            edit.remove("rag_store_name_dnd").remove("rag_store_name_mystara").remove("rag_key_fingerprint_dnd").remove("rag_key_fingerprint_mystara").remove("legacy_mixed_rag_store").putBoolean("manual_local_index_v1",true);
        }
        edit.apply();
    }

    private String[] themeLabels(){ArrayList<String> out=new ArrayList<String>();Collections.addAll(out,new String[]{"Pathfinder Escarlate","Arcano Violeta","Mar Interior","Floresta Esmeralda","Forja Rubra","Norte Glacial","Arquivo de Pergaminho"});Collections.addAll(out,GameBoyPaletteRegistry.labels());return out.toArray(new String[out.size()]);}
    private String themeLabel(String mode){String gb=GameBoyPaletteRegistry.labelForMode(mode);if(gb!=null)return gb;if("arcane".equals(mode))return "Arcano Violeta";if("realms".equals(mode))return "Mar Interior";if("forest".equals(mode))return "Floresta Esmeralda";if("infernal".equals(mode))return "Forja Rubra";if("frost".equals(mode))return "Norte Glacial";if("parchment".equals(mode))return "Arquivo de Pergaminho";return "Pathfinder Escarlate";}
    private String themeMode(String label){String gb=GameBoyPaletteRegistry.modeForLabel(label);if(gb!=null)return gb;if("Arcano Violeta".equals(label))return "arcane";if("Mar Interior".equals(label))return "realms";if("Floresta Esmeralda".equals(label))return "forest";if("Forja Rubra".equals(label))return "infernal";if("Norte Glacial".equals(label))return "frost";if("Arquivo de Pergaminho".equals(label))return "parchment";return "pathfinder";}
    private void renderThemePreview(String mode,LinearLayout strip,TextView info){
        GameBoyPaletteRegistry.Palette p=GameBoyPaletteRegistry.byMode(mode);
        strip.removeAllViews();
        if(p==null){
            strip.setVisibility(View.GONE);
            info.setText("Identidade Pathfinder 2e Remaster. As paletas alteram apenas apresentação, nunca regras.");
            return;
        }
        strip.setVisibility(View.VISIBLE);
        StringBuilder hex=new StringBuilder();
        for(int i=0;i<p.colors.length;i++){
            int c=p.colors[i];if(i>0)hex.append("  ");
            hex.append(String.format(Locale.US,"#%06X",(0xFFFFFF&c)));
            View swatch=new View(this);swatch.setBackgroundColor(c);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(34),1);lp.setMargins(i==0?0:dp(2),dp(3),i==p.colors.length-1?0:dp(2),dp(3));strip.addView(swatch,lp);
        }
        info.setText(p.technicalId+" • "+p.name+"\n"+hex.toString());
    }
    private int themedButtonTextColor(int background){
        if(!GameBoyPaletteRegistry.isGameBoyMode(activeThemeMode()))return TEXT;
        return GameBoyPaletteRegistry.contrast(TEXT,background)>=GameBoyPaletteRegistry.contrast(BG,background)?TEXT:BG;
    }
