    private void runKingmakerSoloStep(JSONObject step){
        String key=step==null?"":step.optString("key");
        if("go_jamandi_mansion".equals(key)){startJamandiMansionFromUi();return;}
        if("restov_sandbox".equals(key)){navigate("Mestre IA");sendAi("Narrador","Continue a vida sandbox em Restov a partir do estado persistido. Faça o mundo se mover naturalmente; não leve o grupo à mansão de Lady Jamandi sem escolha explícita do jogador.","PLAYER_ACTION");return;}
        if("jamandi_mansion".equals(key)){continueKingmakerMansionFromUi();return;}
        if("camp".equals(key)){showKingmakerActiveCampOrCamps();return;}
        if("camp_encounter".equals(key)){playKingmakerPendingCampEncounter();return;}
        if("war".equals(key)){showKingmakerActiveWarOrArmies();return;}
        if("event".equals(key)){showKingmakerEventsDialog();return;}
        if("companion_event".equals(key)||"companion".equals(key)){playPendingKingmakerCompanionEvent();return;}
        if("companions".equals(key)){showKingmakerCompanionFocus();return;}
        if("exploration_event".equals(key)){showKingmakerExplorationGuide();return;}
        if("explore".equals(key)||"explore_current".equals(key)||"plan_expedition".equals(key)||"expedition_travel".equals(key)||"travel".equals(key)||"free_exploration".equals(key)){showKingmakerExplorationGuide();return;}
        if("kingdom_turn".equals(key)||"kingdom_transition".equals(key)){runGuidedKingdomDecision();return;}
        if("adventure_start".equals(key)){beginAdventure(false);return;}
        navigate("Mestre IA");
    }

    /** CTA único: lê adventure_guide e encaminha para uma superfície jogável. */
    private void continueKingmakerCampaign(){
        JSONObject solo=kingmakerService==null?new JSONObject():kingmakerService.soloSnapshot();
        JSONObject guide=solo.optJSONObject("adventure_guide");
        String action=KingmakerSoloFlowRouter.actionFor(guide==null?"":guide.optString("next_scene"));
        if(KingmakerSoloFlowRouter.START_ADVENTURE.equals(action)){beginAdventure(false);return;}
        if(KingmakerSoloFlowRouter.CAMP_ENCOUNTER.equals(action)){playKingmakerPendingCampEncounter();return;}
        if(KingmakerSoloFlowRouter.CAMP.equals(action)){showKingmakerActiveCampOrCamps();return;}
        if(KingmakerSoloFlowRouter.WAR.equals(action)){showKingmakerActiveWarOrArmies();return;}
        if(KingmakerSoloFlowRouter.EXPLORATION_RESOLUTION.equals(action)){showKingmakerExplorationGuide();return;}
        if(KingmakerSoloFlowRouter.COMPANION.equals(action)){playPendingKingmakerCompanionEvent();return;}
        if(KingmakerSoloFlowRouter.KINGDOM_BRIDGE.equals(action)){runGuidedKingdomDecision();return;}
        if(KingmakerSoloFlowRouter.TRAVEL.equals(action)||KingmakerSoloFlowRouter.FREE_EXPLORATION.equals(action)){showKingmakerExplorationGuide();return;}
        navigate("Mestre IA");
    }

    private void showKingmakerActiveCampOrCamps(){
        for(JSONObject camp:kingmakerRepository.camps(20))if("active".equals(camp.optString("status"))){showKingmakerCampDetails(camp);return;}
        showKingmakerCampsDialog();
    }

    private void showKingmakerExplorationGuide(){JSONObject solo=kingmakerService==null?new JSONObject():kingmakerService.soloSnapshot();final JSONObject guide=solo.optJSONObject("exploration_guide");if(guide==null||guide.length()==0){navigate("Mapa");return;}if(guide.optBoolean("blocked_by_camp")){toast("Conclua ou resolva o acampamento antes de avançar a expedição.");showKingmakerCampsDialog();return;}final String current=guide.optString("current_hex");if(current.length()==0){toast("Defina primeiro a posição do grupo no Atlas.");navigate("Mapa");return;}final String pendingHex=guide.optString("pending_event_hex");if(guide.optBoolean("pending_event")&&pendingHex.length()>0&&!pendingHex.equals(current)){new AlertDialog.Builder(this).setTitle("Exploração pendente — "+pendingHex).setMessage(fallback(guide.optString("pending_event_title"),"Há uma exploração ainda sem resultado")+".\n\nA expedição não abre outro trecho enquanto essa cena estiver pendente. Retorne ao hex "+pendingHex+" pelo Atlas e conclua o resultado; o modo Solo não teletransporta o grupo.").setNegativeButton("Voltar",null).setPositiveButton("ABRIR ATLAS",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){navigate("Mapa");}}).show();return;}String next=guide.optString("next_hex"),destination=guide.optString("destination_hex"),status=guide.optString("current_status","desconhecido");JSONObject pending=kingmakerRepository.pendingExplorationEvent(current);if(pending.length()>0){final JSONObject event=pending;new AlertDialog.Builder(this).setTitle("Exploração em andamento — "+current).setMessage(event.optString("title")+"\n\n"+event.optString("notes")+"\n\nO hex só muda de estado quando você registrar o resultado depois da cena.").setNegativeButton("Voltar",null).setNeutralButton("CONTINUAR CENA",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){playKingmakerExplorationEvent(event);}}).setPositiveButton("REGISTRAR RESULTADO",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){showKingmakerExplorationResultDialog(current,event);}}).show();return;}if(next.length()>0){new AlertDialog.Builder(this).setTitle("Expedição planejada").setMessage("Hex atual: "+current+"\nPróximo trecho: "+next+"\nDestino: "+fallback(destination,next)+"\n\nO modo Solo não teletransporta o grupo. O deslocamento continua no motor PF2e do Atlas, por AVANÇAR 1 HEX.").setNegativeButton("Voltar",null).setNeutralButton("REPLANEJAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){showKingmakerExpeditionPlanner();}}).setPositiveButton("ABRIR ATLAS E AVANÇAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){navigate("Mapa");}}).show();return;}if("desconhecido".equals(status)||"reconnoiterado".equals(status)){String action="desconhecido".equals(status)?"RECONHECER O HEX":"RESOLVER AMEAÇAS DO HEX";new AlertDialog.Builder(this).setTitle("Hex "+current+" • "+status).setMessage("Jogue primeiro a exploração como cena. Reconhecimento ou limpeza só serão persistidos depois de uma confirmação explícita; a IA não grava mecânica.").setNegativeButton("Voltar",null).setNeutralButton("PLANEJAR PRÓXIMO TRECHO",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){showKingmakerExpeditionPlanner();}}).setPositiveButton(action,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){playKingmakerCurrentHexExploration();}}).show();return;}showKingmakerExpeditionPlanner();}

    private void showKingmakerExpeditionPlanner(){JSONObject solo=kingmakerService==null?new JSONObject():kingmakerService.soloSnapshot();JSONObject guide=solo.optJSONObject("exploration_guide");if(guide==null){navigate("Mapa");return;}final String current=guide.optString("current_hex");String pendingHex=guide.optString("pending_event_hex");if(guide.optBoolean("pending_event")&&pendingHex.length()>0&&!pendingHex.equals(current)){toast("Conclua primeiro a exploração pendente no hex "+pendingHex+".");showKingmakerExplorationGuide();return;}final JSONArray neighbors=guide.optJSONArray("neighbors");if(current.length()==0||neighbors==null||neighbors.length()==0){toast("O Atlas não forneceu vizinhos canônicos para planejar a expedição.");navigate("Mapa");return;}final String[] labels=new String[neighbors.length()];final String[] ids=new String[neighbors.length()];for(int i=0;i<neighbors.length();i++){JSONObject n=neighbors.optJSONObject(i);ids[i]=n==null?"":n.optString("hex_id");labels[i]=ids[i]+" • "+(n==null?"desconhecido":n.optString("status","desconhecido"));}new AlertDialog.Builder(this).setTitle("Próximo trecho a partir de "+current).setItems(labels,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){if(which<0||which>=ids.length||ids[which].length()==0)return;planKingmakerNeighbor(current,ids[which]);}}).setNegativeButton("Cancelar",null).show();}

    private void planKingmakerNeighbor(String current,String target){try{JSONObject map=db.getMapState();if(map.optInt("position_locked",0)!=1){toast("Confirme primeiro a posição atual no Atlas.");navigate("Mapa");return;}MapManifestGeometry geometry=MapManifestGeometry.parse(map.optString("manifest_json"));if(!geometry.neighbors(current).contains(target))throw new IllegalArgumentException("O destino precisa ser um hex canônico adjacente.");JSONArray route=new JSONArray().put(target);JSONObject before=new JSONObject(map.toString());db.saveMapTravelState(true,target,route.toString(),"Kingmaker Solo");db.addAuditEvent("kingmaker_expedicao","Trecho de expedição planejado",current+" → "+target,before.toString(),db.getMapState().toString(),true);toast("Trecho "+current+" → "+target+" planejado. O movimento será feito pelo Atlas.");navigate("Mapa");}catch(Exception e){toast("Expedição: "+e.getMessage());}}

    private void playKingmakerCurrentHexExploration(){try{String hex=db.getMapState().optString("current_hex_id").trim().toUpperCase(Locale.US);JSONObject event=kingmakerRepository.ensureExplorationEvent(hex);if(event.length()==0){toast("Este hex já está reconhecido e limpo.");showKingmakerExpeditionPlanner();return;}playKingmakerExplorationEvent(event);}catch(Exception e){toast("Exploração: "+e.getMessage());}}

    private void playKingmakerExplorationEvent(JSONObject event){String source=event.optString("source_ref"),hex=db.getMapState().optString("current_hex_id");String stage=source.endsWith(":clear")?"resolver as ameaças":"reconhecer o território";navigate("Mestre IA");sendAi("Narrador","EXPEDIÇÃO KINGMAKER SOLO — "+stage.toUpperCase(Locale.US)+" no hex "+hex+". Evento persistido: "+event.optString("title")+". "+event.optString("notes")+" Use o Atlas canônico, Mundo Vivo, clima, período, companions e fatos já persistidos. Não invente mudança de território e não marque o hex automaticamente. Conduza a exploração em cena; testes e combate usam as autoridades PF2e existentes. Ao final, o jogador registrará explicitamente o resultado no modo Kingmaker Solo.");}

    private void showKingmakerExplorationResultDialog(final String hex,final JSONObject event){String stage=event.optString("source_ref").endsWith(":clear")?"clear":"reconnoiter";String label="clear".equals(stage)?"Marcar como limpo":"Marcar como reconhecido";LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),dp(16));form.addView(text("Registre somente depois de a cena ter sido realmente resolvida. Esta confirmação usa o repositório Kingmaker existente; a IA não altera o hex.",12,MUTED,false));final EditText notes=labeledField(form,"O que foi descoberto / resolvido","",true);new AlertDialog.Builder(this).setTitle(label+" — "+hex).setView(scrollableDialogView(form)).setNegativeButton("Cancelar",null).setPositiveButton("CONFIRMAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{JSONObject updated=kingmakerRepository.resolveExplorationEvent(hex,value(notes));showKingmaker();toast("Hex "+hex+" atualizado: "+(updated.optInt("cleared",0)==1?"limpo":"reconhecido")+".");}catch(Exception e){toast("Exploração: "+e.getMessage());}}}).show();}

    private void showKingdomTurnGuideDialog(){try{KingmakerTurnGuide guide=new KingmakerTurnGuide(db,kingmakerRepository,kingmakerRules);new AlertDialog.Builder(this).setTitle("ⓘ Guia do Turno do Reino").setMessage(guide.renderText()).setNegativeButton("Fechar",null).setPositiveButton("IR PARA A PRÓXIMA DECISÃO",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){runGuidedKingdomDecision();}}).show();}catch(Exception e){toast("Guia do Reino: "+e.getMessage());}}

    private void runGuidedKingdomDecision(){JSONObject solo=kingmakerService==null?new JSONObject():kingmakerService.soloSnapshot();JSONObject guide=solo.optJSONObject("kingdom_turn_guide");if(guide==null||!guide.optBoolean("active")){showStartKingdomTurnDialog();return;}String action=guide.optString("action");if("resolve_consumption".equals(action)){showKingmakerConsumptionDialog();return;}if("resolve_event".equals(action)){showKingmakerEventsDialog();return;}if("phase_choice".equals(action)){showGuidedKingdomPhaseDialog(guide);return;}if("advance_phase".equals(action)){advanceKingmakerPhase();return;}showKingdomCheckDialog();}

    private void showGuidedKingdomPhaseDialog(final JSONObject guide){String phase=guide.optString("phase");String label=KingmakerService.phaseLabel(phase);new AlertDialog.Builder(this).setTitle("Turno guiado • "+label).setMessage(guide.optString("text")+"\n\nEscolha somente o que o Reino fará agora. Você não precisa abrir a ficha técnica.").setNegativeButton("Voltar",null).setNeutralButton("RESOLVER UMA AÇÃO",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){showKingdomCheckDialog();}}).setPositiveButton("CONCLUIR ESTA FASE",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){advanceKingmakerPhase();}}).show();}

    private static String kingmakerCompanionKey(JSONObject focus){return KingmakerSoloEventPolicy.companionKey(focus);}

    private void showKingmakerCompanionFocus(){JSONObject solo=kingmakerService==null?new JSONObject():kingmakerService.soloSnapshot();final JSONObject focus=solo.optJSONObject("companion_focus");if(focus==null||focus.length()==0){showKingmakerCompanionsDialog();return;}final String name=focus.optString("name","Companheiro"),hook=focus.optString("personal_hook");String message=hook.length()>0?hook:("Função atual: "+focus.optString("assignment","reserve")+". Barbara pode dar espaço a este companheiro dentro da cena atual sem fabricar efeitos mecânicos.");new AlertDialog.Builder(this).setTitle("Cena pessoal — "+name).setMessage(message).setNegativeButton("Ver ficha",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){for(JSONObject c:kingmakerRepository.companions())if(c.optString("companion_key").equals(kingmakerCompanionKey(focus))){showKingmakerCompanionDetails(c);return;}showKingmakerCompanionsDialog();}}).setNeutralButton("REGISTRAR PROGRESSO",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){showKingmakerCompanionProgressDialog(focus);}}).setPositiveButton("JOGAR ESTA CENA",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{kingmakerRepository.ensureCompanionPersonalEvent(kingmakerCompanionKey(focus));}catch(Exception e){toast("Companheiro: "+e.getMessage());return;}navigate("Mestre IA");String prompt="Dê espaço agora ao companheiro "+name+" em uma cena orgânica da campanha Kingmaker. "+(hook.length()>0?("Hook pessoal persistido: "+hook+". "):"")+"Use o local, clima, período, relações e fatos já persistidos. Não altere influência, Reino, inventário ou qualquer mecânica diretamente; apresente ficção, diálogo e escolhas, deixando consequências mecânicas para as autoridades existentes.";sendAi("Narrador",prompt);}}).show();}

    private void showKingmakerCompanionProgressDialog(final JSONObject focus){LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),dp(16));final String[] states={"in_progress","complete"};final Spinner status=spinner(states,"in_progress");form.addView(cardWithLabel("ESTADO DO ARCO",status));final EditText notes=labeledField(form,"O que mudou nesta cena","",true);new AlertDialog.Builder(this).setTitle("Progresso — "+focus.optString("name","Companheiro")).setView(scrollableDialogView(form)).setNegativeButton("Cancelar",null).setPositiveButton("REGISTRAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{JSONObject updated=kingmakerRepository.recordCompanionQuestProgress(kingmakerCompanionKey(focus),String.valueOf(status.getSelectedItem()),value(notes));JSONObject pending=kingmakerRepository.pendingCompanionEvent(kingmakerCompanionKey(focus));if(pending.length()>0)kingmakerRepository.resolveEvent(pending.optLong("id"),new JSONObject().put("companion_arc_status",updated.optString("personal_quest_status")).put("notes",value(notes)));showKingmaker();toast("Arco pessoal atualizado: "+updated.optString("personal_quest_status")+".");}catch(Exception e){toast("Companheiro: "+e.getMessage());}}}).show();}

    private void playPendingKingmakerCompanionEvent(){JSONObject solo=kingmakerService==null?new JSONObject():kingmakerService.soloSnapshot(),focus=solo.optJSONObject("companion_focus");long pendingId=focus==null?0:focus.optLong("pending_event_id",0);List<JSONObject> companions=kingmakerRepository.companions();JSONObject chosen=KingmakerSoloEventPolicy.choose(kingmakerRepository.events("pending"),companions,pendingId);if(chosen.length()==0){showKingmakerCompanionFocus();return;}String source=chosen.optString("source_ref"),companionKey=source.startsWith("companion:")?source.substring("companion:".length()):kingmakerCompanionKey(focus);JSONObject companion=new JSONObject();for(JSONObject c:companions)if(c.optInt("available",1)==1&&c.optString("companion_key").equals(companionKey)){companion=c;break;}if(companion.length()==0){toast("O evento pessoal pertence a um companion indisponível; ele não será jogado.");showKingmakerCompanionsDialog();return;}final JSONObject event=chosen,selected=companion;final String name=selected.optString("name",event.optString("title","Companheiro"));navigate("Mestre IA");sendAi("Narrador","Continue agora o evento pessoal persistido de "+name+": "+event.optString("title")+". Contexto registrado: "+event.optString("notes")+". Use apenas fatos, local, clima, relações e história persistidos. Não altere influência, Reino, inventário ou outra mecânica; ofereça ficção e escolhas. O jogador registrará progresso depois da cena.");}

