    /** Official Kingmaker: Claim Hex must make its Kingdom skill check and persist the outcome. */
    private void showKingmakerClaimHexDialog(final String hexId,final String sourceNotes){
        final String[] skills={"exploration","intrigue","magic","wilderness"};
        final String[] labels={"Exploração","Intriga","Magia","Sobrevivência"};
        LinearLayout form=new LinearLayout(this);
        form.setOrientation(LinearLayout.VERTICAL);
        form.setPadding(dp(12),0,dp(12),dp(16));
        form.addView(text("Reivindicar Hex custa 1 RP antes do teste. O motor valida reconhecimento, adjacência, limites por turno e consequências.",13,TEXT,false));
        final Spinner selected=spinner(labels,labels[0]);
        form.addView(cardWithLabel("PERÍCIA OFICIAL",selected));
        final int rolled=new Random().nextInt(20)+1;
        final EditText natural=labeledField(form,"d20",String.valueOf(rolled),false);
        natural.setInputType(InputType.TYPE_CLASS_NUMBER);
        new AlertDialog.Builder(this).setTitle("Reivindicar Hex • "+hexId)
            .setView(scrollableDialogView(form))
            .setNegativeButton("Cancelar",null)
            .setPositiveButton("RESOLVER",(dialog,which)->{
                try{
                    JSONObject result=kingmakerRepository.resolveClaimHex(
                        hexId,num(natural,rolled),skills[selected.getSelectedItemPosition()],sourceNotes);
                    screenCache.clear();showKingmaker();
                    JSONObject check=result.optJSONObject("check");
                    String roll=check==null?"":("\nTeste: "+check.optString("degree_pt")+
                        " • total "+check.optInt("total")+" contra CD "+check.optInt("dc"));
                    new AlertDialog.Builder(MainActivity.this)
                        .setTitle("Reivindicar Hex — consequência")
                        .setMessage(result.optString("outcome_pt")+roll)
                        .setPositiveButton("Fechar",null).show();
                }catch(Exception ex){toast("Reivindicar Hex: "+ex.getMessage());}
            }).show();
    }

    private void showKingmakerHexDialog(){
        final List<JSONObject> rows=kingmakerRepository.hexes();LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),dp(16));JSONObject map=db.getMapState();form.addView(text("O Atlas oficial é validado e permanece somente leitura. O estado abaixo é uma sobreposição da campanha.",12,MUTED,false));StringBuilder summary=new StringBuilder();for(JSONObject row:rows){if(summary.length()>0)summary.append("\n");summary.append(row.optString("hex_id")).append(" • ").append(hexKingmakerStatus(row));if(row.optString("improvement").length()>0)summary.append(" • ").append(row.optString("improvement"));}form.addView(text(summary.length()==0?"Nenhum hex Kingmaker registrado.":summary.toString(),12,TEXT,false));final EditText hex=labeledField(form,"Hex",map.optString("current_hex_id"),false),notes=labeledField(form,"Notas / fonte","",true);final String[] actions={"Reconnoiterar","Limpar","Reivindicar (1 RP)","Construir melhoria / estrada","Abandonar reivindicação"};final Spinner action=spinner(actions,actions[0]);form.addView(cardWithLabel("AÇÃO",action));new AlertDialog.Builder(this).setTitle("Hexploração Kingmaker").setView(scrollableDialogView(form)).setNegativeButton("Fechar",null).setNeutralButton("ABRIR ATLAS",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){navigate("Mapa");}}).setPositiveButton("APLICAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{String h=value(hex).toUpperCase(Locale.US);int a=action.getSelectedItemPosition();if(a==0)kingmakerRepository.reconnoiterHex(h,value(notes));else if(a==1)kingmakerRepository.clearHex(h,value(notes));else if(a==2){showKingmakerClaimHexDialog(h,value(notes));return;}else if(a==3){showKingmakerHexImprovementDialog(h);return;}else kingmakerRepository.relinquishHex(h);screenCache.clear();showKingmaker();toast("Hex "+h+" atualizado.");}catch(Exception e){toast("Hexploração: "+e.getMessage());}}}).show();
    }

    private String hexKingmakerStatus(JSONObject row){if(row.optInt("claimed")==1)return "REIVINDICADO";if(row.optInt("cleared")==1)return "LIMPO";if(row.optInt("reconnoitered")==1)return "RECONNOITERADO";return "DESCONHECIDO";}

    private void showKingmakerHexImprovementDialog(final String hex){JSONObject current=kingmakerRepository.hex(hex);if(current.length()==0||current.optInt("claimed")!=1){toast("Reivindique o hex antes de construir melhoria.");return;}LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),dp(16));final EditText improvement=labeledField(form,"Melhoria",current.optString("improvement"),false),resource=labeledField(form,"Sítio de recurso",current.optString("resource_site"),false),notes=labeledField(form,"Notas",current.optString("notes"),true);final CheckBox road=check("Estrada construída",current.optInt("road")==1),farmland=check("Fazendas / farmland",current.optInt("farmland")==1),landmark=check("Landmark oficial neste hex",current.optInt("landmark")==1),refuge=check("Refuge oficial neste hex",current.optInt("refuge")==1);form.addView(road);form.addView(farmland);form.addView(landmark);form.addView(refuge);new AlertDialog.Builder(this).setTitle("Melhorias em "+hex).setView(form).setNegativeButton("Cancelar",null).setPositiveButton("SALVAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{kingmakerRepository.improveHex(hex,value(improvement),road.isChecked(),farmland.isChecked(),landmark.isChecked(),refuge.isChecked(),value(resource),value(notes));showKingmaker();toast("Melhoria territorial salva.");}catch(Exception e){toast("Melhoria: "+e.getMessage());}}}).show();}

