    private void showKingmakerStartCampDialog(){final JSONObject context;try{context=kingmakerService==null?new JSONObject():kingmakerService.contextualCampProposal();}catch(Exception e){toast("Não foi possível montar o contexto do acampamento: "+e.getMessage());return;}LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),dp(16));String contextText="Hex "+fallback(context.optString("hex_id"),"—")+" • dia "+context.optInt("day_number",db.getSceneState().optInt("day_number",1))+" • "+fallback(context.optString("period"),"período não registrado")+" • "+fallback(context.optString("weather"),"clima não registrado")+" • "+fallback(context.optString("terrain"),"terreno não catalogado");form.addView(text(contextText,13,TEXT,true));form.addView(text("O contexto vem do Atlas/Mundo atual. CDs começam sem valor quando não existem na fonte persistida; o aplicativo não inventa dificuldade de zona ou encontro.",12,MUTED,false));final EditText zone=labeledField(form,"Zona / local de acampamento",context.optString("zone_name"),false),zoneDc=labeledField(form,"CD da Zona confirmada (0 = não informada)","0",false),encounterDc=labeledField(form,"CD inicial de encontro confirmada (0 = não informada)","0",false),ingredients=labeledField(form,"Ingredientes especiais","0",false),notes=labeledField(form,"Notas / fonte",context.optString("policy"),true);for(EditText e:new EditText[]{zoneDc,encounterDc,ingredients})e.setInputType(InputType.TYPE_CLASS_NUMBER);final String[] degrees={"not_rolled","critical_success","success","failure","critical_failure"};final Spinner prepare=spinner(degrees,degrees[0]);form.addView(cardWithLabel("RESULTADO DE PREPARE CAMP",prepare));final CheckBox reused=check("Reutilizando este acampamento",false);form.addView(reused);new AlertDialog.Builder(this).setTitle("Preparar acampamento").setView(scrollableDialogView(form)).setNegativeButton("Cancelar",null).setPositiveButton("INICIAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{kingmakerService.startCampAtCurrentPosition(value(zone),num(zoneDc,0),num(encounterDc,0),String.valueOf(prepare.getSelectedItem()),reused.isChecked(),num(ingredients,0),value(notes));showKingmaker();toast("Acampamento iniciado no contexto atual.");}catch(Exception e){toast("Acampamento: "+e.getMessage());}}}).show();}
    private void showKingmakerCampDetails(final JSONObject camp){JSONObject result=parseLooseJson(camp.optString("result_json","{}"));String zoneDcLabel=camp.optInt("zone_dc")>0?String.valueOf(camp.optInt("zone_dc")):"não confirmada",encounterNow=camp.optInt("current_encounter_dc")>0?String.valueOf(camp.optInt("current_encounter_dc")):"não confirmada",encounterInitial=camp.optInt("encounter_dc")>0?String.valueOf(camp.optInt("encounter_dc")):"não confirmada";String message="Dia "+camp.optInt("day_number")+" • hex "+fallback(camp.optString("hex_id"),"—")+" • "+camp.optString("status")+"\nZona: "+fallback(camp.optString("zone_name"),"—")+" • CD "+zoneDcLabel+"\nPrepare Camp: "+fallback(camp.optString("prepare_degree"),"não rolado")+" • reutilizado: "+(camp.optInt("reused")==1?"sim":"não")+"\nHoras de atividade: "+camp.optInt("elapsed_hours")+" • CD de encontro atual "+encounterNow+" (inicial "+encounterInitial+")\nIngredientes especiais: "+camp.optInt("special_ingredients")+" • clima: "+fallback(camp.optString("weather"),"—")+"\n\nAtividades:\n"+campActivitiesSummary(camp.optString("activities_json","[]"))+"\n\nVigias: "+campWatchSummary(camp.optString("watch_json","[]"))+"\nEncontro: "+campEncounterSummary(camp.optString("encounter_json","{}"))+(result.length()>0?"\nResultado: "+fallback(result.optString("notes"),result.toString()):"")+"\n\n"+camp.optString("notes");if("active".equals(camp.optString("status"))){final boolean pendingEncounter="RANDOM_ENCOUNTER".equals(camp.optString("phase"));final String[] actions=pendingEncounter?new String[]{"Jogar encontro em cena","Retomar acampamento após resolver"}:new String[]{"Registrar hora de atividade","Concluir: refeição, vigia e descanso"};new AlertDialog.Builder(this).setTitle("Acampamento "+camp.optString("camp_key")).setMessage(message).setItems(actions,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){if(pendingEncounter){if(which==0)playKingmakerCampEncounter(camp);else showKingmakerResumeCampEncounterDialog(camp);}else{if(which==0)showKingmakerCampHourDialog(camp);else showKingmakerCompleteCampDialog(camp);}}}).setNegativeButton("Fechar",null).show();}else new AlertDialog.Builder(this).setTitle("Acampamento "+camp.optString("camp_key")).setMessage(message).setPositiveButton("Fechar",null).show();}

    private String campActivitiesSummary(String raw){JSONArray rows=parseLooseJsonArray(raw);if(rows.length()==0)return "Nenhuma atividade registrada.";StringBuilder out=new StringBuilder();for(int i=0;i<rows.length();i++){JSONObject x=rows.optJSONObject(i);if(x==null)continue;if(out.length()>0)out.append("\n");out.append("• ").append(fallback(x.optString("activity"),"Atividade"));String result=x.optString("result");if(result.length()>0)out.append(" — ").append(result);}return out.length()==0?"Atividades registradas.":out.toString();}
    private String campWatchSummary(String raw){JSONArray rows=parseLooseJsonArray(raw);if(rows.length()==0)return "não registrada";StringBuilder out=new StringBuilder();for(int i=0;i<rows.length();i++){JSONObject x=rows.optJSONObject(i);if(x==null)continue;if(out.length()>0)out.append("; ");out.append(fallback(x.optString("notes"),x.optString("name","vigia")));}return out.length()==0?"registrada":out.toString();}
    private String campEncounterSummary(String raw){JSONObject x=parseLooseJson(raw);if(x.length()==0)return "nenhum registrado";if(x.optBoolean("triggered"))return "acionado na hora "+x.optInt("hour")+" (d20 "+x.optInt("roll")+" contra CD "+x.optInt("dc")+")"+(x.optBoolean("resolved")?" • resolvido":" • pendente");return fallback(x.optString("notes"),"registrado");}

    private void playKingmakerPendingCampEncounter(){for(JSONObject camp:kingmakerRepository.camps(20))if("active".equals(camp.optString("status"))&&"RANDOM_ENCOUNTER".equals(camp.optString("phase"))){playKingmakerCampEncounter(camp);return;}showKingmakerCampsDialog();}
    private void playKingmakerCampEncounter(final JSONObject camp){JSONObject encounter=parseLooseJson(camp.optString("encounter_json","{}"));JSONObject solo=kingmakerService==null?new JSONObject():kingmakerService.soloSnapshot();JSONObject focus=solo.optJSONObject("companion_focus");String companions=focus==null||focus.length()==0?"nenhum companion em foco":focus.optString("name")+" em foco";navigate("Mestre IA");sendAi("Narrador","ENCONTRO DE ACAMPAMENTO KINGMAKER. O descanso está pausado no hex "+fallback(camp.optString("hex_id"),"desconhecido")+", dia "+camp.optInt("day_number")+", clima "+fallback(camp.optString("weather"),"não registrado")+", zona "+fallback(camp.optString("zone_name"),"não registrada")+". O teste persistido disparou o encontro na hora "+encounter.optInt("hour")+" com d20 "+encounter.optInt("roll")+" contra CD "+encounter.optInt("dc")+"; isso apenas determina que há encontro, não inventa criatura nem resultado. "+companions+". Crie a cena usando somente Atlas, Mundo Vivo e fatos recuperáveis; se houver combate ou teste, use as autoridades PF2e existentes. Não marque o encontro como resolvido automaticamente.");}
