    private void showKingmakerCampHourDialog(final JSONObject camp){LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),dp(16));final int automaticRoll=new Random().nextInt(20)+1;form.addView(text("Registre o que o grupo fez nesta hora. O teste de encontro já foi rolado automaticamente; altere apenas se usar dado físico.",12,MUTED,false));final String[] activities={"Descansar","Preparar refeição","Vigiar","Caçar / coletar","Explorar arredores","Tratar ferimentos","Crafting / manutenção","Interagir com companheiro","Harrim — Mesclar-se à Noite","Outra atividade"};final Spinner activity=spinner(activities,activities[0]);form.addView(cardWithLabel("ATIVIDADE",activity));final EditText result=labeledField(form,"Resultado / observação","",true),roll=labeledField(form,"d20 de encontro",String.valueOf(automaticRoll),false);roll.setInputType(InputType.TYPE_CLASS_NUMBER);new AlertDialog.Builder(this).setTitle("Hora "+(camp.optInt("elapsed_hours")+1)).setView(scrollableDialogView(form)).setNegativeButton("Cancelar",null).setPositiveButton("REGISTRAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{JSONObject activityJson=new JSONObject().put("activity",String.valueOf(activity.getSelectedItem())).put("result",value(result)).put("hour",camp.optInt("elapsed_hours")+1);if("Harrim — Mesclar-se à Noite".equals(String.valueOf(activity.getSelectedItem())))activityJson.put("companion_activity","harrim_blend_into_night");JSONObject updated=kingmakerRepository.recordCampHour(camp.optString("camp_key"),activityJson.toString(),num(roll,automaticRoll));if(!advanceSceneHours(1d))toast("A hora do acampamento foi salva, mas o relógio da cena não avançou; revise o estado antes de continuar.");showKingmaker();boolean triggered=parseLooseJson(updated.optString("encounter_json","{}")).optBoolean("triggered");toast(triggered?"Encontro aleatório acionado após a hora registrada.":"Hora registrada; relógio e acampamento avançaram juntos.");}catch(Exception e){toast("Acampamento: "+e.getMessage());}}}).show();}

    private void showKingmakerCompleteCampDialog(final JSONObject camp){LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),dp(16));form.addView(text("Conclua o acampamento em linguagem comum. O histórico de atividades e o encontro já registrados serão preservados pelo motor.",12,MUTED,false));final EditText watch=labeledField(form,"Vigias / ordem de guarda","",true),meal=labeledField(form,"Refeição / suprimentos","",true),rest=labeledField(form,"Descanso / recuperação / observações","",true);final CheckBox slept=check("Confirmar sono completo pelas horas de Descansar já registradas e pela rotação de vigias",false);form.addView(slept);new AlertDialog.Builder(this).setTitle("Concluir acampamento").setView(scrollableDialogView(form)).setNegativeButton("Cancelar",null).setPositiveButton("CONCLUIR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{JSONArray watches=new JSONArray();if(value(watch).length()>0)watches.put(new JSONObject().put("notes",value(watch)));JSONArray activities=parseLooseJsonArray(camp.optString("activities_json","[]"));JSONObject encounter=parseLooseJson(camp.optString("encounter_json","{}"));String notes="Refeição: "+fallback(value(meal),"não registrada")+". Descanso: "+fallback(value(rest),"sem observações")+".";if(slept.isChecked())kingmakerRepository.recordCompletedCampSleep(camp.optString("camp_key"));kingmakerRepository.completeCamp(camp.optString("camp_key"),watches.toString(),activities.toString(),encounter.toString(),notes);showKingmaker();toast("Acampamento concluído e persistido.");}catch(Exception e){toast("Acampamento: "+e.getMessage());}}}).show();}

    private JSONArray parseDiceList(String raw,int maxCount,int die)throws Exception{JSONArray out=new JSONArray();String value=raw==null?"":raw.trim();if(value.length()==0)return out;String[] parts=value.split("[,;\\s]+");if(parts.length>maxCount)throw new Exception("Informe no máximo "+maxCount+" resultado(s).");for(String part:parts){int n=Integer.parseInt(part);if(n<1||n>die)throw new Exception("Cada resultado deve ficar entre 1 e "+die+".");out.put(n);}return out;}
    private static String fallback(String value,String fallback){return value==null||value.trim().length()==0?fallback:value.trim();}

    private String pf2CampaignStyle(String raw){String v=raw==null?"":raw.trim();String[] valid={"Contratos e missões de guilda","Exploração de fronteira","Intriga urbana e facções","Expedição a ruínas e masmorras","Caçada a monstros","Mistério e ocultismo","Sobrevivência e viagem","Saga épica de nível 1 a 20"};for(String x:valid)if(x.equals(v))return x;String n=v.toLowerCase(new Locale("pt","BR"));if(n.contains("invest" )||n.contains("horror"))return "Mistério e ocultismo";if(n.contains("dungeon"))return "Expedição a ruínas e masmorras";if(n.contains("grim")||n.contains("espada"))return "Sobrevivência e viagem";if(n.contains("cinemat")||n.contains("alta fantasia"))return "Saga épica de nível 1 a 20";return "Contratos e missões de guilda";}

    private void beginAdventure(final boolean reset){
        if(adventureStartRunning||aiBusy){toast("A abertura já está sendo preparada.");return;}
        if(db.listActiveCharacters().isEmpty()){toast("Ative ao menos um personagem antes de começar.");navigate("Personagens");return;}
        if(reset){try{safety.beforeDestructiveChange("começar uma nova aventura");db.clearStoryState();lastNarration="";lastVisualPrompt="";currentOptions=new JSONArray();pendingTest=new JSONObject();sharedImageUri=null;prefs.edit().remove(PREF_SCENE_IMAGE_URI).remove(PREF_SCENE_IMAGE_FINGERPRINT).remove(PREF_PENDING_IMAGE_FINGERPRINT).remove(PREF_PENDING_IMAGE_TARGET).remove(PREF_PENDING_CHARACTER_ID).remove(PREF_PENDING_NPC_ID).remove("kingmaker_restov_arrival_seed").remove("kingmaker_mansion_attack_combat_started").remove("kingmaker_mansion_attack_combat_finished").remove(PREF_RECENT_SCENE_OPTIONS).apply();db.saveSceneOptionHistory("[]");db.addAuditEvent("campanha","Nova aventura iniciada","História anterior preservada em snapshot","{}","{}",true);if(kingmakerRepository!=null)kingmakerRepository.resetCampaignPrelude();}catch(Exception error){adventureStartupCoordinator.phase(AdventureStartupCoordinator.Phase.BLOCKED,"Falha ao reiniciar: "+safeMessage(error));toast("Falha ao reiniciar: "+safeMessage(error));return;}}
        launchAdventure(reset,"");
    }

    private void launchAdventure(final boolean reset,final String requestedHex){
        adventureStartRunning=true;setStatus("Preparando a primeira cena...");
        try{
            String phase=kingmakerRepository==null?KingmakerPreludePolicy.PHASE_RESTOV_ARRIVAL:kingmakerRepository.campaignStoryPhase();
            final boolean restovPrelude=kingmakerRepository!=null&&KingmakerPreludePolicy.isPreExpeditionPhase(phase);
            final JSONObject startingPoint;
            if(restovPrelude)startingPoint=prepareKingmakerRestovStart(reset);
            else startingPoint=prepareAdventureStartingPoint(requestedHex);
            final String startingHex=startingPoint.optString("hex_id","");
            if(!restovPrelude){if(reset)resetSceneClock();else initializeSceneClock();}
            final JSONObject campaign=db.getCampaign();
            final String world=activeWorldProfile();
            final String tone=campaign.optString("tone","aventura");
            final String campaignName=campaign.optString("name","Kingmaker");
            final long openingSeed=System.currentTimeMillis()^((long)campaignName.hashCode()<<17)^world.hashCode();
            final String openingInstruction;
            if(restovPrelude)openingInstruction=KingmakerPreludePolicy.arrivalDirective(openingSeed);
            else openingInstruction=AdventureOpeningPlanner.choose(world,campaignName,tone,startingHex,prefs.getString("recent_opening_plans","[]"),prefs.getString("recent_opening_texts","[]"),openingSeed).instruction;

            final String opening;
            if(restovPrelude){
                opening="INÍCIO AUTOMÁTICO — PRIMEIRA CENA NARRATIVA DE KINGMAKER. "
                        +"A âncora obrigatória é RESTOV, em Rostland/Brevoy: a primeira cena mostra os personagens CHEGANDO À CIDADE. "
                        +openingInstruction+" Horário e clima já foram sorteados e estão no scene_state; respeite-os. "
                        +"Depois da entrada, Restov é SANDBOX. NPCs, rumores, trabalhos, pequenos conflitos e acontecimentos podem surgir organicamente e variar entre campanhas. "
                        +"A mansão de Lady Jamandi Aldori pode existir como destino conhecido, convite, rumor ou possibilidade, mas NÃO leve os personagens até lá, NÃO aceite a convocação por eles e NÃO comece a campanha principal até o jogador escolher explicitamente ir à mansão. "
                        +"Não mencione Oleg nem coloque o grupo nas Terras Roubadas nesta abertura. Não transforme a cidade em menu de opções ou tutorial. Não transforme profissão, ferramenta, material ou rotina cotidiana em assunto principal só para parecer detalhado; detalhe só permanece se ajudar espaço, pessoa, pista, risco, humor ou consequência. "
                        +"Esta é uma CENA PRINCIPAL: escreva aproximadamente 5.000 a 6.000 caracteres de prosa PT-BR, em parágrafos substanciais, com câmera narrativa, sensorialidade funcional, pessoas agindo e espaço jogável. "
                        +"A chegada precisa ser concreta e variar naturalmente; exemplos como esconder-se sob feno, vir a cavalo ou chegar a pé são apenas exemplos, nunca uma lista fechada. "
                        +"Preserve a agência: descreva estímulos e circunstâncias, não sentimentos ou decisões voluntárias dos personagens. "
                        +"Todo personagem ou grupo visível, falante ou agente deve constar em scene_state.present_npcs; NPCs nomeados/persistentes também entram em npc_updates. "
                        +"Termine em um ponto real de decisão dentro de Restov e ofereça 4 a 6 escolhas ligadas ao que aconteceu, podendo incluir — sem obrigar — seguir o assunto da convocação de Lady Jamandi.";
            }else{
                opening="INÍCIO AUTOMÁTICO — PRIMEIRA CENA NARRATIVA. Comece a aventura agora como ficção de mesa, não como explicação de regras, tutorial, relatório do aplicativo ou resposta sobre o funcionamento do sistema. "
                        +"A abertura deve ser LONGA, IMERSIVA, JOGÁVEL e significativa desde o primeiro parágrafo: situe quem, onde, o que está acontecendo, o que mudou ou pressiona a cena e por que o personagem precisa prestar atenção. "
                        +openingInstruction+" O estado autoritativo, o Atlas, a campanha, os personagens, os NPCs e o Mundo Vivo já estão no contexto interno do Mestre; use esses fatos sem mencioná-los como estrutura técnica. "
                        +"Todo personagem ou grupo visível, falante ou agente deve constar em scene_state.present_npcs. NPCs nomeados, persistentes ou individualmente relevantes também devem constar em npc_updates, com name, role, present=true e visual_description concreta. "
                        +"Escreva aproximadamente 5.000 a 6.000 caracteres em 6 a 8 parágrafos substanciais. Termine num ponto de decisão concreto e ofereça de 4 a 6 escolhas diretamente ligadas ao que acabou de acontecer.";
            }

            adventureStartupCoordinator.phase(AdventureStartupCoordinator.Phase.NARRATIVE,"Solicitando a primeira cena narrativa");
            ui.post(new Runnable(){public void run(){
                adventureStartRunning=false;lastAiUsedRag=false;lastAiManuals=new JSONArray();lastRagCitations=new JSONArray();activeRuleRetrieval=new JSONObject();
                prefs.edit().remove("last_rag_citations").remove("last_manual_context").apply();
                setStatus(restovPrelude?"Restov • escrevendo a chegada dos personagens…":(startingHex.length()>0?"Atlas pronto • escrevendo a primeira cena…":"Aventura iniciada sem Atlas • escrevendo a primeira cena…"));
                sendAi("Narrador",opening,"PLAYER_ACTION");
            }});
        }catch(Exception error){adventureStartRunning=false;adventureStartupCoordinator.phase(AdventureStartupCoordinator.Phase.BLOCKED,"Falha de abertura: "+safeMessage(error));toast("Abertura: "+safeMessage(error));}
    }

    private JSONObject prepareKingmakerRestovStart(boolean reset)throws Exception{
        if(kingmakerRepository!=null&&(reset||!KingmakerPreludePolicy.isPreExpeditionPhase(kingmakerRepository.campaignStoryPhase())))
            kingmakerRepository.resetCampaignPrelude();
        JSONObject scene=db.getSceneState();
        boolean alreadyInRestov=!reset&&scene.optString("location","").toLowerCase(Locale.ROOT).contains("restov")
                &&scene.has("clock_hour")&&scene.optString("weather","").trim().length()>0;
        long seed=prefs.getLong("kingmaker_restov_arrival_seed",0L);
        if(seed==0L||reset){seed=System.nanoTime()^System.currentTimeMillis()^activeWorldProfile().hashCode();prefs.edit().putLong("kingmaker_restov_arrival_seed",seed).apply();}
        if(!alreadyInRestov){
            String daypart=KingmakerPreludePolicy.randomDaypart(seed);
            scene=new JSONObject();
            scene.put("day_number",1);
            scene.put("location","Restov, Rostland, Brevoy");
            scene.put("hex_id","AB2");
            scene.put("time_of_day",daypart);
            scene.put("clock_hour",KingmakerPreludePolicy.hourForDaypart(daypart));
            scene.put("weather",KingmakerPreludePolicy.randomWeather(seed));
            scene.put("lighting",KingmakerPreludePolicy.lightingForDaypart(daypart));
            scene.put("danger","");
            scene.put("objective","Entrar em Restov e decidir livremente o que fazer na cidade.");
            scene.put("present_npcs",new JSONArray());
            scene.put("threats",new JSONArray());
            scene.put("clues",new JSONArray());
            scene.put("pending_consequences",new JSONArray());
            db.saveSceneState(scene);
            db.addAuditEvent("kingmaker_prologo","Chegada preparada em Restov",daypart+" • "+scene.optString("weather"),"{}",scene.toString(),true);
        }else{
            initializeSceneClock(); // retoma o relógio persistido; nunca sorteia novamente clima/horário.
        }
        JSONObject map=db.getMapState();String packageId=map.optString("map_package_id","");
        if(packageId.length()>0&&db.isMapPackageUsable(packageId))db.saveMapTravelState(false,"","[]","Kingmaker — Restov (âncora urbana; hexploração ainda não iniciada)");
        prefs.edit().putString("kingmaker_atlas_mode","restov_city").putString("kingmaker_atlas_anchor_name","Restov, Rostland, Brevoy").apply();
        return new JSONObject().put("hex_id","").put("start_location_name","Restov, Rostland, Brevoy").put("atlas_optional",false).put("map_grounded",true).put("atlas_mode","urban_anchor").put("prelude","restov");
    }

    private String prepareKingmakerPreludeAction(String raw){
        if(kingmakerRepository==null)return raw==null?"":raw;
        String text=raw==null?"":raw;
        try{
            String phase=kingmakerRepository.campaignStoryPhase();
            if(KingmakerPreludePolicy.PHASE_RESTOV_ARRIVAL.equals(phase)&&db.getStoryState().optInt("started",0)==1){
                kingmakerRepository.setCampaignStoryPhase(KingmakerPreludePolicy.PHASE_RESTOV_SANDBOX,false);
                phase=KingmakerPreludePolicy.PHASE_RESTOV_SANDBOX;
            }
            if(KingmakerPreludePolicy.isRestovPhase(phase)&&KingmakerPreludePolicy.isMansionIntent(text)){
                phase=KingmakerPreludePolicy.PHASE_JAMANDI_APPROACH;
                kingmakerRepository.setCampaignStoryPhase(phase,true);
                JSONObject scene=db.getSceneState();
                scene.put("location","Restov — caminho para a Mansão de Lady Jamandi Aldori");
                scene.put("hex_id","");
                scene.put("objective","Chegar à mansão de Lady Jamandi e responder à Convocação de Heróis.");
                db.saveSceneState(scene);
                prefs.edit().putString("kingmaker_atlas_anchor_name","Mansão de Lady Jamandi Aldori, Restov").apply();
                db.addAuditEvent("kingmaker_prologo","Campanha principal iniciada","Jogador escolheu ir à mansão de Lady Jamandi","{}",scene.toString(),true);
                return text+"\n\n"+KingmakerPreludePolicy.directiveForPhase(phase);
            }
            if(KingmakerPreludePolicy.isMansionPhase(phase)){
                String next=KingmakerPreludePolicy.nextMansionPhaseForAction(phase,text);
                if(!next.equals(phase)){
                    boolean expedition=KingmakerPreludePolicy.PHASE_STOLEN_LANDS_EXPEDITION.equals(next);
                    kingmakerRepository.setCampaignStoryPhase(next,true);
                    phase=next;
                    if(expedition)prepareStolenLandsDepartureAtlas();
                }
            }
            String directive=KingmakerPreludePolicy.directiveForPhase(phase);
            return directive.length()==0?text:(text+"\n\n"+directive);
        }catch(Exception error){AppLog.w("KingmakerPrelude","Falha ao atualizar fase narrativa; preservando ação original.",error);return text;}
    }

    private void continueKingmakerMansionFromUi(){
        if(kingmakerRepository==null){navigate("Mestre IA");return;}
        try{
            String phase=kingmakerRepository.campaignStoryPhase();
            if(KingmakerPreludePolicy.PHASE_JAMANDI_ATTACK.equals(phase)){
                if(db.getCombatState().optInt("running",0)==1){toast("Conclua o encontro atual antes de avançar o ataque à mansão.");navigate("Combate");return;}
                if(!prefs.getBoolean("kingmaker_mansion_attack_combat_finished",false)){
                    navigate("Mestre IA");sendAi("Narrador","Continue o ataque à mansão a partir do ponto atual. Ainda não avance para as consequências finais: resolva primeiro as ameaças e encontros que ainda estiverem em curso.","PLAYER_ACTION");return;
                }
                kingmakerRepository.setCampaignStoryPhase(KingmakerPreludePolicy.PHASE_JAMANDI_AFTER_ATTACK,true);
                phase=KingmakerPreludePolicy.PHASE_JAMANDI_AFTER_ATTACK;
            }else{
                String next=KingmakerPreludePolicy.nextMansionPhaseForContinue(phase);
                if(!next.equals(phase)){kingmakerRepository.setCampaignStoryPhase(next,true);phase=next;}
            }
            navigate("Mestre IA");
            sendAi("Narrador","Continue o arco da Convocação de Heróis exatamente do marco persistido agora. Não resuma nem salte acontecimentos futuros.\n\n"+KingmakerPreludePolicy.directiveForPhase(phase),"PLAYER_ACTION");
        }catch(Exception error){toast("Kingmaker: "+safeMessage(error));}
    }

    private void markKingmakerMansionCombatStartedIfNeeded(){
        try{if(kingmakerRepository!=null&&KingmakerPreludePolicy.PHASE_JAMANDI_ATTACK.equals(kingmakerRepository.campaignStoryPhase()))
            prefs.edit().putBoolean("kingmaker_mansion_attack_combat_started",true).putBoolean("kingmaker_mansion_attack_combat_finished",false).apply();}
        catch(Exception ignored){}
    }
    private void markKingmakerMansionCombatFinishedIfNeeded(){
        try{if(kingmakerRepository!=null&&KingmakerPreludePolicy.PHASE_JAMANDI_ATTACK.equals(kingmakerRepository.campaignStoryPhase())
                &&prefs.getBoolean("kingmaker_mansion_attack_combat_started",false))
            prefs.edit().putBoolean("kingmaker_mansion_attack_combat_finished",true).apply();}
        catch(Exception ignored){}
    }

    private void prepareStolenLandsDepartureAtlas(){
        try{
            JSONObject map=db.getMapState();String packageId=map.optString("map_package_id","");
            if(packageId.length()>0&&db.isMapPackageUsable(packageId)){
                JSONObject oleg=db.describeCatalogedAdventureStart(packageId,"H_OLEG");
                if(oleg.length()>0)db.saveMapTravelState(false,"H_OLEG","[]","Kingmaker — expedição às Terras Roubadas");
            }
            JSONObject scene=db.getSceneState();
            scene.put("location","Estrada ao sul de Restov — rumo às Terras Roubadas");
            scene.put("hex_id","");
            scene.put("objective","Viajar às Terras Roubadas; o Atlas só fixa H_OLEG quando a chegada for estabelecida na ficção.");
            db.saveSceneState(scene);
            prefs.edit().putString("kingmaker_atlas_mode","stolen_lands").putString("kingmaker_atlas_anchor_name","Estrada ao sul de Restov — rumo às Terras Roubadas").apply();
            db.addAuditEvent("kingmaker_prologo","Expedição iniciada","Restov → Terras Roubadas; H_OLEG é destino canônico, não teleporte","{}",scene.toString(),true);
        }catch(Exception error){AppLog.w("KingmakerPrelude","Não foi possível preparar o destino do Atlas; a ficção continuará sem teleporte.",error);}
    }

    private void startJamandiMansionFromUi(){
        try{
            if(kingmakerRepository!=null&&KingmakerPreludePolicy.isRestovPhase(kingmakerRepository.campaignStoryPhase()))
                kingmakerRepository.setCampaignStoryPhase(KingmakerPreludePolicy.PHASE_JAMANDI_APPROACH,true);
            prefs.edit().putString("kingmaker_atlas_anchor_name","Mansão de Lady Jamandi Aldori, Restov").apply();
        }catch(Exception error){AppLog.w("KingmakerPrelude","Não foi possível persistir a ida à mansão antes da narração.",error);}
        navigate("Mestre IA");
        sendAi("Narrador","O jogador decide ir agora à mansão de Lady Jamandi Aldori para responder à convocação. Narre a aproximação e a entrada naturalmente; não resuma acontecimentos futuros.\n\n"+KingmakerPreludePolicy.directiveForPhase(KingmakerPreludePolicy.PHASE_JAMANDI_APPROACH),"PLAYER_ACTION");
    }

    private boolean isEligibleAdventureStartHex(String hexId){
        if(hexId==null||hexId.trim().length()==0)return false;JSONObject state=db.getMapState();String packageId=state.optString("map_package_id","");return packageId.length()>0&&db.isCatalogedAdventureStartHex(packageId,hexId.trim());
    }

    private JSONObject nearestCatalogedAdventureStart(String touchedHex){
        JSONObject state=db.getMapState();String packageId=state.optString("map_package_id","");if(packageId.length()==0)return new JSONObject();
        List<JSONObject> nearest=db.findNearestAdventureStartCandidates(packageId,touchedHex,1);return nearest.isEmpty()?new JSONObject():nearest.get(0);
    }

    

    private void explicitRepairActiveAtlas(){
        if(adventureStartCatalogMigrationRunning){toast("O reparo do Atlas já está em execução.");return;}
        final String packageId=db.getMapState().optString("map_package_id","");if(packageId.length()==0){toast("Nenhum Atlas ativo.");return;}
        adventureStartCatalogMigrationRunning=true;setStatus("Reparando somente posições verificáveis do Atlas…");
        AppExecutors.io().execute(new Runnable(){public void run(){
            final int before=db.countMapPositionedLocations(packageId);
            final int seeded=db.applyBundledResolvedLocations(packageId);
            final int migrated=db.migrateConfirmedLocationPlacementsToPackage(packageId);
            final int after=db.countMapPositionedLocations(packageId);
            ui.post(new Runnable(){public void run(){adventureStartCatalogMigrationRunning=false;screenCache.remove("Mapa");screenCacheTime.remove("Mapa");db.addAuditEvent("mapa","Reparo explícito do Atlas 5.0",before+" → "+after+" posições • "+seeded+" embarcadas verificadas • "+migrated+" legadas recuperadas","{}","{}",true);setStatus("Atlas reparado: "+after+" locais posicionados; nenhuma coordenada foi inventada.");if("Mapa".equals(currentScreen))showMap();}});
        }});
    }

    private String adventureStartPointLabel(JSONObject point){
        if(point==null||point.length()==0)return "ponto catalogado";
        String name=point.optString("start_location_name","").trim();String type=formatLocationTypePt(point.optString("start_location_type","")).trim();String terrain=terrainPt(point.optString("terrain_primary","")).trim();String label=name.length()>0?name:(terrain.length()>0?terrain:"ponto catalogado");
        if(type.length()>0&&name.length()>0)label+=" — "+type;return label;
    }

    private void confirmCatalogedAdventureStart(final String chosenHex,final String touchedHex,final boolean resetStart){
        final JSONObject point=db.describeCatalogedAdventureStart(db.getMapState().optString("map_package_id",""),chosenHex);if(point.length()==0){toast("O catálogo mudou; escolha outro ponto.");return;}
        String label=adventureStartPointLabel(point);String message;
        if(touchedHex!=null&&touchedHex.length()>0&&!touchedHex.equalsIgnoreCase(chosenHex))message="O hex "+touchedHex+" não possui conteúdo catalogado para uma abertura. O ponto catalogado mais próximo é "+label+", no hex "+chosenHex+". Iniciar ali?";
        else message=label+" • hex "+chosenHex+". Este ponto catalogado será fixado como início. Em seguida o aplicativo consultará as regras e escreverá a primeira cena ancorada nele.";
        new AlertDialog.Builder(MainActivity.this).setTitle("Iniciar neste ponto catalogado?").setMessage(message).setNegativeButton("OUTRO PONTO",null).setNeutralButton("CANCELAR INÍCIO",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){pendingAdventureStartFromMap=false;pendingAdventureStartReset=false;setStatus("Início da aventura cancelado.");}}).setPositiveButton("CONFIRMAR E INICIAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){pendingAdventureStartFromMap=false;pendingAdventureStartReset=false;launchAdventure(resetStart,chosenHex);}}).show();
    }

    private JSONObject prepareAdventureStartingPoint(String requestedHex)throws Exception{
        JSONObject state=db.getMapState();String packageId=state.optString("map_package_id","");String requested=requestedHex==null?"":requestedHex.trim();
        if(packageId.length()==0){return new JSONObject().put("selection_mode","narrative_only").put("atlas_status","pending").put("map_grounded",false).put("hex_id","").put("start_kind","unmapped").put("start_location_name",NarrativeLocationNaturalizer.currentNarrativeLabel(db));}
        int reconciled=db.applyBundledResolvedLocations(packageId);if(reconciled>0)db.addAuditEvent("atlas","Posições catalogadas reconciliadas",String.valueOf(reconciled),"{}","{}",true);
        List<JSONObject> candidates=db.listAdventureStartHexes(packageId,"",1000);JSONObject chosen=new JSONObject();
        if(requested.length()>0)chosen=db.describeCatalogedAdventureStart(packageId,requested);
        if(chosen.length()==0&&!candidates.isEmpty()){String historyKey="recent_adventure_start_points_"+activeWorldProfile();chosen=AdventureStartSelector.choose(candidates,prefs.getString(historyKey,"[]"),System.nanoTime()^UUID.randomUUID().getMostSignificantBits());if(chosen.length()>0){chosen.put("selection_mode","weighted_random");prefs.edit().putString(historyKey,AdventureStartSelector.remember(prefs.getString(historyKey,"[]"),chosen)).apply();}}
        if(chosen.length()==0){return new JSONObject().put("selection_mode","narrative_only").put("atlas_status","catalog_pending").put("map_grounded",false).put("hex_id","").put("start_kind","unmapped").put("start_location_name",NarrativeLocationNaturalizer.currentNarrativeLabel(db));}
        chosen.put("map_grounded",true);String hex=chosen.optString("hex_id","");if(hex.length()==0)return new JSONObject().put("selection_mode","narrative_only").put("atlas_status","identity_missing").put("map_grounded",false).put("hex_id","").put("start_kind","unmapped");
        String previous=state.optString("current_hex_id","");String reveals=new JSONObject().put("hexIds",new JSONArray().put(hex)).put("points",new JSONArray()).toString();db.saveMapPackageState(state.optString("image_uri"),state.optString("overlay_uri"),state.optString("manifest_json"),packageId,hex,state.optInt("overlay_visible",1)==1,reveals,state.optString("grid_type","Quadrada"),(float)state.optDouble("grid_size",64),state.optInt("fog_enabled",0)==1,(float)state.optDouble("token_x",.5),(float)state.optDouble("token_y",.5),(float)state.optDouble("scale",1),(float)state.optDouble("offset_x",0),(float)state.optDouble("offset_y",0));db.saveMapTravelState(true,"","[]","Jogador");prefs.edit().putString("last_adventure_start_hex_"+activeWorldProfile(),hex).apply();db.addAuditEvent("atlas","Ponto inicial PF2e definido",previous+" → "+hex,"{}",chosen.toString(),true);return chosen;
    }

    private String buildAdventureStartContext(JSONObject point){
        if(point==null||!point.optBoolean("map_grounded",false)||point.optString("hex_id","").length()==0){String known=NarrativeLocationNaturalizer.currentNarrativeLabel(db);if(known==null||known.trim().length()==0)known="esta região";return "ATLAS AINDA NÃO VINCULADO OU NÃO CATALOGADO. A aventura DEVE começar normalmente. Referência narrativa atual: "+known+". Não invente como fatos cartográficos nomes de rios, estradas, montanhas, cidades, distâncias, hexes ou POIs. Crie profundidade por situação, pessoas, sensações, arquitetura local não-georreferenciada, objetivos e consequências; marque geografia precisa como desconhecida até o Atlas fornecer evidência. ";}
        String hex=point.optString("hex_id","");String kind=point.optString("start_kind","");StringBuilder out=new StringBuilder("PONTO INICIAL CATALOGADO: hex ").append(hex).append(". ");JSONObject state=db.getMapState();String packageId=state.optString("map_package_id","");boolean localWater=hasConfirmedWaterwayNear(packageId,hex);String hydro=confirmedWaterwayContext(packageId,hex);
        if("location".equals(kind)){String name=cleanJsonText(point.optString("start_location_name"),"Local catalogado"),type=formatLocationTypePt(point.optString("start_location_type")),region=cleanJsonText(point.optString("start_location_region"),"");String description="";try{JSONObject raw=new JSONObject(point.optString("start_location_raw","{}"));description=cleanJsonText(raw.optString("description"),cleanJsonText(raw.optString("descricao_linha_1"),""));}catch(Exception ignored){AppLog.ignored("AdventureStart","Descrição catalogada ausente.",ignored);}description=sanitizeCatalogGeography(description,localWater);out.append("LOCAL: ").append(name).append("; categoria: ").append(type.length()>0?type:"ponto de interesse");if(region.length()>0)out.append("; região: ").append(region);out.append(". ");if(description.length()>0)out.append("REFERÊNCIA DE LORE: ").append(promptTail(description,520)).append(". ");}else{String terrain=terrainPt(point.optString("terrain_primary",""));out.append("TERRENO CONFIRMADO: ").append(terrain.length()>0?terrain:"terreno revisado").append(". ");}
        if(localWater)out.append("HIDROGRAFIA CONFIRMADA: ").append(hydro).append(". ");else out.append("HIDROGRAFIA LOCAL: nenhuma confirmada no hex atual ou adjacentes; não invente cursos d'água como fatos. ");out.append("PRECEDÊNCIA ESPACIAL: Atlas e manifesto > catálogo/lore > inferência. Nunca trate inferência como geografia confirmada. ");return out.toString();
    }

    private boolean hasConfirmedWaterwayNear(String packageId,String hexId){return confirmedWaterwayContext(packageId,hexId).length()>0;}
    private String confirmedWaterwayContext(String packageId,String hexId){
        if(packageId==null||packageId.length()==0||hexId==null||hexId.length()==0)return "";LinkedHashSet<String> found=new LinkedHashSet<String>();ArrayList<String> ids=new ArrayList<String>();ids.add(hexId);JSONObject state=db.getMapState();MapManifestGeometry geometry=mapGeometryFromState(state);List<String> neighbors=geometry==null?flatTopNeighbors(hexId,295,165):geometry.neighbors(hexId);ids.addAll(neighbors);
        for(String id:ids){JSONObject hex=db.getMapHex(packageId,id);if(hex.length()==0||!isReliableMapHex(hex))continue;try{JSONArray routes=new JSONArray(hex.optString("waterways_json","[]"));for(int i=0;i<routes.length();i++){Object raw=routes.opt(i);if(raw instanceof JSONObject){JSONObject route=(JSONObject)raw;if(route.optBoolean("needsReview",false))continue;String status=cleanJsonText(route.optString("status"),"").toLowerCase(Locale.US);if(status.contains("review")||status.contains("candidate")||status.contains("approx"))continue;String name=cleanJsonText(route.optString("name"),"");String kind=routeKindPt(cleanJsonText(route.optString("kind"),""));String label=name.length()>0?name:kind;if(label.length()>0)found.add(label+" ["+id+"]");}else{String label=cleanJsonText(String.valueOf(raw),"");if(label.length()>0&&!"null".equalsIgnoreCase(label))found.add(label+" ["+id+"]");}}}catch(Exception ignored){AppLog.ignored("AdventureStart","Hidrografia local inválida.",ignored);}}
        StringBuilder b=new StringBuilder();for(String item:found){if(b.length()>0)b.append(", ");b.append(item);if(b.length()>280)break;}return b.toString();
    }
    private String sanitizeCatalogGeography(String description,boolean localWater){
        String d=cleanJsonText(description,"");if(d.length()==0||localWater)return d;StringBuilder keep=new StringBuilder();for(String sentence:d.split("(?<=[.!?])\\s+")){String n=sentence.toLowerCase(new Locale("pt","BR"));boolean hydro=n.matches(".*\\b(rio|rios|riacho|riachos|c[oó]rrego|c[oó]rregos|canal|canais|margem|margens|costa|costeiro|costeira|lago|lagos|mar|mares|delta|estu[aá]rio|porto|portos|doca|docas|navega[cç][aã]o|chionthar)\\b.*");if(hydro)continue;if(keep.length()>0)keep.append(' ');keep.append(sentence.trim());}return cleanJsonText(keep.toString(),"");
    }



    

    

    

    
    

