    private void showCharacterSheetDialog(final JSONObject character){
        final JSONObject s=parseLooseJson(character.optString("sheet_json","{}"));ScrollView scroll=new ScrollView(this);LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(16),dp(10),dp(16),dp(24));
        body.addView(text(character.optString("name","Personagem"),24,GOLD,true));body.addView(text(character.optString("species")+(s.optString("heritage","").length()>0?" • "+s.optString("heritage"):"")+" • "+character.optString("class_name")+" "+character.optInt("level",1),14,MUTED,false));
        addSheetSection(body,"NÚCLEO PF2E","PV "+character.optInt("hp")+"/"+character.optInt("max_hp")+" • CA "+character.optInt("ac")+" • Percepção "+signedModifier(pathfinderRules.initiativeBonus(character,"Percepção"))+"\n3 ações + reação • quatro graus de sucesso • MAP -5/-10 (ou -4/-8 ágil)");
        addSheetSection(body,"MODIFICADORES","FOR "+signedModifier(character.optInt("str"))+" • DES "+signedModifier(character.optInt("dex"))+" • CON "+signedModifier(character.optInt("con"))+"\nINT "+signedModifier(character.optInt("int_score"))+" • SAB "+signedModifier(character.optInt("wis"))+" • CAR "+signedModifier(character.optInt("cha")));
        JSONObject ranks=s.optJSONObject("skill_ranks");if(ranks!=null)addSheetSection(body,"PERÍCIAS E PROFICIÊNCIAS",ranks.toString());addSheetSection(body,"ANTECEDENTE",character.optString("background"));addSheetSection(body,"EQUIPAMENTO",character.optString("equipment"));addSheetSection(body,"MAGIAS / HABILIDADES",character.optString("spells"));addSheetSection(body,"IDENTIDADE VISUAL",character.optString("visual_description"));addSheetSection(body,"PERSONALIDADE",s.optString("personality"));addSheetSection(body,"NOTAS",character.optString("notes"));
        final JSONObject merged=mergeVisualCharacter(character,s);try{merged.put("system","pathfinder_2e").put("rules_profile",Pathfinder2eRulesEngine.PROFILE).put("schema","braseiro_pf2_character_v1");}catch(Exception ignored){AppLog.ignored("CharacterSheet","Falha tolerada ao marcar perfil PF2e.",ignored);}Button export=button("EXPORTAR FICHA JSON",GOLD);export.setTextColor(Color.BLACK);export.setOnClickListener(new View.OnClickListener(){public void onClick(View v){beginCharacterExport(merged,character.optInt("active",1)==1);}});body.addView(export);Button prompt=button("PROMPT VISUAL GEMINI",PANEL2);prompt.setOnClickListener(new View.OnClickListener(){public void onClick(View v){sharePromptToGeminiForCharacter(PathfinderTokenPromptBuilder.build(merged,NarrativeLocationNaturalizer.currentNarrativeLabel(db)),character.optLong("id"));}});body.addView(prompt);scroll.addView(body);new AlertDialog.Builder(this).setTitle("Ficha Pathfinder 2e").setView(scroll).setPositiveButton("Fechar",null).show();
    }

    

    
    
    
    
    
    
    
    
