    private JSONObject pf2CombatState(JSONObject combatant){try{JSONObject r=new JSONObject(combatant==null?"{}":combatant.optString("resources_json","{}"));if(!r.has("dying"))r.put("dying",0);if(!r.has("wounded"))r.put("wounded",0);if(!r.has("doomed"))r.put("doomed",0);return r;}catch(Exception e){return new JSONObject();}}
    private String pf2CombatSummary(JSONObject c){JSONObject p=pf2CombatState(c);StringBuilder x=new StringBuilder("PV ").append(c.optInt("hp")).append('/').append(c.optInt("max_hp"));if(c.optInt("temp_hp")>0)x.append(" +").append(c.optInt("temp_hp")).append(" temp");x.append(" • CA ").append(c.optInt("ac"));if(c.optString("conditions").trim().length()>0)x.append(" • ").append(c.optString("conditions"));if(p.optInt("dying",0)>0)x.append(" • dying ").append(p.optInt("dying"));if(p.optInt("wounded",0)>0)x.append(" • wounded ").append(p.optInt("wounded"));if(p.optInt("doomed",0)>0)x.append(" • doomed ").append(p.optInt("doomed"));if(p.optString("persistent_damage","").trim().length()>0)x.append(" • dano persistente: ").append(p.optString("persistent_damage"));if(c.optInt("reaction_used")==1)x.append(" • reação usada");return x.toString();}


    private void showNarrator(){
        sanitizeReservedNpcAliases();
        if(prefs!=null&&prefs.getBoolean("master_screen_safe_mode",false)){showNarratorRecovery(null);return;}
        try{showNarratorFull();}
        catch(Throwable error){
            AppLog.e("MestreIA","Falha ao montar a tela completa do Mestre IA; abrindo modo seguro funcional.",error);
            if(prefs!=null)prefs.edit().putBoolean("master_screen_safe_mode",true).apply();
            showNarratorRecovery(error);
        }
    }

