    private void addMasterSupportCard(final LinearLayout parent){
        try{
            JSONArray citations=lastRagCitations==null?new JSONArray():copyJsonArray(lastRagCitations);
            if(citations.length()==0)try{citations=new JSONArray(prefs.getString("last_rag_citations","[]"));}catch(Exception ignored){citations=new JSONArray();}
            if(lastMasterSupport==null||lastMasterSupport.length()==0){
                lastMasterSupport=MasterSupportPanelEngine.build(new JSONObject(),activeRuleRetrieval,citations,db.getSceneState(),safeActiveCharacters(),currentOptions,pendingTest,lastPrompt);
            }
            final LinearLayout help=card();int helpAccent=Color.rgb(96,200,230);help.setBackground(makeBg(Color.rgb(19,49,73),helpAccent,12));
            help.addView(text("AJUDA DO MESTRE — FORA DA NARRATIVA",15,helpAccent,true));
            help.addView(text("Nada escrito neste quadro vira fala, ação, passagem de tempo ou consequência da aventura.",11,Color.rgb(190,225,238),false));
            String supportQuestion=lastMasterSupport.optString("last_question","");String supportAnswer=lastMasterSupport.optString("last_answer","");if(supportAnswer.length()>0){help.addView(text("ÚLTIMA PERGUNTA",11,helpAccent,true));if(supportQuestion.length()>0)help.addView(text(supportQuestion,12,Color.rgb(214,231,238),false));help.addView(text("RESPOSTA DO MESTRE",12,helpAccent,true));TextView immediateAnswer=text(supportAnswer,14,Color.WHITE,false);immediateAnswer.setTextIsSelectable(true);immediateAnswer.setLineSpacing(0,1.12f);help.addView(immediateAnswer);}

            String sceneSummary=lastMasterSupport.optString("scene_summary","");if(sceneSummary.length()>0){help.addView(text("CENA AGORA",11,helpAccent,true));help.addView(text(sceneSummary,13,Color.WHITE,false));}
            String did=lastMasterSupport.optString("what_happened","");if(did.length()>0){help.addView(text("O QUE O SISTEMA FEZ",11,helpAccent,true));help.addView(text(did,13,Color.WHITE,false));}
            help.addView(text("REGRAS",11,helpAccent,true));
            String rules=lastMasterSupport.optString("rules_explanation",prefs.getString("last_manual_context","Nenhuma explicação mecânica registrada."));help.addView(text(rules,13,Color.WHITE,false));
            int evidence=lastMasterSupport.optInt("evidence_count",0);String ruleStatus=lastMasterSupport.optBoolean("rules_searched",false)?(evidence>0?"✓ Manuais consultados • "+evidence+" fonte(s) pertinente(s)":"✓ Consulta executada • nenhuma passagem pertinente; mecânicas bloqueadas"):"Nenhuma consulta mecânica necessária nesta batida";help.addView(text(ruleStatus,11,evidence>0?Color.rgb(151,235,184):Color.rgb(240,211,132),true));

            JSONArray skills=lastMasterSupport.optJSONArray("skill_suggestions");if(skills!=null&&skills.length()>0){help.addView(text("PERÍCIAS / ABORDAGENS POSSÍVEIS",11,helpAccent,true));for(int i=0;i<skills.length();i++){JSONObject sk=skills.optJSONObject(i);if(sk==null)continue;String best=sk.optString("best_character","");String line="• "+sk.optString("skill","Abordagem")+(best.length()>0?" — melhor ficha: "+best:"")+"\n  "+sk.optString("why","");help.addView(text(line,12,Color.WHITE,false));}help.addView(text("São possibilidades opcionais. O Mestre só pede rolagem quando houver incerteza, consequência e competência relevante.",11,Color.rgb(190,225,238),false));}

            JSONArray sources=lastMasterSupport.optJSONArray("sources");if(sources!=null&&sources.length()>0){help.addView(text("FONTES CONSULTADAS",11,helpAccent,true));for(int i=0;i<sources.length()&&i<4;i++){JSONObject src=sources.optJSONObject(i);if(src==null)continue;String line="• "+src.optString("book","Manual")+(src.optInt("page",0)>0?" • p. "+src.optInt("page"):"");help.addView(text(line,11,Color.rgb(190,225,238),false));}}

            help.addView(text("PERGUNTAR AO MESTRE SEM AGIR",12,helpAccent,true));
            final EditText question=input("Ex.: Quem está na cena? Qual a distância até a porta? O que meu personagem sabe? Que perícias poderiam servir?","",true);question.setMinLines(2);question.setEnabled(!aiBusy);help.addView(question);
            LinearLayout quick=new LinearLayout(this);quick.setOrientation(LinearLayout.HORIZONTAL);Button who=smallButton("QUEM ESTÁ AQUI?",PANEL2),where=smallButton("POSIÇÃO E DISTÂNCIAS",PANEL2);who.setTextSize(10);where.setTextSize(10);who.setEnabled(!aiBusy);where.setEnabled(!aiBusy);who.setOnClickListener(new View.OnClickListener(){public void onClick(View v){sendMasterSideQuestion("Quem está presente nesta cena agora, incluindo heróis e NPCs? O que cada um está fazendo e onde está, conforme o estado já estabelecido?");}});where.setOnClickListener(new View.OnClickListener(){public void onClick(View v){sendMasterSideQuestion("Descreva a posição relativa dos presentes, as saídas visíveis e as distâncias já estabelecidas. Onde não houver medida exata no estado, diga claramente que ela ainda não foi fixada.");}});quick.addView(who,new LinearLayout.LayoutParams(0,dp(44),1));quick.addView(where,new LinearLayout.LayoutParams(0,dp(44),1));help.addView(quick);
            Button ask=button(aiBusy&&masterSideQueryActive?"RESPONDENDO...":"PERGUNTAR SEM AVANÇAR A CENA",helpAccent);ask.setTextColor(Color.rgb(8,24,36));ask.setEnabled(!aiBusy);ask.setOnClickListener(new View.OnClickListener(){public void onClick(View v){String q=question.getText().toString().trim();if(q.length()==0){toast("Escreva uma pergunta ao Mestre.");return;}sendMasterSideQuestion(q);}});help.addView(ask);
            parent.addView(help);
        }catch(Throwable error){AppLog.e("MasterSupportPanel","Falha ao montar o quadro auxiliar.",error);LinearLayout fallback=card();fallback.setBackground(makeBg(Color.rgb(19,49,73),Color.rgb(96,200,230),12));fallback.addView(text("AJUDA DO MESTRE INDISPONÍVEL",13,Color.WHITE,true));fallback.addView(text("A narrativa continua isolada. O quadro auxiliar encontrou: "+safeUiError(error),11,Color.WHITE,false));parent.addView(fallback);}
    }

    private void sendMasterSideQuestion(String rawQuestion){
        String question=rawQuestion==null?"":rawQuestion.trim();if(question.length()==0){toast("Escreva uma pergunta ao Mestre.");return;}if(aiBusy){toast("Aguarde a resposta atual.");return;}
        masterSideQueryActive=true;masterSideQueryText=question;masterSidePreviousAiMode=lastAiMode;masterSidePreviousPrompt=lastPrompt;masterSidePreviousUsedRag=lastAiUsedRag;masterSidePreviousCitations=copyJsonArray(lastRagCitations);masterSidePreviousRuleRetrieval=copyJsonObject(activeRuleRetrieval);masterSidePreviousManuals=copyJsonArray(lastAiManuals);masterSidePreviousManualContext=prefs.getString("last_manual_context","");masterSidePreviousSourceAudit=prefs.getString("last_source_audit","{}");
        sendAi("Narrador",question,"GM_HELP");
    }

    private void restoreAfterMasterSideQuery(){
        lastAiMode=masterSidePreviousAiMode;lastPrompt=masterSidePreviousPrompt;lastAiUsedRag=masterSidePreviousUsedRag;lastRagCitations=copyJsonArray(masterSidePreviousCitations);activeRuleRetrieval=copyJsonObject(masterSidePreviousRuleRetrieval);lastAiManuals=copyJsonArray(masterSidePreviousManuals);
        SharedPreferences.Editor edit=prefs.edit().putString("last_manual_context",masterSidePreviousManualContext).putString("last_source_audit",masterSidePreviousSourceAudit).putString("last_ai_response_mode",lastAiMode);if(lastRagCitations.length()>0)edit.putString("last_rag_citations",lastRagCitations.toString());else edit.remove("last_rag_citations");edit.apply();
        masterSideQueryActive=false;masterSideQueryText="";activeMasterPlan=null;if(masterOrchestrator!=null)masterOrchestrator.setActivePlanForValidation(null);
    }

    private void showMasterSideAnswerDialog(String question,String answer){
        String q=question==null?"":question.trim();String a=answer==null?"":answer.trim();if(a.length()==0)a="O Mestre não devolveu texto para esta pergunta.";
        if(!canShowDialog())return;
        showReadableAlert(new AlertDialog.Builder(this).setTitle("Resposta do Mestre — cena congelada").setMessage((q.length()>0?("PERGUNTA\n"+q+"\n\n"):"")+"RESPOSTA\n"+a+"\n\nNada nesta resposta avançou tempo, NPCs, mapa, combate ou Mundo Vivo.").setPositiveButton("FECHAR",null));
    }

