    private void addSceneStatusStrip(LinearLayout parent){
        JSONObject scene=db.getSceneState();
        int day=Math.max(1,scene.optInt("day_number",1));
        String weather=scene.optString("weather","Céu limpo").trim();
        if(weather.length()==0)weather="Céu limpo";
        SceneTemporalResolver.Result temporal=SceneTemporalResolver.resolve(
                scene.optString("time_of_day","Manhã"),scene.optDouble("clock_hour",9d),scene.has("clock_hour"),
                "",0d,false,lastNarration,scene.optString("lighting",""));
        String time=temporal.label;
        try{
            if(Math.abs(scene.optDouble("clock_hour",-99d)-temporal.hour)>.01d||!time.equals(scene.optString("time_of_day"))||!temporal.lighting.equals(scene.optString("lighting"))){
                scene.put("clock_hour",temporal.hour);scene.put("time_of_day",time);scene.put("lighting",temporal.lighting);db.saveSceneState(scene);
            }
        }catch(Exception error){AppLog.w("SceneClock","Não foi possível reparar o relógio da cena.",error);}

        LinearLayout strip=card();
        strip.setOrientation(LinearLayout.HORIZONTAL);
        strip.setGravity(Gravity.CENTER);
        strip.addView(sceneStatusCell(weatherIcon(weather),shortWeatherLabel(weather)),new LinearLayout.LayoutParams(0,dp(72),1));
        strip.addView(sceneStatusCell("◈","DIA "+day),new LinearLayout.LayoutParams(0,dp(72),1));
        strip.addView(sceneStatusCell(timeIcon(time),timeLabel(time)),new LinearLayout.LayoutParams(0,dp(72),1));
        parent.addView(strip);
    }

    private LinearLayout sceneStatusCell(String icon,String label){
        LinearLayout cell=new LinearLayout(this);
        cell.setOrientation(LinearLayout.VERTICAL);
        cell.setGravity(Gravity.CENTER);
        TextView iconView=text(icon,25,GOLD,true);
        iconView.setGravity(Gravity.CENTER);
        TextView labelView=text(label,10,TEXT,true);
        labelView.setGravity(Gravity.CENTER);
        labelView.setMaxLines(1);
        labelView.setEllipsize(TextUtils.TruncateAt.END);
        cell.addView(iconView,new LinearLayout.LayoutParams(-1,dp(38)));
        cell.addView(labelView,new LinearLayout.LayoutParams(-1,dp(24)));
        return cell;
    }

    private String weatherIcon(String weather){
        String w=weather==null?"":weather.toLowerCase(Locale.ROOT);
        if(w.contains("tempest")||w.contains("trovo")||w.contains("raio"))return "⚡";
        if(w.contains("chuva")||w.contains("garoa"))return "☂";
        if(w.contains("neve")||w.contains("granizo"))return "❄";
        if(w.contains("névo")||w.contains("nevo")||w.contains("bruma")||w.contains("neblina"))return "≋";
        if(w.contains("nuv")||w.contains("encoberto"))return "☁";
        if(w.contains("vento")||w.contains("vendaval"))return "↝";
        return "☀";
    }

    private String shortWeatherLabel(String weather){
        String clean=weather==null?"":weather.trim();
        if(clean.length()==0)return "CÉU LIMPO";
        return clean.toUpperCase(new Locale("pt","BR"));
    }

    private String timeIcon(String time){
        String t=time==null?"":time.toLowerCase(Locale.ROOT);
        if(t.contains("noite")||t.contains("madrugada"))return "☾";
        if(t.contains("amanhe")||t.contains("alvor"))return "◐";
        if(t.contains("entard")||t.contains("crepúsc")||t.contains("crepusc"))return "◑";
        return "☀";
    }

    private String timeLabel(String time){
        String t=time==null?"":time.trim();
        if(t.length()==0)return "DIA";
        return t.toUpperCase(new Locale("pt","BR"));
    }

    private void initializeSceneClock(){
        JSONObject scene=db.getSceneState();
        try{
            scene.put("day_number",Math.max(1,scene.optInt("day_number",1)));
            SceneTemporalResolver.Result temporal=SceneTemporalResolver.resolve(
                    scene.optString("time_of_day","Manhã"),scene.optDouble("clock_hour",9d),scene.has("clock_hour"),
                    "",0d,false,"",scene.optString("lighting",""));
            scene.put("clock_hour",temporal.hour);scene.put("time_of_day",temporal.label);scene.put("lighting",temporal.lighting);
            if(scene.optString("weather").trim().length()==0)scene.put("weather","Céu limpo");
            JSONObject map=db.getMapState();
            if(scene.optString("hex_id").trim().length()==0&&map.optString("current_hex_id").trim().length()>0)scene.put("hex_id",map.optString("current_hex_id"));
            db.saveSceneState(scene);
        }catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}
    }

    private void resetSceneClock(){
        JSONObject scene=new JSONObject();
        try{
            scene.put("day_number",1);
            scene.put("time_of_day","Manhã");
            scene.put("clock_hour",9d);
            scene.put("weather","Céu limpo");
            JSONObject map=db.getMapState();
            scene.put("hex_id",map.optString("current_hex_id"));
            scene.put("location","");
            scene.put("lighting","Luz da manhã");
            scene.put("danger","");
            scene.put("objective","");
            scene.put("present_npcs",new JSONArray());
            scene.put("threats",new JSONArray());
            scene.put("clues",new JSONArray());
            scene.put("pending_consequences",new JSONArray());
            db.saveSceneState(scene);
        }catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}
    }

    

    private boolean advanceSceneHours(double hours){
        if(hours<=0)return true;
        JSONObject scene=db.getSceneState();
        try{
            double currentHour=scene.optDouble("clock_hour",sceneHour(scene.optString("time_of_day","Manhã")));
            double total=currentHour+Math.max(0d,hours);
            int days=(int)Math.floor(total/24d);
            double exact=((total%24d)+24d)%24d;
            scene.put("day_number",Math.max(1,scene.optInt("day_number",1))+days);
            scene.put("clock_hour",exact);
            scene.put("time_of_day",sceneTimeLabel(exact));
            db.saveSceneState(scene);return true;
        }catch(Exception ignored){return false;}
    }

    private static double sceneHour(String label){return SceneTemporalResolver.hourForLabel(label);}
    private static String sceneTimeLabel(double hour){return SceneTemporalResolver.labelForHour(hour);}



