    private JSONArray buildSceneCastPreview(JSONObject envelope){
        JSONArray out=new JSONArray();HashSet<String> seen=new HashSet<String>();if(envelope==null)return out;
        try{
            JSONObject scene=envelope.optJSONObject("scene_state");if(scene!=null){appendPreviewNpcs(out,seen,scene.opt("present_npcs"));appendPreviewNpcs(out,seen,scene.opt("present_npcs_json"));}
            JSONArray updates=envelope.optJSONArray("npc_updates");if(updates!=null)for(int i=0;i<updates.length();i++){JSONObject npc=updates.optJSONObject(i);if(npc==null||npc.optInt("active",1)==0||npc.optBoolean("left_scene",false)||npc.optBoolean("departed",false)||!npc.optBoolean("present",true))continue;appendPreviewNpc(out,seen,npc);}
        }catch(Exception error){AppLog.w("SceneCast","Não foi possível montar a prévia do elenco.",error);}
        return out;
    }

    private void mergeNarratedKnownNpcs(JSONArray out,String narration){
        if(out==null||narration==null||narration.trim().length()==0)return;
        HashSet<String> seen=new HashSet<String>();for(int i=0;i<out.length();i++){JSONObject current=out.optJSONObject(i);if(current!=null)seen.add(normalizeForNameMatch(current.optString("name","")));}
        String haystack=normalizeForNameMatch(narration);
        JSONArray memories=db.listNpcMemories(120);
        for(int i=0;i<memories.length();i++){
            JSONObject npc=memories.optJSONObject(i);if(npc==null||npc.optInt("active",1)==0)continue;String name=npc.optString("name","").trim();if(name.length()<2||SceneEntityGrounding.isNonNpcIdentity(db,db.getSceneState(),name)||seen.contains(normalizeForNameMatch(name)))continue;
            if(!containsNormalizedName(haystack,name))continue;
            try{appendPreviewNpc(out,seen,npc);}catch(Exception error){AppLog.w("SceneCast","Falha ao incluir NPC narrado no painel visual.",error);}
        }
    }

    private void mergeExplicitlyNamedNpcHints(JSONArray out,String narration){
        if(out==null||narration==null||narration.trim().length()==0)return;
        HashSet<String> seen=new HashSet<String>();for(int i=0;i<out.length();i++){JSONObject npc=out.optJSONObject(i);if(npc!=null)seen.add(normalizeForNameMatch(npc.optString("name","")));}
        java.util.Set<String> excluded=SceneEntityGrounding.nonNpcAliases(db,db.getSceneState());
        JSONArray extracted=NarratedNpcExtractor.extract(narration,12,excluded);for(int i=0;i<extracted.length();i++){
            JSONObject npc=extracted.optJSONObject(i);if(npc==null)continue;String key=normalizeForNameMatch(npc.optString("name",""));if(key.length()<2||seen.contains(key))continue;
            try{
                // A narração aceita pode provar presença. NPC nomeado permanece na cena
                // e recebe identidade persistente; grupos/figurantes anônimos continuam
                // transitórios para não poluir a memória mundial.
                npc.put("narration_only",true);
                if(npc.optBoolean("anonymous",false)||npc.optBoolean("group",false))npc.put("transient",true);
                else npc.remove("transient");
                appendPreviewNpc(out,seen,npc);
            }catch(Exception error){AppLog.w("SceneCast","Falha ao registrar NPC explícito da narração.",error);}
        }
    }

    private void synchronizeVisualSceneCast(){
        if(currentSceneCastPreview==null||currentSceneCastPreview.length()==0)return;
        try{
            JSONObject scene=db.getSceneState();JSONArray merged=new JSONArray();HashSet<String> seen=new HashSet<String>();appendPersistentSceneNpcs(merged,seen,scene.opt("present_npcs"));appendPersistentSceneNpcs(merged,seen,scene.opt("present_npcs_json"));
            for(int i=0;i<currentSceneCastPreview.length();i++){JSONObject npc=currentSceneCastPreview.optJSONObject(i);if(npc!=null)appendPreviewNpc(merged,seen,npc);}
            scene.put("present_npcs",merged);if(scene.optString("hex_id","").length()==0)scene.put("hex_id",db.getMapState().optString("current_hex_id",""));db.saveSceneState(scene);
            String where=scene.optString("location",NarrativeLocationNaturalizer.currentNarrativeLabel(db));String hex=scene.optString("hex_id","");
            for(int i=0;i<currentSceneCastPreview.length();i++){
                JSONObject visible=currentSceneCastPreview.optJSONObject(i);if(visible==null)continue;String name=visible.optString("name","").trim();if(name.length()==0||isReservedSceneIdentity(name)||SceneEntityGrounding.isNonNpcIdentity(db,scene,name))continue;
                // Figurantes derivados apenas da prosa pertencem à cena, não à memória mundial.
                // Isso mantém a barra fiel sem criar NPCs permanentes chamados "Velho" ou "Corredores".
                if(visible.optBoolean("transient",false)||visible.optBoolean("anonymous",false))continue;
                JSONObject memory=db.findNpcMemoryByName(name);JSONObject update=memory.length()>0?new JSONObject(memory.toString()):new JSONObject();update.put("name",name).put("active",1).put("hex_id",hex).put("last_seen",where);
                String role=visible.optString("role","").trim(),summary=visible.optString("summary","").trim(),visual=visible.optString("visual_description","").trim();if(summary.length()==0&&role.length()>0)summary=role+" presente na cena atual.";if(summary.length()>0)update.put("summary",summary);if(visual.length()>0)update.put("visual_description",visual);db.upsertNpcMemory(update);
            }
        }catch(Exception error){AppLog.w("SceneCast","Não foi possível sincronizar imediatamente o elenco visual da cena.",error);}
    }


    /** Mantém NPCs persistentes entre batidas, mas remove figurantes transitórios da batida anterior. */
    private void appendPersistentSceneNpcs(JSONArray out,Set<String> seen,Object raw)throws Exception{
        JSONArray values=raw instanceof JSONArray?(JSONArray)raw:null;if(values==null&&raw instanceof String)try{values=new JSONArray(String.valueOf(raw));}catch(Exception ignored){return;}if(values==null)return;
        for(int i=0;i<values.length();i++){Object value=values.opt(i);if(value instanceof JSONObject){JSONObject npc=(JSONObject)value;if(npc.optBoolean("transient",false)||npc.optBoolean("anonymous",false))continue;appendPreviewNpc(out,seen,npc);}else if(value!=null){String name=GeneratedTextSanitizer.scalar(String.valueOf(value),"name");if(name.length()>0)appendPreviewNpc(out,seen,new JSONObject().put("name",name));}}
    }

    private static boolean containsNormalizedName(String normalizedText,String name){String needle=normalizeForNameMatch(name);if(needle.length()<2)return false;return (" "+normalizedText+" ").contains(" "+needle+" ");}
    private static String normalizeForNameMatch(String value){if(value==null)return "";return java.text.Normalizer.normalize(value,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}+","").toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+"," ").replaceAll("\\s+"," ").trim();}

    private static boolean isReservedSceneIdentity(String value){
        String n=normalizeForNameMatch(value);
        if(n.length()==0)return true;
        String[] reserved={"voce","voces","eu","nos","ele","ela","eles","elas","jogador","jogadora","jogadores","jogadoras","o jogador","a jogadora",
                "grupo","o grupo","grupo de aventureiros","companhia","a companhia","heroi","herois","aventureiro","aventureiros","player","players","party","the party","narrador","narradora","mestre do jogo","game master","gm",
                "restov","brevoy","rostland","issia","pitax","varnhold","drelev","fort drelev","golarion","terras roubadas","stolen lands",
                "cinturao verde","greenbelt","narlmarches","floresta narlmarches","kamelands","dunsward","hooktongue","pantano hooktongue",
                "glenebon","altiplanos de glenebon","thousand voices","tors of levenies","rio shrike","rio thorn","lago candlemere","tuskwater",
                "lago silverstep","lago hooktongue","lago rushlight","posto comercial de oleg","posto de oleg","oleg","forte serenko","serenko",
                "nivakta","travessia de nivakta","littletown","velho sicomoro","cavernas sootscale","sootscale","templo do alce",
                "fortaleza do senhor dos cervos","senhor dos cervos","ilha candlemere","candlemere","cabana de bokken","bokken",
                "arbustos fangberry","fangberry","travessia de nettle","nettle","covil do tatzlwyrm","tatzlwyrm","covil de tuskgutter",
                "tuskgutter","fortaleza de hargulka","hargulka","tatzlford","tumba de vordakai","vordakai","senhores tigres","tiger lords"};
        for(String alias:reserved)if(n.equals(alias))return true;
        return false;
    }

    private void sanitizeReservedNpcAliases(){
        if(db==null)return;
        try{
            JSONObject scene=db.getSceneState();JSONArray source=new JSONArray(scene.optString("present_npcs_json","[]"));JSONArray clean=new JSONArray();boolean changed=false;
            for(int i=0;i<source.length();i++){
                Object raw=source.opt(i);String name=GeneratedTextSanitizer.scalar(String.valueOf(raw),"name").trim();
                if(name.length()==0||isReservedSceneIdentity(name)||SceneEntityGrounding.isNonNpcIdentity(db,scene,name)){changed=true;JSONObject memory=db.findNpcMemoryByName(name);if(memory.length()>0&&SceneEntityGrounding.isWeakAutoNpc(memory))db.deleteNpcMemory(memory.optLong("id"));continue;}
                JSONObject canonical;
                if(raw instanceof JSONObject)canonical=new JSONObject(raw.toString());else{canonical=new JSONObject();changed=true;}
                String previous=canonical.optString("name",canonical.optString("label","")).trim();
                if(!name.equals(previous)){canonical.put("name",name);changed=true;}
                for(String field:new String[]{"role","summary","visual_description"}){
                    if(!canonical.has(field))continue;
                    String before=canonical.optString(field,"");
                    String after=GeneratedTextSanitizer.humanText(before);
                    if(!after.equals(before)){canonical.put(field,after);changed=true;}
                }
                clean.put(canonical);
            }
            if(changed){scene.put("present_npcs",clean);scene.put("present_npcs_json",clean.toString());db.saveSceneState(scene);currentSceneCastPreview=new JSONArray();}
        }catch(Exception error){AppLog.w("SceneCast","Não foi possível limpar aliases reservados ou payloads estruturados do elenco.",error);}
    }

    private void appendPreviewNpcs(JSONArray out,Set<String> seen,Object raw)throws Exception{
        JSONArray values=raw instanceof JSONArray?(JSONArray)raw:null;if(values==null&&raw instanceof String)try{values=new JSONArray(String.valueOf(raw));}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}
        if(values==null)return;for(int i=0;i<values.length();i++){Object value=values.opt(i);if(value instanceof JSONObject)appendPreviewNpc(out,seen,(JSONObject)value);else if(value!=null){String name=GeneratedTextSanitizer.scalar(String.valueOf(value),"name");if(name.length()>0)appendPreviewNpc(out,seen,new JSONObject().put("name",name));}}
    }

    private void appendPreviewNpc(JSONArray out,Set<String> seen,JSONObject npc)throws Exception{
        String name=GeneratedTextSanitizer.scalar(npc.optString("name",npc.optString("label")),"name");if(name.length()==0||isReservedSceneIdentity(name)||SceneEntityGrounding.isNonNpcIdentity(db,db.getSceneState(),name))return;String key=normalizeForNameMatch(name);if(!seen.add(key))return;
        JSONObject visible=new JSONObject().put("name",name);for(String field:new String[]{"token_uri","role","summary","visual_description"}){String value=GeneratedTextSanitizer.scalar(npc.optString(field),field);if(value.length()>0)visible.put(field,value);}if(npc.optBoolean("anonymous",false))visible.put("anonymous",true);if(npc.optBoolean("transient",false))visible.put("transient",true);if(npc.optBoolean("group",false))visible.put("group",true);if(npc.has("count"))visible.put("count",Math.max(1,npc.optInt("count",1)));out.put(visible);
    }

    private JSONArray collectSceneCast(){
        JSONArray out=new JSONArray();HashSet<String> seen=new HashSet<String>();
        try{
            for(JSONObject hero:db.listActiveCharacters())addSceneCastEntry(out,seen,hero.optString("name","Aventureiro"),"AVENTUREIRO",hero.optString("token_uri",""),heroSpeciesLabel(hero),1,false,false);
            JSONObject scene=db.getSceneState();String raw=scene.optString("present_npcs_json","[]");
            try{JSONArray npcs=new JSONArray(raw);for(int i=0;i<npcs.length();i++){Object value=npcs.opt(i);if(value instanceof JSONObject){JSONObject npc=(JSONObject)value;String name=GeneratedTextSanitizer.scalar(npc.toString(),"name");if(SceneEntityGrounding.isNonNpcIdentity(db,scene,name))continue;boolean transientNpc=npc.optBoolean("transient",false)||npc.optBoolean("anonymous",false);JSONObject memory=transientNpc?new JSONObject():db.findNpcMemoryByName(name);addSceneCastEntry(out,seen,name,"NPC",npc.optString("token_uri",memory.optString("token_uri","")),npc.optString("role",npc.optString("summary",memory.optString("summary",""))),Math.max(1,npc.optInt("count",1)),npc.optBoolean("group",false),transientNpc);}else{String name=GeneratedTextSanitizer.scalar(String.valueOf(value),"name");if(SceneEntityGrounding.isNonNpcIdentity(db,scene,name))continue;JSONObject memory=db.findNpcMemoryByName(name);addSceneCastEntry(out,seen,name,"NPC",memory.optString("token_uri",""),memory.optString("summary",""),1,false,false);}}}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}
            if(currentSceneCastPreview!=null)for(int i=0;i<currentSceneCastPreview.length();i++){JSONObject npc=currentSceneCastPreview.optJSONObject(i);if(npc==null)continue;String name=npc.optString("name","NPC");if(SceneEntityGrounding.isNonNpcIdentity(db,scene,name))continue;boolean transientNpc=npc.optBoolean("transient",false)||npc.optBoolean("anonymous",false);JSONObject memory=transientNpc?new JSONObject():db.findNpcMemoryByName(name);addSceneCastEntry(out,seen,name,"NPC",npc.optString("token_uri",memory.optString("token_uri","")),npc.optString("role",npc.optString("summary",memory.optString("summary",""))),Math.max(1,npc.optInt("count",1)),npc.optBoolean("group",false),transientNpc);}
            for(JSONObject combatant:db.listCombatants())if(combatant.optInt("is_player",0)!=1)addSceneCastEntry(out,seen,combatant.optString("name","Inimigo"),"INIMIGO",combatant.optString("token_uri",""),combatant.optString("conditions",""),1,false,false);
        }catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}
        return out;
    }

    private String heroSpeciesLabel(JSONObject hero){String species=hero==null?"":hero.optString("species","").trim();if(species.length()==0&&hero!=null)try{JSONObject sheet=new JSONObject(hero.optString("sheet_json","{}"));species=sheet.optString("species",sheet.optString("race","")).trim();}catch(Exception ignored){AppLog.ignored("SceneCast","Espécie ausente na ficha compacta.",ignored);}return species.length()==0?"AVENTUREIRO":GeneratedTextSanitizer.humanText(species);}

    private void addSceneCastEntry(JSONArray out,Set<String> seen,String name,String kind,String tokenUri,String hint,int count,boolean group,boolean transientNpc){
        String clean=name==null?"":name.trim();if(clean.length()==0||"null".equalsIgnoreCase(clean)||isReservedSceneIdentity(clean)||(!"AVENTUREIRO".equalsIgnoreCase(kind)&&SceneEntityGrounding.isNonNpcIdentity(db,db.getSceneState(),clean)))return;String key=normalizeForNameMatch(clean);if(!seen.add(key))return;
        try{if(!transientNpc&&(tokenUri==null||tokenUri.trim().length()==0)){JSONObject token=db.findLocalTokenForScene(clean);tokenUri=token.optString("local_uri","");}JSONObject entry=new JSONObject().put("name",clean).put("kind",kind).put("token_uri",tokenUri==null?"":tokenUri).put("hint",hint==null?"":hint);if(count>1)entry.put("count",count);if(group)entry.put("group",true);if(transientNpc)entry.put("transient",true);out.put(entry);}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}
    }

    private View sceneTokenTile(JSONObject entry){
        LinearLayout tile=new LinearLayout(this);tile.setOrientation(LinearLayout.VERTICAL);tile.setGravity(Gravity.CENTER);tile.setPadding(dp(2),dp(2),dp(5),0);
        String name=entry.optString("name","?");String kind=entry.optString("kind","NPC");String uri=entry.optString("token_uri","");
        FrameLayout circle=new FrameLayout(this);GradientDrawable clip=new GradientDrawable();clip.setShape(GradientDrawable.OVAL);clip.setColor(INPUT_BG);circle.setBackground(clip);circle.setClipToOutline(true);GradientDrawable ring=new GradientDrawable();ring.setShape(GradientDrawable.OVAL);ring.setColor(Color.TRANSPARENT);ring.setStroke(dp(2),"INIMIGO".equals(kind)?RED:GOLD);circle.setForeground(ring);
        TextView initial=text(name.length()>0?name.substring(0,1).toUpperCase(new Locale("pt","BR")):"?",22,TEXT,true);initial.setGravity(Gravity.CENTER);initial.setBackgroundColor(INPUT_BG);circle.addView(initial,new FrameLayout.LayoutParams(-1,-1));
        if(uri.length()>0){ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);try{Bitmap tokenBitmap=ImageStorageManager.decodeSampled(this,Uri.parse(uri),256,256);if(tokenBitmap!=null){image.setImageBitmap(tokenBitmap);circle.addView(image,new FrameLayout.LayoutParams(-1,-1));}}catch(Throwable ignored){AppLog.ignored("SceneToken","Token inválido ou pesado foi ignorado sem fechar o Mestre IA.",ignored);}}
        int count=Math.max(1,entry.optInt("count",1));if(count>1){TextView badge=text("×"+count,8,TEXT,true);badge.setGravity(Gravity.CENTER);GradientDrawable badgeBg=new GradientDrawable();badgeBg.setShape(GradientDrawable.OVAL);badgeBg.setColor(PANEL2);badge.setBackground(badgeBg);FrameLayout.LayoutParams bp=new FrameLayout.LayoutParams(dp(22),dp(22),Gravity.END|Gravity.BOTTOM);circle.addView(badge,bp);}
        tile.addView(circle,new LinearLayout.LayoutParams(dp(58),dp(58)));
        TextView label=text(name,10,TEXT,true);label.setGravity(Gravity.CENTER);label.setMaxLines(1);label.setEllipsize(android.text.TextUtils.TruncateAt.END);tile.addView(label,new LinearLayout.LayoutParams(dp(70),dp(21)));
        String visibleRole=sceneCastVisibleRole(entry);TextView role=text(visibleRole,8,"INIMIGO".equals(kind)?RED:MUTED,true);role.setGravity(Gravity.CENTER);role.setMaxLines(1);role.setEllipsize(android.text.TextUtils.TruncateAt.END);tile.addView(role,new LinearLayout.LayoutParams(dp(70),dp(16)));
        if("NPC".equals(kind)){final JSONObject target=entry;tile.setClickable(true);tile.setContentDescription("Abrir ou gerar retrato de "+name);tile.setOnClickListener(new View.OnClickListener(){public void onClick(View v){handleSceneNpcPortrait(target);}});}
        return tile;
    }

    private void handleSceneNpcPortrait(JSONObject entry){
        if(entry==null)return;String name=entry.optString("name","").trim();if(name.length()==0)return;
        if(entry.optBoolean("group",false)||entry.optBoolean("transient",false)){toast("Este é um grupo/figurante transitório. Dê um nome individual antes de criar um retrato persistente.");return;}
        JSONObject memory=db.findNpcMemoryByName(name);if(memory.length()==0){try{JSONObject seed=new JSONObject().put("name",name).put("active",1).put("summary",entry.optString("hint",entry.optString("role","NPC presente"))).put("last_seen",db.getSceneState().optString("location","")).put("hex_id",db.getSceneState().optString("hex_id",""));db.upsertNpcMemoryChecked(seed);memory=db.findNpcMemoryByName(name);}catch(Exception error){AppLog.e("NpcPortrait","Não foi possível estabilizar a identidade do NPC.",error);toast("Não foi possível preparar o NPC para um retrato persistente.");return;}}
        long npcId=memory.optLong("id",0L);String uri=memory.optString("token_uri",entry.optString("token_uri","")).trim();if(uri.length()>0){try{Uri portrait=Uri.parse(uri);if(ImageStorageManager.isReadable(this,portrait)){showNpcPortraitFullscreen(name,portrait);return;}}catch(Exception ignored){AppLog.ignored("NpcPortrait","Retrato anterior indisponível; será possível regenerar.",ignored);}}
        if(!hasStrongNpcVisualIdentity(entry,memory)){enrichNpcVisualIdentityThenGenerate(entry,memory);return;}
        String prompt=buildNpcPortraitPrompt(entry,memory);generateNpcPortrait(npcId,name,prompt);
    }

    private boolean hasStrongNpcVisualIdentity(JSONObject entry,JSONObject memory){
        String visual=entry==null?"":entry.optString("visual_description","");if(visual.trim().length()==0&&memory!=null)visual=memory.optString("visual_description","");
        JSONObject stats=new JSONObject();try{if(memory!=null)stats=new JSONObject(memory.optString("stats_json","{}"));}catch(Exception ignored){AppLog.ignored("NpcIdentity","stats_json inválido; identidade será enriquecida.",ignored);}
        String species=stats.optString("ancestry",stats.optString("species","")).trim();String gender=stats.optString("gender",stats.optString("sex",stats.optString("gender_presentation",""))).trim();String age=stats.optString("apparent_age",stats.optString("age","")).trim();
        String low=java.text.Normalizer.normalize(visual.toLowerCase(new Locale("pt","BR")),java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","");
        boolean speciesKnown=species.length()>0||low.matches("(?s).*(humano|humana|elfo|elfa|anao|ana|gnomo|gnoma|halfling|orc|meio-orc|goblin|leshy|tengu|kobold|catfolk|ratfolk|dwarf|human|elf|gnome).*");
        boolean genderKnown=gender.length()>0||low.matches("(?s).*(homem|mulher|masculin|feminin|androg|nao-binari|male|female).*");
        boolean ageKnown=age.length()>0||low.matches("(?s).*(jovem|adolescente|adult|meia-idade|idos|velh|vinte|trinta|quarenta|cinquenta|sessenta).*");
        return visual.trim().length()>=90&&speciesKnown&&genderKnown&&ageKnown;
    }

    private void enrichNpcVisualIdentityThenGenerate(final JSONObject entry,final JSONObject memory){
        final String name=entry.optString("name",memory.optString("name","NPC")).trim();final long npcId=memory.optLong("id",0L);if(npcId<=0){toast("NPC sem identidade persistente.");return;}
        final String key=geminiKey();if(key.trim().length()<20){setStatus("Configure a chave Gemini para consolidar a identidade visual de "+name+" antes do retrato.");return;}
        final String role=entry.optString("role",entry.optString("hint",memory.optString("summary","NPC presente")));final String summary=memory.optString("summary","");final String existing=entry.optString("visual_description",memory.optString("visual_description",""));final String scene=lastNarration==null?"":promptTail(lastNarration,1800);
        final String system="BRAS_NPC_VISUAL_IDENTITY BRAS_SINGLE_CALL. Consolide UMA identidade visual persistente para um NPC de Pathfinder 2e. Preserve todo fato já estabelecido. Se espécie/ancestralidade, apresentação de gênero ou idade aparente não estiverem definidos, escolha UMA opção plausível agora e trate-a como canônica dali em diante. Não altere essa identidade em futuras aparições. Retorne SOMENTE JSON válido com as chaves ancestry_or_species, gender_presentation, apparent_age, skin, hair, eyes, build, clothing, distinctive_features, visible_equipment, visual_description. visual_description deve resumir todos esses campos em português do Brasil.";
        final String prompt="NPC: "+name+"\nPapel: "+role+"\nResumo persistente: "+summary+"\nDescrição visual existente: "+existing+"\nCena atual: "+scene+"\nGere identidade concreta suficiente para um retrato exclusivo. Não use expressões vagas como 'personagem nomeado', 'NPC ativo' ou 'aparência coerente'.";
        setStatus("Consolidando identidade física persistente de "+name+" antes do retrato…");
        gemini.generateText(key,prefs.getString("text_model","gemini-3.5-flash-lite"),system,prompt,new GeminiService.TextCallback(){
            public void onSuccess(final String raw){ui.post(new Runnable(){public void run(){try{JSONObject id=parseAiEnvelope(raw);String species=id.optString("ancestry_or_species","").trim(),gender=id.optString("gender_presentation","").trim(),age=id.optString("apparent_age","").trim(),skin=id.optString("skin","").trim(),hair=id.optString("hair","").trim(),eyes=id.optString("eyes","").trim(),build=id.optString("build","").trim(),clothing=id.optString("clothing","").trim(),features=id.optString("distinctive_features","").trim(),equipment=id.optString("visible_equipment","").trim(),visual=id.optString("visual_description","").trim();if(visual.length()<80){StringBuilder b=new StringBuilder();if(species.length()>0)b.append(species).append(", " );if(gender.length()>0)b.append(gender).append(", " );if(age.length()>0)b.append(age).append(". " );if(skin.length()>0)b.append("Pele: " ).append(skin).append(". " );if(hair.length()>0)b.append("Cabelo/barba: " ).append(hair).append(". " );if(eyes.length()>0)b.append("Olhos: " ).append(eyes).append(". " );if(build.length()>0)b.append("Porte: " ).append(build).append(". " );if(clothing.length()>0)b.append("Roupa/armadura: " ).append(clothing).append(". " );if(features.length()>0)b.append("Marcas: " ).append(features).append(". " );if(equipment.length()>0)b.append("Equipamento visível: " ).append(equipment).append("." );visual=b.toString().trim();}if(species.length()==0||gender.length()==0||age.length()==0||visual.length()<60){setStatus("O Gemini não consolidou identidade suficiente para "+name+"; o retrato não foi gerado para evitar uma face genérica.");return;}JSONObject stats;try{stats=new JSONObject(memory.optString("stats_json","{}"));}catch(Exception e){stats=new JSONObject();}stats.put("ancestry",species).put("species",species).put("gender_presentation",gender).put("apparent_age",age).put("skin",skin).put("hair",hair).put("eyes",eyes).put("build",build).put("clothing",clothing).put("distinctive_features",features).put("visible_equipment",equipment);JSONObject updated=new JSONObject(memory.toString()).put("visual_description",visual).put("stats_json",stats.toString()).put("active",1);db.upsertNpcMemory(updated);JSONObject stored=db.findNpcMemoryByName(name);String portraitPrompt=buildNpcPortraitPrompt(entry,stored);generateNpcPortrait(stored.optLong("id",npcId),name,portraitPrompt);}catch(Exception error){AppLog.e("NpcIdentity","Falha ao consolidar identidade visual.",error);setStatus("Não foi possível consolidar a identidade de "+name+". O retrato não foi gerado.");}}});}
            public void onError(final String error){ui.post(new Runnable(){public void run(){setStatus("Identidade visual de "+name+" não pôde ser consolidada agora: "+compactGeminiFailure(error));}});}
        });
    }

    private String buildNpcPortraitPrompt(JSONObject entry,JSONObject memory){
        String name=entry.optString("name",memory.optString("name","NPC"));String role=entry.optString("role",entry.optString("hint",memory.optString("summary","")));String visual=entry.optString("visual_description",memory.optString("visual_description",""));String summary=memory.optString("summary",entry.optString("hint",""));JSONObject stats=new JSONObject();try{stats=new JSONObject(memory.optString("stats_json","{}"));}catch(Exception ignored){AppLog.ignored("NpcPortrait","Ficha visual estruturada inválida.",ignored);}String species=stats.optString("ancestry",stats.optString("species","")),gender=stats.optString("gender_presentation",stats.optString("gender",stats.optString("sex",""))),age=stats.optString("apparent_age",stats.optString("age","")),skin=stats.optString("skin",""),hair=stats.optString("hair",""),eyes=stats.optString("eyes",""),build=stats.optString("build",""),clothing=stats.optString("clothing",""),features=stats.optString("distinctive_features",""),equipment=stats.optString("visible_equipment","");String location=NarrativeLocationNaturalizer.currentNarrativeLabel(db);
        StringBuilder p=new StringBuilder();p.append("Crie um retrato persistente e exclusivo do NPC ").append(name).append(" para um jogo Pathfinder 2e. Mostrar APENAS esta pessoa, enquadramento do peito para cima, rosto grande e claramente visível, olhos e traços faciais em evidência. Sem outros personagens, sem texto, letras, moldura, ficha ou interface. Fantasia medieval Pathfinder, pintura digital nítida, iluminação natural coerente. IDENTIDADE CANÔNICA — não omita nem altere estes dados: ");
        if(species.length()>0)p.append("espécie/ancestralidade: ").append(species).append("; ");if(gender.length()>0)p.append("apresentação de gênero/sexo aparente: ").append(gender).append("; ");if(age.length()>0)p.append("idade aparente: ").append(age).append("; ");if(skin.length()>0)p.append("pele/tez: ").append(skin).append("; ");if(hair.length()>0)p.append("cabelo/barba: ").append(hair).append("; ");if(eyes.length()>0)p.append("olhos: ").append(eyes).append("; ");if(build.length()>0)p.append("porte físico: ").append(build).append("; ");if(clothing.length()>0)p.append("roupa/armadura: ").append(clothing).append("; ");if(features.length()>0)p.append("marcas e traços distintivos: ").append(features).append("; ");if(equipment.length()>0)p.append("equipamento visível: ").append(equipment).append("; ");
        if(visual.length()>0)p.append("descrição visual persistente: ").append(visual).append(". ");if(role.length()>0)p.append("Papel na cena: ").append(role).append(". ");else if(summary.length()>0)p.append("Contexto do personagem: ").append(summary).append(". ");if(location.length()>0)p.append("Contexto discreto de fundo: ").append(location).append("; o fundo não deve competir com o rosto. ");p.append("Não reutilize o rosto de nenhum outro NPC. A mesma pessoa deve continuar reconhecível em todas as futuras reaparições.");String out=p.toString();return out.length()>3200?out.substring(0,3200):out;
    }

    private void generateNpcPortrait(final long npcId,final String npcName,final String prompt){
        if(npcId<=0){toast("NPC sem identidade persistente.");return;}String key=geminiKey();if(key.trim().length()<20){sharePromptToGeminiForNpc(prompt,npcId,npcName);return;}setStatus("Gerando retrato persistente de "+npcName+"…");gemini.generateImage(key,prefs.getString("image_model","gemini-3.1-flash-image"),prompt,new GeminiService.FileCallback(){public void onSuccess(final File file,String mime){AppExecutors.io().execute(new Runnable(){public void run(){try{final Uri portrait=ImageStorageManager.importImage(MainActivity.this,Uri.fromFile(file),"npc_avatars","npc_"+npcId+"_portrait",80);db.setNpcToken(npcId,portrait.toString());ui.post(new Runnable(){public void run(){applyNpcPortraitToScene(npcName,portrait.toString());setStatus("Retrato gerado e vinculado exclusivamente a "+npcName+".");showNpcPortraitFullscreen(npcName,portrait);}});}catch(final Exception error){AppLog.e("NpcPortrait","Falha ao armazenar retrato gerado.",error);ui.post(new Runnable(){public void run(){setStatus("O retrato foi gerado, mas não pôde ser persistido.");toast(String.valueOf(error.getMessage()));}});}}});}public void onError(final String error){ui.post(new Runnable(){public void run(){setStatus("Geração interna de retrato indisponível. Abrindo o fluxo pelo Gemini.");sharePromptToGeminiForNpc(prompt,npcId,npcName);}});}});
    }

    private void applyNpcPortraitToScene(String npcName,String uri){
        if(npcName==null||npcName.trim().isEmpty()||uri==null||uri.trim().isEmpty())return;String key=normalizeForNameMatch(npcName);try{if(currentSceneCastPreview!=null)for(int i=0;i<currentSceneCastPreview.length();i++){JSONObject npc=currentSceneCastPreview.optJSONObject(i);if(npc!=null&&key.equals(normalizeForNameMatch(npc.optString("name",""))))npc.put("token_uri",uri);}JSONObject scene=db.getSceneState();JSONArray present;try{present=new JSONArray(scene.optString("present_npcs_json","[]"));}catch(Exception e){present=new JSONArray();}for(int i=0;i<present.length();i++){JSONObject npc=present.optJSONObject(i);if(npc!=null&&key.equals(normalizeForNameMatch(npc.optString("name",""))))npc.put("token_uri",uri);}scene.put("present_npcs",present).put("present_npcs_json",present.toString());db.saveSceneState(scene);prefs.edit().putString("last_scene_cast_preview",currentSceneCastPreview==null?"[]":currentSceneCastPreview.toString()).apply();screenCache.remove("Mestre IA");screenCacheTime.remove("Mestre IA");if("Mestre IA".equals(currentScreen))showNarrator();}catch(Exception error){AppLog.w("NpcPortrait","Retrato persistiu no NPC, mas a prévia da cena não foi atualizada imediatamente.",error);}
    }

    private void showNpcPortraitFullscreen(final String name,final Uri uri){
        if(uri==null)return;try{final ImageView full=new ImageView(this);full.setBackgroundColor(Color.BLACK);full.setScaleType(ImageView.ScaleType.FIT_CENTER);full.setAdjustViewBounds(true);full.setImageBitmap(ImageStorageManager.decodeSampled(this,uri,1600,2000));LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(8),dp(8),dp(8),dp(8));box.addView(full,new LinearLayout.LayoutParams(-1,0,1));new AlertDialog.Builder(this).setTitle(name).setView(box).setNegativeButton("Fechar",null).setNeutralButton("REGERAR RETRATO",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){JSONObject memory=db.findNpcMemoryByName(name);if(memory.length()==0)return;JSONObject entry=new JSONObject();try{entry.put("name",name).put("role",memory.optString("summary","")).put("visual_description",memory.optString("visual_description",""));}catch(Exception ignored){}generateNpcPortrait(memory.optLong("id"),name,buildNpcPortraitPrompt(entry,memory));}}).show();}catch(Exception error){toast("Retrato indisponível: "+String.valueOf(error.getMessage()));}
    }

    private String sceneCastVisibleRole(JSONObject entry){
        String kind=entry==null?"NPC":entry.optString("kind","NPC").trim();
        if(!"AVENTUREIRO".equalsIgnoreCase(kind)){if(entry!=null&&entry.optBoolean("group",false))return entry.optInt("count",1)>1?"GRUPO ×"+entry.optInt("count",1):"GRUPO";return kind.length()==0?"NPC":kind.toUpperCase(new Locale("pt","BR"));}
        String species=entry.optString("hint","").trim();
        if(species.length()==0||"null".equalsIgnoreCase(species))return "AVENTUREIRO";
        species=GeneratedTextSanitizer.humanText(species);if(species.length()>26)species=species.substring(0,26).trim();
        return species.toUpperCase(new Locale("pt","BR"));
    }

    private void showAttachManualDialog(){
        final String world=WORLD_PF2;
        List<JSONObject> all=filterManualsForWorld(db.listManuals(""),world);
        final ArrayList<JSONObject> valid=new ArrayList<JSONObject>();
        for(JSONObject m:all)if(m.optInt("enabled",1)==1&&!"Sistema externo bloqueado".equals(m.optString("category")))valid.add(m);
        if(valid.size()==0){
            new AlertDialog.Builder(this).setTitle("Biblioteca Pathfinder 2e").setMessage("Nenhum manual Pathfinder habilitado. Importe Player Core, GM Core, Monster Core, Lost Omens ou material de campanha; fontes externas nunca recebem autoridade mecânica.").setPositiveButton("OK",null).show();
            return;
        }
        final String[] labels=new String[valid.size()+1];labels[0]="Nenhum livro prioritário — buscar em toda a biblioteca PF2e";
        long currentId=attachedManualId(world);int current=0;
        for(int i=0;i<valid.size();i++){JSONObject m=valid.get(i);labels[i+1]=manualDisplayTitle(m)+"\n"+m.optString("category")+("ready".equals(m.optString("rag_status"))?" • pronto":" • será indexado");if(m.optLong("id")==currentId)current=i+1;}
        final int[] chosen={current};
        new AlertDialog.Builder(this).setTitle("Livro prioritário • Pathfinder 2e").setSingleChoiceItems(labels,current,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){chosen[0]=which;}}).setNegativeButton("Cancelar",null).setPositiveButton("APLICAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){if(chosen[0]<=0){prefs.edit().remove(attachedManualPrefKey(world)).apply();toast("Livro prioritário removido. O Mestre pesquisará toda a biblioteca PF2e.");showNarrator();return;}JSONObject m=valid.get(chosen[0]-1);if(!manualBelongsToWorld(m,world)){toast("Fonte bloqueada para autoridade Pathfinder.");return;}prefs.edit().putString(attachedManualPrefKey(world),String.valueOf(m.optLong("id"))).apply();toast("Livro prioritário: "+manualDisplayTitle(m));if(!"ready".equals(m.optString("rag_status")))scheduleRagIndexing(false);showNarrator();}}).show();
    }

    private void addOptionButton(LinearLayout parent,final JSONObject option){String label=option.optString("label","Opção");String description=option.optString("description",option.optString("action",""));JSONObject test=option.optJSONObject("test");String suffix="";if(test!=null&&test.optBoolean("required",false))suffix="\nTeste: "+testLabel(test);Button button=button(label+(description.length()>0?"\n"+description:"")+suffix,PANEL2);button.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);button.setAllCaps(false);button.setTextSize(14);boolean blocked=aiBusy||(pendingTest!=null&&pendingTest.length()>0&&pendingTest.optBoolean("required",true));button.setEnabled(!blocked);button.setAlpha(blocked?0.58f:1f);button.setOnClickListener(new View.OnClickListener(){public void onClick(View v){handleOption(option);}});parent.addView(button,new LinearLayout.LayoutParams(-1,-2));}
    private void handleOption(JSONObject option){if(aiBusy)return;if(pendingTest!=null&&pendingTest.length()>0&&pendingTest.optBoolean("required",true)){toast("Resolva ou cancele o teste pendente antes de escolher outra ação.");return;}JSONObject test=option.optJSONObject("test");String action=option.optString("action",option.optString("description",option.optString("label")));if(test!=null&&test.optBoolean("required",false)){try{JSONObject prepared=new JSONObject(test.toString());prepared.put("option_label",option.optString("label"));pendingTest=ensurePendingTestIdentity(prepared,action);persistStory(action);showNarrator();}catch(Exception e){toast("Não foi possível preparar o teste.");}}else sendAi("Narrador","O jogador escolheu: "+action+". Continue a partir dessa escolha, sem repetir a cena anterior.");}
    private void addPendingTestCard(LinearLayout parent,final JSONObject test){LinearLayout card=card();card.setBackground(makeBg(Color.rgb(73,49,31),GOLD,12));card.addView(text("TESTE OBRIGATÓRIO — A HISTÓRIA ESTÁ PAUSADA",15,GOLD,true));card.addView(text(testLabel(test),18,TEXT,true));String action=test.optString("action");if(action.length()>0)card.addView(text(action,14,MUTED,false));Button roll=button("ROLAR AGORA",GOLD);roll.setTextColor(Color.BLACK);roll.setOnClickListener(new View.OnClickListener(){public void onClick(View v){rollPendingTest(test);}});card.addView(roll);Button cancel=button("CANCELAR ESTA AÇÃO",PANEL2);cancel.setOnClickListener(new View.OnClickListener(){public void onClick(View v){pendingTest=new JSONObject();persistStory("");showNarrator();}});card.addView(cancel);parent.addView(card);}
    private String testLabel(JSONObject test){String type=test.optString("type","check");String label;if("save".equalsIgnoreCase(type))label="Salvamento de "+test.optString("save_type","Fortitude");else if("attack".equalsIgnoreCase(type))label="Ataque";else label=test.optString("skill","Percepção");int dc=test.optInt("dc",15);String mode=normalizeRollMode(test.optString("mode","Normal"));return label+" • CD "+dc+("Normal".equals(mode)?"":" • "+mode);}
    private int pf2TestBonus(JSONObject hero,JSONObject test){if(test==null)return 0;String type=test.optString("type","check");if("save".equalsIgnoreCase(type))return pathfinderRules.savingThrowBonus(hero,test.optString("save_type","Fortitude"));if("attack".equalsIgnoreCase(type)&&test.has("local_modifier"))return test.optInt("local_modifier",0);return pathfinderRules.checkBonus(hero,test.optString("ability"),test.optString("skill","Percepção"));}
    private String pf2TestModifierSource(JSONObject test){if(test==null)return "pf2_check";String type=test.optString("type","check");if("save".equalsIgnoreCase(type))return "pf2_save:"+test.optString("save_type","Fortitude");if("attack".equalsIgnoreCase(type))return "pf2_attack_local";return "pf2_skill:"+test.optString("skill","Percepção");}
    private void rollPendingTest(final JSONObject test){
        final List<JSONObject> heroes=db.listActiveCharacters();if(heroes.isEmpty()){toast("Nenhum personagem em jogo.");return;}LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),0);String[] names=new String[heroes.size()];for(int i=0;i<heroes.size();i++)names[i]=heroes.get(i).optString("name");final Spinner hero=spinner(names,names[0]);form.addView(cardWithLabel("PERSONAGEM",hero));final TextView calc=text("",13,MUTED,false);form.addView(calc);final Runnable update=new Runnable(){public void run(){JSONObject ch=heroes.get(hero.getSelectedItemPosition());int b=pf2TestBonus(ch,test);calc.setText("Bônus da ficha: "+signedModifier(b)+" • CD "+test.optInt("dc",15)+" • quatro graus de sucesso.");}};hero.setOnItemSelectedListener(new SimpleItemSelected(){public void selected(){update.run();}});update.run();new AlertDialog.Builder(this).setTitle(testLabel(test)).setView(form).setNegativeButton("Cancelar",null).setPositiveButton("ROLAR D20 3D",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){final JSONObject selected=heroes.get(hero.getSelectedItemPosition());int b=pf2TestBonus(selected,test);final String formula="d20"+(b>=0?"+":"")+b;final String rollMode=normalizeRollMode(test.optString("mode","Normal"));rollPhysical(formula,rollMode,selected.optString("name"),new PhysicalRollAction(){public void run(DiceResult r){showTestResult(test,selected,r,formula,rollMode);}});}}).show();
    }

    
    
    
    
    

    private void showTestResult(final JSONObject rawTest,final JSONObject hero,final DiceResult result,final String formula,String mode){
        final JSONObject test=ensurePendingTestIdentity(rawTest,rawTest==null?"":rawTest.optString("action"));
        try{
            int dc=Math.max(0,test.optInt("dc",10));
            int modifier=pf2TestBonus(hero,test);
            Pathfinder2eRulesEngine.Degree degree=pathfinderRules.degree(result.natural,result.total,dc);
            boolean success=degree==Pathfinder2eRulesEngine.Degree.SUCCESS||degree==Pathfinder2eRulesEngine.Degree.CRITICAL_SUCCESS;
            String degreePt=pathfinderRules.degreeLabel(degree);
            String action=test.optString("action");
            String modifierSource=pf2TestModifierSource(test);
            JSONObject context=rollBindingContext(test,hero,degree.name().toLowerCase(Locale.US),formula,normalizeRollMode(mode),result.natural,modifier,modifierSource);
            long rollId=db.addDiceHistoryBound(formula,result.detail,result.total,"Teste PF2e obrigatório",context);
            String resolution="[RESOLUÇÃO MECÂNICA PF2E] "+hero.optString("name")+" tentou "+action+". Rolagem natural "+result.natural+", total "+result.total+" contra CD "+dc+": "+degreePt+". roll_id="+rollId+". Continue exatamente deste resultado; não rerrole e não troque o grau.";
            pendingTest=new JSONObject();persistStory(resolution);sendAi("Narrador",resolution);
            toast(degreePt+" • "+result.total+" vs CD "+dc);
        }catch(Exception e){toast("Falha ao registrar teste PF2e: "+e.getMessage());}
    }

    private JSONObject ensurePendingTestIdentity(JSONObject raw,String action){
        try{
            JSONObject test=raw==null?new JSONObject():new JSONObject(raw.toString());String safeAction=action==null?test.optString("action"):action;test.put("action",safeAction);
            JSONObject support=test.optJSONObject("rule_support");String ruleId=support==null?test.optString("source_rule_id",test.optString("rule_id","")):support.optString("rule_id","");
            if(ruleId.trim().length()==0)ruleId="local-engine:pf2e-remaster:"+test.optString("type","check");
            String procedureId=test.optString("procedure_id",support==null?"":support.optString("procedure_id",""));if(procedureId.trim().length()==0)procedureId=ruleId+":procedure:local";test.put("procedure_id",procedureId);
            String scene=stableFingerprint(db.getActiveMapProfile()+"|"+db.getSceneState().toString()+"|"+lastNarration);
            String actionSignature=stableFingerprint(db.getActiveMapProfile()+"|"+safeAction.trim().toLowerCase(Locale.ROOT));
            String testKey=test.optString("test_key","");if(testKey.trim().length()==0)testKey=stableFingerprint(scene+"|"+actionSignature+"|"+testLabel(test)+"|"+ruleId);
            String campaign=stableFingerprint(db.getActiveMapProfile()+"|"+db.getCampaign().toString());String target=stableFingerprint(db.getActiveMapProfile()+"|"+test.optString("target",test.optString("target_name","scene")));String consequence=stableFingerprint("consequence|"+campaign+"|"+testKey);
            test.put("test_key",testKey).put("action_signature",actionSignature).put("scene_fingerprint",scene).put("source_rule_id",ruleId).put("campaign_fingerprint",campaign).put("target_signature",target).put("consequence_key",consequence).put("created_at",System.currentTimeMillis());
            return test;
        }catch(Exception error){AppLog.e("PendingTest","Não foi possível identificar o teste.",error);return raw==null?new JSONObject():raw;}
    }

    private JSONObject rollBindingContext(JSONObject test,JSONObject hero,String outcome,String formula,String rollMode,int naturalRoll,int modifier,String modifierSource)throws Exception{
        return new JSONObject().put("actor_character_id",hero.optLong("id",hero.optLong("character_id",0))).put("actor_name",hero.optString("name"))
            .put("test_key",test.optString("test_key")).put("action_signature",test.optString("action_signature")).put("source_rule_id",test.optString("source_rule_id"))
                .put("procedure_id",test.optString("procedure_id")).put("scene_fingerprint",test.optString("scene_fingerprint")).put("campaign_fingerprint",test.optString("campaign_fingerprint"))
                .put("target_signature",test.optString("target_signature")).put("consequence_key",test.optString("consequence_key")).put("formula",formula).put("modifier",modifier).put("modifier_source",modifierSource)
                .put("roll_mode",rollMode).put("natural_roll",naturalRoll).put("critical",naturalRoll==20).put("critical_failure",naturalRoll==1).put("outcome",outcome);
    }

    private String stableFingerprint(String value){try{MessageDigest md=MessageDigest.getInstance("SHA-256");byte[] digest=md.digest((value==null?"":value).getBytes("UTF-8"));StringBuilder out=new StringBuilder();for(int i=0;i<16&&i<digest.length;i++)out.append(String.format(Locale.US,"%02x",digest[i]));return out.toString();}catch(Exception error){return UUID.nameUUIDFromBytes((value==null?"":value).getBytes()).toString();}}

    private String normalizeRollMode(String raw){String s=raw==null?"":raw.toLowerCase(Locale.US);if(s.contains("infort")||s.contains("desvantagem"))return "Infortúnio";if(s.contains("fortun")||s.contains("vantagem"))return "Fortuna";return "Normal";}

    private void sendAi(final String mode,String userText){sendAi(mode,userText,null);}

    private void sendAi(final String mode,String userText,final String inputChannel){
        if(inputChannel!=null&&!"PLAYER_ACTION".equals(inputChannel)&&!"GM_HELP".equals(inputChannel)){toast("Canal de entrada inválido.");return;}
        if(aiBusy){toast("Aguarde a resposta atual.");return;}
        String preparedText=userText==null?"":userText;
        final boolean rawOpening=RuleRetrievalEngine.isNarrativeOpeningRequest(preparedText);
        if("Narrador".equals(mode)&&!"GM_HELP".equals(inputChannel)&&!rawOpening)preparedText=prepareKingmakerPreludeAction(preparedText);
        final String requestedText=preparedText;
        final String mapContext=buildMapAiContext(requestedText);
        final JSONObject sceneSnapshot=copyJsonObject(db.getSceneState());
        final JSONObject mapSnapshot=copyJsonObject(db.getMapState());
        final JSONObject combatSnapshot=copyJsonObject(db.getCombatState());
        final boolean legacyWorld=false;
        final boolean economy=aiQuotaGovernor!=null&&aiQuotaGovernor.economyMode();
        final boolean openingRequest=RuleRetrievalEngine.isNarrativeOpeningRequest(requestedText);
        final long ruleSearchWatchdog=openingRequest?OPENING_RULE_SEARCH_WATCHDOG_MS:RULE_SEARCH_WATCHDOG_MS;
        final long pipelineId=++aiPipelineGeneration;
        final boolean contextOnlyHelp="GM_HELP".equals(inputChannel)&&BraseiroNarrativeDirector.classify(requestedText)!=BraseiroNarrativeDirector.Intent.RULE_QUERY;
        final boolean combatNeedsRules=combatSnapshot.optInt("running",0)==1&&"Narrador".equals(mode)&&!contextOnlyHelp;
        final boolean retrievalNeeded=!openingRequest&&(combatNeedsRules||RuleRetrievalEngine.shouldRetrieve(mode,requestedText,lastNarration,sceneSnapshot));
        final String ruleScope=SceneRuleCache.scope(sceneSnapshot,mapSnapshot,combatSnapshot);
        final String ruleCacheKey=RuleRetrievalEngine.retrievalCacheKey(mode,requestedText,lastNarration,sceneSnapshot);
        if(!openingRequest&&combatSnapshot.optInt("running",0)==1){String state=combatSnapshot.optString("state","");if(CombatStateMachine.ACTIVE_ROUND.equals(state))db.transitionCombatState(CombatStateMachine.RESOLVING,new JSONObject());}
        aiBusy=true;streamingNarration="";
        if("Narrador".equals(mode)&&!"GM_HELP".equals(inputChannel))onMasterNarrationStarted();
        if("Mestre IA".equals(currentScreen))showNarrator();
        if(contextOnlyHelp){JSONObject skipped=noRuleRetrievalBundle("gm_help_context_only","Pergunta contextual fora da ficção: responder pelo estado atual sem consultar regras nem avançar a cena.");deliverAiRuleSearch(pipelineId,mode,requestedText,mapContext,new RuleRetrievalEngine.Result(skipped,new ArrayList<JSONObject>()),null,inputChannel);return;}
        if(openingRequest){
            setStatus("Abertura narrativa: sem consulta aos manuais; montando campanha, cena, NPCs e Mundo Vivo…");
            JSONObject skipped=noRuleRetrievalBundle("opening_narrative_direct","A primeira cena é ficção. Não consulte manuais nem responda sobre regras; qualquer mecânica futura será recuperada somente quando a ação do jogador realmente exigir.");
            try{skipped.put("opening_narrative",true).put("opening_no_rag",true);}catch(Exception ignored){AppLog.ignored("MainActivity","Falha ao marcar abertura sem RAG.",ignored);}
            deliverAiRuleSearch(pipelineId,mode,requestedText,mapContext,new RuleRetrievalEngine.Result(skipped,new ArrayList<JSONObject>()),null,inputChannel);return;
        }
        if(!retrievalNeeded){
            setStatus("Cena ficcional: nenhuma consulta mecânica necessária; montando o estado da campanha...");
            JSONObject skipped=noRuleRetrievalBundle("not_required_fiction","A ação não exige procedimento mecânico novo. Continue a ficção com o estado persistido; se surgir teste ou consequência mecânica, o aplicativo exigirá regra específica antes de aplicá-la.");
            deliverAiRuleSearch(pipelineId,mode,requestedText,mapContext,new RuleRetrievalEngine.Result(skipped,new ArrayList<JSONObject>()),null,inputChannel);return;
        }
        RuleRetrievalEngine.Result cachedRules=sceneRuleCache.get(ruleScope,ruleCacheKey);
        if(cachedRules!=null){
            setStatus("Regra já conhecida nesta cena; reutilizando a prova local sem nova busca...");
            deliverAiRuleSearch(pipelineId,mode,requestedText,mapContext,cachedRules,null,inputChannel);return;
        }
        setStatus(openingRequest?"Consultando o índice local para ancorar somente as regras pertinentes da abertura...":"Consultando uma regra/procedimento novo para esta cena...");
        ui.postDelayed(new Runnable(){public void run(){
            if(!aiBusy||pipelineId!=aiPipelineGeneration||aiRuleSearchResolvedPipeline==pipelineId)return;
            JSONObject timedOut=new JSONObject();
            try{timedOut.put("required",true).put("status","retrieval_timeout").put("error","A busca local excedeu o limite seguro de espera.")
                    .put("evidence",new JSONArray()).put("structured_rules",new JSONArray()).put("evidence_count",0).put("sufficient_for_mechanics",false)
                    .put("opening_narrative",openingRequest).put("instruction",openingRequest?"A abertura pode continuar como ficção; nenhuma consequência mecânica pode ser aplicada sem evidência específica.":"A narração pode continuar sem consequências mecânicas; a busca atrasada não pode aplicar efeitos depois desta cena.");}
            catch(Exception ignored){AppLog.ignored("MainActivity","Falha ao registrar timeout da recuperação de regras.",ignored);}
            RuleRetrievalEngine.Result fallback=new RuleRetrievalEngine.Result(timedOut,new ArrayList<JSONObject>());
            deliverAiRuleSearch(pipelineId,mode,requestedText,mapContext,fallback,null,inputChannel);
        }},ruleSearchWatchdog);
        AppExecutors.io().execute(new Runnable(){public void run(){
            RuleRetrievalEngine.Result retrieval;
            try{
                RuleRetrievalEngine engine=ruleRetrievalEngine==null?new RuleRetrievalEngine(db):ruleRetrievalEngine;
                retrieval=engine.retrieve(mode,requestedText,lastNarration,sceneSnapshot,legacyWorld,economy);
                sceneRuleCache.put(ruleScope,ruleCacheKey,retrieval);
            }catch(Throwable failure){
                AppLog.e("MainActivity","Falha na recuperação obrigatória dos manuais.",failure);
                JSONObject blocked=new JSONObject();
                try{blocked.put("required",true).put("status","error").put("error",safeMessage(failure)).put("evidence",new JSONArray()).put("structured_rules",new JSONArray()).put("evidence_count",0).put("sufficient_for_mechanics",false);}catch(Exception ignored){AppLog.ignored("MainActivity","Falha ao registrar bloqueio de regras.",ignored);}
                retrieval=new RuleRetrievalEngine.Result(blocked,new ArrayList<JSONObject>());
            }
            final RuleRetrievalEngine.Result readyRetrieval=retrieval;
            ui.post(new Runnable(){public void run(){deliverAiRuleSearch(pipelineId,mode,requestedText,mapContext,readyRetrieval,null,inputChannel);}});
        }});
    }

    private JSONObject noRuleRetrievalBundle(String status,String instruction){
        JSONObject out=new JSONObject();try{out.put("required",false).put("status",status).put("world","pathfinder_2e").put("mechanical_candidate",false).put("evidence",new JSONArray()).put("structured_rules",new JSONArray()).put("evidence_count",0).put("sufficient_for_mechanics",false).put("mechanics_blocked",true).put("instruction",instruction);}catch(Exception ignored){AppLog.ignored("MainActivity","Falha ao montar estado de consulta dispensada.",ignored);}return out;
    }

    private synchronized boolean claimAiRuleSearch(long pipelineId){
        if(!aiBusy||pipelineId!=aiPipelineGeneration||aiRuleSearchResolvedPipeline==pipelineId)return false;
        aiRuleSearchResolvedPipeline=pipelineId;return true;
    }

    

    private void deliverAiRuleSearch(final long pipelineId,final String mode,final String requestedText,final String mapContext,final RuleRetrievalEngine.Result retrieval,MasterOrchestrator.Plan ignoredPlan,final String inputChannel){
        if(!claimAiRuleSearch(pipelineId))return;
        String status=retrieval==null?"":retrieval.bundle.optString("status");
        boolean opening=RuleRetrievalEngine.isNarrativeOpeningRequest(requestedText)||(retrieval!=null&&retrieval.bundle.optBoolean("opening_narrative",false));
        int evidence=retrieval==null?0:retrieval.bundle.optInt("evidence_count",retrieval.hits==null?0:retrieval.hits.size());
        boolean grounded=("opening_rules_ready".equals(status)||"opening_rules_partial".equals(status))&&evidence>0;
        if("retrieval_timeout".equals(status)){setStatus(opening?"A consulta específica excedeu o limite; a abertura continuará com o contexto completo da campanha e sem efeitos mecânicos não comprovados.":"A busca local demorou demais; o Mestre continuará com o contexto completo da campanha, sem efeitos mecânicos não comprovados.");}
        if(opening&&"opening_narrative_direct".equals(status)){setStatus("Abertura narrativa isolada de regras; montando o estado da campanha…");}
        else if(opening&&!grounded&&!"retrieval_timeout".equals(status)){setStatus("A abertura seguirá pela camada ficcional segura enquanto regras permanecem bloqueadas.");}
        if(masterOrchestrator==null){continueSendAiAfterRuleSearch(mode,requestedText,mapContext,retrieval,null);return;}
        if(opening)adventureStartupCoordinator.phase(AdventureStartupCoordinator.Phase.CONTEXT,"Montando game_bus e contexto operacional");setStatus(opening?"Montando campanha, cena, personagens e Mundo Vivo…":"Regras localizadas; montando o estado da campanha...");
        AppExecutors.io().execute(new Runnable(){public void run(){
            MasterOrchestrator.Plan plan=null;Throwable failure=null;
            try{plan=masterOrchestrator.prepare(mode,requestedText,mapContext,audioDiagnosticSnapshot(),retrieval==null?new JSONObject():retrieval.bundle,inputChannel);}
            catch(Throwable error){failure=error;AppLog.e("MainActivity","Falha ao montar o contexto operacional depois da busca de regras.",error);}
            final MasterOrchestrator.Plan readyPlan=plan;final Throwable readyFailure=failure;
            ui.post(new Runnable(){public void run(){
                if(!aiBusy||pipelineId!=aiPipelineGeneration)return;
                if(readyFailure!=null){aiBusy=false;activeMasterPlan=null;masterOrchestrator.setActivePlanForValidation(null);setStatus("A busca de regras terminou, mas o contexto da campanha não pôde ser montado: "+safeMessage(readyFailure));toast("Falha ao preparar o estado da campanha. Nenhuma chamada ao Gemini foi feita.");if("Mestre IA".equals(currentScreen))showNarrator();return;}
                continueSendAiAfterRuleSearch(mode,requestedText,mapContext,retrieval,readyPlan);
            }});
        }});
    }

    /** Continua a chamada somente depois que a biblioteca local terminou. */
    private void continueSendAiAfterRuleSearch(final String mode,final String userText,final String mapContext,RuleRetrievalEngine.Result retrieval,MasterOrchestrator.Plan preparedPlan){
        if(!aiBusy)return;
        activeRuleRetrieval=retrieval==null?new JSONObject():retrieval.bundle;
        activeMasterPlan=preparedPlan;
        boolean openingRequest=RuleRetrievalEngine.isNarrativeOpeningRequest(userText)||activeRuleRetrieval.optBoolean("opening_narrative",false);
        String openingStatus=activeRuleRetrieval.optString("status","");
        int openingEvidence=activeRuleRetrieval.optInt("evidence_count",activeRuleRetrieval.optJSONArray("evidence")==null?0:activeRuleRetrieval.optJSONArray("evidence").length());
        boolean openingGrounded=("opening_rules_ready".equals(openingStatus)||"opening_rules_partial".equals(openingStatus))&&openingEvidence>0;
        boolean openingDirect=openingRequest&&"opening_narrative_direct".equals(openingStatus);
        if(openingDirect){
            try{activeRuleRetrieval.put("required",false).put("opening_no_rag",true).put("evidence",new JSONArray()).put("structured_rules",new JSONArray()).put("evidence_count",0).put("sufficient_for_mechanics",false).put("mechanics_blocked",true);}catch(Exception ignored){AppLog.ignored("MainActivity","Falha ao isolar abertura de regras.",ignored);}
            openingGrounded=true;
        }else if(openingRequest&&!openingGrounded){
            JSONObject hot=EssentialRulesCache.snapshot(activeWorldProfile());try{activeRuleRetrieval.put("status","opening_fiction_grounded").put("essential_rules_cache",hot).put("sufficient_for_mechanics",false).put("mechanics_blocked",true).put("opening_narrative",true);}catch(Exception ignored){AppLog.ignored("MainActivity","Falha ao anexar cache essencial.",ignored);}
            openingStatus="opening_fiction_grounded";openingGrounded=true;
        }
        if(activeMasterPlan!=null&&!activeMasterPlan.contextReady){if(masterOrchestrator!=null)masterOrchestrator.setActivePlanForValidation(null);String reason=activeMasterPlan.contextError.length()==0?"O estado operacional não pôde ser montado com segurança.":activeMasterPlan.contextError;activeMasterPlan=null;aiBusy=false;toast("O Mestre foi bloqueado para não narrar com contexto incompleto.");setStatus(reason);if("Mestre IA".equals(currentScreen))showNarrator();return;}
        if(masterOrchestrator!=null)masterOrchestrator.setActivePlanForValidation(activeMasterPlan);
        final String effectiveUserText=activeMasterPlan==null?userText:activeMasterPlan.userPrompt;
        final String model=prefs.getString("text_model","gemini-3.5-flash-lite").trim();pendingAiModel=model;
        if(!openingRequest&&masterOrchestrator!=null&&activeMasterPlan!=null){String cached=masterOrchestrator.cachedResponse(activeMasterPlan,model,mode);if(cached.length()>0){lastAiMode=mode;lastPrompt=effectiveUserText;pendingAiInputChars=0;aiBusy=false;handleAiResponse(cached,userText);setStatus("Resposta idêntica recuperada do cache local; nenhuma chamada Gemini foi consumida.");return;}}
        List<JSONObject> localHits=retrieval==null?new ArrayList<JSONObject>():retrieval.hits;
        prioritizeAttachedLocalHits(localHits);
        if(("Regras RAW/RAI".equals(mode)||"Sortear dos livros".equals(mode))&&localHits.isEmpty()){lastAiMode=mode;lastAiUsedRag=false;lastRagCitations=new JSONArray();lastNarration="Não encontrei, no índice local deste mundo, um trecho verificável que responda a esse pedido. Para não inventar uma regra, tabela, livro ou página, a resposta foi interrompida. Confirme que o manual correspondente está marcado como PRONTO e refaça a pergunta com o nome da regra, criatura, magia, local ou tabela.";lastVisualPrompt="";currentOptions=new JSONArray();pendingTest=new JSONObject();prefs.edit().remove("last_rag_citations").putString("last_manual_context","Nenhuma fonte verificável encontrada.").apply();persistStory(userText);aiBusy=false;setStatus("Resposta bloqueada por falta de fonte local verificável.");showNarrator();return;}
        lastAiMode=mode;lastAiManuals=new JSONArray();lastRagCitations=openingDirect?new JSONArray():buildLocalManualCitations(localHits,effectiveUserText);lastAiUsedRag=!openingDirect&&lastRagCitations.length()>0;
        if(lastRagCitations.length()>0)prefs.edit().putString("last_rag_citations",lastRagCitations.toString()).apply();else prefs.edit().remove("last_rag_citations").apply();
        String retrievalStatus=activeRuleRetrieval.optString("status","unknown");
        String manualSummary;
        if("opening_narrative_direct".equals(retrievalStatus))manualSummary="";
        else if("not_required_fiction".equals(retrievalStatus))manualSummary="CENA FICCIONAL: nenhuma consulta mecânica foi necessária; o Mestre continua com o estado persistido sem pesquisar os manuais.";
        else if("scene_rule_cache_hit".equals(retrievalStatus))manualSummary="CACHE DE CENA: a regra/procedimento pertinente já havia sido recuperado nesta cena; a mesma prova local foi reutilizada sem nova busca.";
        else manualSummary=lastAiUsedRag?"ÍNDICE LOCAL: "+localHits.size()+" passagens recuperadas pelo índice invertido local do aparelho.":"ÍNDICE LOCAL: consulta necessária foi executada, mas nenhuma passagem suficientemente pertinente foi encontrada; mudanças mecânicas ficarão bloqueadas.";
        if("index_unavailable".equals(retrievalStatus))manualSummary="ÍNDICE LOCAL INDISPONÍVEL: nenhum manual deste mundo está pronto; a cena pode continuar sem mutações mecânicas.";
        else if("index_incomplete".equals(retrievalStatus))manualSummary="ÍNDICE LOCAL INCOMPLETO: "+activeRuleRetrieval.optInt("ready_manuals",0)+" de "+activeRuleRetrieval.optInt("enabled_manuals",0)+" manuais habilitados estão prontos; novas consequências mecânicas permanecem bloqueadas.";
        else if("opening_rules_ready".equals(retrievalStatus))manualSummary="ABERTURA ANCORADA EM REGRAS: "+activeRuleRetrieval.optInt("evidence_count",localHits.size())+" passagens pertinentes foram recuperadas antes da primeira cena; elas orientam o enquadramento, sem impor teste antecipado.";
        else if("opening_rules_partial".equals(retrievalStatus))manualSummary="ABERTURA ANCORADA EM ÍNDICE PARCIAL: "+activeRuleRetrieval.optInt("evidence_count",localHits.size())+" passagens pertinentes foram recuperadas e usadas para enquadrar a cena; efeitos mecânicos permanecem bloqueados até a indexação terminar.";
        else if("opening_fiction_grounded".equals(retrievalStatus))manualSummary="ABERTURA FICCIONAL SEGURA: o cache de regras essenciais enquadra a cena, mas nenhuma consequência mecânica será aplicada sem evidência específica.";
        else if("opening_no_relevant_evidence".equals(retrievalStatus)||"opening_index_incomplete".equals(retrievalStatus))manualSummary="ABERTURA SEM PASSAGEM PERTINENTE: a busca local foi executada antes da primeira cena, mas não encontrou regra compatível; a abertura continuará somente como ficção, sem teste ou consequência mecânica.";
        else if("retrieval_timeout".equals(retrievalStatus))manualSummary="BUSCA LOCAL ENCERRADA PELO LIMITE DE ESPERA: esta cena continua apenas como ficção e não pode aplicar consequências mecânicas.";
        if(openingDirect)prefs.edit().remove("last_manual_context").remove("last_rag_citations").apply();else prefs.edit().putString("last_manual_context",manualSummary).apply();
        String localContext=openingDirect?"":buildLocalManualContext(localHits,effectiveUserText)+buildRuleRetrievalContext(activeRuleRetrieval);
        if(openingRequest)adventureStartupCoordinator.phase(AdventureStartupCoordinator.Phase.NARRATIVE,"Escrevendo a primeira cena");
        final String key=geminiKey();
        if(key.trim().length()<20){runOfflineMaster(mode,userText,localHits,"chave Gemini ausente");return;}
        if(masterOrchestrator!=null&&!masterOrchestrator.canCall()){runOfflineMaster(mode,userText,localHits,"limite remoto diário atingido");return;}
        final String sys=buildSystemPrompt(mode,effectiveUserText,(lastAiUsedRag?buildLocalCatalogSummary(localHits):"Nenhuma prova manual pertinente foi recuperada.")+"\n\nESTADO DA BIBLIOTECA: "+manualSummary+localContext);
        final ArrayList<String> noRemoteFiles=new ArrayList<String>();
        lastPrompt=effectiveUserText;pendingAiInputChars=sys.length()+effectiveUserText.length();if(aiQuotaGovernor!=null&&!aiQuotaGovernor.canCall(pendingAiInputChars)){runOfflineMaster(mode,userText,localHits,"orçamento remoto insuficiente para esta cena");return;}streamingNarration="";lastStreamUiAt=0L;lastStreamUiLength=0;lastStreamPostAt=0L;final long requestId=++aiRequestGeneration;if(narrativeAudio!=null)narrativeAudio.cancelNarration();
        if("not_required_fiction".equals(retrievalStatus))setStatus("Cena ficcional: sem consulta de regras; o Mestre está escrevendo com o estado vivo da campanha...");
        else if("scene_rule_cache_hit".equals(retrievalStatus))setStatus("Regra reutilizada do cache desta cena; nenhuma nova busca foi feita...");
        else setStatus(lastAiUsedRag?"Manuais consultados quando necessário; o Mestre está escrevendo em uma única chamada...":"Consulta mecânica concluída sem prova suficiente; o Mestre continuará somente a ficção... "+(masterOrchestrator==null?"":masterOrchestrator.quotaStatus()));
        if("Mestre IA".equals(currentScreen))showNarrator();
        gemini.generateTextWithFilesStreaming(key,model,sys,effectiveUserText,noRemoteFiles,new GeminiService.StreamingTextCallback(){
            public void onPartial(String rawPartial){streamNarrationPartial(requestId,rawPartial);}
            public void onSuccess(final String text){ui.post(new Runnable(){public void run(){if(requestId!=aiRequestGeneration)return;acceptOrRepairNarration(mode,userText,text,sys,key,model,requestId,0);}});}
            public void onError(final String error){ui.post(new Runnable(){public void run(){if(requestId!=aiRequestGeneration)return;if(streamingNarration.length()>240){lastNarration=completeNarrationSafely(streamingNarration);lastVisualPrompt=sanitizeVisualSource(lastNarration);JSONArray fallbackHistory=SceneOptionDiversifier.parseHistory(db.getSceneOptionHistory());currentOptions=SceneOptionDiversifier.ensureAlways(new JSONArray(),fallbackHistory,lastNarration,userText,db.getSceneState(),db.getMasterRuntimeState().optInt("beat_no",0)+1);pendingTest=new JSONObject();persistStory(userText);if(masterOrchestrator!=null)masterOrchestrator.afterAccepted(activeMasterPlan,lastNarration,pendingAiInputChars,streamingNarration.length());aiBusy=false;streamingNarration="";setStatus("A conexão terminou, mas o trecho narrativo recebido foi concluído e preservado sem uma segunda chamada.");showNarrator();return;}if(aiQuotaGovernor!=null)aiQuotaGovernor.recordCall(pendingAiInputChars,streamingNarration.length());aiBusy=false;streamingNarration="";runOfflineMaster(mode,userText,localHits,"falha de conexão: "+error);}});}
        });
    }

    private void runOfflineMaster(String mode,String originalUserText,List<JSONObject> localHits,String reason){
        try{
            if(offlineMaster==null)offlineMaster=new OfflineMasterEngine();
            JSONObject envelope=offlineMaster.generate(mode,originalUserText,activeMasterPlan,localHits);
            lastAiMode=mode;pendingAiInputChars=0;aiBusy=false;streamingNarration="";
            handleAiResponse(envelope.toString(),originalUserText);
            setStatus("Mestre local offline ativo • "+reason+" • nenhuma chamada externa consumida");
        }catch(Exception failure){
            aiBusy=false;streamingNarration="";AppLog.e("MainActivity","Falha no Mestre local offline.",failure);
            toast("O Mestre local não conseguiu concluir a cena. Nenhuma alteração foi aplicada.");
            setStatus("Mestre local bloqueado por segurança: "+(failure.getMessage()==null?failure.getClass().getSimpleName():failure.getMessage()));
            if("Mestre IA".equals(currentScreen))showNarrator();
        }
    }

    private void acceptOrRepairNarration(final String mode,final String originalUserText,final String raw,final String systemPrompt,final String key,final String model,final long requestId,final int repairAttempt){
        if(requestId!=aiRequestGeneration)return;
        final boolean opening=isOpeningNarrationRequest(originalUserText);
        if(opening){
            final JSONObject envelope=parseAiEnvelope(raw);
            final String draft=PortugueseNarrationSanitizer.sanitize(completeNarrationSafely(envelope.optString("narration",raw))).trim();
            final String misroute=openingNarrationMisrouteReason(draft);
            final boolean leak=hasInternalNarrationLeak(draft);
            final int words=countNarrationWords(draft),paragraphs=countNarrationParagraphs(draft);
            final boolean needsExpansion=draft.length()<4800||paragraphs<6;
            final boolean unusable=draft.length()<100||leak||misroute.length()>0;

            // R25: a abertura NUNCA é barrada por npc_updates, retrato, token, memória ou outro
            // campo auxiliar. Esses dados são enriquecidos depois. O único gate aqui é a própria
            // narração, e até uma abertura curta é expandida pelo Gemini em vez de descartada.
            if((needsExpansion||unusable)&&repairAttempt<2&&key!=null&&key.trim().length()>=20){
                final JSONObject stableEnvelope=copyJsonObject(envelope);
                final boolean continuationPass=repairAttempt>0;
                final String openingSystem=continuationPass
                        ?"BRAS_OPENING_CONTINUATION BRAS_SINGLE_CALL. Você é o Motor Barbara continuando a PRIMEIRA CENA JOGÁVEL de Pathfinder 2e. Não recomece a cena, não repita o texto já escrito e não explique regras ou bastidores. Retorne SOMENTE JSON válido no formato {\"continuation\":\"...\",\"options\":[{\"label\":\"...\",\"description\":\"...\",\"action\":\"...\"}]}. Gere 4 a 6 opções concretas baseadas na cena COMPLETA."
                        :"BRAS_OPENING_COMPLETER BRAS_SINGLE_CALL. Você é o Motor Barbara completando a PRIMEIRA CENA JOGÁVEL de Pathfinder 2e. Preserve os fatos concretos já estabelecidos quando coerentes e reescreva livremente a forma para produzir uma abertura longa, imersiva e clara. NÃO explique regras, aplicativo, RAG, Motor Barbara ou bastidores. NÃO exija npc_updates, ficha, retrato, token ou metadados para a cena existir. Retorne SOMENTE JSON válido no formato {\"narration\":\"...\",\"options\":[{\"label\":\"...\",\"description\":\"...\",\"action\":\"...\"}]}. Gere 4 a 6 opções concretas e diferentes ligadas ao ponto de decisão final.";
                final int missingChars=Math.max(900,5200-draft.length());
                final String openingPrompt=continuationPass
                        ?"CENA JÁ ESCRITA (NÃO REPITA):\n"+draft+"\n\nCONTINUE EXATAMENTE DEPOIS DA ÚLTIMA FRASE COM CERCA DE "+Math.min(2200,missingChars+350)+" CARACTERES NOVOS, em 2 a 4 parágrafos. A cena principal completa deve ficar aproximadamente na faixa de 5.000 a 6.000 caracteres. A continuação deve aprofundar presença, espaço, tensão, relações, sinais observáveis e consequências em curso; não faça resumo nem catálogo. Feche a cena completa em uma decisão concreta. Em options, devolva 4 a 6 ações diferentes que só façam sentido por causa de fatos presentes nesta cena completa."
                        :"RASCUNHO RECEBIDO DO GEMINI:\n"+draft+"\n\nREESCREVA/EXPANDA ESTA CENA PRINCIPAL PARA APROXIMADAMENTE 5.000 A 6.000 CARACTERES, EM 6 A 8 PARÁGRAFOS SUBSTANCIAIS. Nos primeiros parágrafos deixe claros protagonista/foco, local, situação atual, pressão e por que isso importa. Use detalhes sensoriais com função, geografia acionável, pessoas/forças que possam reagir e consequências em curso. Não transforme ferramentas, materiais, arquitetura ou rotina em catálogo técnico. Termine em uma decisão concreta do jogador. Em options, devolva 4 a 6 ações específicas, distintas e diretamente ancoradas nessa decisão; não use opções genéricas. Não mencione estrutura de JSON, fontes, regras ou software.";
                final int repairInputChars=openingSystem.length()+openingPrompt.length();
                if(aiQuotaGovernor==null||aiQuotaGovernor.canCall(repairInputChars)){
                    setStatus(continuationPass?"A abertura ainda veio curta; o Motor Barbara está continuando a mesma cena…":"O Gemini trouxe uma abertura curta; o Motor Barbara está expandindo a mesma cena e reconstruindo as ações…");
                    gemini.generateText(key,openingLongFormModel(model),openingSystem,openingPrompt,new GeminiService.TextCallback(){
                        public void onSuccess(final String repairedRaw){ui.post(new Runnable(){public void run(){if(requestId!=aiRequestGeneration)return;try{JSONObject rep=parseAiEnvelope(repairedRaw);String candidate;if(continuationPass){String continuation=PortugueseNarrationSanitizer.sanitize(completeNarrationSafely(rep.optString("continuation",rep.optString("narration","")))).trim();candidate=continuation.length()>=80?(draft+"\n\n"+continuation):draft;}else{String repaired=PortugueseNarrationSanitizer.sanitize(completeNarrationSafely(rep.optString("narration",repairedRaw))).trim();candidate=repaired.length()>draft.length()?repaired:draft;}stableEnvelope.put("narration",candidate);JSONArray repairedOptions=rep.optJSONArray("options");if(repairedOptions!=null&&repairedOptions.length()>0)stableEnvelope.put("options",repairedOptions);stableEnvelope.put("opening_expanded_by_gemini",true).put("opening_completion_pass",repairAttempt+1);}catch(Exception ignored){AppLog.ignored("OpeningCompleter","Falha ao interpretar complemento; preservando cena já recebida.",ignored);}if(aiQuotaGovernor!=null)aiQuotaGovernor.recordCall(repairInputChars,repairedRaw==null?0:repairedRaw.length());acceptOrRepairNarration(mode,originalUserText,stableEnvelope.toString(),systemPrompt,key,model,requestId,repairAttempt+1);}});}
                        public void onError(final String error){ui.post(new Runnable(){public void run(){if(requestId!=aiRequestGeneration)return;try{stableEnvelope.put("narration",draft);stableEnvelope.put("opening_expansion_error",error);}catch(Exception ignored){AppLog.ignored("OpeningCompleter","Falha tolerada ao registrar indisponibilidade.",ignored);}acceptOrRepairNarration(mode,originalUserText,stableEnvelope.toString(),systemPrompt,key,model,requestId,repairAttempt+1);}});}
                    });
                    return;
                }
            }

            // Depois de uma tentativa de expansão, a cena útil SEMPRE começa. Identidade de NPC,
            // retrato e outros metadados são pós-processamento e nunca podem travar a aventura.
            if(draft.length()>=100&&!leak&&misroute.length()==0){
                try{envelope.put("narration",draft).put("opening_scene_started",true).put("opening_word_count",words).put("opening_paragraph_count",paragraphs);if(needsExpansion)envelope.put("opening_quality_warning","O Gemini não atingiu integralmente a faixa longa mesmo após complementação; a cena foi mantida para nunca travar a partida.");}catch(Exception ignored){AppLog.ignored("OpeningCompleter","Falha ao registrar telemetria da abertura.",ignored);}
                aiBusy=false;streamingNarration="";
                handleAiResponse(envelope.toString(),originalUserText);
                setStatus("Aventura iniciada pelo "+textModelStatus()+" • identidade de NPC e retratos são enriquecidos sem bloquear a cena.");
                return;
            }
            // Uma resposta meta ou vazia ainda não vira cena. Não inventamos uma falsa abertura local.
            aiBusy=false;streamingNarration="";
            setStatus("O Gemini não entregou uma cena ficcional utilizável. Toque em iniciar novamente; nenhum estado da aventura foi alterado.");
            if("Mestre IA".equals(currentScreen))showNarrator();
            return;
        }

        String problem="Narrador".equals(mode)?narrationQualityProblem(raw,originalUserText):"";
        if(problem.length()>0){
            JSONObject envelope=parseAiEnvelope(raw);
            String draft=PortugueseNarrationSanitizer.sanitize(completeNarrationSafely(envelope.optString("narration",raw)));
            final boolean nonAdvancingRepair=BraseiroNarrativeDirector.isNonAdvancing(originalUserText);final int repairMinLength=nonAdvancingRepair?8:240;
            if(draft.length()<repairMinLength){
                if(aiQuotaGovernor!=null)aiQuotaGovernor.recordCall(pendingAiInputChars,raw==null?0:raw.length());
                aiBusy=false;streamingNarration="";
                runOfflineMaster(mode,originalUserText,new ArrayList<JSONObject>(),"resposta remota incompleta");
                return;
            }
            if(repairAttempt<1&&key!=null&&key.trim().length()>=20){
                final JSONObject stableEnvelope=copyJsonObject(envelope);
                final String repairSystem=nonAdvancingRepair?
                    "BRAS_CONTEXT_EDITOR. Você é somente editor de resposta do Mestre. Reescreva a resposta para esclarecer a dúvida do jogador SEM fazer o tempo passar, SEM mover NPCs, SEM introduzir acontecimento novo, SEM transformar a pergunta em fala do personagem e SEM acrescentar ação, opção ou mecânica. Preserve somente os fatos já contidos na resposta. Seja direto e natural em português do Brasil. Retorne SOMENTE JSON válido no formato {\"narration\":\"...\"}."
                    :"BRAS_NARRATIVE_EDITOR. Você é somente editor de prosa. Reescreva a narração fornecida sem mudar nenhum fato, personagem, fala necessária, resultado, posição, item, regra, número, consequência ou estado. Corrija exclusivamente o problema de qualidade indicado. Use português do Brasil, espacialidade clara, ação concreta, poucos detalhes que trabalham, variedade sintática. Não acrescente opções, pistas, NPCs nem mecânicas. Retorne SOMENTE JSON válido no formato {\"narration\":\"...\"}.";
                final String repairProblem=problem;
                final String repairPrompt="PROBLEMA DETECTADO: "+repairProblem+"\nALVO DE FORMA: "+narrationQualityTarget(originalUserText)+"\n\nNARRAÇÃO A REESCREVER SEM ALTERAR FATOS:\n"+draft;
                final int repairInputChars=repairSystem.length()+repairPrompt.length();
                if(aiQuotaGovernor==null||aiQuotaGovernor.canCall(repairInputChars)){
                    setStatus(nonAdvancingRepair?"A direção narrativa está corrigindo o esclarecimento sem avançar a cena…":"A direção narrativa está corrigindo a prosa uma única vez…");
                    gemini.generateText(key,model,repairSystem,repairPrompt,new GeminiService.TextCallback(){
                        public void onSuccess(final String repairedRaw){ui.post(new Runnable(){public void run(){if(requestId!=aiRequestGeneration)return;String repaired="";try{JSONObject rep=parseAiEnvelope(repairedRaw);repaired=PortugueseNarrationSanitizer.sanitize(completeNarrationSafely(rep.optString("narration",repairedRaw)));}catch(Exception ignored){AppLog.ignored("NarrativeDirector","Falha ao interpretar revisão narrativa; preservando a cena original.",ignored);}if(aiQuotaGovernor!=null)aiQuotaGovernor.recordCall(repairInputChars,repairedRaw==null?0:repairedRaw.length());try{if(repaired.length()>=repairMinLength)stableEnvelope.put("narration",repaired);stableEnvelope.put("narrative_quality_repair",repairProblem);}catch(Exception ignored){AppLog.ignored("NarrativeDirector","Falha ao registrar revisão narrativa.",ignored);}acceptOrRepairNarration(mode,originalUserText,stableEnvelope.toString(),systemPrompt,key,model,requestId,1);}});}
                        public void onError(final String error){ui.post(new Runnable(){public void run(){if(requestId!=aiRequestGeneration)return;try{stableEnvelope.put("narration",draft);stableEnvelope.put("narrative_quality_repair_failed",error);}catch(Exception ignored){AppLog.ignored("NarrativeDirector","Falha tolerada ao registrar revisão indisponível.",ignored);}acceptOrRepairNarration(mode,originalUserText,stableEnvelope.toString(),systemPrompt,key,model,requestId,1);}});}
                    });
                    return;
                }
            }
            if(hasInternalNarrationLeak(draft)){aiBusy=false;streamingNarration="";runOfflineMaster(mode,originalUserText,new ArrayList<JSONObject>(),"resposta remota continha instruções internas");return;}
            try{envelope.put("narration",draft);envelope.put("quality_recovered_locally",problem);}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}
            aiBusy=false;streamingNarration="";
            if(masterOrchestrator!=null)masterOrchestrator.cacheResponse(activeMasterPlan,pendingAiModel,mode,envelope.toString());
            handleAiResponse(envelope.toString(),originalUserText);
            setStatus("Cena pronta • "+textModelStatus()+" • a revisão opcional de estilo não respondeu; o texto principal foi preservado.");
            return;
        }
        aiBusy=false;streamingNarration="";
        if(masterOrchestrator!=null)masterOrchestrator.cacheResponse(activeMasterPlan,pendingAiModel,mode,raw);
        handleAiResponse(raw,originalUserText);
        if(BraseiroNarrativeDirector.isNonAdvancing(originalUserText))setStatus("Dúvida respondida sem avançar a cena • "+textModelStatus());else setStatus("Cena pronta"+(lastAiUsedRag?" • fonte local consultada":"")+" • "+textModelStatus());
    }

    private String openingLongFormModel(String configured){String model=configured==null?"":configured.trim();if("gemini-3.5-flash-lite".equalsIgnoreCase(model))return "gemini-3.5-flash";if("gemini-2.5-flash-lite".equalsIgnoreCase(model))return "gemini-2.5-flash";return model.length()==0?"gemini-3.5-flash":model;}

    private String textModelStatus(){String configured=prefs==null?"":prefs.getString("text_model","gemini-3.5-flash-lite").trim();String actual=gemini==null?"":gemini.getLastWorkingTextModel().trim();if(actual.length()==0)actual=configured;if(configured.length()==0||actual.equalsIgnoreCase(configured))return "Gemini "+actual;return "Gemini "+actual+" (fallback; configurado: "+configured+")";}
    private String ttsModelStatus(){String configured=prefs==null?"":canonicalConfiguredTtsModel(prefs.getString("tts_model","gemini-2.5-flash-preview-tts"));String actual=gemini==null?"":gemini.getLastWorkingTtsModel().trim();if(actual.length()==0)actual=configured;if(configured.length()==0||actual.equalsIgnoreCase(configured))return actual;return actual+" (fallback de "+configured+")";}
    private static String compactGeminiFailure(String error){String raw=error==null?"erro sem detalhes":error.replaceAll("\\s+"," ").trim();String low=raw.toLowerCase(Locale.US);if(low.contains("401")||low.contains("api key not valid")||low.contains("invalid api key"))return "chave Gemini inválida";if(low.contains("403")||low.contains("permission_denied"))return "modelo/projeto sem permissão";if(low.contains("429")||low.contains("quota")||low.contains("resource_exhausted")||low.contains("rate limit"))return low.contains("limit: 0")?"cota deste modelo indisponível para esta chave":"limite temporário/cota do modelo";if(low.contains("404")||low.contains("not found"))return "modelo indisponível";if(low.contains("timeout")||low.contains("timed out"))return "tempo limite da API";return raw.length()>120?raw.substring(0,117)+"...":raw;}

    private String openingNarrationMisrouteReason(String narration){
        if(narration==null)return "narração vazia";String n=java.text.Normalizer.normalize(narration.toLowerCase(new Locale("pt","BR")),java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","");
        String[] markers={"pergunta sobre as regras","funcionamento da sessao","mestre do braseiro atua","aplicativo local administra","tres acoes disponiveis por turno","quatro graus de sucesso","biblioteca rag","fontes recuperadas","motor barbara","como arbitro e tradutor das mecanicas","na mesa viva, nenhum"};
        for(String m:markers)if(n.contains(m))return "a resposta caiu no canal de regras/meta em vez de abrir a aventura";
        String first=n.length()>1500?n.substring(0,1500):n;String[] micro={"formao","goiva","serrote","lixa","espiga","ranhura","encaixe","espessura","batente","travessa","lasca","rebite","parafuso","engrenagem","dobradica","carvalho","betula","tempera","costura","ponto de costura","fio encerado"};int hits=0;
        for(String term:micro)if(first.contains(term)&&++hits>=5)return "a abertura ficou presa em microdescrição técnica de ofício/material em vez de chegar ao conflito jogável";
        return "";
    }

    private String narrationQualityProblem(String raw,String userText){
        JSONObject env=parseAiEnvelope(raw);String narration=sanitizeNarrationPayload(env.optString("narration",raw)).trim();
        if(hasInternalNarrationLeak(narration))return "vazamento de instruções internas do motor na narração";
        String directed=BraseiroNarrativeDirector.qualityProblem(narration,recentNarrativeTexts(),userText);
        if(BraseiroNarrativeDirector.isNonAdvancing(userText))return directed;
        String tableDirected=LiveTableNarrativeDirector.qualityProblem(narration,braseiroNarrativeMemory(),db.getSceneState(),userText);
        if(tableDirected.length()>0)return tableDirected;
        boolean opening=isOpeningNarrationRequest(userText);
        if(opening){String misroute=openingNarrationMisrouteReason(narration);if(misroute.length()>0)return misroute;int words=countNarrationWords(narration),paragraphs=countNarrationParagraphs(narration);if(paragraphs<3)return "a abertura veio em "+paragraphs+" parágrafo(s); a apresentação inicial obrigatória precisa de 3 a 5 parágrafos substanciais";if(words<300)return "a abertura tem apenas "+words+" palavras; a apresentação inicial precisa desenvolver cenário, atividade, NPCs e ponto de decisão antes de devolver a vez";}
        if(directed.length()>0)return directed;
        if(narration.length()==0)return "narração vazia";char last=narration.charAt(narration.length()-1);if(last!='.'&&last!='!'&&last!='?'&&last!='…'&&last!='”'&&last!='\'')return "termina com uma frase incompleta";return "";
    }

    private boolean hasInternalNarrationLeak(String narration){
        if(narration==null)return false;String n=narration.toLowerCase(new Locale("pt","BR"));
        String[] markers={"ponto inicial catalogado desta aventura","referência do catálogo:","referencia do catalogo:","foco de regras para a abertura","scene_state.present_npcs","npc_updates","host_world_authority","duplicate_gemini_call","autoridade do aplicativo","continuidade preservada no banco local","sem depender de conexão externa","sem depender de conexao externa"};
        for(String marker:markers)if(n.contains(marker))return true;return false;
    }

    private String narrationQualityTarget(String userText){
        if(BraseiroNarrativeDirector.isNonAdvancing(userText))return "ESCLARECIMENTO: responda em 1 a 6 frases, sem avançar tempo, cena, NPCs ou estado e sem criar acontecimento novo no final.";
        boolean opening=isOpeningNarrationRequest(userText);String mode=currentMasterSceneMode();
        if(opening)return "ABERTURA JOGÁVEL: cena principal com 6 a 8 parágrafos substanciais, normalmente cerca de 5.000 a 6.000 caracteres. Nos primeiros 80 a 120 termos estabeleça protagonista/foco, lugar, situação atual, pressão e importância; detalhe sensorial só entra quando serve espaço, risco, pista, relação ou humor. Nada de microdescrição técnica de ofício ou objetos como enchimento. Termine em decisão concreta. Metadados de NPC nunca bloqueiam a cena: se algum campo auxiliar faltar, a narração continua e o aplicativo enriquece a identidade depois.";
        if("conversa".equals(mode))return "DIÁLOGO: responda naturalmente, encene o NPC enquanto fala e pare quando a resposta devolver agência; normalmente 25 a 140 palavras.";
        if("combate".equals(mode))return "AÇÃO: uma imagem dominante, causalidade física e geografia clara; normalmente 35 a 160 palavras, sem recapitular o combate.";
        if("viagem".equals(mode)||"tempo_livre".equals(mode)||"descanso".equals(mode))return "TRANSIÇÃO: comprima rotina e expanda somente mudança, descoberta ou consequência; normalmente 45 a 190 palavras.";
        return "BATIDA: não escreva por cota. Use somente o tamanho necessário para situar, mostrar o que mudou, destacar algo significativo e devolver uma decisão; normalmente 45 a 240 palavras.";
    }

    private String currentMasterSceneMode(){try{if(activeMasterPlan!=null&&activeMasterPlan.cognitivePlan!=null)return activeMasterPlan.cognitivePlan.optString("scene_mode","exploracao");}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}return "exploracao";}

    private String narrativeMemoryPrefKey(){return "narrative_director_memory_"+activeWorldProfile();}
    private String recentNarrationsPrefKey(){return "narrative_director_recent_"+activeWorldProfile();}
    private JSONObject narrativeSessionPreferences(){
        try{JSONObject party=db==null?new JSONObject():db.getPartyState();return new JSONObject(party.optString("session_preferences_json","{}"));}catch(Exception e){return new JSONObject();}
    }
    private void saveNarrativeSessionPreferences(JSONObject session){
        if(db==null)return;try{JSONObject party=db.getPartyState();party.put("session_preferences_json",session==null?"{}":session.toString());db.savePartyState(party);}catch(Exception e){AppLog.w("NarrativeDirector","Não foi possível espelhar a memória narrativa no backup portátil; mantendo a cópia local.",e);}
    }
    private JSONObject braseiroNarrativeMemory(){
        try{JSONObject session=narrativeSessionPreferences();JSONObject saved=session.optJSONObject("braseiro_narrative_memory");if(saved!=null)return saved;}catch(Exception ignored){AppLog.ignored("MainActivity","Memória narrativa persistente indisponível; usando fallback local.",ignored);}try{return new JSONObject(prefs.getString(narrativeMemoryPrefKey(),"{}"));}catch(Exception e){return new JSONObject();}
    }
    private void saveBraseiroNarrativeMemory(JSONObject memory){
        JSONObject safe=memory==null?new JSONObject():memory;if(prefs!=null)prefs.edit().putString(narrativeMemoryPrefKey(),safe.toString()).apply();try{JSONObject session=narrativeSessionPreferences();session.put("braseiro_narrative_memory",safe);saveNarrativeSessionPreferences(session);}catch(Exception e){AppLog.w("NarrativeDirector","Falha ao persistir memória narrativa no perfil da companhia.",e);}
    }
    private JSONArray recentNarrativeTexts(){
        try{JSONObject session=narrativeSessionPreferences();JSONArray saved=session.optJSONArray("braseiro_recent_narrations");if(saved!=null)return saved;}catch(Exception ignored){AppLog.ignored("MainActivity","Histórico narrativo persistente indisponível; usando fallback local.",ignored);}try{return new JSONArray(prefs.getString(recentNarrationsPrefKey(),"[]"));}catch(Exception e){return new JSONArray();}
    }
    private void rememberNarrativeText(String narration){
        if(narration==null||narration.trim().length()==0)return;JSONArray old=recentNarrativeTexts(),next=new JSONArray();for(int i=Math.max(0,old.length()-14);i<old.length();i++)next.put(old.opt(i));next.put(narration.length()>4200?narration.substring(0,4200):narration);if(prefs!=null)prefs.edit().putString(recentNarrationsPrefKey(),next.toString()).apply();try{JSONObject session=narrativeSessionPreferences();session.put("braseiro_recent_narrations",next);saveNarrativeSessionPreferences(session);}catch(Exception e){AppLog.w("NarrativeDirector","Falha ao persistir histórico narrativo no perfil da companhia.",e);}
    }

    private int countNarrationWords(String text){String clean=text==null?"":text.trim();if(clean.length()==0)return 0;return clean.split("\\s+").length;}
    private int countNarrationParagraphs(String text){String clean=text==null?"":text.trim();if(clean.length()==0)return 0;String[] blocks=clean.split("\\r?\\n\\s*");int count=0;for(String block:blocks)if(block!=null&&block.trim().length()>0)count++;return Math.max(1,count);}

    private void streamNarrationPartial(final long requestId,String rawPartial){final String partial=PortugueseNarrationSanitizer.sanitize(extractPartialNarration(rawPartial));if(partial.length()==0||requestId!=aiRequestGeneration)return;if(partial.length()<streamingNarration.length())return;streamingNarration=partial;if(!masterSideQueryActive)onNarrationChunk(partial);long now=System.currentTimeMillis();boolean ending=partial.endsWith(".")||partial.endsWith("!")||partial.endsWith("?")||partial.endsWith("…");if(!ending&&now-lastStreamPostAt<320L)return;lastStreamPostAt=now;ui.post(new Runnable(){public void run(){if(!aiBusy||requestId!=aiRequestGeneration)return;long uiNow=System.currentTimeMillis();boolean enoughTime=uiNow-lastStreamUiAt>=450L;boolean enoughText=partial.length()-lastStreamUiLength>=160;boolean finalPunctuation=partial.endsWith(".")||partial.endsWith("!")||partial.endsWith("?")||partial.endsWith("…");if(masterSideQueryActive){if(enoughTime&&(enoughText||finalPunctuation)){lastStreamUiAt=uiNow;lastStreamUiLength=partial.length();setStatus("Respondendo no painel auxiliar... "+partial.length()+" caracteres");}}else if(narratorOutput!=null&&enoughTime&&(enoughText||finalPunctuation)){lastStreamUiAt=uiNow;lastStreamUiLength=partial.length();narratorOutput.setText(partial+" ▌");setStatus("Escrevendo a cena... "+partial.length()+" caracteres");}}});}

    private void handleAiResponse(String raw,String action){
        JSONObject env=parseAiEnvelope(raw);if(masterOrchestrator!=null)env=masterOrchestrator.validateEnvelope(env,action);
        if(masterSideQueryActive){
            String answer=completeNarrationSafely(GeneratedTextSanitizer.narrative(env.optString("narration",raw)));String question=masterSideQueryText;JSONObject sideRetrieval=copyJsonObject(activeRuleRetrieval);JSONArray sideCitations=copyJsonArray(lastRagCitations);
            JSONObject support=MasterSupportPanelEngine.build(env,sideRetrieval,sideCitations,db.getSceneState(),safeActiveCharacters(),currentOptions,pendingTest,question);lastMasterSupport=MasterSupportPanelEngine.withAnswer(support,question,answer,sideRetrieval,sideCitations);prefs.edit().putString("last_master_support_json",lastMasterSupport.toString()).apply();saveBraseiroNarrativeMemory(BraseiroNarrativeDirector.recordClarification(braseiroNarrativeMemory(),question,answer));
            if(masterOrchestrator!=null)masterOrchestrator.afterAccepted(activeMasterPlan,answer,env,pendingAiInputChars,raw==null?0:raw.length());db.addAuditEvent("consulta_auxiliar","Pergunta ao Mestre sem avanço",question,"{}",lastMasterSupport.toString(),false);restoreAfterMasterSideQuery();setStatus("Pergunta respondida sem avançar a cena.");if("Mestre IA".equals(currentScreen))showNarrator();showMasterSideAnswerDialog(question,answer);return;
        }
        boolean nonAdvancing="Narrador".equals(lastAiMode)&&env.optBoolean("_non_advancing",BraseiroNarrativeDirector.isNonAdvancing(action));
        JSONArray previousOptions=currentOptions==null?new JSONArray():currentOptions;JSONArray previousCast=copyJsonArray(currentSceneCastPreview);String previousVisual=lastVisualPrompt==null?"":lastVisualPrompt;JSONObject previousAudio=lastAudioPlan==null?new JSONObject():copyJsonObject(lastAudioPlan);JSONObject previousPendingTest=pendingTest==null?new JSONObject():copyJsonObject(pendingTest);
        JSONArray optionHistory=SceneOptionDiversifier.parseHistory(db.getSceneOptionHistory());optionHistory=SceneOptionDiversifier.appendHistory(optionHistory,previousOptions);JSONArray opts=env.optJSONArray("options");ChoiceSplit choiceSplit=splitNarrationChoices(GeneratedTextSanitizer.narrative(env.optString("narration",raw)),opts);lastNarration=completeNarrationSafely(choiceSplit.narration);
        if(nonAdvancing){
            currentSceneCastPreview=previousCast;lastVisualPrompt=previousVisual;lastAudioPlan=previousAudio;pendingTest=previousPendingTest;currentOptions=previousOptions;saveBraseiroNarrativeMemory(BraseiroNarrativeDirector.recordClarification(braseiroNarrativeMemory(),action,lastNarration));
        }else{
            currentSceneCastPreview=buildSceneCastPreview(env);mergeNarratedKnownNpcs(currentSceneCastPreview,lastNarration);mergeExplicitlyNamedNpcHints(currentSceneCastPreview,lastNarration);synchronizeVisualSceneCast();prefs.edit().putString("last_scene_cast_preview",currentSceneCastPreview.toString()).apply();
            lastVisualPrompt=env.optString("visual_prompt","").trim();if(lastVisualPrompt.length()==0)lastVisualPrompt=sanitizeVisualSource(lastNarration);invalidateSceneImageIfContextChanged();lastAudioPlan=env.optJSONObject("audio_plan");if(lastAudioPlan==null)lastAudioPlan=new JSONObject();JSONObject pt=env.optJSONObject("pending_test");pendingTest=pt!=null&&pt.optBoolean("required",true)?ensurePendingTestIdentity(pt,action):new JSONObject();
            if(db.getCombatState().optInt("running",0)==1){JSONObject cs=db.getCombatState();String combatPhase=cs.optString("state","");if(pendingTest.length()>0){if(CombatStateMachine.ACTIVE_ROUND.equals(combatPhase))db.transitionCombatState(CombatStateMachine.RESOLVING,new JSONObject());db.transitionCombatState(CombatStateMachine.AWAITING_ROLL,pendingTest);}else if(CombatStateMachine.RESOLVING.equals(combatPhase)||CombatStateMachine.AWAITING_ROLL.equals(combatPhase))db.transitionCombatState(CombatStateMachine.ACTIVE_ROUND,new JSONObject());}
            boolean narrativeResponse="Narrador".equals(lastAiMode);JSONObject projectedScene=projectSceneForSuggestions(env,currentSceneCastPreview);JSONArray diversifiedOptions=narrativeResponse?SceneOptionDiversifier.ensureAlways(choiceSplit.options,optionHistory,lastNarration,action,projectedScene,db.getMasterRuntimeState().optInt("beat_no",0)+1):new JSONArray();currentOptions=diversifiedOptions;db.saveSceneOptionHistory(SceneOptionDiversifier.appendHistory(optionHistory,currentOptions).toString());
            if(isOpeningNarrationRequest(action)){prefs.edit().putString("recent_opening_texts_"+activeWorldProfile(),AdventureOpeningPlanner.rememberText(prefs.getString("recent_opening_texts_"+activeWorldProfile(),"[]"),lastNarration)).apply();adventureStartupCoordinator.phase(AdventureStartupCoordinator.Phase.COMPLETE,"Primeira cena persistida");}
            if(narrativeResponse){rememberNarrativeText(lastNarration);saveBraseiroNarrativeMemory(BraseiroNarrativeDirector.recordAdvancingMemory(braseiroNarrativeMemory(),action,lastNarration,env,projectedScene));}
            scheduleSceneNpcTokenBinding();
        }
        prefs.edit().putString("last_ai_response_mode",lastAiMode).apply();
        if(lastRagCitations!=null&&lastRagCitations.length()>0)try{env.put("sources",lastRagCitations);}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}
        boolean openingResponse=isOpeningNarrationRequest(action);JSONObject sourceAudit=openingResponse?openingNoSourceAudit():(lastAiUsedRag?buildRagSourceAudit(lastRagCitations):characterRulesValidator.auditAiAnswer(lastAiMode,env,lastAiManuals));lastMasterSupport=MasterSupportPanelEngine.build(env,activeRuleRetrieval,lastRagCitations,db.getSceneState(),safeActiveCharacters(),currentOptions,pendingTest,action);prefs.edit().putString("last_source_audit",sourceAudit.toString()).putString("last_audio_plan",lastAudioPlan.toString()).putString("last_master_support_json",lastMasterSupport.toString()).apply();db.addAuditEvent("ia",nonAdvancing?"Esclarecimento do Mestre — "+lastAiMode:"Resposta do Mestre — "+lastAiMode,sourceAudit.optString("warning",lastNarration.length()>140?lastNarration.substring(0,140):lastNarration),"{}",sourceAudit.toString(),false);
        boolean changes=!nonAdvancing&&(masterOrchestrator!=null?masterOrchestrator.hasStructuredChanges(env):(stateTransactionManager!=null&&stateTransactionManager.hasChanges(env)));long transactionId=-1;if(changes&&stateTransactionManager!=null)transactionId=stateTransactionManager.stage(env,lastNarration,action);prefs.edit().putString("last_state_update_summary",changes?"Consequências aguardando sua confirmação.":"").apply();if(!nonAdvancing)persistStory(action);
        if(masterOrchestrator!=null)masterOrchestrator.afterAccepted(activeMasterPlan,lastNarration,env,pendingAiInputChars,raw==null?0:raw.length());
        if(!nonAdvancing){JSONObject responseCombat=env.optJSONObject("combat");String responseCombatAction=responseCombat==null?"none":responseCombat.optString("action","none").toLowerCase(Locale.ROOT);boolean combatNarration=db.getCombatState().optInt("running",0)==1||"start".equals(responseCombatAction)||"update".equals(responseCombatAction);if(combatNarration&&lastNarration!=null&&lastNarration.trim().length()>0)prefs.edit().putString("last_combat_narration",lastNarration).apply();}
        onMasterNarrationEnded();if(!nonAdvancing&&!changes&&"Narrador".equals(lastAiMode))maybeOfferNarrativePoiProposal(lastNarration);
        setStatus(nonAdvancing?"Dúvida respondida. A cena, o tempo, os NPCs e o Mundo Vivo permaneceram no mesmo ponto.":(changes?"Cena pronta. Revise todas as consequências antes de aplicá-las.":"Cena pronta. Nenhuma mudança persistente foi proposta."));if("Mestre IA".equals(currentScreen))showNarrator();else if("Combate".equals(currentScreen))showCombat();if(changes)showTransactionReviewDialog(transactionId,env);
    }

    private void showTransactionReviewDialog(final long transactionId,final JSONObject envelope){
        final JSONObject stableEnvelope=copyJsonObject(envelope);
        try{
            if(!canShowDialog())return;
            String description=stateTransactionManager==null?"Mudanças persistentes propostas.":stateTransactionManager.describe(stableEnvelope);
            StringBuilder message=new StringBuilder("O Mestre propôs as mudanças abaixo. Nada foi aplicado ainda.\n\n")
                    .append(description)
                    .append("\n\nA narração permanece mesmo que você descarte as consequências.");
            final AlertDialog dialog=new AlertDialog.Builder(this)
                    .setTitle("Confirmar consequências da cena")
                    .setMessage(message.toString())
                    .setNegativeButton("SÓ NARRATIVA",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){
                        try{
                            if(stateTransactionManager!=null&&transactionId>0)stateTransactionManager.discarded(transactionId);
                            if(masterOrchestrator!=null)masterOrchestrator.afterConsequencesDiscarded(activeMasterPlan,stableEnvelope);
                            prefs.edit().putString("last_state_update_summary","Consequências descartadas pelo jogador.").apply();
                            setStatus("A narração foi mantida; nenhum estado, relógio, NPC ou recurso foi alterado.");
                        }catch(Exception error){
                            AppLog.e("TransactionReview","Falha ao descartar consequências.",error);
                            setStatus("A narração foi preservada, mas o registro do descarte falhou.");
                        }
                    }})
                    .setNeutralButton("REVISAR POR CATEGORIA",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){
                        try{d.dismiss();}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}
                        openPartialTransactionDialogSafely(transactionId,stableEnvelope);
                    }})
                    .setPositiveButton("APLICAR TUDO",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){
                        applyMasterConsequencesSafely(transactionId,stableEnvelope);
                    }})
                    .create();
            dialog.show();
        }catch(Throwable error){
            AppLog.e("TransactionReview","Não foi possível abrir a revisão de consequências.",error);
            setStatus("A cena foi preservada. A revisão de consequências não pôde ser aberta.");
            toast("A revisão não abriu. Nenhuma consequência foi aplicada.");
        }
    }

    private void openPartialTransactionDialogSafely(final long transactionId,final JSONObject envelope){
        if(!partialTransactionDialogOpening.compareAndSet(false,true)){
            toast("A revisão por categoria já está sendo aberta.");
            return;
        }
        final JSONObject stableEnvelope=copyJsonObject(envelope);
        Handler handler=ui==null?new Handler(Looper.getMainLooper()):ui;
        handler.postDelayed(new Runnable(){public void run(){
            try{
                if(!canShowDialog()){partialTransactionDialogOpening.set(false);return;}
                showPartialTransactionDialog(transactionId,stableEnvelope);
            }catch(Throwable error){
                partialTransactionDialogOpening.set(false);
                AppLog.e("TransactionReview","Falha ao abrir a revisão por categoria.",error);
                setStatus("A cena foi preservada. Nenhuma consequência foi aplicada.");
                toast("A revisão por categoria falhou sem alterar a campanha.");
            }
        }},180L);
    }

    private void showPartialTransactionDialog(final long transactionId,final JSONObject envelope){
        final JSONObject stableEnvelope=copyJsonObject(envelope);
        ScrollView scroll=new ScrollView(this);
        LinearLayout list=new LinearLayout(this);
        list.setOrientation(LinearLayout.VERTICAL);
        list.setPadding(dp(16),dp(8),dp(16),dp(18));
        scroll.addView(list,new ScrollView.LayoutParams(-1,-2));
        final LinkedChangeChecks checks=new LinkedChangeChecks();
        checks.add(list,"Heróis e inventário",arrayLength(stableEnvelope,"state_updates")>0,"state_updates");
        JSONObject combat=stableEnvelope.optJSONObject("combat");
        checks.add(list,"Combate",combat!=null&&!"none".equalsIgnoreCase(combat.optString("action","none")),"combat");
        JSONObject scene=stableEnvelope.optJSONObject("scene_state");
        checks.add(list,"Cena, local, clima e elenco",scene!=null&&scene.length()>0,"scene_state");
        checks.add(list,"Memória e decisões dos NPCs",arrayLength(stableEnvelope,"npc_updates")+arrayLength(stableEnvelope,"npc_cognition_updates")>0,"npcs");
        checks.add(list,"Conhecimentos, pistas e segredos revelados",arrayLength(stableEnvelope,"knowledge_updates")>0,"knowledge_updates");
        checks.add(list,"Missões, facções, relógios e eventos",arrayLength(stableEnvelope,"quest_updates")+arrayLength(stableEnvelope,"faction_updates")+arrayLength(stableEnvelope,"guild_updates")+arrayLength(stableEnvelope,"clock_updates")+arrayLength(stableEnvelope,"world_events")+arrayLength(stableEnvelope,"event_resolutions")+arrayLength(stableEnvelope,"pending_resolutions")>0,"world");
        checks.add(list,"Mapa e rota",arrayLength(stableEnvelope,"map_updates")>0,"map_updates");
        checks.add(list,"Tabuleiro tático",arrayLength(stableEnvelope,"tactical_updates")>0,"tactical_updates");
        checks.add(list,"Diário da campanha",arrayLength(stableEnvelope,"journal_updates")>0,"journal_updates");
        JSONObject tick=stableEnvelope.optJSONObject("_local_tick");
        checks.add(list,"Passagem do tempo, provisões e mundo fora de cena",tick!=null&&tick.length()>0,"_local_tick");
        if(checks.isEmpty())list.addView(text("Não há categorias persistentes disponíveis nesta cena. A narração foi preservada e nada foi aplicado.",13,TEXT,false));
        final AlertDialog dialog=new AlertDialog.Builder(this)
                .setTitle("Aplicação por categoria")
                .setView(scroll)
                .setNegativeButton("Cancelar",null)
                .setPositiveButton("APLICAR SELECIONADOS",null)
                .create();
        dialog.setOnDismissListener(new DialogInterface.OnDismissListener(){public void onDismiss(DialogInterface d){partialTransactionDialogOpening.set(false);}});
        dialog.setOnShowListener(new DialogInterface.OnShowListener(){public void onShow(DialogInterface d){
            Button apply=dialog.getButton(AlertDialog.BUTTON_POSITIVE);
            apply.setEnabled(!checks.isEmpty());
            apply.setOnClickListener(new View.OnClickListener(){public void onClick(View v){
                if(!consequenceApplyRunning.compareAndSet(false,true)){toast("A aplicação das consequências já está em andamento.");return;}
                try{
                    JSONObject selected=checks.filter(stableEnvelope);
                    if(selected.length()==0){toast("Nenhuma categoria pôde ser preparada. Nada foi aplicado.");return;}
                    dialog.dismiss();
                    applyMasterConsequences(transactionId,selected);
                }catch(Throwable error){
                    AppLog.e("TransactionReview","Falha antes de aplicar categorias; a campanha foi preservada.",error);
                    setStatus("A revisão por categoria falhou antes de alterar a campanha.");
                    toast("Nada foi aplicado. Tente abrir a revisão novamente.");
                }finally{consequenceApplyRunning.set(false);}
            }});
        }});
        dialog.show();
    }

    private void consumeMechanicalRolls(JSONObject envelope)throws Exception{
        java.util.LinkedHashMap<Long,JSONObject> bindings=new java.util.LinkedHashMap<Long,JSONObject>();collectMechanicalRollBindings(envelope,bindings);
        for(java.util.Map.Entry<Long,JSONObject> entry:bindings.entrySet()){JSONObject binding=entry.getValue();db.consumeDiceHistoryChecked(entry.getKey(),binding.optString("test_key"),binding.optString("consequence_key"));}
    }

    private void collectMechanicalRollBindings(Object node,java.util.Map<Long,JSONObject> out)throws Exception{
        if(node instanceof JSONObject){JSONObject object=(JSONObject)node;JSONObject calculation=object.has("source_type")?object.optJSONObject("calculation"):null;if(calculation!=null){long id=calculation.optLong("roll_id",0);String key=calculation.optString("test_key","").trim(),consequence=calculation.optString("consequence_key","").trim();if(id>0){if(key.length()==0||consequence.length()==0)throw new IllegalStateException("Consequência com roll_id sem test_key/consequence_key.");JSONObject previous=out.get(id);if(previous!=null&&(!previous.optString("test_key").equals(key)||!previous.optString("consequence_key").equals(consequence)))throw new IllegalStateException("A mesma rolagem foi associada a testes ou consequências diferentes.");out.put(id,new JSONObject().put("test_key",key).put("consequence_key",consequence));}}
            java.util.Iterator<String> keys=object.keys();while(keys.hasNext()){String key=keys.next();Object child=object.opt(key);if(child instanceof JSONObject||child instanceof JSONArray)collectMechanicalRollBindings(child,out);}
        }else if(node instanceof JSONArray){JSONArray array=(JSONArray)node;for(int i=0;i<array.length();i++){Object child=array.opt(i);if(child instanceof JSONObject||child instanceof JSONArray)collectMechanicalRollBindings(child,out);}}
    }

    private void applyMasterConsequencesSafely(final long transactionId,final JSONObject envelope){
        if(!consequenceApplyRunning.compareAndSet(false,true)){toast("A aplicação das consequências já está em andamento.");return;}
        try{applyMasterConsequences(transactionId,copyJsonObject(envelope));}
        finally{consequenceApplyRunning.set(false);}
    }

    private void applyMasterConsequences(final long transactionId,final JSONObject envelope){
        File rollback=null;
        try{
            if(envelope==null)throw new Exception("Consequências ausentes.");
            JSONObject validation=envelope.optJSONObject("_master_validation");
            if(validation==null||!validation.optBoolean("valid",false))throw new Exception("A resposta do Mestre não passou pela validação fechada.");
            rollback=safety.beforeDestructiveChange("aplicar consequências confirmadas da cena");
            if(stateTransactionManager!=null&&transactionId>0)stateTransactionManager.attachRollbackSnapshot(transactionId,rollback.getName());
            final boolean combatWasRunning=db.getCombatState().optInt("running",0)==1;
            final boolean[] combatRunningAfter=new boolean[]{combatWasRunning};
            final String[] combinedHolder=new String[]{""};
            db.runInTransactionChecked(new AppDb.CheckedTransaction(){public void run() throws Exception{
                JSONArray stateUpdates=envelope.optJSONArray("state_updates");
                JSONObject combatPlan=envelope.optJSONObject("combat");
                String stateSummary=applyStateUpdates(stateUpdates);
                String combatSummary=applyCombatPlan(combatPlan);
                String sceneSummary="";
                JSONObject scene=envelope.optJSONObject("scene_state");
                if(scene!=null&&scene.length()>0){
                    JSONObject before=db.getSceneState();
                    JSONObject after=sceneStateEngine.apply(envelope,lastNarration,db.getMapState());
                    sceneSummary="Cena: "+before.optString("location")+" → "+after.optString("location");
                }
                String combined=joinSummaries(stateSummary,combatSummary,sceneSummary,stateTransactionManager==null?"":stateTransactionManager.describe(envelope));
                if(combined.length()==0)combined="Consequências confirmadas.";
                combinedHolder[0]=combined;
                consumeMechanicalRolls(envelope);
                if(stateTransactionManager!=null&&transactionId>0)stateTransactionManager.applied(transactionId);
                db.addAuditEvent("mecânica","Consequências confirmadas pelo jogador",combined,"{}",envelope.toString(),true);
                // Último passo: só marca o plano em memória após todas as gravações
                // persistentes terem sido concluídas dentro da mesma transação SQLite.
                if(masterOrchestrator!=null)masterOrchestrator.afterConsequencesApplied(activeMasterPlan,envelope,lastNarration);
                syncPresentNpcsIntoRunningCombat(envelope);
                String combatAction=combatPlan==null?"none":combatPlan.optString("action","none").toLowerCase(Locale.ROOT);
                if(("start".equals(combatAction)||"update".equals(combatAction))&&lastNarration!=null&&lastNarration.trim().length()>0){
                    db.addJournalChecked("Combate • Rodada "+db.getCombatState().optInt("round_no",1),stripMarkdown(lastNarration),"Combate");
                }
                combatRunningAfter[0]=db.getCombatState().optInt("running",0)==1;
            }});
            if(masterOrchestrator!=null)masterOrchestrator.markConsequencesCommitted(activeMasterPlan);
            runWorldSixAsync();
            prefs.edit().putString("last_state_update_summary",combinedHolder[0]).apply();
            assignMissingNpcTokensAsync(false);
            screenCache.remove("Combate");screenCacheTime.remove("Combate");
            setStatus(combinedHolder[0]);
            if(!combatWasRunning&&combatRunningAfter[0]){currentScreen="";navigate("Combate");}
            else if("Combate".equals(currentScreen))showCombat();
            else if("Mestre IA".equals(currentScreen))showNarrator();
        }catch(Throwable error){
            AppLog.e("TransactionApply","Falha ao aplicar consequências; iniciando reversão.",error);
            if(masterOrchestrator!=null)masterOrchestrator.markConsequencesRolledBack(activeMasterPlan,envelope);
            String recovery="";
            // runInTransactionChecked encerra sem setTransactionSuccessful quando há exceção:
            // o SQLite já reverteu atomicamente todas as gravações desta batida. Não restauramos
            // um snapshot por cima de um banco saudável, pois isso criava uma segunda oportunidade
            // de falha e era a origem do aviso enganoso de recuperação automática.
            boolean databaseRolledBackCleanly=false;
            try{databaseRolledBackCleanly=db.quickIntegrityCheck();}
            catch(Throwable healthError){AppLog.e("TransactionApply","Não foi possível confirmar o rollback SQLite.",healthError);}
            if(databaseRolledBackCleanly)recovery=" O SQLite confirmou a reversão atômica; o snapshot de segurança foi preservado sem ser reaplicado.";
            else if(rollback!=null&&safety!=null){
                try{recovery=" Banco restaurado pelo snapshot "+safety.restoreSnapshot(rollback.getName())+".";}
                catch(Exception restoreError){AppLog.e("TransactionApply","A restauração do snapshot também falhou.",restoreError);recovery=" O banco requer verificação manual em Segurança; nenhum novo estado foi marcado como confirmado.";}
            }
            if(stateTransactionManager!=null&&transactionId>0){try{stateTransactionManager.failed(transactionId,String.valueOf(error.getMessage()));}catch(Exception ignored){AppLog.ignored("MainActivity","Falha ao registrar a transação como falha.",ignored);}}
            setStatus("Nenhuma consequência foi mantida após a falha."+recovery);
            if(canShowDialog())new AlertDialog.Builder(this)
                    .setTitle("Consequências não aplicadas")
                    .setMessage("O aplicativo encontrou uma falha e reverteu toda a operação.\n\n"+safeMessage(error)+recovery)
                    .setPositiveButton("Fechar",null)
                    .show();
            else toast("Consequências não aplicadas. A campanha foi preservada.");
        }
    }

    private JSONObject copyJsonObject(JSONObject source){
        try{return new JSONObject(source==null?"{}":source.toString());}
        catch(Exception ignored){return new JSONObject();}
    }

    private boolean canShowDialog(){
        if(isFinishing())return false;
        return Build.VERSION.SDK_INT<17||!isDestroyed();
    }

    private String safeMessage(Throwable error){
        String message=error==null?"Erro desconhecido.":String.valueOf(error.getMessage());
        if(message==null||"null".equals(message)||message.trim().length()==0)message=error==null?"Erro desconhecido.":error.getClass().getSimpleName();
        message=message.replaceAll("\\s+"," ").trim();
        return message.length()>300?message.substring(0,297)+"...":message;
    }

    private String joinSummaries(String... values){StringBuilder b=new StringBuilder();for(String v:values)if(v!=null&&v.trim().length()>0){if(b.length()>0)b.append("\n");b.append(v.trim());}return b.toString();}
    private int arrayLength(JSONObject o,String key){JSONArray a=o==null?null:o.optJSONArray(key);return a==null?0:a.length();}
    private final class LinkedChangeChecks{
        final HashMap<String,CheckBox> values=new HashMap<String,CheckBox>();
        void add(LinearLayout parent,String label,boolean visible,String key){
            if(!visible||parent==null||key==null)return;
            CheckBox c=check(label,true);
            c.setContentDescription("Aplicar categoria: "+label);
            values.put(key,c);
            parent.addView(c);
        }
        boolean isEmpty(){return values.isEmpty();}
        JSONObject filter(JSONObject source){
            JSONObject out=copyJsonObject(source);
            try{
                if(values.containsKey("state_updates")&&!values.get("state_updates").isChecked())out.put("state_updates",new JSONArray());
                if(values.containsKey("combat")&&!values.get("combat").isChecked())out.put("combat",new JSONObject().put("action","none"));
                if(values.containsKey("scene_state")&&!values.get("scene_state").isChecked())out.put("scene_state",new JSONObject());
                if(values.containsKey("npcs")&&!values.get("npcs").isChecked()){out.put("npc_updates",new JSONArray());out.put("npc_cognition_updates",new JSONArray());}
                if(values.containsKey("knowledge_updates")&&!values.get("knowledge_updates").isChecked())out.put("knowledge_updates",new JSONArray());
                if(values.containsKey("world")&&!values.get("world").isChecked()){out.put("quest_updates",new JSONArray());out.put("faction_updates",new JSONArray());out.put("guild_updates",new JSONArray());out.put("clock_updates",new JSONArray());out.put("world_events",new JSONArray());out.put("event_resolutions",new JSONArray());out.put("pending_resolutions",new JSONArray());}
                if(values.containsKey("map_updates")&&!values.get("map_updates").isChecked())out.put("map_updates",new JSONArray());
                if(values.containsKey("tactical_updates")&&!values.get("tactical_updates").isChecked())out.put("tactical_updates",new JSONArray());
                if(values.containsKey("journal_updates")&&!values.get("journal_updates").isChecked())out.put("journal_updates",new JSONArray());
                if(values.containsKey("_local_tick")&&!values.get("_local_tick").isChecked())out.put("_local_tick",new JSONObject());
            }catch(Exception error){
                AppLog.e("TransactionReview","Falha ao filtrar categorias; nenhuma alteração será aplicada.",error);
                return new JSONObject();
            }
            return out;
        }
    }

    

    

    private void prioritizeAttachedLocalHits(List<JSONObject> hits){
        if(hits==null||hits.size()<2)return;final long attached=attachedManualId(activeWorldProfile());if(attached<=0)return;
        Collections.sort(hits,new Comparator<JSONObject>(){public int compare(JSONObject a,JSONObject b){boolean aa=a.optLong("manual_id")==attached,bb=b.optLong("manual_id")==attached;if(aa!=bb)return aa?-1:1;return Integer.compare(b.optInt("_score"),a.optInt("_score"));}});
    }

    private JSONArray buildLocalManualCitations(List<JSONObject> hits,String query){
        JSONArray out=new JSONArray();if(hits==null)return out;HashSet<String> seen=new HashSet<String>();
        for(JSONObject hit:hits){try{String book=manualDisplayTitle(new JSONObject().put("title",hit.optString("manual_title",hit.optString("title","Manual"))));int page=hit.optInt("page_no",0);String excerpt=localExcerpt(hit.optString("content",hit.optString("excerpt")),query,560);String key=book+"|"+page;if(!seen.add(key))continue;out.put(new JSONObject().put("manual_id",hit.optLong("manual_id")).put("book",book).put("title",book).put("page",page).put("pdf_page",page).put("excerpt",excerpt).put("category",hit.optString("category","Trecho local")).put("rule_profile",hit.optString("rule_profile")).put("authority",hit.optString("_authority")).put("source","Índice local do aparelho").put("confirmed",true));if(out.length()>=6)break;}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}}
        return out;
    }

    private String buildLocalManualContext(List<JSONObject> hits,String query){
        if(hits==null||hits.isEmpty())return "";
        StringBuilder b=new StringBuilder("\n\nTRECHOS LOCAIS RECUPERADOS — use somente quando pertinentes; não invente página nem conteúdo:\n");int used=0;
        for(JSONObject hit:hits){String title=manualDisplayTitle(new JSONObjectSafe().putSafe("title",hit.optString("manual_title",hit.optString("title","Manual"))).value());String excerpt=localExcerpt(hit.optString("content",hit.optString("excerpt")),query,900);if(excerpt.length()<30)continue;String authority=hit.optString("_authority",hit.optString("rule_profile"));String block="\n[Fonte: "+title+" • página "+hit.optInt("page_no",0)+(authority.length()>0?" • "+authority:"")+"]\n"+excerpt+"\n";if(b.length()+block.length()>(masterOrchestrator!=null&&masterOrchestrator.economyMode()?4500:7000))break;b.append(block);used++;if(used>=(masterOrchestrator!=null&&masterOrchestrator.economyMode()?3:5))break;}return b.toString();
    }

    private String buildLocalCatalogSummary(List<JSONObject> hits){StringBuilder b=new StringBuilder("FONTES LOCAIS SELECIONADAS:\n");HashSet<String> seen=new HashSet<String>();for(JSONObject h:hits){String title=h.optString("manual_title",h.optString("title","Manual"));if(seen.add(title))b.append("• ").append(manualDisplayTitle(new JSONObjectSafe().putSafe("title",title).value())).append("\n");}return b.toString();}

    private String buildRuleRetrievalContext(JSONObject bundle){
        if(bundle==null||bundle.length()==0)return "";
        try{
            JSONObject compact=new JSONObject();
            compact.put("status",bundle.optString("status")).put("required",bundle.optBoolean("required",true))
                    .put("mechanical_candidate",bundle.optBoolean("mechanical_candidate",true))
                    .put("sufficient_for_mechanics",bundle.optBoolean("sufficient_for_mechanics",false))
                    .put("intents",bundle.optJSONArray("intents")==null?new JSONArray():bundle.optJSONArray("intents"))
                    .put("queries",bundle.optJSONArray("queries")==null?new JSONArray():bundle.optJSONArray("queries"))
                    .put("structured_rules",bundle.optJSONArray("structured_rules")==null?new JSONArray():bundle.optJSONArray("structured_rules"))
                    .put("instruction",bundle.optString("instruction"));
            String raw=compact.toString();if(raw.length()>6500)raw=raw.substring(0,6500);
            return "\n\nPACOTE ESTRUTURADO DE REGRAS RECUPERADAS — este pacote foi produzido localmente antes da chamada e é a única base manual válida desta cena:\n"+raw+"\n";
        }catch(Exception failure){AppLog.e("MainActivity","Falha ao montar o pacote de regras recuperadas.",failure);return "\n\nA recuperação local falhou; não proponha mutações mecânicas.\n";}
    }


    private String localExcerpt(String content,String query,int max){
        String x=content==null?"":content.replaceAll("\\s+"," ").trim();if(x.length()<=max)return x;String nq=LocalManualIndexer.normalize(query);int best=-1;for(String term:nq.split("\\s+")){if(term.length()<4)continue;int at=LocalManualIndexer.normalize(x).indexOf(term);if(at>=0){best=at;break;}}if(best<0)best=0;int start=Math.max(0,best-max/3),end=Math.min(x.length(),start+max);if(start>0)start=x.indexOf(' ',start);if(start<0)start=0;if(end<x.length()){int e=x.lastIndexOf(' ',end);if(e>start)end=e;}return (start>0?"… ":"")+x.substring(start,end).trim()+(end<x.length()?" …":"");
    }

    /** Pequeno construtor que evita espalhar try/catch só para montar JSON interno. */
    private static final class JSONObjectSafe{final JSONObject o=new JSONObject();JSONObjectSafe putSafe(String k,Object v){try{o.put(k,v);}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}return this;}JSONObject value(){return o;}}

    private void finalizeStreamingNarrationNow(){if(!aiBusy||streamingNarration.trim().length()==0)return;String problem=narrationQualityProblem(streamingNarration,lastPrompt);if(problem.length()>0){toast("O trecho ainda não forma uma cena cinematográfica completa.");setStatus("Texto parcial preservado na tela, mas não aplicado: "+problem+".");return;}aiRequestGeneration++;int received=streamingNarration.length();ChoiceSplit split=splitNarrationChoices(streamingNarration,new JSONArray());lastNarration=completeNarrationSafely(split.narration);lastVisualPrompt=sanitizeVisualSource(lastNarration);JSONArray history=SceneOptionDiversifier.parseHistory(db.getSceneOptionHistory());history=SceneOptionDiversifier.appendHistory(history,currentOptions==null?new JSONArray():currentOptions);currentOptions=SceneOptionDiversifier.ensureAlways(split.options,history,lastNarration,lastPrompt,db.getSceneState(),db.getMasterRuntimeState().optInt("beat_no",0)+1);db.saveSceneOptionHistory(SceneOptionDiversifier.appendHistory(history,currentOptions).toString());pendingTest=new JSONObject();aiBusy=false;streamingNarration="";persistStory(lastPrompt);if(masterOrchestrator!=null)masterOrchestrator.afterAccepted(activeMasterPlan,lastNarration,pendingAiInputChars,received);setStatus("Cena completa encerrada com o texto já recebido.");showNarrator();}
    private String completeNarrationSafely(String text){String x=PortugueseNarrationSanitizer.sanitize(sanitizeNarrationPayload(text==null?"":text.replace(" ▌","")).trim()).trim();if(x.length()==0)return "A cena aguarda a ação do grupo.";x=x.replace("\r","").replaceAll("[\u0000-\u0008\u000b\u000c\u000e-\u001f]+"," ").replaceAll("[ \t]+"," ").replaceAll("\n{3,}","\n\n").trim();int cut=Math.max(Math.max(x.lastIndexOf('.'),x.lastIndexOf('!')),Math.max(x.lastIndexOf('?'),x.lastIndexOf('…')));char last=x.charAt(x.length()-1);if(!(last=='.'||last=='!'||last=='?'||last=='…'||last=='”'||last=='\''||last==')')){if(cut>x.length()*0.55)x=x.substring(0,cut+1);else{x=x.replaceAll("[,;:\\-–—\\s]+$","");x=x+".";}}x=NarrativeLocationNaturalizer.naturalize(x,db);return x;}

    private JSONArray ensureSceneOptions(JSONArray source,String narration){JSONArray out=new JSONArray();try{if(source!=null)for(int i=0;i<source.length()&&out.length()<6;i++){JSONObject original=source.optJSONObject(i);if(original==null)continue;JSONObject o=copyJsonObject(original);String action=GeneratedTextSanitizer.scalar(o.optString("action"),"action");String label=GeneratedTextSanitizer.scalar(o.optString("label"),"label");String description=GeneratedTextSanitizer.scalar(o.optString("description"),"description");if(action.length()==0)action=label.length()>0?label:description;if(label.length()==0)label=action;if(action.length()==0)continue;o.put("action",action);o.put("label",label);o.put("description",description);out.put(o);}}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}return out;}

    private ChoiceSplit splitNarrationChoices(String raw,JSONArray source){
        String narration=GeneratedTextSanitizer.narrative(raw);
        JSONArray options=ensureSceneOptions(source,narration);
        String[] lines=narration.split("\n",-1);ArrayList<String> extracted=new ArrayList<String>();int cut=lines.length;boolean marker=false;
        Pattern numbered=Pattern.compile("(?iu)^\\s*(?:op(?:ç|c)[aã]o\\s*)?(\\d{1,2})\\s*[.): -]\\s*(.+?)\\s*$");
        Pattern choiceMarker=Pattern.compile("(?iu)^\\s*(?:op(?:ç|c)[õo]es|sugest[õo]es|escolhas|o que (?:voc[eê]|o grupo) faz\\??|caminhos poss[ií]veis)\\s*:?\\s*$");
        for(int i=lines.length-1;i>=0;i--){String line=lines[i].trim();if(line.length()==0){if(!extracted.isEmpty())cut=i;continue;}Matcher match=numbered.matcher(line);if(match.matches()){extracted.add(0,GeneratedTextSanitizer.scalar(match.group(2),"action"));cut=i;continue;}if(!extracted.isEmpty()&&choiceMarker.matcher(line).matches()){marker=true;cut=i;continue;}break;}
        if(extracted.isEmpty()){
            InlineChoiceTail inline=extractInlineChoiceTail(narration);
            if(inline!=null){extracted.addAll(inline.actions);narration=inline.narration;marker=true;}
        }else if(marker||extracted.size()>=2){StringBuilder clean=new StringBuilder();for(int i=0;i<cut;i++){if(clean.length()>0)clean.append('\n');clean.append(lines[i]);}narration=GeneratedTextSanitizer.narrative(clean.toString());}
        if(!extracted.isEmpty()&&(marker||extracted.size()>=2)&&options.length()==0)for(String action:extracted){if(action.length()==0||options.length()>=6)continue;options.put(sceneOption(action,"",action));}
        return new ChoiceSplit(narration,options);
    }

    private InlineChoiceTail extractInlineChoiceTail(String text){
        if(text==null||text.length()<20)return null;
        Pattern marker=Pattern.compile("(?iu)(?:^|\\s)(\\d{1,2})\\s*[.)]\\s+");Matcher matcher=marker.matcher(text);
        ArrayList<Integer> starts=new ArrayList<Integer>();ArrayList<Integer> contentStarts=new ArrayList<Integer>();ArrayList<Integer> numbers=new ArrayList<Integer>();
        while(matcher.find()){int number;try{number=Integer.parseInt(matcher.group(1));}catch(Exception ignored){continue;}if(starts.isEmpty()&&number!=1)continue;if(!numbers.isEmpty()&&number!=numbers.get(numbers.size()-1)+1)continue;starts.add(matcher.start());contentStarts.add(matcher.end());numbers.add(number);if(numbers.size()>=6)break;}
        if(numbers.size()<2)return null;
        int first=starts.get(0);if(first<Math.max(60,text.length()-1400))return null;
        ArrayList<String> actions=new ArrayList<String>();for(int i=0;i<numbers.size();i++){int from=contentStarts.get(i),to=i+1<starts.size()?starts.get(i+1):text.length();String action=GeneratedTextSanitizer.scalar(text.substring(from,to).trim(),"action");action=action.replaceAll("[;•\\s]+$","").trim();if(action.length()>0)actions.add(action);}
        if(actions.size()<2)return null;
        String narration=text.substring(0,first).replaceFirst("(?iu)\\s*(?:op(?:ç|c)[õo]es|sugest[õo]es|escolhas|o que (?:voc[eê]|o grupo) faz\\??|caminhos poss[ií]veis)\\s*:?\\s*$","").trim();
        if(narration.length()<20)return null;return new InlineChoiceTail(GeneratedTextSanitizer.narrative(narration),actions);
    }

    private static final class InlineChoiceTail{final String narration;final ArrayList<String> actions;InlineChoiceTail(String n,ArrayList<String> a){narration=n;actions=a;}}

    private static final class ChoiceSplit{final String narration;final JSONArray options;ChoiceSplit(String n,JSONArray o){narration=n==null?"":n;options=o==null?new JSONArray():o;}}

    private JSONObject sceneOption(String label,String description,String action){try{return new JSONObject().put("label",label).put("description",description).put("action",action);}catch(Exception e){return new JSONObject();}}
    private JSONObject parseAiEnvelope(String raw){
        String original=raw==null?"":raw.trim();
        try{
            String clean=original.replaceFirst("(?s)^```(?:json)?\\s*","").replaceFirst("(?s)\\s*```$","");
            int a=clean.indexOf('{'),b=clean.lastIndexOf('}');if(a>=0&&b>a)clean=clean.substring(a,b+1);
            JSONObject o=new JSONObject(clean);normalizeEnvelopeAliases(o);
            String narration=sanitizeNarrationPayload(o.optString("narration",""));if(narration.length()==0)narration=extractPartialNarration(original);o.put("narration",narration);
            if(!o.has("options")||!(o.opt("options") instanceof JSONArray))o.put("options",new JSONArray());
            return o;
        }catch(Exception e){
            try{String partial=extractPartialNarration(original);if(partial.length()==0)partial=sanitizeNarrationPayload(original);return new JSONObject().put("narration",partial).put("visual_prompt",sanitizeVisualSource(partial)).put("options",new JSONArray()).put("pending_test",JSONObject.NULL).put("state_updates",new JSONArray()).put("combat",new JSONObject().put("action","none"));}
            catch(Exception ignored){return new JSONObject();}
        }
    }

    private void normalizeEnvelopeAliases(JSONObject o)throws Exception{
        if(o==null)return;
        if(!o.has("narration")){String[] aliases={"naration","narracao","narração","narrativa","story","text"};for(String key:aliases)if(o.has(key)&&!o.isNull(key)){o.put("narration",String.valueOf(o.opt(key)));break;}}
        if(!o.has("visual_prompt")){String[] aliases={"visualPrompt","image_prompt","prompt_visual"};for(String key:aliases)if(o.has(key)&&!o.isNull(key)){o.put("visual_prompt",String.valueOf(o.opt(key)));break;}}
        if(!o.has("options")){JSONArray options=o.optJSONArray("choices");if(options==null)options=o.optJSONArray("decisions");if(options!=null)o.put("options",options);}
        if(!o.has("pending_test")&&o.has("test")){JSONObject test=o.optJSONObject("test");if(test!=null&&test.optBoolean("required",false))o.put("pending_test",test);}
    }

    private String sanitizeNarrationPayload(String raw){
        if(raw==null)return "";String x=raw.trim();if(x.length()==0)return "";
        if(x.startsWith("{")||x.contains("\"narration\"")||x.contains("\"naration\"")||x.contains("\"narracao\"")){String extracted=extractJsonStringValue(x,new String[]{"narration","naration","narracao","narração","narrativa"});if(extracted.length()>0)x=extracted;}
        x=x.replace("\\n","\n").replace("\\r","").replace("\\t"," ").replace("\\\"","\"");
        Matcher tail=Pattern.compile("(?s)\\s*\"?\\s*,\\s*\"(?:visual_prompt|visualPrompt|options|choices|pending_test|state_updates|combat|scene_state|npc_updates|npc_cognition_updates|knowledge_updates|quest_updates|faction_updates|guild_updates|clock_updates|world_events|event_resolutions|pending_resolutions|map_updates|tactical_updates|journal_updates|sources|rules_verified)\"\\s*:").matcher(x);if(tail.find())x=x.substring(0,tail.start());
        x=x.replaceFirst("(?s)^\\s*\\{?\\s*\"?(?:narration|naration|narracao|narração|narrativa)\"?\\s*:\\s*\"?","");
        x=x.replaceFirst("(?s)\"?\\s*\\}?\\s*$","").trim();
        return x;
    }

    private String extractJsonStringValue(String raw,String[] keys){
        if(raw==null)return "";for(String key:keys){int at=raw.indexOf("\""+key+"\"");if(at<0)continue;int colon=raw.indexOf(':',at+key.length()+2);if(colon<0)continue;int quote=raw.indexOf('"',colon+1);if(quote<0)continue;StringBuilder out=new StringBuilder();boolean escape=false;for(int i=quote+1;i<raw.length();i++){char c=raw.charAt(i);if(escape){if(c=='n')out.append('\n');else if(c=='r'){}else if(c=='t'||c=='b'||c=='f')out.append(' ');else if(c=='u'&&i+4<raw.length()){try{out.append((char)Integer.parseInt(raw.substring(i+1,i+5),16));i+=4;}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}}else out.append(c);escape=false;continue;}if(c=='\\'){escape=true;continue;}if(c=='"')return out.toString().trim();out.append(c);}if(out.length()>0)return out.toString().trim();}return "";
    }


    

    private JSONObject buildRagSourceAudit(JSONArray citations){
        JSONObject audit=new JSONObject();JSONArray sources=new JSONArray();try{for(int i=0;i<citations.length();i++){JSONObject c=citations.optJSONObject(i);if(c==null)continue;int page=c.optInt("page",c.optInt("pdf_page",0));JSONObject s=new JSONObject().put("book",c.optString("book",c.optString("title","Material consultado"))).put("edition",c.optString("rule_profile")).put("language","fonte original; resposta em PT-BR").put("chapter_or_table",c.optString("category","Trecho recuperado pelo Mestre")).put("printed_page",page>0?String.valueOf(page):"").put("pdf_page",page>0?String.valueOf(page):"").put("original_term","").put("explanation_pt_br",c.optString("excerpt","Trecho consultado automaticamente para esta resposta.")).put("confirmed",true).put("uri",c.optString("uri"));sources.put(s);}audit.put("verified",sources.length()>0).put("sources",sources).put("warning",sources.length()>0?"Referências recuperadas diretamente do índice local do aparelho.":"O Mestre decidiu que nenhum complemento era necessário nesta resposta.");}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}return audit;
    }

