    /** Oculta mensagens técnicas antigas gravadas pelo Gemini e sempre mostra uma explicação em PT-BR. */
    private String manualIndexErrorPtBr(String raw){if(raw==null||raw.trim().length()==0)return "";String n=raw.toLowerCase(Locale.ROOT);if(n.contains("cello error")||n.startsWith("sns:")||n.contains("contentprovider")||n.contains("deadobjectexception"))return "O provedor de arquivos do Android interrompeu a leitura deste PDF. O Braseiro preservou o progresso e tentará pela cópia local ou por uma duplicada equivalente.";if(n.contains("unable to resolve host")||n.contains("no address associated")||n.contains("unknownhost")||n.contains("network")||n.contains("failed to connect"))return "A internet ficou indisponível durante o download. O que já foi salvo permanece e a tarefa pode ser retomada.";if(n.contains("google drive")||n.contains("drive desconectado"))return "Vincule a pasta de manuais pelo seletor do Android. Depois a pesquisa funciona offline.";if(n.contains("camada de texto")||n.contains("composto por imagens")||n.contains("needs_ocr"))return "Este PDF parece ser formado por imagens e não possui texto extraível neste aparelho. Ele não bloqueia os outros manuais.";if(n.contains("espaço")||n.contains("space")||n.contains("enospc"))return "Não há espaço livre suficiente para a cópia local deste PDF.";if(n.contains("permission")||n.contains("permissão")||n.contains("securityexception"))return "O Android perdeu a permissão para ler este arquivo. Importe-o novamente ou reconecte o Drive.";if(n.contains("pdf grande demais"))return "O leitor compatível recusou este PDF grande; os leitores página a página já foram tentados e o progresso válido foi preservado.";return raw;}

    private void postRagProgress(final String message){pendingRagProgress=message==null?"":message;long now=System.currentTimeMillis();if(now-lastRagProgressUiAt<1200L)return;lastRagProgressUiAt=now;ui.post(new Runnable(){public void run(){String latest=pendingRagProgress;if(latest.length()>0)setStatus(latest);}});}

    private void scheduleRagIndexing(final boolean force){
        final String worldAtStart=activeWorldProfile();
        if(localManualIndexer==null||ragIndexingRunning)return;
        if(ragPauseRequested&&!force)return;
        if(force){resetRagPauseState();}
        final boolean all=force||localIndexAllRequested;localIndexAllRequested=false;
        if(force)db.resetLocalManualIndexForWorld(false);
        ragIndexingRunning=true;ragIndexingWorld=worldAtStart;
        AppExecutors.indexing().execute(new Runnable(){public void run(){
            try{android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND);}catch(Throwable ignored){Thread.currentThread().setPriority(Thread.MIN_PRIORITY);}int completed=0,failed=0,waiting=0,duplicates=0;
            try{
                final long attached=attachedManualId(worldAtStart);List<JSONObject> manuals=filterManualsForWorld(db.listManuals(""),worldAtStart);
                ArrayList<JSONObject> enabled=new ArrayList<JSONObject>();for(JSONObject m:manuals)if(m.optInt("enabled",1)==1)enabled.add(m);
                final HashSet<String> successfulDuplicateKeys=new HashSet<String>();
                for(JSONObject m:enabled){String key=LocalManualIndexer.duplicateKey(m.optString("title"));if(key.length()>=8&&"ready".equals(m.optString("rag_status")))successfulDuplicateKeys.add(key);}
                Collections.sort(enabled,new Comparator<JSONObject>(){public int compare(JSONObject a,JSONObject b){boolean aa=a.optLong("id")==attached,bb=b.optLong("id")==attached;if(aa!=bb)return aa?-1:1;boolean ac=a.optString("category").toLowerCase(Locale.US).contains("núcleo oficial"),bc=b.optString("category").toLowerCase(Locale.US).contains("núcleo oficial");if(ac!=bc)return ac?-1:1;boolean al=a.optString("local_uri").length()>0,bl=b.optString("local_uri").length()>0;if(al!=bl)return al?-1:1;boolean ar="ready".equals(a.optString("rag_status")),br="ready".equals(b.optString("rag_status"));if(ar!=br)return ar?1:-1;return Long.compare(a.optLong("size_bytes",Long.MAX_VALUE),b.optLong("size_bytes",Long.MAX_VALUE));}});
                int max=all?Integer.MAX_VALUE:3;
                for(JSONObject manual:enabled){
                    if(completed>=max||ragPauseRequested||localManualIndexer.isCancelRequested())break;if(!worldAtStart.equals(activeWorldProfile()))break;
                    String dupKey=LocalManualIndexer.duplicateKey(manual.optString("title"));
                    if(dupKey.length()>=8&&successfulDuplicateKeys.contains(dupKey)&&!"ready".equals(manual.optString("rag_status"))){String msg="Duplicado já coberto por outra cópia pronta; esta entrada não precisa ser lida.";db.setManualRagProgress(manual.optLong("id"),"duplicate_skipped",msg,"",LocalManualIndexer.STORE,manual.optString("modified_time"),"",0,0,0,"local");duplicates++;continue;}
                    String sourceKey="";try{sourceKey=LocalManualIndexer.sourceKey(manual);}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}
                    if(!force&&"ready".equals(manual.optString("rag_status"))&&LocalManualIndexer.STORE.equals(manual.optString("rag_store_name"))&&sourceKey.equals(manual.optString("rag_source_hash"))&&db.countManualLocalPages(manual.optLong("id"),sourceKey)>0)continue;
                    if(manual.optString("local_uri").length()==0&&!drive.isConnected()){db.setManualRagProgress(manual.optLong("id"),"waiting_drive","Conecte o Google Drive uma vez para baixar este PDF; depois o índice funcionará offline.","",LocalManualIndexer.STORE,manual.optString("modified_time"),sourceKey,0,0,0,"local");waiting++;continue;}
                    int navigationWait=0;while(navigationInProgress&&navigationWait++<12){try{Thread.sleep(250L);}catch(InterruptedException e){Thread.currentThread().interrupt();break;}}
                    try{final JSONObject current=manual;localManualIndexer.index(manual,force,new LocalManualIndexer.Progress(){public void update(String message,int done,int total){postRagProgress(message);}});completed++;if(dupKey.length()>=8)successfulDuplicateKeys.add(dupKey);}
                    catch(Exception e){if(ragPauseRequested||localManualIndexer.isCancelRequested()||String.valueOf(e.getMessage()).toLowerCase(Locale.US).contains("indexação pausada"))break;failed++;String status=findManualById(manual.optLong("id")).optString("rag_status");if(!"needs_ocr".equals(status)&&!"waiting_drive".equals(status)){String st=isTransientNetworkError(e)?"waiting_network":"error";db.setManualRagProgress(manual.optLong("id"),st,st.equals("waiting_network")?"Download pausado; retomará quando a internet voltar.":"Índice local pausado; toque para tentar novamente.",e.getMessage(),LocalManualIndexer.STORE,manual.optString("modified_time"),sourceKey,0,0,0,"local");if("waiting_network".equals(st))waiting++;}}
                }
                final int done=completed,errors=failed,wait=waiting,dups=duplicates;ui.post(new Runnable(){public void run(){ragIndexingRunning=false;ragIndexingWorld="";int ready=db.countLocalReadyStatusForWorld(false);String label="Pathfinder 2e";boolean more=hasPendingLocalIndexWork(worldAtStart);boolean paused=ragPauseRequested;String remaining=more?(all?" • itens aguardando Drive/internet":" • outros livros disponíveis em INDEXAR TUDO"):"";String pauseMessage="cache".equals(ragPauseReason)?"Indexação pausada temporariamente para manutenção do cache.":"narration".equals(ragPauseReason)?"Indexação pausada enquanto a narração usa áudio e memória.":"Indexação pausada com segurança.";setStatus(paused?pauseMessage:"Índice local de "+label+": "+ready+" manuais prontos"+(done>0?" • "+done+" atualizados":"")+(dups>0?" • "+dups+" duplicados ignorados":"")+(wait>0?" • "+wait+" aguardando Drive/internet":"")+(errors>0?" • "+errors+" pendentes":"")+remaining+". Gemini não foi usado para indexar.");if("Manuais".equals(currentScreen)&&worldAtStart.equals(activeWorldProfile()))showManuals(manualVisibleFilter);}});
            }catch(final Exception e){ui.post(new Runnable(){public void run(){ragIndexingRunning=false;ragIndexingWorld="";setStatus("Índice local: "+manualIndexErrorPtBr(e.getMessage()));if("Manuais".equals(currentScreen))showManuals(manualVisibleFilter);}});}
        }});
    }

    private void indexAllLocalManuals(){resetRagPauseState();localIndexAllRequested=true;scheduleRagIndexing(false);}

    private boolean hasPendingLocalIndexWork(String world){
        for(JSONObject manual:filterManualsForWorld(db.listManuals(""),world)){
            if(manual.optInt("enabled",1)!=1)continue;String status=manual.optString("rag_status","not_indexed");if("duplicate_skipped".equals(status))continue;
            try{String source=LocalManualIndexer.sourceKey(manual);boolean currentStore=LocalManualIndexer.STORE.equals(manual.optString("rag_store_name"))&&source.equals(manual.optString("rag_source_hash"));boolean ready="ready".equals(status)&&currentStore&&db.countManualLocalPages(manual.optLong("id"),source)>0;if(ready)continue;if(("needs_ocr".equals(status)||"error".equals(status))&&currentStore)continue;}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}
            if(manual.optString("local_uri").length()>0)return true;if(drive.isConnected())return true;
        }
        return false;
    }

    private void confirmDeleteAllManuals(){
        if(manualDeleteRunning||manualCacheClearRunning){toast("A manutenção dos manuais já está em andamento.");return;}
        new AlertDialog.Builder(this).setTitle("Apagar todos os manuais?")
                .setMessage("Isso remove da aba todos os PDFs de regras externas incompatíveis com Pathfinder 2e, além dos índices locais e estados de indexação. Campanha, personagens, mapas, tokens e sons não serão apagados. A pasta de manuais será desconectada para que os arquivos não reapareçam automaticamente.")
                .setNegativeButton("Cancelar",null)
                .setPositiveButton("APAGAR TUDO",new DialogInterface.OnClickListener(){public void onClick(DialogInterface dialog,int which){deleteAllManualsAsync();}})
                .show();
    }

    private void deleteAllManualsAsync(){
        manualDeleteRunning=true;ragPauseRequested=true;ragPauseReason="delete";localIndexAllRequested=false;if(localManualIndexer!=null)localManualIndexer.requestCancel();setStatus("Apagando fontes incompatíveis e todos os índices de manuais…");if("Manuais".equals(currentScreen))showManuals(manualVisibleFilter);
        AppExecutors.indexing().execute(new Runnable(){public void run(){
            long deadline=System.currentTimeMillis()+30000L;while(ragIndexingRunning&&System.currentTimeMillis()<deadline){try{Thread.sleep(160L);}catch(InterruptedException e){Thread.currentThread().interrupt();break;}}
            if(ragIndexingRunning){ui.post(new Runnable(){public void run(){manualDeleteRunning=false;resetRagPauseState();setStatus("Um PDF ainda está sendo fechado. Nada foi apagado; tente novamente em instantes.");toast("Exclusão adiada com segurança.");if("Manuais".equals(currentScreen))showManuals(manualVisibleFilter);}});return;}
            int removed=0;String failure="";
            try{
                removed=db.deleteAllManuals();
                if(localManualIndexer!=null)localManualIndexer.clearCachePreservingIndex();
                if(libraryConnections!=null)libraryConnections.disconnect(LibraryConnectionManager.MANUALS);
                try{if(drive!=null)drive.disconnect();}catch(Throwable ignored){AppLog.ignored("ManualDelete","Falha tolerada ao desconectar Drive legado.",ignored);}
                SharedPreferences.Editor edit=prefs.edit().remove("attached_manual_id_dnd").remove("attached_manual_id_mystara").remove("last_manual_context").remove("last_rag_citations").remove("last_source_audit").remove("rag_store_name").remove("rag_key_fingerprint").putBoolean("bundled_mythic_manual_suppressed",true);edit.commit();
                lastAiManuals=new JSONArray();lastRagCitations=new JSONArray();lastAiUsedRag=false;manualCacheBytesEstimate=0L;
            }catch(Throwable error){failure=error.getClass().getSimpleName()+": "+String.valueOf(error.getMessage());AppLog.e("ManualDelete","Falha ao apagar a biblioteca de manuais.",error);}
            final int count=removed;final String errorText=failure;ui.post(new Runnable(){public void run(){manualDeleteRunning=false;resetRagPauseState();screenCache.remove("Manuais");screenCacheTime.remove("Manuais");if(errorText.length()>0){setStatus("Falha ao apagar manuais: "+errorText);toast("Os manuais não foram removidos por completo.");}else{setStatus(count+" manual(is) apagado(s). Fontes incompatíveis foram removidas, e a pasta foi desconectada.");toast("Todos os manuais foram apagados.");}if("Manuais".equals(currentScreen))showManuals("");}});
        }});
    }

    private void clearManualCache(){
        if(manualCacheClearRunning||manualDeleteRunning){toast("A manutenção dos manuais já está em andamento.");return;}
        confirm("Limpar as cópias temporárias dos manuais agora? O índice textual, os PDFs originais e a campanha serão preservados.",new Runnable(){public void run(){
            manualCacheClearRunning=true;ragPauseReason="cache";ragPauseRequested=true;localIndexAllRequested=false;if(localManualIndexer!=null)localManualIndexer.requestCancel();setStatus("Limpando apenas os arquivos temporários dos manuais…");if("Manuais".equals(currentScreen))showManuals(manualVisibleFilter);
            AppExecutors.io().execute(new Runnable(){public void run(){
                long deadline=System.currentTimeMillis()+30000L;while(ragIndexingRunning&&System.currentTimeMillis()<deadline){try{Thread.sleep(160L);}catch(InterruptedException e){Thread.currentThread().interrupt();break;}}
                if(ragIndexingRunning){ui.post(new Runnable(){public void run(){manualCacheClearRunning=false;resetRagPauseState();setStatus("A indexação ainda está fechando um PDF. A limpeza foi adiada sem deixar a indexação pausada.");toast("Limpeza adiada com segurança.");if("Manuais".equals(currentScreen))showManuals(manualVisibleFilter);}});return;}
                long before=localManualIndexer==null?0L:localManualIndexer.cacheBytes();int removed=localManualIndexer==null?0:localManualIndexer.clearCachePreservingIndex();long after=localManualIndexer==null?0L:localManualIndexer.cacheBytes();final long freed=Math.max(0L,before-after);final int files=removed;manualCacheBytesEstimate=after;
                ui.post(new Runnable(){public void run(){manualCacheClearRunning=false;resetRagPauseState();toast("Cache limpo: "+humanSize(freed)+" liberados em "+files+" item(ns).");setStatus("Cache dos manuais limpo. A indexação está disponível novamente; ela só inicia quando você solicitar.");if("Manuais".equals(currentScreen))showManuals(manualVisibleFilter);}});
            }});
        }});
    }

    private void refreshManualCacheSizeAsync(){
        if(localManualIndexer==null||manualCacheSizeRefreshRunning)return;manualCacheSizeRefreshRunning=true;
        AppExecutors.io().execute(new Runnable(){public void run(){final long bytes=localManualIndexer.cacheBytes();manualCacheBytesEstimate=bytes;ui.post(new Runnable(){public void run(){manualCacheSizeRefreshRunning=false;if(manualCacheInfoView!=null)manualCacheInfoView.setText("Cache temporário dos manuais: "+humanSize(bytes)+". Limpar não apaga o índice local nem os PDFs originais.");}});}});
    }

    

    private boolean isTransientNetworkError(Throwable error){
        Throwable current=error;
        while(current!=null){
            String message=String.valueOf(current.getMessage()).toLowerCase(Locale.ROOT);
            String type=current.getClass().getSimpleName().toLowerCase(Locale.ROOT);
            if(type.contains("unknownhost")||type.contains("sockettimeout")||type.contains("connectexception")||
                message.contains("unable to resolve host")||message.contains("no address associated")||
                message.contains("unknownhost")||message.contains("network is unreachable")||
                message.contains("temporarily unavailable")||message.contains("failed to connect")||
                message.contains("connection reset")||message.contains("connection aborted")||
                message.contains("software caused connection abort")||message.contains("timeout")||
                message.contains("timed out")||message.contains("unexpected end of stream"))return true;
            current=current.getCause();
        }
        return false;
    }

    


    

    

    
