    private String applyStateUpdates(JSONArray updates) throws Exception{
        if(updates==null||updates.length()==0)return "";if(pendingTest!=null&&pendingTest.length()>0)throw new IllegalStateException("Há um teste pendente; alterações de ficha não podem ser aplicadas ainda.");StringBuilder summary=new StringBuilder();
        for(int i=0;i<updates.length();i++){
            JSONObject u=updates.optJSONObject(i);if(u==null)throw new IllegalArgumentException("Alteração de ficha inválida.");String reason=u.optString("reason").trim();if(reason.length()==0)throw new IllegalArgumentException("Alteração de ficha sem justificativa.");JSONObject ch=db.findCharacterByName(u.optString("character"));if(ch.length()==0)throw new IllegalStateException("Personagem não encontrado: "+u.optString("character"));long id=ch.optLong("id");int oldHp=ch.optInt("hp"),newHp=oldHp,hpMax=Math.max(1,ch.optInt("max_hp",1));
            if(u.has("hp_set")&&!u.isNull("hp_set"))newHp=Math.max(0,Math.min(hpMax,u.optInt("hp_set",oldHp)));else if(u.has("hp_delta")){int delta=Math.max(-hpMax,Math.min(hpMax,u.optInt("hp_delta",0)));newHp=Math.max(0,Math.min(hpMax,oldHp+delta));}
            String equipment=ch.optString("equipment");JSONArray added=u.optJSONArray("add_items"),removed=u.optJSONArray("remove_items");ArrayList<String> changes=new ArrayList<String>();if(newHp!=oldHp){JSONObject combatant=db.findCombatantByName(ch.optString("name"));boolean inEncounter=db.getCombatState().optInt("running",0)==1&&combatant.length()>0;if(inEncounter){if(!u.has("hp_delta"))throw new IllegalStateException("Durante combate, mudança de PV deve usar hp_delta para preservar PV temporários e dying/wounded.");int delta=newHp-oldHp;if(delta<0)db.applyCombatantDamagePf2(combatant.optLong("id"),-delta,u.optBoolean("critical_damage",false),u.optBoolean("nonlethal_damage",false));else db.applyCombatantHealingPf2(combatant.optLong("id"),delta);int applied=db.findCharacterByName(ch.optString("name")).optInt("hp",oldHp);changes.add("PV "+oldHp+" → "+applied);}else{db.setCharacterHpChecked(id,newHp);changes.add("PV "+oldHp+" → "+newHp);}}
            if(added!=null)for(int j=0;j<added.length();j++){String item=itemLabel(added.opt(j));if(item.length()>0){equipment=addEquipmentItem(equipment,item);changes.add("+ "+item);}}
            if(removed!=null)for(int j=0;j<removed.length();j++){String item=itemLabel(removed.opt(j));if(item.length()>0){String changed=removeEquipmentItem(equipment,item);if(!changed.equals(equipment)){equipment=changed;changes.add("− "+item);}}}
            String notes=ch.optString("notes"),append=u.optString("notes_append").trim();if(append.length()>0&&!notes.contains(append)){notes+=(notes.length()>0?"\n":"")+"[Mestre] "+append;changes.add("anotação persistente");}
            JSONObject sheet=parseJsonObject(ch.optString("sheet_json","{}"));JSONArray conditions=sheet.optJSONArray("conditions");if(conditions==null)conditions=new JSONArray();JSONArray addConditions=u.optJSONArray("condition_add"),removeConditions=u.optJSONArray("condition_remove");
            if(addConditions!=null)for(int j=0;j<addConditions.length();j++){Object raw=addConditions.opt(j);String condition=conditionLabel(raw);if(condition.length()>0&&!jsonArrayContainsIgnoreCase(conditions,condition)){conditions.put(raw instanceof JSONObject?raw:condition);changes.add("condição + "+condition);}}
            if(removeConditions!=null)for(int j=0;j<removeConditions.length();j++){String condition=conditionLabel(removeConditions.opt(j));JSONArray next=new JSONArray();boolean changed=false;for(int k=0;k<conditions.length();k++){String existing=conditionLabel(conditions.opt(k));if(!changed&&existing.equalsIgnoreCase(condition)){changed=true;continue;}next.put(conditions.opt(k));}conditions=next;if(changed)changes.add("condição − "+condition);}
            sheet.put("conditions",conditions);
            JSONObject resources=sheet.optJSONObject("resources");if(resources==null)resources=new JSONObject();JSONObject resourceChanges=u.optJSONObject("resource_changes");if(resourceChanges!=null){JSONArray keys=resourceChanges.names();if(keys!=null)for(int j=0;j<keys.length();j++){String key=keys.optString(j);Object raw=resourceChanges.opt(key),stateRaw=resources.opt(key);JSONObject state=stateRaw instanceof JSONObject?(JSONObject)stateRaw:null;int before=state==null?resources.optInt(key,0):state.optInt("current",state.optInt("value",0)),after=before,resourceMin=state==null?0:state.optInt("min",0),resourceMax=state==null?Integer.MAX_VALUE:state.optInt("max",Integer.MAX_VALUE);if(raw instanceof JSONObject){JSONObject change=(JSONObject)raw;if(change.has("set"))after=change.optInt("set",before);else after=before+change.optInt("delta",0);}else if(raw instanceof Number)after=before+((Number)raw).intValue();after=Math.max(resourceMin,Math.min(resourceMax,after));if(state!=null){state.put("current",after);resources.put(key,state);}else resources.put(key,after);if(after!=before)changes.add(key+" "+before+" → "+after);}}
            sheet.put("resources",resources);
            if(!equipment.equals(ch.optString("equipment"))||!notes.equals(ch.optString("notes")))db.setCharacterEquipmentAndNotesChecked(id,equipment,notes);db.updateCharacterSheetChecked(id,sheet.toString());
            if(!changes.isEmpty()){if(summary.length()>0)summary.append("\n");summary.append(ch.optString("name")).append(": ");for(int k=0;k<changes.size();k++){if(k>0)summary.append("; ");summary.append(changes.get(k));}summary.append(" — ").append(reason);}
        }
        if(summary.length()>0)db.addJournalChecked("Alterações confirmadas de ficha — "+dateNow(),summary.toString(),"Ficha");return summary.toString();
    }
    private JSONObject parseJsonObject(String raw){try{return new JSONObject(raw==null?"{}":raw);}catch(Exception e){return new JSONObject();}}
    private boolean jsonArrayContainsIgnoreCase(JSONArray array,String value){if(array==null||value==null)return false;for(int i=0;i<array.length();i++)if(value.equalsIgnoreCase(conditionLabel(array.opt(i))))return true;return false;}
    private String conditionLabel(Object raw){if(raw==null||raw==JSONObject.NULL)return "";if(raw instanceof JSONObject)return ((JSONObject)raw).optString("name").trim();return String.valueOf(raw).trim();}
    private String itemLabel(Object raw){if(raw==null||raw==JSONObject.NULL)return "";if(raw instanceof JSONObject){JSONObject o=(JSONObject)raw;String name=o.optString("name").trim();int q=Math.max(1,o.optInt("quantity",1));return name.length()==0?"":(q>1?q+"x ":"")+name;}return String.valueOf(raw).trim();}
    private String addEquipmentItem(String equipment,String item){String base=equipment==null?"":equipment.trim();String clean=item.trim();if(clean.length()==0)return base;if(base.toLowerCase(Locale.US).contains(clean.toLowerCase(Locale.US)))return base;return base+(base.length()>0?"\n":"")+"• "+clean;}
    private String removeEquipmentItem(String equipment,String item){if(equipment==null||equipment.trim().length()==0)return "";String target=item.toLowerCase(Locale.US).replaceFirst("^\\d+\\s*[x×]\\s*","").trim();String[] parts=equipment.split("\\s*(?:\\n|,|;)\\s*");StringBuilder out=new StringBuilder();boolean removed=false;for(String part:parts){String normalized=part.toLowerCase(Locale.US).replace("•","").trim();if(!removed&&(normalized.contains(target)||target.contains(normalized))){removed=true;continue;}if(part.trim().length()>0){if(out.length()>0)out.append("\n");out.append(part.trim());}}return removed?out.toString():equipment;}

    private void syncPresentNpcsIntoRunningCombat(JSONObject envelope)throws Exception{
        if(db.getCombatState().optInt("running",0)!=1)return;
        java.util.LinkedHashMap<String,JSONObject> candidates=new java.util.LinkedHashMap<String,JSONObject>();
        JSONObject scene=envelope==null?null:envelope.optJSONObject("scene_state");
        if(scene!=null)addNpcCandidates(candidates,scene.opt("present_npcs"));
        JSONObject persisted=db.getSceneState();try{addNpcCandidates(candidates,new JSONArray(persisted.optString("present_npcs_json","[]")));}catch(Exception ignored){AppLog.ignored("CombatNpcSync","Lista persistida de NPCs inválida.",ignored);}
        JSONArray updates=envelope==null?null:envelope.optJSONArray("npc_updates");if(updates!=null)for(int i=0;i<updates.length();i++){JSONObject npc=updates.optJSONObject(i);if(npc==null||npc.optBoolean("left_scene",false)||npc.optBoolean("departed",false)||!npc.optBoolean("present",true)||npc.optInt("active",1)==0)continue;addNpcCandidate(candidates,npc);}
        if(currentSceneCastPreview!=null)for(int i=0;i<currentSceneCastPreview.length();i++){JSONObject npc=currentSceneCastPreview.optJSONObject(i);if(npc!=null)addNpcCandidate(candidates,npc);}
        for(JSONObject candidate:candidates.values()){
            String name=candidate.optString("name","").trim();if(name.length()==0||db.findCharacterByName(name).length()>0||db.findCombatantByName(name).length()>0)continue;
            if((candidate.optBoolean("transient",false)||candidate.optBoolean("anonymous",false))&&!candidate.optBoolean("hostile",false))continue;
            JSONObject memory=db.findNpcMemoryByName(name);JSONObject stats=parseObjectSafe(candidate.opt("stats_json"));if(stats.length()==0)stats=parseObjectSafe(memory.opt("stats_json"));
            String role=(candidate.optString("role","")+" "+candidate.optString("attitude",memory.optString("attitude",""))+" "+candidate.optString("summary",memory.optString("summary",""))).toLowerCase(Locale.ROOT);
            boolean hostile=role.contains("hostil")||role.contains("inimig")||role.contains("agressiv")||candidate.optBoolean("hostile",false);
            int maxHp=Math.max(1,Math.min(999,stats.optInt("max_hp",stats.optInt("hp",stats.optInt("hit_points",1)))));int hp=Math.max(0,Math.min(maxHp,stats.optInt("hp",maxHp)));
            int ac=Math.max(1,Math.min(50,stats.optInt("ac",10)));
            int initiative=hostile?new Random().nextInt(20)+1+Math.max(-20,Math.min(40,stats.optInt("initiative_bonus",stats.optInt("perception_bonus",0)))):0;
            String npcToken=candidate.optString("token_uri",memory.optString("token_uri",""));long id=db.addCombatantWithVisualChecked(name,initiative,hp,maxHp,ac,stats.optString("conditions",""),false,"npc",memory.optLong("id",0),npcToken);
            JSONObject resources=new JSONObject();java.util.Iterator<String> keys=stats.keys();while(keys.hasNext()){String key=keys.next();resources.put(key,stats.opt(key));}
            resources.put("npc_memory_id",memory.optLong("id",0));resources.put("scene_role",hostile?"hostile":"present");resources.put("noncombatant",!hostile);resources.put("token_uri",candidate.optString("token_uri",memory.optString("token_uri","")));
            db.updateCombatantPf2AdvancedChecked(id,0,false,stats.optString("conditions",""),"[]",stats.optString("resistances",""),stats.optString("vulnerabilities",""),stats.optString("immunities",""),resources.toString());
        }
        db.ensureTacticalTokensForCombat();
    }

    private void addNpcCandidates(java.util.Map<String,JSONObject> out,Object raw)throws Exception{
        if(raw==null||raw==JSONObject.NULL)return;JSONArray values=raw instanceof JSONArray?(JSONArray)raw:null;if(values==null&&raw instanceof String)try{values=new JSONArray(String.valueOf(raw));}catch(Exception ignored){return;}if(values==null)return;
        for(int i=0;i<values.length();i++){Object value=values.opt(i);if(value instanceof JSONObject)addNpcCandidate(out,(JSONObject)value);else if(value!=null){String name=String.valueOf(value).trim();if(name.length()>0)addNpcCandidate(out,new JSONObject().put("name",name));}}
    }
    private void addNpcCandidate(java.util.Map<String,JSONObject> out,JSONObject npc){if(npc==null)return;String name=npc.optString("name",npc.optString("label","")).trim();if(name.length()==0)return;String key=normalizeForNameMatch(name);JSONObject previous=out.get(key);if(previous==null||npc.length()>previous.length())out.put(key,npc);}
    private JSONObject parseObjectSafe(Object raw){if(raw instanceof JSONObject)return (JSONObject)raw;try{String value=raw==null?"{}":String.valueOf(raw);return value.trim().startsWith("{")?new JSONObject(value):new JSONObject();}catch(Exception ignored){return new JSONObject();}}

    private String applyCombatPlan(JSONObject combat) throws Exception{
        if(combat==null||combat.length()==0)return "";
        StringBuilder summary=new StringBuilder();JSONArray manorTreasuryActions=combat.optJSONArray("manor_treasury_actions");if(manorTreasuryActions!=null)for(int n=0;n<manorTreasuryActions.length();n++)kingmakerRepository.resolveManorTreasuryAction(manorTreasuryActions.optJSONObject(n));JSONArray manorActions=combat.optJSONArray("manor_actions");if(manorActions!=null)for(int n=0;n<manorActions.length();n++)kingmakerRepository.resolveManorFireAction(manorActions.optJSONObject(n));String action=combat.optString("action","none").toLowerCase(Locale.US);if("none".equals(action)||action.length()==0)return (manorActions!=null&&manorActions.length()>0)||(manorTreasuryActions!=null&&manorTreasuryActions.length()>0)?"Ações da mansão resolvidas.":"";
        if("start".equals(action)){
            String room=combat.optString("canonical_room");
            if(room.length()>0){
                if(kingmakerService==null||!kingmakerService.enabled()||!KingmakerPreludePolicy.isMansionPhase(kingmakerRepository.campaignStoryPhase()))throw new IllegalStateException("Encontros da mansão exigem presença no prólogo Kingmaker.");
                JSONObject encounter=KingmakerCampaignGate.mansionEncounter(room);
                if("A1".equals(room)&&"perception".equals(combat.optString("initiative_mode")))encounter.optJSONArray("enemies").optJSONObject(0).put("initiative_bonus",3);
                combat.put("enemies",encounter.optJSONArray("enemies")).put("source_ref",encounter.optString("source_ref"));
            }

            if(db.getCombatState().optInt("running",0)==0){db.resetCombatChecked();for(JSONObject h:db.listActiveCharacters()){int init=new Random().nextInt(20)+1+pathfinderRules.initiativeBonus(h,"Percepção");db.addCombatantChecked(h.optString("name"),init,h.optInt("hp"),h.optInt("max_hp"),h.optInt("ac"),"",true);}db.setCombatRunningChecked(true);markKingmakerMansionCombatStartedIfNeeded();}
            JSONArray enemies=combat.optJSONArray("enemies");int added=0;
            if(enemies!=null)for(int i=0;i<enemies.length();i++){
                JSONObject e=enemies.optJSONObject(i);if(e==null)throw new IllegalArgumentException("Inimigo inválido no plano de combate.");
                String base=e.optString("name","Inimigo").trim();int count=Math.max(1,Math.min(20,e.optInt("count",1))),hp=Math.max(1,Math.min(999,e.optInt("hp",1))),ac=Math.max(1,Math.min(30,e.optInt("ac",10))),bonus=Math.max(-10,Math.min(20,e.optInt("initiative_bonus",0)));
                for(int n=1;n<=count;n++){
                    String name=count>1?base+" "+n:base;if(db.findCombatantByName(name).length()>0)continue;
                    long enemyId=db.addCombatantWithVisualChecked(name,new Random().nextInt(20)+1+bonus,hp,Math.max(hp,Math.min(999,e.optInt("max_hp",hp))),ac,e.optString("conditions"),false,"",0,e.optString("token_uri",""));
                    JSONObject enemyResources=new JSONObject().put("block_id",e.optString("block_id")).put("attacks",e.optString("attacks")).put("speed",e.optString("speed"));
                    if(e.optJSONObject("official_stats")!=null)enemyResources.put("official_stats",new JSONObject(e.optJSONObject("official_stats").toString())).put("source_ref",e.optString("source_ref"));

                    db.updateCombatantPf2AdvancedChecked(enemyId,0,false,e.optString("conditions"),"[]",e.optString("resistances"),e.optString("vulnerabilities"),e.optString("immunities"),enemyResources.toString());added++;
                }
            }
            if(db.getCombatState().optInt("running",0)==1&&db.listCombatants().size()>0){boolean hasTurn=false;for(JSONObject active:db.listCombatants())if(active.optInt("active_turn",0)==1){hasTurn=true;break;}if(!hasTurn)db.nextTurn();}
            summary.append("Combate iniciado automaticamente");if(added>0)summary.append(" com ").append(added).append(" inimigo(s)");String reason=combat.optString("reason");if(reason.length()>0)summary.append(" — ").append(reason);
        }
        JSONArray changes=combat.optJSONArray("updates");if(("update".equals(action)||"start".equals(action))&&changes!=null)for(int i=0;i<changes.length();i++){JSONObject u=changes.optJSONObject(i);if(u==null)throw new IllegalArgumentException("Atualização de combatente inválida.");JSONObject c=db.findCombatantByName(u.optString("name"));if(c.length()==0)throw new IllegalStateException("Combatente não encontrado: "+u.optString("name"));int before=c.optInt("hp"),after=before;if(u.has("hp_set")&&!u.isNull("hp_set"))after=Math.max(0,Math.min(c.optInt("max_hp",before),u.optInt("hp_set",before)));else after=Math.max(0,Math.min(c.optInt("max_hp",before),before+u.optInt("hp_delta",0)));if(after!=before)db.adjustCombatantHpChecked(c.optLong("id"),after-before,after);String cond=u.optString("conditions");if(cond.length()>0)db.updateConditionsChecked(c.optLong("id"),cond);if(summary.length()>0)summary.append("\n");summary.append(c.optString("name")).append(": PV ").append(before).append(" → ").append(after);if(cond.length()>0)summary.append("; ").append(cond);}
        if("end".equals(action)){for(JSONObject c:db.listCombatants())if(c.optInt("is_player",0)==1){JSONObject h=db.findCharacterByName(c.optString("name"));if(h.length()==0)throw new IllegalStateException("Herói do combate não encontrado: "+c.optString("name"));db.setCharacterHpChecked(h.optLong("id"),c.optInt("hp"));}String reason=combat.optString("reason","Confronto encerrado");db.addJournalChecked("Fim de combate — "+dateNow(),reason,"Combate");db.resetCombatChecked();markKingmakerMansionCombatFinishedIfNeeded();summary.append(summary.length()>0?"\n":"").append("Combate encerrado automaticamente — ").append(reason);}return summary.toString();}

    

    private String buildHeroAiContext(JSONObject legacy){
        JSONObject h=legacy==null?new JSONObject():legacy;
        JSONObject sh=parseLooseJson(h.optString("sheet_json","{}"));
        StringBuilder b=new StringBuilder();
        b.append(h.optString("name","Personagem")).append(" — ").append(h.optString("species")).append(" ").append(h.optString("class_name")).append(" nível ").append(h.optInt("level",1));
        b.append("; PV ").append(h.optInt("hp")).append('/').append(h.optInt("max_hp")).append("; CA ").append(h.optInt("ac"));
        b.append("; FOR ").append(signedModifier(h.optInt("str"))).append(", DES ").append(signedModifier(h.optInt("dex"))).append(", CON ").append(signedModifier(h.optInt("con"))).append(", INT ").append(signedModifier(h.optInt("int_score"))).append(", SAB ").append(signedModifier(h.optInt("wis"))).append(", CAR ").append(signedModifier(h.optInt("cha")));
        b.append("; Percepção ").append(signedModifier(pathfinderRules.initiativeBonus(h,"Percepção")));
        String visual=h.optString("visual_description","");
        if(visual.length()==0)visual=sh.optString("visual_description","");
        if(visual.length()>0)b.append(". Visual físico/vestimenta: ").append(promptTail(visual,260));
        String armor=h.optString("armor",sh.optString("armor",sh.optString("armor_name","")));
        if(armor.length()>0)b.append(". Armadura/Vestes: ").append(promptTail(armor,120));
        String weapons=h.optString("weapons",sh.optString("weapons",sh.optString("weapon","")));
        if(weapons.length()>0)b.append(". Armas empunhadas/visíveis: ").append(promptTail(weapons,160));
        String personality=sh.optString("personality","");
        if(personality.length()>0)b.append(". Personalidade: ").append(promptTail(personality,180));
        String equipment=h.optString("equipment",sh.optString("equipment",""));
        if(equipment.length()>0)b.append(". Equipamento: ").append(promptTail(equipment,260));
        return b.toString().replaceAll("\\s+"," ").trim();
    }
    
    

    private boolean isOpeningNarrationRequest(String userText){
        String q=java.text.Normalizer.normalize(userText==null?"":userText.toLowerCase(new Locale("pt","BR")),java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","");
        return q.contains("inicio automatico")||q.contains("abertura de historia")||q.contains("inicio da aventura")||q.contains("inicio da campanha")||q.contains("nova aventura")||q.contains("nova campanha")||(lastNarration.trim().length()==0&&db.getStoryState().optInt("started",0)==0);
    }

    

    private JSONObject liveTableWorldContext(){
        JSONObject out=new JSONObject();
        try{
            out.put("quests",new JSONArray(db.listQuests("active",12)));
            out.put("factions",new JSONArray(db.listFactions(10)));
            out.put("clocks",new JSONArray(db.listWorldClocks(true,14)));
            out.put("events_due_or_upcoming",new JSONArray(db.listUpcomingWorldEvents(10)));
        }catch(Exception e){AppLog.w("MesaViva","Falha ao montar contexto compacto de mundo; usando estado parcial.",e);}
        return out;
    }

    /** Contexto de abertura deliberadamente sem regras, RAG, catálogos de manuais ou combate.
     * Evita que a primeira cena seja confundida com uma consulta técnica. */
    private String openingNarrativeContext(String raw){
        try{
            JSONObject source=new JSONObject(raw==null||raw.trim().length()==0?"{}":raw);
            JSONObject out=new JSONObject();
            String[] keep=new String[]{"campaign","story","scene","party","cognitive_plan","knowledge","npcs","guilds","relevant_memories","world","living_world","world_beat","narrative_pacing","map","local_tick","narrative_intent","input_channel","fiction_frozen","canonical_position","campaign_pois_public","campaign_pois_private","scene_entity_grounding","spotlight_hint","authority"};
            for(String key:keep)if(source.has(key))out.put(key,source.opt(key));
            JSONObject campaign=out.optJSONObject("campaign");if(campaign!=null){campaign.remove("rules_profile");campaign.remove("feats");campaign.remove("multiclass");campaign.remove("flanking");}
            out.put("opening_narrative",true).put("opening_no_rag",true).put("mechanics_deferred",true);
            return out.toString();
        }catch(Exception e){AppLog.w("NarrativeOpening","Falha ao reduzir contexto técnico da abertura; usando contexto mínimo.",e);return "{\"opening_narrative\":true,\"opening_no_rag\":true,\"mechanics_deferred\":true}";}
    }

    private JSONObject openingNoSourceAudit(){
        JSONObject audit=new JSONObject();try{audit.put("verified",false).put("sources",new JSONArray()).put("warning","Abertura narrativa direta: nenhum manual ou regra foi consultado.").put("opening_no_rag",true);}catch(Exception ignored){AppLog.ignored("NarrativeOpening","Falha ao registrar auditoria sem fontes.",ignored);}return audit;
    }

    private String buildFastNarratorPrompt(String userText,String manualSummary){
        JSONObject c=db.getCampaign();StringBuilder p=new StringBuilder();String sceneMode=currentMasterSceneMode();boolean opening=isOpeningNarrationRequest(userText);boolean economy=masterOrchestrator!=null&&masterOrchestrator.economyMode();
        StringBuilder heroes=new StringBuilder();List<JSONObject> list=db.listActiveCharacters();for(int i=0;i<list.size();i++){JSONObject h=list.get(i);if(i>0)heroes.append("\n");heroes.append(buildHeroAiContext(h));}
        p.append(masterOrchestrator==null?"BRAS_QUOTA_NORMAL":masterOrchestrator.marker()).append(" BRAS_MASTER_COGNITIVE_340 BRAS_SINGLE_CALL. Você é o Mestre do Braseiro. O aplicativo local já planejou causalidade, regras, passagem do tempo, memória, conhecimento, autonomia dos NPCs, fila da companhia e persistência. Você interpreta a intenção e transforma o plano em ficção natural. Não refaça cálculos locais e nunca peça chamada de reparo. ");
        if(opening)p.append("A PRIMEIRA CENA É FICÇÃO, não uma resposta sobre o sistema. Use Pathfinder 2e apenas como pano de fundo implícito; nenhuma regra deve ser explicada ao jogador nesta chamada. ");
        else p.append("Sistema: ").append(Pathfinder2eRulesEngine.PROFILE).append(". ").append(pathfinderRules.authority()).append(' ');
        JSONObject liveParty=partyDirector==null?new JSONObject():partyDirector.compactStateForPrompt(economy?2600:3800);
        JSONObject liveWorld=liveTableWorldContext();
        p.append("\n").append(BraseiroNarrativeDirector.contract(c,db.getSceneState(),recentNarrativeTexts()));p.append(BraseiroNarrativeDirector.interactionContract(userText,braseiroNarrativeMemory()));
        p.append(LiveTableNarrativeDirector.contract(c,db.getSceneState(),liveParty,liveWorld,braseiroNarrativeMemory(),userText));
        p.append("PERSONAGENS ATIVOS E ANCORAGEM MATERIAL:\n").append(heroes.length()==0?"nenhum registrado":heroes.toString()).append("\n");
        p.append("\nDIRETRIZES FUNDAMENTAIS DO MESTRE HUMANO IMERSIVO (5 PILARES OBRIGATÓRIOS):\n");
        p.append("1. ENQUADRAMENTO SENSORIAL, CLIMA E TERRENO (MACRO): Estabeleça a atmosfera física: céu, incidência de luz/período, vento no rosto, sensação térmica e suor/arrepio, cheiros do ambiente (fumaça de lenha, terra molhada, ferro, folhas secas) e o chão sob as botas (lama viscosa, cascalho solto, pedras escorregadias).\n");
        p.append("2. ANCORAGEM FÍSICA DOS HERÓIS (MICRO - MANDATÓRIO): Chame os heróis pelos seus NOMES PRÓPRIOS. Descreva a presença física deles: o que estão vestindo (mantos, cotas de malha, couro, capuzes), as armas reais empunhadas ou nas costas, o peso das mochilas nas correias, o vapor da respiração no ar frio ou o cansaço visível na postura.\n");
        p.append("3. O MUNDO EM MOVIMENTO CONTÍNUO: O mundo não fica em pausa esperando o clique do jogador. NPCs entram em plena atividade (trabalhando, raspando balcão, amolando lâminas, comendo, vigiando) e não estáticos. O ambiente é dinâmico (galhos estalando, cães ao longe, telhas gotejando).\n");
        p.append("4. DINÂMICA DE CÂMERA (ZOOM CONSCIENTE): Siga Macro (território, clima e horizonte) -> Meso (localidade e construções) -> Micro (os heróis, suas vestes, armas e posturas) -> Estímulo Focal (o som, a sombra ou o detalhe que exige reação).\n");
        p.append("5. DEVOLUÇÃO ORGÂNICA DE AGÊNCIA (ZERO MULETAS): NUNCA termine com a pergunta mecânica 'O que você faz?'. Conclua com a tensão no ar, com uma pergunta situada para um herói específico, ou pausando no momento crucial. NUNCA dite sentimentos ou emoções involuntárias ('você sente medo' é proibido; descreva o ruído sinistro para que o jogador sinta o medo). NUNCA use metalinguagem de software ('A cena responde', 'Antes que qualquer explicação seja necessária', 'Opções disponíveis', 'Status:', 'Hex 14').\n");
        p.append("Todo conteúdo visível deve estar em português do Brasil. Responda SOMENTE com um JSON válido, começando por narration. Termine a narração em frase completa e revise palavras coladas. Na prosa de narration, nunca diga hex, hexágono, célula, grade nem um código cartográfico como EH92. Use o nome confirmado do local, a região ou reino confirmado, o tipo de terreno confirmado ou, quando o atlas ainda não souber, a expressão esta região. Códigos de hex só podem existir em campos técnicos de estado e rota. Referência narrativa do local atual: ").append(NarrativeLocationNaturalizer.currentNarrativeLabel(db)).append(".\n");        p.append(SceneEntityGrounding.promptDirective(db,db.getSceneState()));

        String masterContext=activeMasterPlan==null?"{}":activeMasterPlan.compactContext;
        if(opening)masterContext=openingNarrativeContext(masterContext);
        p.append("ESTADO COMPACTO AUTORITATIVO E PLANO LOCAL:\n").append(masterContext).append("\n");
        p.append("RITMO ADAPTATIVO: use narrative_pacing como direção de comprimento e função da cena. A faixa de palavras é apenas guia, nunca quota. Varie visivelmente o tamanho entre cenas conforme conversa, ação, chegada, investigação, revelação e abertura; não produza blocos quase iguais por hábito. ");
        p.append("MUNDO AUTÔNOMO: quando world_beat.active=true, incorpore organicamente uma consequência ou sinal perceptível que não seja simples resposta à ação do jogador. Ela deve nascer apenas de world_beat/environmental_director/Mundo Vivo persistido. Não revele causa privada, segredo ou evento futuro. Quando world_beat.active=false, não invente um acontecimento só para movimentar a cena.\n");
        p.append("AGÊNCIA: todos os heróis ativos coexistem. Resolva declarações em causal_order. Nunca decida ação importante por herói em modo manual. Pode oferecer reação, sensação ou observação coerente, mas a decisão continua do jogador. Recursos limitados só podem ser gastos quando declarados ou confirmados. Respeite subgrupos, distância, conhecimento individual e spotlight_hint.\n");
        p.append("FIREWALL DE CONHECIMENTO: o contexto já contém somente fatos reveláveis. Não invente conhecimento para personagens, não revele plano oculto de facção, segredo de NPC ou consequência futura. knowledge_updates registra apenas algo que realmente se tornou conhecido nesta batida.\n");
        p.append("ELENCO E LOCAL OBRIGATÓRIOS: todo personagem ou grupo que aparece, fala, entrega algo, exige algo ou age na narração deve existir em scene_state.present_npcs. NPCs nomeados, persistentes ou individualmente relevantes devem entrar em npc_updates com name, role, present=true e visual_description concreta QUANDO isso couber na mesma resposta; se algum dado visual faltar, NÃO interrompa nem encurte a narração por causa disso — a cena tem prioridade e o aplicativo enriquecerá a identidade depois. Se um figurante não tiver nome próprio, use apenas rótulo descritivo de cena sem inventar identidade (ex.: \"Velho do bebedouro\", \"Corredores com peixes\"), marque anonymous=true e transient=true e use count quando houver quantidade; não o coloque em npc_updates até ele se tornar individualmente relevante. Nunca deixe pessoas visíveis só na prosa. Na abertura, scene_state também deve registrar hex_id técnico, location, objective e, quando existirem, clues e threats. Não deixe um NPC apenas no texto.\n");
        if(BraseiroNarrativeDirector.isNonAdvancing(userText)){
            p.append("MODO DE RESPOSTA: esclarecimento sem avanço ficcional. Preserve exatamente o instante e o checkpoint da cena; não gere reação nova do mundo.\n");
        }else if(opening){
            p.append("ABERTURA LONGA DO MESTRE — REQUISITO DE JOGO: esta é a primeira cena jogável, não uma vinheta atmosférica nem demonstração de prosa. Escreva 6 a 8 parágrafos substanciais, normalmente em torno de 5.000 a 6.000 caracteres. NOS PRIMEIROS 80 A 120 TERMOS, deixe inequívocos: quem está em foco, onde está, o que está acontecendo AGORA, qual pressão/mudança exige atenção e por que isso importa. O primeiro parágrafo já precisa conter um gancho observável, uma relação, uma ameaça, uma oportunidade ou uma consequência em curso; não gaste o começo apenas descrevendo objetos. Até o segundo parágrafo deve haver pelo menos uma pessoa/NPC, grupo ou força ativa capaz de reagir às decisões dos personagens. ORIENTAÇÃO ESPACIAL: dê 2 a 4 referências concretas que permitam imaginar posições e distâncias úteis para agir. SENSORIAL COM FUNÇÃO: use 2 a 4 detalhes sensoriais fortes por parágrafo, escolhidos porque revelam espaço, humor, pista, risco, pessoa ou mudança; não catalogue cheiro, cor e textura por obrigação. PROIBIDO COMO ENCHIMENTO: microdescrição técnica de ofício, materiais, encaixes, ferramentas, medidas, espessuras, processos manuais ou anatomia mecânica de objetos. Se uma profissão ou ferramenta for relevante, resuma o trabalho em no máximo uma frase e passe imediatamente para o que muda a situação. Não transforme carpintaria, cozinha, ferraria, escrita, preparação de equipamento ou qualquer rotina em tutorial técnico. Prefira verbos, relações e consequências a adjetivos ornamentais. Varie frases curtas e longas; use diálogo quando ele tornar a pressão mais humana. Termine apenas quando houver um ponto de decisão concreto para o grupo, com informação suficiente para escolher sem adivinhar o que está acontecendo. Não transforme a apresentação em resumo, catálogo, ficha de cenário, trailer ou exposição de bastidores. A longa apresentação acontece UMA VEZ na abertura; cenas seguintes voltam ao ritmo normal.\n");
        }else{
            p.append("MODO DE CENA: ").append(sceneMode).append(". ").append(narrationPaceInstruction()).append(" Não recapitule a campanha; narre somente o que mudou, a reação do mundo e o ponto de decisão.\n");
        }
        if(!opening&&manualSummary!=null&&manualSummary.trim().length()>0)p.append("FONTES LOCAIS RECUPERADAS SEM CHAMADA EXTRA:\n").append(manualSummary).append("\nUse somente trechos pertinentes. Não invente regra, página, geografia ou lore canônico.\n");
        if(opening)p.append("ISOLAMENTO DA ABERTURA: esta chamada não é uma consulta de regras. Não explique o Pathfinder, o Braseiro, o Motor Barbara, o funcionamento da sessão, ações por turno, quatro graus de sucesso, RAG, fontes ou arquitetura do aplicativo. Entregue somente a primeira cena ficcional e os campos estruturados exigidos.\n");
        if(opening)p.append("ESCOLHAS DA ABERTURA: pending_test deve ser vazio e state_updates deve ser vazio nesta primeira apresentação. Ofereça 4 a 6 opções concretas e diferentes ligadas somente ao que acabou de acontecer, além da ação livre. Não resolva nenhuma dessas escolhas antecipadamente.\n");
        else p.append("TESTES: pending_test só existe quando rules_frame autoriza risco, oposição, custo ou incerteza. Pare antes do resultado. Não proponha mudança mecânica dependente desse teste. A ação livre é principal; em Kingmaker Solo, options deve conter normalmente 4 a 6 escolhas específicas e realmente diferentes (3 somente quando a situação for objetivamente estreita); fora de Kingmaker, pode usar menos. Cada label deve começar por um verbo concreto e nomear o alvo real da ação; cada description deve explicar método e também risco, custo ou benefício em uma frase curta. As opções precisam responder ao conflito e às entidades desta cena: em uma cobrança ou contrato, por exemplo, negociar a exigência ou examinar o documento; nunca sugerir travessia, porta, rastros, som ou fumaça quando esses elementos não estiverem literalmente presentes. Proibidos títulos abstratos como ‘agir sobre a mudança’, ‘ler a situação’, ‘buscar outro ângulo’ e descrições copiadas da narração. NOVIDADE OBRIGATÓRIA: story.avoid_options contém escolhas exibidas nas cenas recentes. Não repita nem parafraseie a mesma decisão. Distribua o leque entre intenções diferentes e use no máximo duas opções da mesma família quando os métodos forem realmente distintos; cada opção deve nascer de uma mudança concreta desta batida e mencionar alvo, pista, risco, pessoa ou local atual. Se não houver alternativa realmente nova, devolva options vazio.\n");
        if(!opening)p.append("MUTAÇÕES PROPOSTAS: state_updates aceita hp_set ou hp_delta, critical_damage, nonlethal_damage, add_items, remove_items, condition_add, condition_remove, resource_changes, notes_append, reason e mechanical_basis. Em combate, alterações de PV devem usar hp_delta e marcar critical_damage/nonlethal_damage quando aplicável; hp_set é bloqueado para não contornar dying/wounded. Toda alteração de PV, item, condição, recurso, inimigo ou combate exige mechanical_basis={source_type,evidence,rule_id?,book?,page?,excerpt?,calculation?}; para fonte manual, calculation deve conter a operação e valores reproduzíveis por rolagem local recente ou valor fixo literal da regra; sem isso o aplicativo bloqueia a parte mecânica. npc_updates nunca contém secrets; segredos permanecem no firewall local. npc_cognition_updates registra apenas emoção, suspeita, confiança, medo, urgência e próximo passo. knowledge_updates, quest_updates, faction_updates, guild_updates, clock_updates e world_events registram somente fatos concretamente alterados. guild_updates usa ações estruturadas create, update, member_add, member_reputation, rank_create, contract_create, contract_status, project_create, site_create, relation_update ou ledger; nunca trate uma guilda apenas como texto narrativo quando ela alterar membros, reputação, contratos, sedes, relações ou tesouraria. event_resolutions exige {id,transaction_id,resolution_key,status:\"resolved|cancelled\",note} exatos do evento. pending_resolutions exige {transaction_id,resolution_key,status:\"applied|cancelled\",note} para ações autônomas de facção/NPC. Toda mecânica usada para resolver uma pendência deve repetir resolution_key na alteração de ficha ou combate. map_updates altera posição/rota/revelações; tactical_updates move combatentes; journal_updates registra acontecimentos confirmados. O jogador revisará tudo antes da gravação. Não repita estado inalterado.\n");
        p.append("SEMÂNTICA OBRIGATÓRIA: nunca transforme menção, componente, imunidade, resistência ou vantagem contra condição em aplicação. condition_add usa objetos PF2e {name,value,duration,end_check,dc,repeat_timing,source,persistent_damage}; condition_remove só aparece quando o procedimento manda remover. Itens usam {name,quantity,operation,bulk,value,rarity,traits,origin}; componente apenas mencionado não entra em add_items. resource_changes deve respeitar current/min/max da ficha e calculation.resource_deltas só é aceito quando a quantidade foi compilada da fonte; repetir o mesmo número em dois campos não constitui prova. Inimigos repetem block_id e somente estatísticas do mesmo creature_block.\n");
        if(kingmakerService!=null&&kingmakerService.enabled())p.append("KINGMAKER: melhorar estrutura existente usa build_structure com upgrade_from (estrutura original) e structure_key (destino); o motor calcula o custo efetivo e mantém a antiga ativa até concluir. Para missões publicadas, quest_updates deve preservar os IDs dos objetivos. Registre cenas efetivamente resolvidas em objective_resolutions:[{id,waived,resolution_notes}], usando waived somente quando uma escolha do grupo dispensar aquela ramificação. Não conclua missões com objetivos pendentes, não invente objetivos ou recompensas e respeite o nível e o momento das aventuras dos companheiros.\n");if(kingmakerService!=null&&kingmakerService.enabled())p.append("KINGMAKER NA MANSÃO: combat.start usa canonical_room A1, A4, A6, A11, A21 ou A23. O motor fornece as fichas, contagens e condições do livro. Não invente PV, CA ou ataques desses adversários. Gromog está cego e usa suas estatísticas especiais; Jurgrindor inicia ferido com 25/50 PV. Não mova essas batalhas para fora da mansão.\n");if(kingmakerService!=null&&kingmakerService.enabled())p.append("PERIGOS A16/A17: use combat.manor_actions para ações confirmadas do incêndio, inclusive combat.action=none. Cada entrada exige action_id estável, character_id real, room de 1 a 5 (quartos de cima para baixo), action fight_fire/break_window/smoke/fire_damage/breathing_end_turn/suffocation_save/fresh_air, natural_roll real de 1 a 20 quando há teste, skill Acrobatics/Athletics/Survival, water, holding_breath, damage_rolls com dois d6 e suffocation_d4 de 1 a 4. Respiração usa attacked_or_cast, spoke e critical_air_losses reais do turno; suffocation_save exige suffocation_rolls com N d10, N=1+número de testes anteriores, sempre ao fim do turno. fresh_air só quando o personagem for realmente levado para ar livre. O motor determina graus, dano, pontos, janelas, fumaça e XP. Não converta estas consequências em atualizações genéricas de PV nem conceda XP do Reino. Estado factual: "+kingmakerRepository.manorFireState().toString()+"\n");if(kingmakerService!=null&&kingmakerService.enabled())p.append("TESOUROS A4/A7: use combat.manor_treasury_actions para decisões confirmadas, cada uma com action_id estável, character_id real e action search_a4/loot_a4/unlock_key/pick_lock/loot_a7/admit_return/lie/weapons_seen/return_gold/refuse. search_a4 usa Percepção CD15; pick_lock usa Ladroagem treinada CD20, ferramentas reais equipadas, dois sucessos no crítico e três sucessos acumulados; lie usa Enganação CD35. Informe apenas natural_roll real quando houver teste. O motor concede o tesouro uma vez e devolve o ouro realmente disponível. Não replique estas consequências por inventory_updates, moedas genéricas ou narrativa. Tarifa futura é discricionária, nunca automática. Estado factual: "+kingmakerRepository.manorTreasuryState().toString()+"\n");p.append("MUNDO VIVO ESTRUTURADO: faction_updates pode preservar objectives_json, resources_json, territories_json, relations_json, allies_json, enemies_json, information_json, costs_json, risks_json, success_conditions_json, failure_conditions_json e memory_json. npc_cognition_updates pode preservar goals_json, personality_json, knowledge_json, resources_json e recent_events_json, além de agenda, horário, localização, medo, confiança, suspeita e próximo passo. Não apague campos persistentes que não mudaram.\n");
        p.append("ÁUDIO NARRATIVO: preserve os campos existentes de audio_plan e preencha também delivery, intensity e pause_profile de acordo com a cena. delivery aceita normal, calmo, baixo ou urgente; intensity vai de 0 a 5; pause_profile aceita curto, normal ou longo. Use cues apenas para eventos pontuais literalmente narrados; phrase precisa ser substring exata. O motor local cuidará de ambiência, clima, música, rotação, sincronização e da interpretação local desses metadados.\n");
        p.append("JSON: {\"narration\":\"prosa PT-BR concluída\",\"visual_prompt\":\"descrição visual concreta\",\"options\":[],\"pending_test\":null,\"state_updates\":[],\"combat\":{\"action\":\"none\",\"enemies\":[],\"updates\":[],\"reason\":\"\",\"mechanical_basis\":{\"source_type\":\"manual|local_roll|resolved_test|local_engine\",\"rule_id\":\"\",\"book\":\"\",\"page\":0,\"excerpt\":\"\",\"evidence\":\"\",\"calculation\":{\"operation\":\"\",\"procedure_id\":\"\",\"roll_id\":0,\"test_key\":\"\",\"action_signature\":\"\",\"scene_fingerprint\":\"\",\"source_rule_id\":\"\",\"actor_character_id\":0,\"roll_formula\":\"\",\"roll_total\":0,\"flat_modifier\":0,\"modifier_source\":\"strength_mod|dexterity_mod|constitution_mod|intelligence_mod|wisdom_mod|charisma_mod\",\"divide_by\":1,\"rounding\":\"floor\",\"computed_value\":0}}},\"scene_state\":{},\"npc_updates\":[],\"npc_cognition_updates\":[],\"knowledge_updates\":[],\"quest_updates\":[],\"faction_updates\":[],\"guild_updates\":[],\"clock_updates\":[],\"world_events\":[],\"event_resolutions\":[],\"map_updates\":[],\"tactical_updates\":[],\"journal_updates\":[],\"audio_plan\":{\"environment\":\"\",\"weather\":\"\",\"location\":\"\",\"time_of_day\":\"\",\"music_mood\":\"none\",\"transition_ms\":3200,\"delivery\":\"normal\",\"intensity\":1,\"pause_profile\":\"normal\",\"cues\":[]},\"narrative_state\":{\"checkpoint_summary\":\"\",\"scene_function\":\"\",\"temperature\":0,\"focal_point\":\"\",\"motifs\":[],\"clues\":[],\"topology\":[],\"open_questions\":[],\"live_table\":{\"mode\":\"\",\"pattern\":\"\",\"spotlight\":{},\"threads\":[],\"convergence\":{},\"shared_clock\":{},\"scene_promises\":[],\"capsule\":{},\"faction_choices\":[],\"dramatic_irony\":[],\"guest_role\":{}}},\"sources\":[],\"rules_verified\":false}. Nunca escreva Markdown ou texto depois do JSON.");
        return p.toString();
    }

    private String buildSystemPrompt(String mode,String userText,String manualSummary){
        if("Narrador".equals(mode))return buildFastNarratorPrompt(userText,manualSummary);
        JSONObject c=db.getCampaign();StringBuilder heroes=new StringBuilder();List<JSONObject> list=db.listActiveCharacters();for(int i=0;i<list.size();i++){JSONObject h=list.get(i);if(i>0)heroes.append("\n");heroes.append(buildHeroAiContext(h));}
        String profile=Pathfinder2eRulesEngine.PROFILE;String moduleAuthority=activeSystemModule==null?pathfinderRules.authority():activeSystemModule.rulesAuthorityPrompt();String moduleNarrative=activeSystemModule==null?PathfinderNarrativeContract.prompt():activeSystemModule.narrativeDirective();String moduleVisual=activeSystemModule==null?"Preserve a identidade visual persistente dos personagens.":activeSystemModule.visualIdentityDirective();StringBuilder p=new StringBuilder();p.append("Você é o Mestre do aplicativo Braseiro Pathfinder 2e, dirigido pelo Motor Barbara. ");p.append("IDIOMA OBRIGATÓRIO: português do Brasil em TODO conteúdo visível ao usuário, mesmo quando os PDFs recuperados pela Biblioteca RAG estiverem em inglês. Traduza nomes comuns, regras, ações, condições, itens, tabelas e resultados para PT-BR. Preserve em inglês somente nomes próprios ou o nome original de um termo quando indispensável; nesse caso, apresente imediatamente a tradução ou explicação em PT-BR. Nunca devolva parágrafos, listas ou resultados de oráculo em inglês. Retorne SOMENTE um objeto JSON válido, sem cercas de código e sem texto fora do JSON. Emita as chaves nesta ordem: protocol_version, narration, visual_prompt, options, pending_test, state_updates, combat, scene_state, npc_updates, npc_cognition_updates, knowledge_updates, quest_updates, faction_updates, guild_updates, clock_updates, world_events, event_resolutions, map_updates, tactical_updates, journal_updates, audio_plan, narrative_state, sources, rules_verified. protocol_version deve ser exatamente 1; canal estrutural desconhecido será rejeitado. Escreva e CONCLUA narration antes dos outros campos; nunca termine no meio de uma frase. Revise ortografia e espaçamento antes de responder; nunca cole palavras como “deuma”, “demadeira”, “osperigos” ou “homemveste”. Na prosa de narration, nunca diga hex, hexágono, célula, grade nem um código cartográfico como EH92. Use nome confirmado, região/reino confirmado, terreno confirmado ou “esta região”; códigos de hex pertencem somente aos campos técnicos de estado e rota. Referência narrativa do local atual: ").append(NarrativeLocationNaturalizer.currentNarrativeLabel(db)).append(".\n");p.append("PERFIL DE REGRAS: ").append(profile).append(". ").append(moduleAuthority).append(" Toda rolagem, proficiência, CA, CD, condição, recurso e grau de sucesso deve ser validado localmente pelo núcleo PF2e ou por fonte recuperada; ambientação nunca cria mecânica.\n");p.append("DIREÇÃO DO SISTEMA: ").append(moduleNarrative).append("\nIDENTIDADE VISUAL: ").append(moduleVisual).append("\n");p.append("CAMPANHA: ").append(c.optString("name")).append(". Tom: ").append(c.optString("tone")).append(". Arquétipos: ").append(c.optInt("feats")==1?"ativos":"padrão").append(". Arquétipo livre: ").append(c.optInt("multiclass")==1?"ativo":"inativo").append(". Flanqueamento: ").append(c.optInt("flanking")==1?"ativo":"padrão PF2e").append(". Diretrizes: ").append(c.optString("notes")).append(".\nPERSONAGENS E ESTADO ATUAL:\n").append(heroes.length()==0?"nenhum":heroes.toString()).append("\n");
        if(lastNarration.length()>0)p.append("CENA ANTERIOR, apenas para continuidade: ").append(promptTail(stripMarkdown(lastNarration),1600)).append("\n");
        String persistentScene=sceneStateEngine.contextSummary();if(persistentScene.length()>0)p.append("ESTADO E MEMÓRIA PERSISTENTES — preserve continuidade e só altere quando a cena justificar:\n").append(persistentScene).append("\n");
        String integratedMap=buildMapAiContext(userText);String compactMaster=activeMasterPlan==null?masterGameContext.promptSnapshot(integratedMap,audioDiagnosticSnapshot()):activeMasterPlan.compactContext;p.append(masterOrchestrator==null?"BRAS_QUOTA_NORMAL\n":masterOrchestrator.marker()+" BRAS_MASTER_ORCHESTRATED\n");p.append("ESTADO INTEGRADO COMPACTO — FONTE DE VERDADE. Regras e mutações são validadas localmente; não replique todo o estado na resposta. Quando prosa e estado estruturado divergirem, personagens/fichas, cena, Atlas, combate, memória/cognição de NPC, guildas, Mundo Vivo, Diário canônico e regras verificadas do banco têm autoridade; a IA apenas propõe mudanças pelos canais tipados do protocolo v1:\n").append(compactMaster).append("\n");
        p.append("BIBLIOTECA RAG PERSISTENTE DO MESTRE:\n").append(manualSummary).append("\n");
        p.append("AUTONOMIA DE PESQUISA: antes de compor cada cena, avalie silenciosamente se qualquer manual ou complemento da biblioteca pode tornar a cena mais fiel, rica, surpreendente, específica ou mecanicamente correta. Você tem autorização permanente para pesquisar a biblioteca por iniciativa própria, sem esperar o jogador pedir. Pesquise regras, criaturas, magias, itens, cidades, ruínas, facções, povos, costumes, clima, viagens, encontros, armadilhas, tesouros, tabelas, aventuras, NPCs e oportunidades narrativas quando houver relação plausível com a situação. Use a recuperação como matéria-prima, não como roteiro obrigatório: descarte trechos irrelevantes, combine apenas conteúdos compatíveis e nunca force um complemento dentro da cena. Não conte ao jogador que fez uma busca; narre naturalmente. Não invente livro, página ou citação. As referências reais serão capturadas automaticamente pelo aplicativo e exibidas no botão ⓘ FONTES. Nunca transforme suplemento de ambientação em regra oficial.\n");
        p.append(standardMasterJsonContract());
        p.append(characterRulesValidator.citationContract()).append("\n");
        p.append("ATUALIZAÇÃO DE FICHA: sempre registre em state_updates qualquer dano, cura, consumo, ganho, perda, entrega, quebra ou gasto de item que realmente aconteceu. Use somente nomes de personagens existentes. Não altere ficha por intenção, hipótese ou antes de um teste necessário. hp_delta negativo causa dano e positivo cura. Não repita atualização já aplicada na cena anterior.\n");
        p.append("COMBATE PF2E: ao começar hostilidade real, retorne combat.action=start com estatísticas compatíveis com PF2e. Iniciativa normalmente usa Percepção ou a perícia justificada pela abordagem. O turno possui três ações e uma reação; ataques subsequentes usam MAP; resultados de testes usam quatro graus. Durante combate, use update apenas para dano, cura e condições já resolvidos. Use end somente quando o encontro terminou. O jogador não deve cadastrar inimigos manualmente.\n");
        p.append("REGRAS DO JSON: visual_prompt contém apenas elementos visuais concretos. Nunca inclua opções, testes, CD, perguntas, regras, Markdown ou texto para aparecer na imagem. Quando não houver mudança de ficha, state_updates deve ser []. Quando não houver mudança de combate, combat.action deve ser none.\n");
        p.append("REVISÃO OBRIGATÓRIA DO TEXTO: antes de concluir a mesma resposta, revise internamente português do Brasil, concordância, acentuação, pontuação e separação das palavras. Nunca entregue palavras coladas, marcadores literais nn, barras de nova linha visíveis, frases duplicadas ou parágrafos interrompidos. Separe mudanças de foco em parágrafos completos. Essa revisão faz parte da única chamada atual; não solicite uma chamada posterior.\n");
        p.append("ÁUDIO INTELIGENTE: audio_plan deve refletir o estado real da cena. Ambiência representa o ambiente contínuo e muda apenas quando lugar, clima ou contexto acústico mudarem. Música representa emoção e tensão e nunca deve permanecer calma durante perigo imediato. Cada cue é um som pontual que realmente acontece na narration; phrase deve copiar exatamente o trecho da narration no instante do evento. Não transforme ambiência em SFX repetido e não crie cue para objeto apenas mencionado.\n");
        String mapContext=buildMapAiContext(userText);if(mapContext.length()>0)p.append(mapContext);else p.append("VIAGENS E MAPA: sem atlas ativo, não afirme cidades, estradas, rios ou pontos de interesse como confirmados. Não invente teste a cada hex.\n");
        if("Narrador".equals(mode)){
            JSONObject liveParty=partyDirector==null?new JSONObject():partyDirector.compactStateForPrompt(masterOrchestrator!=null&&masterOrchestrator.economyMode()?2600:3800);
            JSONObject liveWorld=liveTableWorldContext();
            p.append(BraseiroNarrativeDirector.contract(c,db.getSceneState(),recentNarrativeTexts())).append(BraseiroNarrativeDirector.interactionContract(userText,braseiroNarrativeMemory())).append(LiveTableNarrativeDirector.contract(c,db.getSceneState(),liveParty,liveWorld,braseiroNarrativeMemory(),userText));
            if(BraseiroNarrativeDirector.isNonAdvancing(userText)){
                p.append("ESCLARECIMENTO CONGELADO: responda ao pedido atual e encerre sem acontecimento novo. options vazio, pending_test null e todas as mutações vazias. Não transforme a pergunta em ação ou fala do personagem.");
            }else{
                p.append(narrationPaceInstruction()).append(" Faça a situação avançar somente pela causalidade da ação atual, com acontecimento, reação, pista, custo ou mudança concreta. Construa espacialidade contínua sem prosa genérica. Não decida ações pelos jogadores. A ação livre é a interface principal. Em Kingmaker Solo, forneça normalmente de 4 a 6 escolhas realmente úteis e distintas; use 3 apenas quando a cena tiver poucas alternativas honestas. Fora de Kingmaker, options pode usar menos. Não preencha quantidade com paráfrases ou ações genéricas; options pode ficar vazio se não houver nenhuma alternativa ancorada. Em diálogo, responda a todas as perguntas pertinentes e termine naturalmente. Só exija teste quando houver INCERTEZA + CONSEQUÊNCIA + COMPETÊNCIA RELEVANTE. Se uma ação exigir teste, pare antes da consequência, deixe state_updates vazio, options vazio e preencha pending_test. Todo NPC nomeado fisicamente presente deve aparecer em scene_state.present_npcs e npc_updates com present=true, visual_description e stats_json quando conhecidos; hostis entram em combat.enemies somente quando o combate realmente começa.");
            }
        }
        else if("Regras RAW/RAI".equals(mode)){p.append("MODO REGRAS: responda objetivamente em narration, diferencie RAW, RAI e decisão de mesa; options vazio, pending_test null, state_updates vazio, combat none e visual_prompt vazio. Consulte autonomamente a Biblioteca RAG, traduza o conteúdo relevante para PT-BR e indique o título do livro e a página quando a página puder ser determinada com segurança.");}
        else if("Sortear dos livros".equals(mode)){p.append("MODO SORTEAR DOS LIVROS: consulte autonomamente a Biblioteca RAG e procure tabelas, oráculos, encontros, itens, NPCs, locais, complicações ou materiais aleatórios pertinentes ao pedido. Faça as rolagens necessárias, aplique o resultado ao contexto atual e entregue tudo em português do Brasil. Informe de forma curta a fonte, a tabela e a rolagem usada. Separe regra oficial, regra de suplemento e sugestão narrativa; não trate conteúdo de ambientação como regra oficial. options vazio, pending_test null, state_updates vazio, combat none e visual_prompt vazio.");}
        else if("Criar encontro".equals(mode)){p.append("MODO ENCONTRO: crie encontro adequado ao grupo, com terreno, objetivo, táticas, negociação e fuga. Se o encontro começar agora, preencha combat.action=start para que a aba Combate fique pronta automaticamente.");}
        else if("Criar NPC".equals(mode)){p.append("MODO NPC: crie nome, aparência visual reutilizável, voz, motivação, falha, segredo, relações, gancho e ficha compacta.");}
        else p.append("MODO PREPARAÇÃO: prepare uma sessão jogável com abertura forte, pistas, NPCs, obstáculos e contingências, sem roteiro ferroviário.");
        p.append("\nHá ").append(filterManualsForWorld(db.listManuals("")).size()).append(" materiais disponíveis para o mundo ativo. rule_retrieval informa se houve consulta nova, reutilização do cache da cena ou nenhuma consulta por não ser necessária. Use somente rule_retrieval.evidence e rule_retrieval.structured_rules quando houver prova recuperada para regras, estatísticas e procedimentos; nunca invente livro, página ou efeito. Sempre mantenha regras oficiais, regras opcionais e ambientação em papéis separados.");return p.toString();
    }

    

    private String standardMasterJsonContract(){return "FORMATO EXATO: {\"protocol_version\":1,\"narration\":\"texto concluído em PT-BR\",\"visual_prompt\":\"descrição visual concreta\",\"options\":[],\"pending_test\":null,\"state_updates\":[{\"character\":\"nome exato\",\"hp_delta\":-3,\"add_items\":[],\"remove_items\":[],\"condition_add\":[],\"condition_remove\":[],\"resource_changes\":{},\"notes_append\":\"\",\"reason\":\"causa concreta\",\"mechanical_basis\":{\"source_type\":\"manual|local_roll|resolved_test|local_engine\",\"rule_id\":\"\",\"book\":\"\",\"page\":0,\"excerpt\":\"\",\"evidence\":\"\",\"calculation\":{\"operation\":\"\",\"procedure_id\":\"\",\"roll_id\":0,\"test_key\":\"\",\"action_signature\":\"\",\"scene_fingerprint\":\"\",\"source_rule_id\":\"\",\"actor_character_id\":0,\"roll_formula\":\"\",\"roll_total\":0,\"flat_modifier\":0,\"modifier_source\":\"strength_mod|dexterity_mod|constitution_mod|intelligence_mod|wisdom_mod|charisma_mod\",\"divide_by\":1,\"rounding\":\"floor\",\"computed_value\":0}}}],\"combat\":{\"action\":\"none|start|update|end\",\"enemies\":[],\"updates\":[],\"reason\":\"\",\"mechanical_basis\":{\"source_type\":\"manual|local_roll|resolved_test|local_engine\",\"rule_id\":\"\",\"book\":\"\",\"page\":0,\"excerpt\":\"\",\"evidence\":\"\",\"calculation\":{\"operation\":\"\",\"procedure_id\":\"\",\"roll_id\":0,\"test_key\":\"\",\"action_signature\":\"\",\"scene_fingerprint\":\"\",\"source_rule_id\":\"\",\"actor_character_id\":0,\"roll_formula\":\"\",\"roll_total\":0,\"flat_modifier\":0,\"modifier_source\":\"strength_mod|dexterity_mod|constitution_mod|intelligence_mod|wisdom_mod|charisma_mod\",\"divide_by\":1,\"rounding\":\"floor\",\"computed_value\":0}}},\"scene_state\":{},\"npc_updates\":[{\"name\":\"\",\"summary\":\"\",\"goals\":\"\",\"attitude\":\"\",\"relationship\":\"\",\"knowledge\":\"\",\"debts\":\"\",\"last_seen\":\"\",\"visual_description\":\"\",\"stats_json\":\"{}\",\"hex_id\":\"\",\"voice_profile\":\"\"}],\"npc_cognition_updates\":[],\"knowledge_updates\":[],\"quest_updates\":[],\"faction_updates\":[],\"guild_updates\":[],\"clock_updates\":[],\"world_events\":[],\"event_resolutions\":[],\"map_updates\":[],\"tactical_updates\":[],\"journal_updates\":[],\"audio_plan\":{\"environment\":\"\",\"weather\":\"\",\"location\":\"\",\"time_of_day\":\"\",\"music_mood\":\"none\",\"transition_ms\":3200,\"delivery\":\"normal\",\"intensity\":1,\"pause_profile\":\"normal\",\"cues\":[]},\"narrative_state\":{\"checkpoint_summary\":\"\",\"scene_function\":\"\",\"temperature\":0,\"focal_point\":\"\",\"motifs\":[],\"clues\":[],\"topology\":[],\"open_questions\":[],\"live_table\":{\"mode\":\"\",\"pattern\":\"\",\"spotlight\":{},\"threads\":[],\"convergence\":{},\"shared_clock\":{},\"scene_promises\":[],\"capsule\":{},\"faction_choices\":[],\"dramatic_irony\":[],\"guest_role\":{}}},\"sources\":[],\"rules_verified\":false}. Nunca inclua secrets em npc_updates. Em todo NPC novo, visual_description deve ser concreta e detalhada: sexo, raça, idade aparente, função, cabelo/barba, roupa, arma ou objeto; isso permite escolher o token local sem nova chamada ao Gemini. Não invente um perfil genérico se personality_json já estiver no game_bus: mantenha modo de falar, desejos, medos, reações, gostos, limites e camadas do catálogo persistente de 300 personalidades.\n";}

    

    private String narrationPaceInstruction(){String mode=currentMasterSceneMode();boolean economy=masterOrchestrator!=null&&masterOrchestrator.economyMode();try{if(!"combate".equals(mode)&&kingmakerRepository!=null&&KingmakerPreludePolicy.isMajorScenePhase(kingmakerRepository.campaignStoryPhase()))return "CENA PRINCIPAL KINGMAKER: narre com aproximadamente 5.000 a 6.000 caracteres quando a cena sustentar essa densidade; use câmera narrativa, sensorialidade funcional, pessoas agindo e geografia jogável; preserve agência e pare em uma decisão real. Esta regra sobrescreve o limite comum de exploração."; }catch(Exception ignored){}if("conversa".equals(mode))return "DIÁLOGO: curto e encenado; responda ao que foi dito, mostre reação/subtexto e pare assim que a réplica devolver uma decisão. Normalmente 25 a 140 palavras; não use a faixa como meta.";if("combate".equals(mode))return "COMBATE: 35 a 160 palavras; ORIGEM → TRAJETÓRIA → CONTATO → RESULTADO, posição final clara e nada de recontar o turno inteiro.";if("viagem".equals(mode))return "VIAGEM: comprima quilômetros sem evento. Expanda somente descoberta, custo, transição espacial ou decisão; normalmente 40 a 180 palavras.";if("descanso".equals(mode)||"tempo_livre".equals(mode))return "INTERLÚDIO: comprima rotina e dê espaço apenas a relação, projeto, consequência ou risco; pare quando houver escolha real.";if(economy)return "EXPLORAÇÃO ECONÔMICA: preserve atmosfera e atividade do lugar, mas não recapitule nem catalogue; encerre no primeiro ponto de decisão.";String pace=prefs.getString("master_pace","balanced");if("fast".equals(pace))return "EXPLORAÇÃO ÁGIL: poucas batidas e detalhe forte; em geral até 170 palavras e sempre pare antes se a decisão já estiver clara.";if("cinematic".equals(pace))return "EXPLORAÇÃO CINEMATOGRÁFICA: permita 1 a 4 batidas, mais espaço em abertura ou revelação; normalmente até 320 palavras, sem preencher por quota.";return "EXPLORAÇÃO EQUILIBRADA: 1 a 3 batidas, normalmente até 240 palavras; comprimento segue importância, não uma meta fixa.";}

    private String promptTail(String text,int max){if(text==null)return "";return text.length()<=max?text:text.substring(text.length()-max);}
    private String extractPartialNarration(String raw){return sanitizeNarrationPayload(extractJsonStringValue(raw,new String[]{"narration","naration","narracao","narração","narrativa"}));}


    private void cancelNarrationAudio(){charonPreparationGeneration++;
        GeminiService.SpeechRequest request=activeCharonRequest;activeCharonRequest=null;if(request!=null)request.cancel();
        AudioSessionCoordinator.Session cancelled=activeAudioSession;if(audioSessionCoordinator!=null)audioSessionCoordinator.cancel("novo PLAY ou parada");if(cancelled!=null&&smartAudio!=null)smartAudio.finishPlaybackSession(cancelled.sessionId,"cancelled");activeAudioSession=null;
        if(audio!=null){audio.endPlaybackSession();audio.stopVoice();audio.setExternalVoiceActive(false);}
        pendingRequestedNativeNarration="";charonNarrationGeneration++;charonVoiceStartedSession=-1L;charonFallbackInProgress=false;
        try{if(nativeTts!=null)nativeTts.stop();}catch(Throwable ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}
        synchronized(nativeVoiceSentenceByUtterance){nativeVoiceSentenceByUtterance.clear();nativeVoiceStartedUtterances.clear();nativeVoicePendingChunks=0;}
        nativeNarrationQueue.clear();nativeChapterStartIndexes.clear();nativeNarrationQueueIndex=0;nativeNarrationSession++;nativeNarrationBedStarted=false;
        if(narrativeAudio!=null)narrativeAudio.cancelNarration();resumeBackgroundWorkAfterNarration();
    }

    private void maybeOfferNarrativePoiProposal(final String narration){
        if(campaignPoiService==null||narration==null||narration.trim().length()==0)return;String hex=db.getMapState().optString("current_hex_id","");if(hex.length()==0)return;final JSONObject candidate=campaignPoiService.proposeFromNarration(narration,hex);if(!candidate.optBoolean("proposed",false))return;final String fingerprint=stableFingerprint(db.getActiveMapProfile()+"|"+hex+"|"+candidate.optString("name")+"|"+candidate.optString("description"));if(campaignPoiService.proposalHandled(fingerprint))return;try{candidate.put("source_text",narration.length()>900?narration.substring(0,900):narration);}catch(Exception ignored){}
        ui.postDelayed(new Runnable(){public void run(){if(!canShowDialog())return;new AlertDialog.Builder(MainActivity.this).setTitle("Novo POI detectado: "+candidate.optString("name","Local")).setMessage(candidate.optString("description","")+"\n\nSalvar como conteúdo desta campanha? Nenhum JSON oficial de Golarion será alterado.").setNegativeButton("IGNORAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){campaignPoiService.rememberProposal(fingerprint,candidate,"ignored");}}).setNeutralButton("EDITAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){campaignPoiService.rememberProposal(fingerprint,candidate,"editing");editCampaignPoiDialog(candidate,candidate.optString("hex_id"));}}).setPositiveButton("SALVAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{JSONObject saved=campaignPoiService.createManual(candidate,candidate.optString("hex_id"));campaignPoiService.rememberProposal(fingerprint,candidate,"saved");refreshCampaignPoiMarkers();toast(saved.optString("name","Local")+" adicionado ao Atlas da campanha.");}catch(Exception e){toast("POI narrativo: "+e.getMessage());}}}).show();}},350L);
    }

    private void onMasterNarrationStarted(){if(candleOverlay!=null)candleOverlay.onMasterNarrationStarted();}
    private void onNarrationChunk(String chunk){if(candleOverlay!=null&&chunk!=null&&chunk.trim().length()>0)candleOverlay.onNarrationChunk();}
    private void onMasterNarrationEnded(){if(candleOverlay!=null)candleOverlay.onMasterNarrationEnded();}
    private void pauseBackgroundWorkForNarration(){onMasterNarrationStarted();if(!ragPauseRequested&&localManualIndexer!=null){narrationPausedRag=true;ragPauseReason="narration";ragPauseRequested=true;localManualIndexer.requestCancel();}}
    private void resumeBackgroundWorkAfterNarration(){onMasterNarrationEnded();if(!narrationPausedRag)return;narrationPausedRag=false;if("narration".equals(ragPauseReason)){ragPauseRequested=false;ragPauseReason="";if(localManualIndexer!=null)localManualIndexer.clearCancelRequest();}}
    private void resetRagPauseState(){ragPauseRequested=false;ragPauseReason="";narrationPausedRag=false;if(localManualIndexer!=null)localManualIndexer.clearCancelRequest();}

    private void beginCoordinatedAudioSession(String backend,String text){
        if(audioSessionCoordinator==null)return;
        String scene="scene_"+Integer.toHexString((text==null?"":text).hashCode());
        activeAudioSession=audioSessionCoordinator.begin(scene);
        if(audio!=null)audio.beginPlaybackSession(activeAudioSession.sessionId);
        if(smartAudio!=null)smartAudio.startPlaybackSession(activeAudioSession.sessionId,scene,backend);
        JSONObject details=new JSONObject();try{details.put("backend",backend).put("chars",text==null?0:text.length());}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}
        audioSessionCoordinator.event(activeAudioSession,"play-requested",details);
    }
    private void completeCoordinatedAudioSession(){
        AudioSessionCoordinator.Session completed=activeAudioSession;
        if(audioSessionCoordinator!=null&&completed!=null)audioSessionCoordinator.complete(completed);
        if(completed!=null&&smartAudio!=null)smartAudio.finishPlaybackSession(completed.sessionId,"completed");
        activeAudioSession=null;if(audio!=null)audio.endPlaybackSession();
    }

    private void failCoordinatedAudioSession(String reason){
        AudioSessionCoordinator.Session failed=activeAudioSession;
        if(audioSessionCoordinator!=null)audioSessionCoordinator.cancel(reason==null?"failed":reason);
        if(failed!=null&&smartAudio!=null)smartAudio.finishPlaybackSession(failed.sessionId,"failed");
        activeAudioSession=null;if(audio!=null)audio.endPlaybackSession();
    }

    private void speakGemini(String text){
        if(text==null||text.trim().length()==0){toast("Não há texto para narrar.");return;}
        final String clean=PortugueseNarrationSanitizer.sanitize(GeneratedTextSanitizer.narrative(stripMarkdown(text)));
        if(!audioEngineReady)initializeAudioEngineAsync();
        if(nativeTts==null||!nativeTtsReady||!nativeTtsLanguageReady)ensureNativeTtsInitialized();
        final List<String> chunks=charonVoiceChunks(clean);final long preparation=++charonPreparationGeneration;
        setStatus("Charon: preparando o primeiro trecho prioritário…");
        ui.post(new Runnable(){public void run(){if(preparation!=charonPreparationGeneration)return;continueCharonPlayback(clean,chunks);}});
    }

    private void continueCharonPlayback(final String clean,final List<String> chunks){
        cancelNarrationAudio();if(charonLatencyTelemetry!=null)charonLatencyTelemetry.begin();beginCoordinatedAudioSession("Charon",clean);pauseBackgroundWorkForNarration();final long session=charonNarrationGeneration;final AudioSessionCoordinator.Session coordinated=activeAudioSession;startAudioServiceSafely();charonVoiceStartedSession=-1L;charonFallbackInProgress=false;
        setStatus("Preparando a voz Charon. A voz Android só será usada após falha real da API ou escolha manual.");
        ui.postDelayed(new Runnable(){public void run(){if(session==charonNarrationGeneration&&isCurrentAudioSession(coordinated)&&charonVoiceStartedSession!=session)setStatus("Charon ainda está sintetizando o primeiro bloco; a conexão continua ativa…");}},NarrationPlaybackPolicy.CHARON_WAIT_STATUS_MS);
        ui.postDelayed(new Runnable(){public void run(){if(session==charonNarrationGeneration&&isCurrentAudioSession(coordinated)&&charonVoiceStartedSession!=session)setStatus("Charon continua processando. O app aguardará a resposta ou o timeout real da conexão, sem trocar de voz antes da hora.");}},NarrationPlaybackPolicy.CHARON_LONG_WAIT_STATUS_MS);
        final NarrativeAudioEngine engine=narrativeAudio;
        // Voz e análise das camadas começam em paralelo. A biblioteca de sons nunca
        // bloqueia a primeira palavra.
        if(engine!=null)engine.prepareSceneAsync(clean,environmentalDirector==null?lastAudioPlan:environmentalDirector.mergeAudioPlan(lastAudioPlan,lastPrompt),db.getSceneState(),null);
        ui.post(new Runnable(){public void run(){if(session!=charonNarrationGeneration||!isCurrentAudioSession(coordinated))return;audio.beginVoiceSession();if(engine!=null)engine.beginNarration(plainVoiceChunks(chunks));setStatus("Charon: sintetizando a leitura contínua • fallback Android já preparado • "+audioLayersStatus()+".");synthesizeChunk(chunks,0,session,coordinated);}});
    }

    private boolean ttsAndroidFallbackAllowed(){return prefs!=null&&prefs.getBoolean("tts_android_fallback_enabled",false);}
    private void migrateGemini25TtsPreference(){
        if(prefs==null||prefs.getBoolean("tts_2_5_primary_r20_migrated",false))return;
        String current=prefs.getString("tts_model","");
        String canonical=canonicalConfiguredTtsModel(current);
        prefs.edit().putString("tts_model",canonical).putBoolean("tts_2_5_primary_r20_migrated",true).apply();
    }

    private static String canonicalConfiguredTtsModel(String configured){String value=configured==null?"":configured.trim();if(value.length()==0)return "gemini-2.5-flash-preview-tts";if("gemini-3.1-flash-tts".equalsIgnoreCase(value))return "gemini-3.1-flash-tts-preview";return value;}

    private String ttsCacheModelKey(String configured){return NarrationPlaybackPolicy.CACHE_PIPELINE_ID+"|"+NarrationPlaybackPolicy.STYLE_ID+"|world="+activeWorldProfile()+"|configured="+(configured==null?"":configured.trim());}
    private String audioLayersStatus(){
        int sounds=smartAudio==null?0:smartAudio.indexedSoundCount();
        return sounds>0?("ambiência, música e SFX ativos com "+sounds+" sons indexados"):
                "voz ativa; sem SFX, música ou ambiência porque a biblioteca de sons está vazia";
    }

    /** Primeiro bloco menor para baixa latência; os seguintes permanecem amplos e semânticos. */
    private List<String> charonVoiceChunks(String text){String def=prefs==null?"Charon":prefs.getString("tts_voice","Charon");return npcVoiceDirector==null?NarrationChunker.charon(text):npcVoiceDirector.voiceChunks(text,def);}

    
    private List<String> nativeVoiceChunks(String text){List<String> out=isNativeNeuralProfile()?NarrationChunker.kokoro(text):NarrationChunker.android(text);nativeChapterStartIndexes.clear();if(!out.isEmpty())nativeChapterStartIndexes.add(0);return out;}

    private void speakNativeNarrationWithSfx(String text){
        final String clean=PortugueseNarrationSanitizer.sanitize(GeneratedTextSanitizer.narrative(stripMarkdown(text)));if(clean.length()==0){toast("Não há texto para narrar.");return;}
        if(!audioEngineReady)initializeAudioEngineAsync();
        if(nativeTts==null||!nativeTtsReady||!nativeTtsLanguageReady){cancelNarrationAudio();pendingRequestedNativeNarration=clean;ensureNativeTtsInitialized();setStatus("PLAY solicitado. Preparando a voz do Android sem bloquear a tela…");return;}
        cancelNarrationAudio();applyNativeNarrativeDelivery();beginCoordinatedAudioSession("Android TTS",clean);pauseBackgroundWorkForNarration();startAudioServiceSafely();final long session=++nativeNarrationSession;final List<String> chunks=nativeVoiceChunks(clean);setStatus("Voz do Android pronta • iniciando em "+chunks.size()+" bloco"+(chunks.size()==1?"":"s")+" contínuo"+(chunks.size()==1?"":"s")+"…");
        final NarrativeAudioEngine engine=narrativeAudio;
        if(engine!=null)engine.prepareSceneAsync(clean,environmentalDirector==null?lastAudioPlan:environmentalDirector.mergeAudioPlan(lastAudioPlan,lastPrompt),db.getSceneState(),null);
        ui.post(new Runnable(){public void run(){if(session!=nativeNarrationSession)return;if(engine!=null)engine.beginNarration(chunks);audio.setExternalVoiceActive(true);nativeNarrationQueue.clear();nativeNarrationQueue.addAll(chunks);nativeNarrationQueueIndex=0;nativeVoicePendingChunks=nativeNarrationQueue.size();nativeNarrationBedStarted=true;setStatus("Voz do Android iniciando • "+audioLayersStatus()+".");speakNextNativeNarrationChunk();}});
    }

    private void speakNextNativeNarrationChunk(){
        if(nativeTts==null||!nativeTtsReady||nativeNarrationQueueIndex<0||nativeNarrationQueueIndex>=nativeNarrationQueue.size()){finishNativeNarration();return;}
        try{
            final String sentence=nativeNarrationQueue.get(nativeNarrationQueueIndex);final String id="narracao_"+nativeNarrationSession+"_"+nativeNarrationQueueIndex;final boolean neural=isNativeNeuralProfile();Bundle params=nativeSpeechParams(id,1f);
            synchronized(nativeVoiceSentenceByUtterance){nativeVoiceSentenceByUtterance.clear();nativeVoiceStartedUtterances.clear();nativeVoiceSentenceByUtterance.put(id,sentence);nativeVoicePendingChunks=nativeNarrationQueue.size()-nativeNarrationQueueIndex;}
            int queueMode=TextToSpeech.QUEUE_FLUSH; // Forbidden Lands: cada segmento curto é uma chamada isolada; onDone dispara o próximo.
            int result=nativeTts.speak(sentence,queueMode,params,id);
            if(result==TextToSpeech.ERROR){synchronized(nativeVoiceSentenceByUtterance){nativeVoiceSentenceByUtterance.remove(id);}if(neural){handleNativeTtsError(id,TextToSpeech.ERROR);return;}nativeNarrationQueueIndex++;ui.postDelayed(new Runnable(){public void run(){speakNextNativeNarrationChunk();}},220L);return;}
            if(neural)return; // inferência neural lenta não recebe watchdog/timeout; somente onDone real avança a fila.
            final long watchdogSession=nativeNarrationSession;final int watchdogIndex=nativeNarrationQueueIndex;
            ui.postDelayed(new Runnable(){public void run(){recoverStuckNativeUtterance(id,watchdogSession,watchdogIndex,true,"A voz Android não iniciou o bloco; o app continuou sem travar.");}},8000L);
            final long timeout=Math.max(20000L,Math.min(100000L,sentence.length()*100L+10000L));ui.postDelayed(new Runnable(){public void run(){recoverStuckNativeUtterance(id,watchdogSession,watchdogIndex,false,"A voz Android não concluiu o bloco; o app continuou sem travar.");}},timeout);
        }catch(Throwable error){if(isNativeNeuralProfile()){setStatus("Kokoro encontrou uma falha; a narração foi interrompida sem pular blocos.");failCoordinatedAudioSession("neural-tts-exception");audio.setExternalVoiceActive(false);if(narrativeAudio!=null)narrativeAudio.cancelNarration();resumeBackgroundWorkAfterNarration();}else{nativeNarrationQueueIndex++;setStatus("A voz Android falhou em um trecho; continuando a partir do próximo.");ui.postDelayed(new Runnable(){public void run(){speakNextNativeNarrationChunk();}},300L);}}
    }
    private void recoverStuckNativeUtterance(String id,long watchdogSession,int watchdogIndex,boolean onlyBeforeStart,String message){
        if(isNativeNeuralProfile())return;String stuck=null;synchronized(nativeVoiceSentenceByUtterance){boolean current=watchdogSession==nativeNarrationSession&&watchdogIndex==nativeNarrationQueueIndex;boolean started=nativeVoiceStartedUtterances.contains(id);if(current&&nativeVoiceSentenceByUtterance.containsKey(id)&&(!onlyBeforeStart||!started)){stuck=nativeVoiceSentenceByUtterance.remove(id);nativeVoiceStartedUtterances.remove(id);}}
        if(stuck==null)return;try{nativeTts.stop();}catch(Throwable ignored){}if(narrativeAudio!=null)narrativeAudio.onUtteranceDone(id);nativeNarrationQueueIndex++;setStatus(message);if(nativeNarrationQueueIndex>=nativeNarrationQueue.size())finishNativeNarration();else ui.postDelayed(new Runnable(){public void run(){speakNextNativeNarrationChunk();}},260L);
    }
    private void finishNativeNarration(){completeCoordinatedAudioSession();nativeNarrationQueue.clear();nativeChapterStartIndexes.clear();nativeNarrationQueueIndex=0;nativeVoicePendingChunks=0;nativeNarrationBedStarted=false;audio.setExternalVoiceActive(false);if(narrativeAudio!=null)narrativeAudio.endNarration();resumeBackgroundWorkAfterNarration();setStatus("Narração concluída. Música e ambiência permanecem suavemente na cena; PLAY repete tudo.");}

    private boolean isCurrentAudioSession(AudioSessionCoordinator.Session coordinated){
        return coordinated!=null&&audioSessionCoordinator!=null&&audioSessionCoordinator.isCurrent(coordinated)&&coordinated==activeAudioSession;
    }

    private JSONObject buildCharonDirection(String speaker,String voice){
        JSONObject out=new JSONObject();JSONObject plan=lastAudioPlan==null?new JSONObject():lastAudioPlan;
        try{
            String who=speaker==null||speaker.trim().length()==0?"Narrador":speaker.trim();
            out.put("speaker",who).put("voice",voice==null?"Charon":voice);
            out.put("delivery",plan.optString("delivery","normal"));
            out.put("intensity",Math.max(0,Math.min(5,plan.optInt("intensity",1))));
            out.put("pause_profile",plan.optString("pause_profile","normal"));
            out.put("environment",plan.optString("environment",""));
            out.put("weather",plan.optString("weather",""));
            out.put("location",plan.optString("location",NarrativeLocationNaturalizer.currentNarrativeLabel(db)));
            out.put("time_of_day",plan.optString("time_of_day",""));
            out.put("music_mood",plan.optString("music_mood",""));
            if("Narrador".equalsIgnoreCase(who)){
                out.put("role","Mestre e narrador da mesa");
                out.put("style",NarrationPlaybackPolicy.DEFAULT_NARRATOR_STYLE);
            }else{
                out.put("role","NPC em diálogo direto na cena");
                JSONObject profile=npcVoiceDirector==null?new JSONObject():npcVoiceDirector.byName(who);
                String register=profile.optString("register_name","");String speaking=profile.optString("speaking_style","");
                StringBuilder identity=new StringBuilder();
                if(register.length()>0)identity.append("registro ").append(register);
                if(speaking.length()>0){if(identity.length()>0)identity.append("; ");identity.append(speaking);}
                if(profile.has("tempo")){if(identity.length()>0)identity.append("; ");identity.append("tempo persistente ").append(String.format(Locale.US,"%.2f",profile.optDouble("tempo",1d)));}
                if(profile.has("warmth")){if(identity.length()>0)identity.append("; ");identity.append("calor ").append(profile.optInt("warmth",50)).append("/100");}
                if(profile.has("formality")){if(identity.length()>0)identity.append("; ");identity.append("formalidade ").append(profile.optInt("formality",50)).append("/100");}
                out.put("speaker_profile",identity.toString());
                out.put("style","Preserve a identidade vocal persistente deste NPC e interprete somente a fala atribuída a ele, com naturalidade humana e sem caricatura.");
            }
        }catch(Exception e){AppLog.w("CharonDirection","Não foi possível montar toda a direção de voz; usando o perfil seguro do narrador.",e);try{out.put("speaker","Narrador").put("role","Mestre e narrador da mesa").put("style",NarrationPlaybackPolicy.DEFAULT_NARRATOR_STYLE);}catch(Exception ignored){AppLog.ignored("CharonDirection","Direção mínima indisponível.",ignored);}}
        return out;
    }

    private void synthesizeChunk(final List<String> chunks,final int index,final long session,final AudioSessionCoordinator.Session coordinated){
        synthesizeChunk(chunks,index,session,coordinated,0);
    }

    private void synthesizeChunk(final List<String> chunks,final int index,final long session,final AudioSessionCoordinator.Session coordinated,final int recoveryAttempt){
        if(session!=charonNarrationGeneration||!isCurrentAudioSession(coordinated))return;
        if(index>=chunks.size()){activeCharonRequest=null;audio.endVoiceSessionInput();if(chunks.isEmpty()&&narrativeAudio!=null)narrativeAudio.endNarration();return;}
        String key=geminiKey();String paidKey=geminiPaidKey();final String model=canonicalConfiguredTtsModel(prefs.getString("tts_model","gemini-2.5-flash-preview-tts"));final String cacheModel=ttsCacheModelKey(model);final String packedSentence=chunks.get(index);final String sentence=NpcVoiceDirector.text(packedSentence);final String voice=NpcVoiceDirector.voice(packedSentence,prefs.getString("tts_voice","Charon"));final String speaker=NpcVoiceDirector.speaker(packedSentence);final JSONObject ttsDirection=buildCharonDirection(speaker,voice);final String delivery=ttsDirection.optString("delivery","normal");final int intensity=ttsDirection.optInt("intensity",1);final String pauseProfile=ttsDirection.optString("pause_profile","normal");final String expressiveText=GeminiTtsMarkupDirector.annotateForModel(model,sentence,delivery,intensity,pauseProfile,speaker);final boolean safeRecovery=recoveryAttempt>0;final String ttsText=safeRecovery?sentence:expressiveText;try{if(safeRecovery)ttsDirection.put("recovery_mode",recoveryAttempt==1?"clean transcript, same performance direction":"clean transcript, simplified reliable delivery");if(recoveryAttempt>=2){ttsDirection.put("delivery","normal");ttsDirection.put("intensity",Math.min(2,intensity));ttsDirection.put("pause_profile","normal");}}catch(Exception ignored){AppLog.ignored("CharonDirection","Falha ao preparar modo seguro de recuperação.",ignored);}final String cacheDirection=ttsDirection.toString();final boolean last=index==chunks.size()-1;
        File cached=ttsCache==null?null:ttsCache.get(cacheModel,voice,ttsText,cacheDirection);
        if(cached!=null){
            activeCharonRequest=null;
            audioSessionCoordinator.event(coordinated,"charon-cache-hit","chars",sentence.length());if(index==0&&charonLatencyTelemetry!=null)charonLatencyTelemetry.firstAudio();
            audio.enqueueTimedVoice(cached,false,new AudioController.TimedVoiceStart(){public void onStart(int durationMs){onCharonVoiceStarted(session,sentence,durationMs,coordinated);if(!last)scheduleNextCharonChunk(chunks,index+1,session,coordinated,durationMs);}},new Runnable(){public void run(){if(session==charonNarrationGeneration&&isCurrentAudioSession(coordinated)&&last){if(narrativeAudio!=null)narrativeAudio.endNarration();completeCoordinatedAudioSession();resumeBackgroundWorkAfterNarration();}}});
            if(last)audio.endVoiceSessionInput();return;
        }
        if(index==0&&aiQuotaGovernor!=null&&!aiQuotaGovernor.canCallTts(Math.max(1,chunks.size()))){
            if(ttsAndroidFallbackAllowed())fallbackToNativeNarration(joinVoiceChunks(chunks),session,"O orçamento local do Charon não comporta a cena inteira.");
            else{audio.stopVoice();if(narrativeAudio!=null)narrativeAudio.cancelNarration();failCoordinatedAudioSession("tts-local-limit");resumeBackgroundWorkAfterNarration();setStatus("Charon não iniciou: o limite local de TTS não comporta a cena. O Android não assumiu porque o fallback automático está desligado.");}
            return;
        }
        final long requestedAt=System.currentTimeMillis();if(index==0&&charonLatencyTelemetry!=null)charonLatencyTelemetry.request();
        JSONObject requestDetails=new JSONObject();try{requestDetails.put("block",index+1).put("blocks",chunks.size()).put("chars",sentence.length()).put("voice",voice).put("model",model).put("textHash",Integer.toHexString(sentence.hashCode())).put("cache",false).put("speaker",speaker).put("delivery",delivery).put("intensity",intensity).put("pauseProfile",pauseProfile).put("inlineTags",!ttsText.equals(sentence)).put("recoveryAttempt",recoveryAttempt).put("safeRecovery",safeRecovery).put("tagCount",GeminiTtsMarkupDirector.tagCount(ttsText));}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}
        audioSessionCoordinator.event(coordinated,"charon-synthesis-request",requestDetails);
        activeCharonRequest=gemini.synthesizeSpeech(key,paidKey,model,voice,ttsText,ttsDirection,new GeminiService.FileCallback(){
            public void onSuccess(final File file,String mime){
                if(!isCurrentAudioSession(coordinated)){if(file!=null)file.delete();return;}
                JSONObject readyDetails=new JSONObject();try{readyDetails.put("block",index+1).put("blocks",chunks.size()).put("bytes",file==null?0:file.length()).put("latencyMs",System.currentTimeMillis()-requestedAt).put("voice",voice).put("model",model).put("textHash",Integer.toHexString(sentence.hashCode()));}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}
                audioSessionCoordinator.event(coordinated,"charon-synthesis-ready",readyDetails);if(index==0&&charonLatencyTelemetry!=null)charonLatencyTelemetry.firstAudio();
                if(aiQuotaGovernor!=null)aiQuotaGovernor.recordTtsCall();
                final File playable=file;
                ui.post(new Runnable(){public void run(){
                    if(session!=charonNarrationGeneration||!isCurrentAudioSession(coordinated)){if(playable!=null)playable.delete();return;}
                    try{
                        // O áudio recém-chegado entra no MediaPlayer antes da cópia para o cache.
                        // Assim a primeira palavra não espera I/O + fsync em armazenamento interno.
                        audio.enqueueTimedVoice(playable,true,new AudioController.TimedVoiceStart(){public void onStart(int durationMs){onCharonVoiceStarted(session,sentence,durationMs,coordinated);if(!last)scheduleNextCharonChunk(chunks,index+1,session,coordinated,durationMs);}},new Runnable(){public void run(){if(session==charonNarrationGeneration&&isCurrentAudioSession(coordinated)&&last){if(narrativeAudio!=null)narrativeAudio.endNarration();completeCoordinatedAudioSession();resumeBackgroundWorkAfterNarration();}}});
                        activeCharonRequest=null;if(last)audio.endVoiceSessionInput();
                        if(ttsCache!=null&&playable!=null){
                            AppExecutors.io().execute(new Runnable(){public void run(){
                                try{ttsCache.store(cacheModel,voice,ttsText,cacheDirection,playable);}
                                catch(Exception cacheError){AppLog.w("TtsCache","A voz tocou normalmente, mas este bloco não pôde ser gravado no cache.",cacheError);}
                            }});
                        }
                        // O próximo request é disparado durante a reprodução, com espaçamento proporcional
                        // à duração do bloco atual. Nunca fazemos rajada de chamadas TTS consecutivas.
                    }catch(Exception e){audio.stopVoice();if(narrativeAudio!=null)narrativeAudio.cancelNarration();failCoordinatedAudioSession("voice-start-error");resumeBackgroundWorkAfterNarration();toast("Voz: "+e.getMessage());}
                }});
            }
            public void onError(final String error){ui.post(new Runnable(){public void run(){
                if(session!=charonNarrationGeneration||!isCurrentAudioSession(coordinated))return;
                activeCharonRequest=null;JSONObject failureDetails=new JSONObject();try{failureDetails.put("block",index+1).put("latencyMs",System.currentTimeMillis()-requestedAt).put("voice",voice).put("model",model).put("textHash",Integer.toHexString(sentence.hashCode())).put("error",error==null?"erro sem detalhe":error);}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}audioSessionCoordinator.event(coordinated,"charon-synthesis-error",failureDetails);
                if(recoveryAttempt<NarrationPlaybackPolicy.CHARON_BLOCK_RECOVERY_ATTEMPTS){
                    final int nextAttempt=recoveryAttempt+1;
                    final long retryDelay=NarrationPlaybackPolicy.CHARON_BLOCK_RETRY_BASE_MS*(long)nextAttempt;
                    setStatus("Charon perdeu o bloco "+(index+1)+"/"+chunks.size()+". "+(nextAttempt==1?"Repetindo o mesmo trecho sem tags inline":"Repetindo em modo seguro de voz")+" (tentativa "+nextAttempt+"/"+NarrationPlaybackPolicy.CHARON_BLOCK_RECOVERY_ATTEMPTS+")…");
                    JSONObject retryDetails=new JSONObject();try{retryDetails.put("block",index+1).put("attempt",nextAttempt).put("delayMs",retryDelay).put("error",compactGeminiFailure(error));}catch(Exception ignored){AppLog.ignored("MainActivity","Falha ao registrar recuperação Charon.",ignored);}
                    audioSessionCoordinator.event(coordinated,"charon-block-retry",retryDetails);
                    ui.postDelayed(new Runnable(){public void run(){if(session==charonNarrationGeneration&&isCurrentAudioSession(coordinated))synthesizeChunk(chunks,index,session,coordinated,nextAttempt);}},retryDelay);
                    return;
                }
                if(charonVoiceStartedSession!=session){
                    if(ttsAndroidFallbackAllowed())fallbackToNativeNarration(joinVoiceChunks(chunks.subList(index,chunks.size())),session,error);
                    else{audio.stopVoice();if(narrativeAudio!=null)narrativeAudio.cancelNarration();failCoordinatedAudioSession("charon-start-error");resumeBackgroundWorkAfterNarration();setStatus("Charon não iniciou após as tentativas de recuperação • "+compactGeminiFailure(error)+" • Android não assumiu automaticamente.");}
                    return;
                }
                audio.endVoiceSessionInput();
                if(ttsAndroidFallbackAllowed()){setStatus("Charon não recuperou o bloco "+(index+1)+". Os blocos já prontos serão concluídos antes do fallback Android.");scheduleNativeContinuationAfterCharon(joinVoiceChunks(chunks.subList(index,chunks.size())),session,error,0);}
                else{setStatus("Charon pausou no bloco "+(index+1)+"/"+chunks.size()+" após tentar recuperá-lo. PLAY pode repetir a cena; nenhum trecho restante foi marcado como narrado.");failCoordinatedAudioSession("charon-partial-error-after-retries");resumeBackgroundWorkAfterNarration();}
            }});}
        });
    }

    private void scheduleNextCharonChunk(final List<String> chunks,final int nextIndex,final long session,final AudioSessionCoordinator.Session coordinated,int currentDurationMs){
        if(nextIndex>=chunks.size()||session!=charonNarrationGeneration||!isCurrentAudioSession(coordinated))return;
        final long delay=NarrationPlaybackPolicy.nextBlockPrefetchDelayMs(currentDurationMs);
        JSONObject paced=new JSONObject();try{paced.put("next_block",nextIndex+1).put("delay_ms",delay).put("current_duration_ms",currentDurationMs);}catch(Exception ignored){AppLog.ignored("MainActivity","Falha ao registrar prefetch Charon.",ignored);}
        audioSessionCoordinator.event(coordinated,"charon-paced-prefetch",paced);
        ui.postDelayed(new Runnable(){public void run(){if(session==charonNarrationGeneration&&isCurrentAudioSession(coordinated))synthesizeChunk(chunks,nextIndex,session,coordinated);}},delay);
    }

    private void onCharonVoiceStarted(long session,String sentence,int durationMs,AudioSessionCoordinator.Session coordinated){
        if(session!=charonNarrationGeneration||!isCurrentAudioSession(coordinated))return;boolean firstStart=charonVoiceStartedSession!=session;charonVoiceStartedSession=session;if(firstStart&&charonLatencyTelemetry!=null)charonLatencyTelemetry.play();charonFallbackInProgress=false;audioSessionCoordinator.event(coordinated,"voice-started",new JSONObject());if(narrativeAudio!=null)narrativeAudio.onSyntheticChunkStart(sentence,durationMs);setStatus("Charon narrando • "+ttsModelStatus()+" • música e ambiência ao fundo.");
    }

    private void scheduleNativeContinuationAfterCharon(final String remaining,final long session,final String reason,final int attempt){
        if(session!=charonNarrationGeneration||remaining==null||remaining.trim().length()==0)return;
        if(audio!=null&&audio.isVoiceActive()&&attempt<120){ui.postDelayed(new Runnable(){public void run(){scheduleNativeContinuationAfterCharon(remaining,session,reason,attempt+1);}},250L);return;}
        if(session!=charonNarrationGeneration)return;
        failCoordinatedAudioSession("charon-partial-error");resumeBackgroundWorkAfterNarration();
        setStatus("Charon concluiu os blocos disponíveis. Continuando somente o trecho restante com a melhor voz pt-BR do Android.");
        speakNativeNarrationWithSfx(remaining);
    }

    private void fallbackToNativeNarration(String text,long session,String reason){
        if(session!=charonNarrationGeneration||charonVoiceStartedSession==session||charonFallbackInProgress)return;charonFallbackInProgress=true;AppLog.w("Charon","Fallback para TTS Android: "+(reason==null?"sem detalhe":reason));cancelNarrationAudio();setStatus("Charon indisponível. Continuando automaticamente com a voz do Android…");speakNativeNarrationWithSfx(text);
    }

    private static List<String> plainVoiceChunks(List<String> chunks){ArrayList<String> out=new ArrayList<String>();if(chunks!=null)for(String c:chunks){String t=NpcVoiceDirector.text(c);if(t!=null&&!t.trim().isEmpty())out.add(t);}return out;}

    private static String joinVoiceChunks(List<String> chunks){StringBuilder out=new StringBuilder();if(chunks!=null)for(String chunk:chunks){String clean=NpcVoiceDirector.text(chunk);if(clean==null||clean.trim().length()==0)continue;if(out.length()>0)out.append(' ');out.append(clean.trim());}return out.toString();}

    private void generateSceneImage(){String prompt=buildGeminiImagePrompt(lastNarration);if(prompt.length()==0){toast("Ainda não há uma cena visual para gerar.");return;}String key=geminiKey();if(key.trim().length()<20){showFriendlyAiError("Chave Gemini não configurada.",true,prompt);return;}setStatus("Tentando geração interna de imagem...");gemini.generateImage(key,prefs.getString("image_model","gemini-3.1-flash-image"),prompt,new GeminiService.FileCallback(){public void onSuccess(final File file,String mime){ui.post(new Runnable(){public void run(){sharedImageUri=Uri.fromFile(file);prefs.edit().putString(PREF_SCENE_IMAGE_URI,sharedImageUri.toString()).putString(PREF_SCENE_IMAGE_FINGERPRINT,currentSceneVisualFingerprint()).remove(PREF_PENDING_IMAGE_FINGERPRINT).apply();displaySceneImage(sharedImageUri);setStatus("Imagem gerada e salva na cena.");}});}public void onError(final String error){ui.post(new Runnable(){public void run(){setStatus("Geração interna indisponível.");showFriendlyAiError(error,true,prompt);}});}});}

    private String buildGeminiImagePrompt(String scene){
        String visual=lastVisualPrompt==null?"":lastVisualPrompt.trim();if(visual.length()==0)visual=sanitizeVisualSource(scene);if(visual.length()==0)return "";
        StringBuilder figures=new StringBuilder();List<JSONObject> heroes=db.listActiveCharacters();for(JSONObject h:heroes){if(figures.length()>0)figures.append("; ");figures.append(PathfinderTokenPromptBuilder.describeForScene(h));}
        if(currentSceneCastPreview!=null)for(int i=0;i<currentSceneCastPreview.length();i++){JSONObject n=currentSceneCastPreview.optJSONObject(i);if(n==null)continue;String name=n.optString("name","NPC");JSONObject memory=db.findNpcMemoryByName(name);String desc=n.optString("visual_description",memory.optString("visual_description",memory.optString("summary",""))).trim();if(desc.length()>0){if(figures.length()>0)figures.append("; ");JSONObject identity=memory.length()>0?memory:n;String persistent=PathfinderTokenPromptBuilder.describeForScene(identity);figures.append(persistent.length()>0?persistent:(name+": "+desc));}}
        JSONObject state=db.getSceneState();String context="Local exato: "+state.optString("location","não definido")+". Horário: "+state.optString("time_of_day","")+". Clima: "+state.optString("weather","")+".";
        String prompt="Crie UMA NOVA imagem exclusivamente para a cena atual. Ilustração vertical cinematográfica de fantasia em proporção 9:16, pintura digital nítida, composição natural, sem texto, letras, logotipos, moldura ou interface. "+context+" Figuras que estão realmente presentes e não podem ser omitidas, substituídas ou ter idade/espécie alterada: "+(figures.length()==0?"nenhuma figura recorrente definida":figures.toString())+". Ação e ambiente desta cena, e somente desta cena: "+visual+". Não reutilize composição de imagem anterior e não acrescente personagens não mencionados.";
        return prompt.length()>3200?prompt.substring(0,3200):prompt;
    }

    private void editVisualPromptAndOpenGemini(){editVisualPrompt(true);}
    private void editVisualPrompt(final boolean openGemini){final String prompt=buildGeminiImagePrompt(lastNarration);if(prompt.length()==0){toast("Ainda não há uma cena para transformar em imagem.");return;}final EditText edit=input("Prompt visual",prompt,true);edit.setMinLines(10);new AlertDialog.Builder(this).setTitle("Prompt visual limpo").setView(edit).setNegativeButton("Cancelar",null).setPositiveButton(openGemini?"ABRIR GEMINI":"COPIAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){String finalPrompt=edit.getText().toString().trim();if(openGemini)sharePromptToGemini(finalPrompt);else{ClipboardManager cm=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);cm.setPrimaryClip(ClipData.newPlainText("Prompt visual",finalPrompt));toast("Prompt visual copiado.");}}}).show();}

    private void sharePromptToGemini(String prompt){sharePromptToGeminiTarget(prompt,"scene",0L,"");}
    private void sharePromptToGeminiForNpc(String prompt,long npcId,String npcName){sharePromptToGeminiTarget(prompt,"npc",npcId,npcName);}
    private void sharePromptToGeminiForCharacter(String prompt,long characterId){sharePromptToGeminiTarget(prompt,"character",characterId,"");}
    private void sharePromptToGeminiTarget(String prompt,String target,long targetId,String npcName){
        String resolvedTarget=("npc".equals(target)||"character".equals(target))?target:"scene";
        lastPrompt=prompt;SharedPreferences.Editor pending=prefs.edit().putString(PREF_PENDING_IMAGE_TARGET,resolvedTarget);
        if("npc".equals(resolvedTarget)){
            pending.remove(PREF_PENDING_IMAGE_FINGERPRINT).remove(PREF_PENDING_CHARACTER_ID)
                    .putLong(PREF_PENDING_NPC_ID,targetId).putString(PREF_PENDING_NPC_NAME,npcName==null?"":npcName)
                    .putString(PREF_PENDING_NPC_PROMPT,prompt==null?"":prompt);
        }else if("character".equals(resolvedTarget)){
            pending.remove(PREF_PENDING_IMAGE_FINGERPRINT).remove(PREF_PENDING_NPC_ID).remove(PREF_PENDING_NPC_NAME).remove(PREF_PENDING_NPC_PROMPT)
                    .putLong(PREF_PENDING_CHARACTER_ID,targetId);
        }else{
            pending.putString(PREF_PENDING_IMAGE_FINGERPRINT,currentSceneVisualFingerprint())
                    .remove(PREF_PENDING_CHARACTER_ID).remove(PREF_PENDING_NPC_ID).remove(PREF_PENDING_NPC_NAME).remove(PREF_PENDING_NPC_PROMPT);
        }
        pending.apply();Intent x=new Intent(Intent.ACTION_SEND);x.setType("text/plain");x.putExtra(Intent.EXTRA_TEXT,prompt);x.setPackage("com.google.android.apps.bard");
        try{startActivity(x);setStatus("Gemini aberto. A imagem compartilhada de volta será vinculada exclusivamente a "+("character".equals(resolvedTarget)?"este personagem":("npc".equals(resolvedTarget)?"este NPC":"esta cena"))+".");}
        catch(ActivityNotFoundException e){Intent fallback=new Intent(Intent.ACTION_SEND);fallback.setType("text/plain");fallback.putExtra(Intent.EXTRA_TEXT,prompt);startActivity(Intent.createChooser(fallback,"Escolha o Gemini"));setStatus("Escolha o Gemini e compartilhe a imagem de volta depois.");}
    }

    private void showFriendlyAiError(final String error,boolean image,final String visualPrompt){String lower=error==null?"":error.toLowerCase(Locale.US);String title=image?"Imagem indisponível":"IA indisponível";String message;if(image&&lower.contains("limit: 0"))message="A API de geração de imagens configurada não oferece cota Free Tier para esta chave. O prompt visual está preservado: use GERAR NO GEMINI ou uma chave de projeto com faturamento habilitado.";else if(lower.contains("429")||lower.contains("quota")||lower.contains("rate-limit")||lower.contains("limit: 0"))message=image?"A cota de geração interna de imagens está esgotada ou indisponível para este modelo. O prompt visual já está pronto para ser enviado ao aplicativo Gemini.":"A cota do modelo de texto foi atingida. O app tentou os modelos de fallback antes de desistir; aguarde o prazo indicado ou confira Detalhes.";else if(lower.contains("404")||lower.contains("not found")||lower.contains("no longer available"))message="Nenhum dos modelos disponíveis para esta chave conseguiu responder. Abra Detalhes para conferir as tentativas.";else if(lower.contains("503")||lower.contains("high demand")||lower.contains("unavailable"))message="Os modelos tentados estavam temporariamente sobrecarregados. O fallback já tentou alternativas; aguarde um instante e toque novamente.";else if(lower.contains("chave")||lower.contains("api key")||lower.contains("401"))message="A chave Gemini está inválida ou não foi aceita. Confira a chave em Config.";else if(lower.contains("403")||lower.contains("permission_denied"))message="A chave foi reconhecida, mas o projeto/modelo recusou a operação. O app já tentou modelos alternativos quando possível; abra Detalhes para identificar qual modelo recusou.";else message=image?"Não foi possível gerar a imagem internamente. Você pode usar o fluxo pelo aplicativo Gemini.":"O fallback não encontrou um modelo que respondesse. Abra Detalhes para ver cada tentativa.";AlertDialog.Builder b=new AlertDialog.Builder(this).setTitle(title).setMessage(message).setNegativeButton("Fechar",null).setNeutralButton("DETALHES",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){final EditText details=input("Detalhes técnicos",error==null?"Sem detalhes.":error,true);details.setMinLines(8);new AlertDialog.Builder(MainActivity.this).setTitle("Detalhes técnicos").setView(details).setPositiveButton("Fechar",null).show();}});if(image&&visualPrompt!=null&&visualPrompt.length()>0)b.setPositiveButton("ABRIR GEMINI",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){sharePromptToGemini(visualPrompt);}});b.show();}

    private String sanitizeVisualSource(String raw){String clean=stripMarkdown(raw);String lower=clean.toLowerCase(Locale.US);String[] cuts={"seus caminhos","caminhos plausíveis","opções:","o que você faz?","o que o guerreiro","opção aberta"};int cut=clean.length();for(String marker:cuts){int i=lower.indexOf(marker);if(i>=0&&i<cut)cut=i;}clean=clean.substring(0,cut);StringBuilder out=new StringBuilder();String[] lines=clean.split("\\n");for(String line:lines){String l=line.trim(),ll=l.toLowerCase(Locale.US);if(l.length()==0)continue;if(ll.matches("^\\d+[.)].*"))continue;if(ll.contains("role um teste")||ll.contains("teste de força")||ll.contains("teste de destreza")||ll.contains("cd sugerida")||ll.matches(".*\\bcd \\d+.*"))continue;if(out.length()>0)out.append(' ');out.append(l);}String result=out.toString().replaceAll("\\s+"," ").trim();return result.length()>1500?result.substring(0,1500):result;}

    private String stripMarkdown(String raw){if(raw==null)return "";return raw.replaceAll("(?m)^#{1,6}\\s*","").replace("**","").replace("__","").replace("`","").replaceAll("(?m)^\\s*[-*]\\s+","• ").replaceAll("(?m)^\\s*\\d+[.)]\\s+","").trim();}

    private void setMarkdown(TextView view,String raw){String html=markdownToHtml(raw);if(Build.VERSION.SDK_INT>=24)view.setText(Html.fromHtml(html,Html.FROM_HTML_MODE_LEGACY));else view.setText(Html.fromHtml(html));}
    private String markdownToHtml(String raw){if(raw==null)return "";String e=raw.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");e=e.replaceAll("(?m)^###\\s*(.+)$","<h3>$1</h3>").replaceAll("(?m)^##\\s*(.+)$","<h2>$1</h2>").replaceAll("(?m)^#\\s*(.+)$","<h1>$1</h1>");e=e.replaceAll("\\*\\*(.+?)\\*\\*","<b>$1</b>").replaceAll("__(.+?)__","<b>$1</b>").replaceAll("(?<!\\*)\\*([^*\\n]+)\\*(?!\\*)","<i>$1</i>");e=e.replaceAll("(?m)^\\s*[-*]\\s+(.+)$","• $1");return e.replace("\n","<br>");}

    private ImageView makeDieTile(int sides){ImageView v=new ImageView(this);v.setContentDescription("Dado de "+sides+" lados");try{InputStream asset=getAssets().open("dice/d"+sides+".png");Bitmap icon=BitmapFactory.decodeStream(asset);asset.close();if(icon!=null){v.setImageBitmap(icon);v.setScaleType(ImageView.ScaleType.CENTER_INSIDE);v.setPadding(dp(2),dp(2),dp(2),dp(2));v.setBackgroundColor(Color.TRANSPARENT);return v;}}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}Bitmap bm=Bitmap.createBitmap(dp(100),dp(100),Bitmap.Config.ARGB_8888);Canvas c=new Canvas(bm);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(GOLD);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(dp(24));p.setTypeface(Typeface.DEFAULT_BOLD);c.drawText("d"+sides,bm.getWidth()/2,bm.getHeight()/2,p);v.setImageBitmap(bm);return v;}

    private JSONObject projectSceneForSuggestions(JSONObject envelope,JSONArray cast){
        JSONObject projected;try{projected=new JSONObject(db.getSceneState().toString());}catch(Exception e){projected=new JSONObject();}
        try{
            JSONObject proposed=envelope==null?null:envelope.optJSONObject("scene_state");
            if(proposed!=null){
                java.util.Iterator<String> keys=proposed.keys();
                while(keys.hasNext()){String key=keys.next();projected.put(key,proposed.opt(key));}
                normalizeProjectedSceneArray(projected,proposed,"present_npcs","present_npcs_json");
                normalizeProjectedSceneArray(projected,proposed,"threats","threats_json");
                normalizeProjectedSceneArray(projected,proposed,"clues","clues_json");
                normalizeProjectedSceneArray(projected,proposed,"pending_consequences","pending_consequences_json");
            }
            JSONArray present=new JSONArray();HashSet<String> names=new HashSet<String>();
            String raw=projected.optString("present_npcs_json","[]");
            try{JSONArray old=new JSONArray(raw);for(int i=0;i<old.length();i++){Object value=old.opt(i);String name=GeneratedTextSanitizer.scalar(String.valueOf(value),"name").trim();if(name.length()>0&&names.add(name.toLowerCase(Locale.ROOT))){if(value instanceof JSONObject){JSONObject npc=new JSONObject(value.toString());npc.put("name",name);present.put(npc);}else present.put(new JSONObject().put("name",name));}}}
            catch(Exception ignored){AppLog.ignored("SceneOptions","Lista antiga de NPCs inválida; reconstruindo a partir da resposta atual.",ignored);}
            if(cast!=null)for(int i=0;i<cast.length();i++){JSONObject npc=cast.optJSONObject(i);if(npc==null)continue;String name=GeneratedTextSanitizer.scalar(npc.toString(),"name").trim();if(name.length()>0&&names.add(name.toLowerCase(Locale.ROOT))){JSONObject cleanNpc=new JSONObject(npc.toString());cleanNpc.put("name",name);present.put(cleanNpc);}}
            JSONArray updates=envelope==null?null:envelope.optJSONArray("npc_updates");
            if(updates!=null)for(int i=0;i<updates.length();i++){JSONObject npc=updates.optJSONObject(i);if(npc==null)continue;String name=GeneratedTextSanitizer.scalar(npc.toString(),"name").trim();if(name.length()>0&&names.add(name.toLowerCase(Locale.ROOT))){JSONObject cleanNpc=new JSONObject(npc.toString());cleanNpc.put("name",name);present.put(cleanNpc);}}
            projected.put("present_npcs_json",present.toString());
        }catch(Exception ignored){AppLog.ignored("SceneOptions","Não foi possível projetar todo o estado da cena.",ignored);}
        return projected;
    }

    private void normalizeProjectedSceneArray(JSONObject projected,JSONObject proposed,String publicKey,String storageKey){
        if(projected==null||proposed==null||(!proposed.has(publicKey)&&!proposed.has(storageKey)))return;
        try{
            Object value=proposed.has(publicKey)?proposed.opt(publicKey):proposed.opt(storageKey);
            JSONArray array;
            if(value instanceof JSONArray)array=new JSONArray(value.toString());
            else if(value instanceof JSONObject)array=new JSONArray().put(new JSONObject(value.toString()));
            else{
                String raw=value==null?"[]":String.valueOf(value).trim();
                try{array=new JSONArray(raw);}catch(Exception malformed){array=new JSONArray();if(!raw.isEmpty()&&!"null".equalsIgnoreCase(raw))array.put(raw);}
            }
            projected.put(storageKey,array.toString());
        }catch(Exception error){AppLog.ignored("SceneOptions","Campo projetado inválido: "+publicKey,error);}
    }

    private void scheduleSceneNpcTokenBinding(){
        if(npcTokenAutoBinder==null||currentSceneCastPreview==null||currentSceneCastPreview.length()==0)return;final ArrayList<String> names=new ArrayList<String>();for(int i=0;i<currentSceneCastPreview.length();i++){JSONObject npc=currentSceneCastPreview.optJSONObject(i);if(npc!=null&&!npc.optBoolean("transient",false)&&!npc.optBoolean("anonymous",false)&&npc.optString("name","").trim().length()>0)names.add(npc.optString("name").trim());}if(names.isEmpty())return;
        AppExecutors.io().execute(new Runnable(){public void run(){boolean changed=false;for(String name:names)changed|=npcTokenAutoBinder.assignIfMissing(name);if(!changed)return;final JSONArray refreshed=new JSONArray();for(int i=0;i<currentSceneCastPreview.length();i++){JSONObject old=currentSceneCastPreview.optJSONObject(i);if(old==null)continue;try{JSONObject copy=new JSONObject(old.toString());JSONObject memory=db.findNpcMemoryByName(copy.optString("name"));if(memory.optString("token_uri","").length()>0)copy.put("token_uri",memory.optString("token_uri"));refreshed.put(copy);}catch(Exception ignored){refreshed.put(old);}}ui.post(new Runnable(){public void run(){currentSceneCastPreview=refreshed;prefs.edit().putString("last_scene_cast_preview",refreshed.toString()).apply();screenCache.remove("Mestre IA");screenCache.remove("Combate");if("Mestre IA".equals(currentScreen))showNarrator();else if("Combate".equals(currentScreen))showCombat();}});}});
    }

    private String currentSceneVisualFingerprint(){StringBuilder b=new StringBuilder();b.append(activeWorldProfile()).append('|').append(lastVisualPrompt==null?"":lastVisualPrompt).append('|');JSONObject scene=db==null?new JSONObject():db.getSceneState();b.append(scene.optString("location")).append('|').append(scene.optString("day_number")).append('|').append(scene.optString("time_of_day")).append('|').append(scene.optString("weather"));if(currentSceneCastPreview!=null)for(int i=0;i<currentSceneCastPreview.length();i++){JSONObject n=currentSceneCastPreview.optJSONObject(i);if(n!=null)b.append('|').append(n.optString("name")).append(':').append(n.optString("visual_description"));}try{MessageDigest md=MessageDigest.getInstance("SHA-256");byte[] bytes=md.digest(b.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder hex=new StringBuilder();for(int i=0;i<12&&i<bytes.length;i++)hex.append(String.format(Locale.US,"%02x",bytes[i]));return hex.toString();}catch(Exception e){return Integer.toHexString(b.toString().hashCode());}}
    private void clearSceneImageReference(){sharedImageUri=null;if(prefs!=null)prefs.edit().remove(PREF_SCENE_IMAGE_URI).remove(PREF_SCENE_IMAGE_FINGERPRINT).apply();}
    private void invalidateSceneImageIfContextChanged(){String stored=prefs.getString(PREF_SCENE_IMAGE_FINGERPRINT,"");if(sharedImageUri!=null&&stored.length()>0&&!stored.equals(currentSceneVisualFingerprint())){clearSceneImageReference();screenCache.remove("Mestre IA");}}

    private void loadStoryState(){JSONObject st=db.getStoryState();String stored=st.optString("last_narration","");JSONArray storedOptions;try{storedOptions=new JSONArray(st.optString("options_json","[]"));}catch(Exception e){storedOptions=new JSONArray();}try{currentSceneCastPreview=new JSONArray(prefs.getString("last_scene_cast_preview","[]"));}catch(Exception e){currentSceneCastPreview=new JSONArray();}ChoiceSplit repaired=splitNarrationChoices(PortugueseNarrationSanitizer.sanitize(sanitizeNarrationPayload(stored)),storedOptions);lastNarration=NarrativeLocationNaturalizer.naturalize(repaired.narration,db);currentOptions=repaired.options;lastVisualPrompt=st.optString("visual_prompt","");lastPrompt=st.optString("last_action","");lastAiMode=prefs.getString("last_ai_response_mode","Narrador");try{String p=st.optString("pending_test_json","");pendingTest=p.length()>0?new JSONObject(p):new JSONObject();}catch(Exception e){pendingTest=new JSONObject();}try{lastAudioPlan=new JSONObject(prefs.getString("last_audio_plan","{}"));}catch(Exception e){lastAudioPlan=new JSONObject();}try{lastMasterSupport=new JSONObject(prefs.getString("last_master_support_json","{}"));}catch(Exception e){lastMasterSupport=new JSONObject();}if(lastNarration.length()>0){mergeNarratedKnownNpcs(currentSceneCastPreview,lastNarration);mergeExplicitlyNamedNpcHints(currentSceneCastPreview,lastNarration);synchronizeVisualSceneCast();prefs.edit().putString("last_scene_cast_preview",currentSceneCastPreview.toString()).apply();}if(lastNarration.length()>0&&pendingTest.length()==0&&"Narrador".equals(lastAiMode)){JSONArray history=SceneOptionDiversifier.parseHistory(db.getSceneOptionHistory());JSONObject projected=projectSceneForSuggestions(new JSONObject(),currentSceneCastPreview);currentOptions=SceneOptionDiversifier.ensureAlways(currentOptions,history,lastNarration,lastPrompt,projected,db.getMasterRuntimeState().optInt("beat_no",0)+1);}if((!lastNarration.equals(stored)||!currentOptions.toString().equals(st.optString("options_json","[]")))&&stored.trim().length()>0)db.saveStoryState(st.optInt("started",0)>0,lastNarration,lastVisualPrompt,currentOptions.toString(),st.optString("pending_test_json",""),lastPrompt);}
    private void persistStory(String action){
        db.saveStoryState(lastNarration.length()>0,lastNarration,lastVisualPrompt,currentOptions==null?"[]":currentOptions.toString(),pendingTest==null||pendingTest.length()==0?"":pendingTest.toString(),action==null?"":action);
        try{
            if(kingmakerRepository!=null&&lastNarration.length()>0&&KingmakerPreludePolicy.PHASE_RESTOV_ARRIVAL.equals(kingmakerRepository.campaignStoryPhase()))
                kingmakerRepository.setCampaignStoryPhase(KingmakerPreludePolicy.PHASE_RESTOV_SANDBOX,false);
        }catch(Exception error){AppLog.w("KingmakerPrelude","Não foi possível avançar chegada → sandbox.",error);}
    }

