    private String subclassOf(String full){if(full==null)return "";int i=full.indexOf(" — ");if(i<0)i=full.indexOf(" - ");return i>0?full.substring(i+(full.charAt(i)==' '?3:1)).trim():"";}
    
    
    
    
    
    
    



