    private void guildSiteDialog(final long gid){LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);final EditText name=labeledField(f,"Nome","",false),type=labeledField(f,"Tipo (sede, filial, oficina, armazém...)","filial",false),location=labeledField(f,"Local","",false),hex=labeledField(f,"Hex do mapa, opcional","",false),services=labeledField(f,"Serviços, um por linha","",true),defenses=labeledField(f,"Defesas, uma por linha","",true),stock=labeledField(f,"Estoque, um por linha","",true);new AlertDialog.Builder(this).setTitle("Novo local de guilda").setView(scrollableDialogView(f)).setNegativeButton("Cancelar",null).setPositiveButton("SALVAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{String hexId=value(hex);if(hexId.length()>0&&db.getRawMapHex(db.getMapState().optString("map_package_id"),hexId).length()==0)throw new IllegalArgumentException("O hex não existe no atlas ativo.");db.addGuildSiteChecked(new JSONObject().put("guild_id",gid).put("name",value(name)).put("site_type",value(type)).put("location",value(location)).put("hex_id",hexId).put("services_json",linesArray(services).toString()).put("defenses_json",linesArray(defenses).toString()).put("stock_json",linesArray(stock).toString()));showGuildDetail(gid);}catch(Exception e){toast("Local não salvo: "+e.getMessage());}}}).show();}

