    private void livingWorldApplyActivity(final long activityId,String title){
        try{safety.beforeDestructiveChange("aplicar resultado documentado da atividade "+title);}catch(Exception e){toast("Aplicação bloqueada: "+e.getMessage());return;}
        JSONObject outcome=livingWorldEngine.applyAuthorizedActivityOutcome(activityId);
        if(outcome.optBoolean("applied",false)){screenCache.clear();showLivingWorld();toast(outcome.optBoolean("idempotent",false)?"Resultado já havia sido aplicado.":"Resultado aplicado à campanha e registrado no diário.");}
        else toast(outcome.optString("reason","O resultado não pôde ser aplicado."));
    }

    private void livingWorldAuthorizeActivityDialog(final long activityId,String title){
        LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.setPadding(dp(12),0,dp(12),dp(12));
        final EditText source=labeledField(f,"Fonte habilitada — título ou arquivo exato","",false),page=labeledField(f,"Página","",false),excerpt=labeledField(f,"Trecho da regra","",true),cost=labeledField(f,"Custo JSON, opcional","{}",true),reward=labeledField(f,"Recompensa JSON, opcional","{}",true);page.setInputType(InputType.TYPE_CLASS_NUMBER);
        final CheckBox requiresRoll=check("A regra exige uma rolagem local já realizada",false);f.addView(requiresRoll);
        final List<JSONObject> recentRolls=new ArrayList<JSONObject>();ArrayList<String> rollLabels=new ArrayList<String>();
        for(JSONObject roll:db.listDiceHistory()){if(roll.optLong("consumed_at",0)>0||roll.optString("test_key","").trim().length()>0)continue;recentRolls.add(roll);String label="#"+roll.optLong("id")+" • "+roll.optString("formula")+" = "+roll.optInt("total");rollLabels.add(label);if(rollLabels.size()>=30)break;}
        if(rollLabels.isEmpty())rollLabels.add("Nenhuma rolagem livre disponível");
        final Spinner rollSpinner=spinner(rollLabels.toArray(new String[0]),rollLabels.get(0));f.addView(cardWithLabel("ROLAGEM LIVRE PARA VINCULAR",rollSpinner));
        f.addView(text("Campos permitidos: gold_delta, xp_delta, provisions_delta, water_delta, downtime_days, item_add, item_remove, resource_key e resource_delta. O trecho precisa demonstrar o tipo de custo/recompensa. Se houver teste, a rolagem escolhida será vinculada exclusivamente a esta atividade e não poderá ser reutilizada.",12,GREEN,false));
        new AlertDialog.Builder(this).setTitle("Documentar regra — "+title).setView(scrollableDialogView(f)).setNegativeButton("Cancelar",null).setPositiveButton("VALIDAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){
            JSONObject checkJson=new JSONObject();
            try{checkJson.put("required",requiresRoll.isChecked());if(requiresRoll.isChecked()){int index=rollSpinner.getSelectedItemPosition();if(recentRolls.isEmpty()||index<0||index>=recentRolls.size()){toast("Faça uma rolagem local antes de vincular o teste.");return;}JSONObject roll=recentRolls.get(index);checkJson.put("verified",true).put("roll_id",roll.optLong("id")).put("formula",roll.optString("formula")).put("total",roll.optInt("total"));}}catch(Exception error){toast("Não foi possível vincular a rolagem.");return;}
            JSONObject costJson=parseJsonObject(value(cost)),rewardJson=parseJsonObject(value(reward));JSONObject result=livingWorldEngine.authorizeMechanicalOutcome(activityId,value(source),num(page,0),value(excerpt),checkJson,costJson,rewardJson);
            if(result.optBoolean("allowed",false)&&result.optBoolean("updated",false)){screenCache.remove("Mundo Vivo");showLivingWorld();toast(result.optBoolean("check_required",false)?"Regra e rolagem vinculadas. Conclua a narrativa e aplique o resultado.":"Regra documentada. Conclua a narrativa e depois aplique o resultado.");}else toast(result.optString("reason","A regra não foi autorizada."));
        }}).show();
    }

    private static String livingWorldModeLabel(String value){if("leve".equals(value))return "Leve";if("simulacao".equals(value))return "Simulação detalhada";return "Equilibrado";}
    private static String livingWorldModeValue(String value){if("Leve".equals(value))return "leve";if("Simulação detalhada".equals(value))return "simulacao";return "equilibrado";}
    private static String troupeModeLabel(String value){return value==null||value.trim().length()==0?"Itinerante":value;}
    private static String emptyAs(String value,String fallback){return value==null||value.trim().length()==0?fallback:value.trim();}
    private String firstLooseArray(String raw){JSONArray values=parseLooseArray(raw);return values.length()==0?"":values.optString(0);}
    private String looseArrayLines(String raw){JSONArray values=parseLooseArray(raw);StringBuilder out=new StringBuilder();for(int i=0;i<values.length();i++){if(out.length()>0)out.append('\n');out.append(values.optString(i));}return out.toString();}

