    private void bardChronicleDialog(){
        final List<JSONObject> journal=db.listJournal();if(journal.isEmpty()){toast("O Diário ainda não possui história para transformar em balada.");return;}
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),dp(10));
        form.addView(text("O PDF reorganiza os registros em ordem cronológica e os apresenta como uma história oral contada numa taverna. Fatos, nomes e consequências vêm somente da campanha; a moldura do bardo é estilística.",13,TEXT,false));
        final EditText bardName=labeledField(form,"Nome do bardo","Bardo do Braseiro",false);
        final Spinner tone=spinner(new String[]{"Épico e caloroso","Aventureiro e bem-humorado","Sombrio e dramático","Sóbrio e lendário"},"Épico e caloroso");form.addView(cardWithLabel("TOM DA NARRAÇÃO",tone));
        final CheckBox useAi=check("Lapidar a prosa com Gemini quando disponível (1 chamada)",geminiKey().trim().length()>=20);form.addView(useAi);
        form.addView(text("Ao marcar Gemini, o conteúdo necessário do Diário é enviado à API configurada para reescrita literária. Desmarque para manter todo o processo no aparelho.",12,GOLD,false));
        form.addView(text("Sem Gemini, a crônica continua sendo gerada inteiramente no aparelho, com prólogo, capítulos, transições e encerramento de bardo. Campanhas muito extensas usam automaticamente o modo local para não cortar acontecimentos.",12,MUTED,false));
        new AlertDialog.Builder(this).setTitle("Crônica de bardo").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("GERAR PDF",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){prepareBardChroniclePdf(value(bardName),String.valueOf(tone.getSelectedItem()),useAi.isChecked());}}).show();
    }

    private void prepareLiteralAdventurePdf(){
        setStatus("Montando o livro da aventura em segundo plano…");
        AppExecutors.io().execute(new Runnable(){public void run(){try{final File file=new AdventurePdfExporter(MainActivity.this).export(db.getCampaign(),db.listJournal());ui.post(new Runnable(){public void run(){pendingAdventurePdfKind="livro";pendingAdventurePdf=file;openAdventurePdfDestination("Cronicas_"+safeExportName(db.getCampaign().optString("name","Braseiro"))+".pdf");setStatus("Livro da aventura pronto para salvar.");}});}catch(final Exception e){ui.post(new Runnable(){public void run(){toast("PDF: "+e.getMessage());setStatus("Não foi possível montar o PDF.");}});}}});
    }

    private void prepareBardChroniclePdf(final String bardName,final String tone,final boolean preferAi){
        setStatus("Organizando o Diário em segundo plano…");
        AppExecutors.io().execute(new Runnable(){public void run(){
            final JSONObject campaign=db.getCampaign();final List<JSONObject> journal=db.listJournal();final List<JSONObject> heroes=db.listActiveCharacters();
            final JSONObject local=BardChronicleComposer.localManuscript(campaign,journal,heroes,bardName,tone);final String prompt=BardChronicleComposer.aiPrompt(campaign,journal,heroes,bardName,tone);final String system=BardChronicleComposer.aiSystem();
            final String key=geminiKey().trim();final boolean aiAllowed=preferAi&&key.length()>=20&&BardChronicleComposer.aiSourceFits(prompt)&&(aiQuotaGovernor==null||aiQuotaGovernor.canCall(system.length()+prompt.length()));
            ui.post(new Runnable(){public void run(){
                if(!aiAllowed){if(preferAi&&!BardChronicleComposer.aiSourceFits(prompt))toast("A campanha é extensa; o PDF será montado localmente para não cortar acontecimentos.");createBardPdf(local);return;}
                setStatus("O bardo está organizando a campanha em uma única chamada…");gemini.generateText(key,prefs.getString("text_model","gemini-3.5-flash-lite"),system,prompt,new GeminiService.TextCallback(){public void onSuccess(final String raw){ui.post(new Runnable(){public void run(){if(aiQuotaGovernor!=null)aiQuotaGovernor.recordCall(system.length()+prompt.length(),raw==null?0:raw.length());JSONObject ai=parseLooseJson(raw);JSONObject manuscript=BardChronicleComposer.sanitizeAiManuscript(ai,local);createBardPdf(manuscript);}});}public void onError(final String error){ui.post(new Runnable(){public void run(){if(aiQuotaGovernor!=null)aiQuotaGovernor.recordCall(system.length()+prompt.length(),0);toast("O bardo IA não respondeu; usando a versão local sem perder os registros.");createBardPdf(local);}});}});
            }});
        }});
    }

    private void createBardPdf(final JSONObject manuscript){
        setStatus("Montando a crônica em PDF em segundo plano…");
        AppExecutors.io().execute(new Runnable(){public void run(){try{final File file=new AdventurePdfExporter(MainActivity.this).exportBardChronicle(db.getCampaign(),manuscript);ui.post(new Runnable(){public void run(){pendingAdventurePdfKind="bardo";pendingAdventurePdf=file;openAdventurePdfDestination("Balada_"+safeExportName(db.getCampaign().optString("name","Braseiro"))+".pdf");setStatus("Crônica de bardo pronta para salvar em PDF.");}});}catch(final Exception error){ui.post(new Runnable(){public void run(){pendingAdventurePdf=null;toast("Crônica de bardo: "+error.getMessage());setStatus("Não foi possível montar o PDF da crônica.");}});}}});
    }

    private void openAdventurePdfDestination(String filename){Intent x=new Intent(Intent.ACTION_CREATE_DOCUMENT);x.addCategory(Intent.CATEGORY_OPENABLE);x.setType("application/pdf");x.putExtra(Intent.EXTRA_TITLE,filename);startActivityForResult(x,REQ_EXPORT_JOURNAL_PDF);}
    private String safeExportName(String value){String safe=java.text.Normalizer.normalize(value==null?"Braseiro":value,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","").replaceAll("[^A-Za-z0-9_-]+","_").replaceAll("^_+|_+$","");return safe.length()==0?"Braseiro":safe;}

    private void journalDialog(){LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.setPadding(dp(12),0,dp(12),0);final EditText title=labeledField(f,"Título","Anotação "+dateNow(),false);final Spinner kind=spinner(new String[]{"Cena","Nota","NPC","Local","Missão","Regra da casa","Resumo"},"Nota");f.addView(kind);final EditText text=labeledField(f,"Texto","",true);text.setMinLines(7);new AlertDialog.Builder(this).setTitle("Nova entrada").setView(f).setNegativeButton("Cancelar",null).setPositiveButton("Salvar",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){db.addJournal(title.getText().toString(),text.getText().toString(),kind.getSelectedItem().toString());showJournal();}}).show();}

    private void showManuals(final String filter){
        String normalizedFilter=filter==null?"":filter.trim();if(!normalizedFilter.equals(manualVisibleFilter)){manualVisibleFilter=normalizedFilter;manualVisibleLimit=36;}
        ScrollView s=page("Manuais","Biblioteca Pathfinder 2e: PDFs PF2e podem fundamentar regras; material de outros sistemas nunca recebe autoridade mecânica.");final LinearLayout b=body(s);
        List<JSONObject> worldManuals=filterManualsForWorld(db.listManuals(""));int enabledCount=0;for(JSONObject wm:worldManuals)if(wm.optInt("enabled",1)==1)enabledCount++;int readyCount=db.countLocalReadyStatusForWorld(false);
        final boolean folderLinked=hasManualFolderAccess();
        LinearLayout cloud=card();
        cloud.addView(text(folderLinked?"PASTA DE MANUAIS VINCULADA":(drive.isConnected()?"GOOGLE DRIVE CONECTADO POR API":"PASTA DE MANUAIS NÃO VINCULADA"),17,folderLinked||drive.isConnected()?GREEN:GOLD,true));
        String sourceLabel=folderLinked?"Acesso concedido pelo seletor do Android — sem OAuth e sem Google Cloud Console":(drive.isConnected()?"Conta: "+prefs.getString("drive_account_name","selecionada")+" • API legada":"Selecione a pasta do Drive que contém os PDFs");
        cloud.addView(text(sourceLabel,12,MUTED,false));
        cloud.addView(text("ÍNDICE LOCAL: "+readyCount+" de "+enabledCount+" manuais prontos"+(ragIndexingRunning?" • trabalhando agora":""),15,readyCount>0?GREEN:GOLD,true));
        cloud.addView(text("O PDF é lido uma única vez pela permissão da pasta escolhida e pesquisado no próprio Android. PDFBox extrai a camada de texto; páginas escaneadas usam OCR latino empacotado e continuam locais. O Mestre recebe somente os trechos relevantes.",13,TEXT,false));
        cloud.addView(text("A indexação só começa quando você toca em INDEXAR AGORA ou RETOMAR / INDEXAR TUDO. Assim ela não disputa memória e processamento com a abertura do app ou com a narração.",13,GOLD,false));
        cloud.addView(text("Arquivos duplicados são detectados; a menor cópia é mantida. O progresso é salvo por página e continua após fechar o app ou perder a internet.",13,GREEN,false));
        LinearLayout actions=new LinearLayout(this);actions.setOrientation(LinearLayout.VERTICAL);
        Button connect=smallButton(folderLinked?"TROCAR PASTA DO DRIVE":"ESCOLHER PASTA NO DRIVE",GREEN);
        Button sync=smallButton("SINCRONIZAR PASTA",GOLD),local=smallButton("IMPORTAR PDFs AVULSOS",PANEL2),indexAll=smallButton(ragIndexingRunning?"INDEXANDO...":"RETOMAR / INDEXAR TUDO",PANEL2),clearManualCache=smallButton(manualCacheClearRunning?"LIMPANDO CACHE…":"LIMPAR CACHE DOS MANUAIS",PANEL2),deleteAllManuals=smallButton(manualDeleteRunning?"APAGANDO MANUAIS…":"APAGAR TODOS OS MANUAIS",RED);
        sync.setTextColor(Color.BLACK);
        connect.setOnClickListener(new View.OnClickListener(){public void onClick(View v){selectManualFolder();}});
        sync.setOnClickListener(new View.OnClickListener(){public void onClick(View v){syncDrive();}});
        local.setOnClickListener(new View.OnClickListener(){public void onClick(View v){openFile("application/pdf",REQ_IMPORT_MANUALS,true);}});
        indexAll.setEnabled(!ragIndexingRunning);indexAll.setOnClickListener(new View.OnClickListener(){public void onClick(View v){indexAllLocalManuals();showManuals(filter);}});
        clearManualCache.setEnabled(!manualCacheClearRunning&&!manualDeleteRunning);clearManualCache.setOnClickListener(new View.OnClickListener(){public void onClick(View v){clearManualCache();}});
        deleteAllManuals.setEnabled(!manualDeleteRunning&&!manualCacheClearRunning);deleteAllManuals.setOnClickListener(new View.OnClickListener(){public void onClick(View v){confirmDeleteAllManuals();}});
        actions.addView(connect);actions.addView(sync);actions.addView(local);actions.addView(indexAll);actions.addView(clearManualCache);actions.addView(deleteAllManuals);cloud.addView(actions);
        manualCacheInfoView=text("Cache temporário dos manuais: "+(manualCacheSizeRefreshRunning?"calculando…":humanSize(manualCacheBytesEstimate))+". Limpar não apaga o índice local nem os PDFs originais.",12,MUTED,false);cloud.addView(manualCacheInfoView);refreshManualCacheSizeAsync();
        Button rebuild=smallButton("APAGAR ÍNDICE LOCAL E REINDEXAR TUDO",RED);rebuild.setOnClickListener(new View.OnClickListener(){public void onClick(View v){rebuildRagLibrary();}});cloud.addView(rebuild);b.addView(cloud);
        final EditText search=input("Buscar por título ou categoria",filter,false);Button go=smallButton("BUSCAR",PANEL2);LinearLayout sr=new LinearLayout(this);sr.addView(search,new LinearLayout.LayoutParams(0,dp(52),1));sr.addView(go);b.addView(sr);go.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showManuals(search.getText().toString());}});
        List<JSONObject> list=filterManualsForWorld(db.listManuals(filter));b.addView(text(list.size()+" ARQUIVOS PATHFINDER",15,GOLD,true));if(list.size()==0){b.addView(empty("Sincronize o Drive ou importe PDFs."));if(prefs.getBoolean("bundled_mythic_manual_suppressed",false)){Button restoreBundled=smallButton("RESTAURAR MANUAL INTEGRADO MYTHIC 2E",PANEL2);restoreBundled.setOnClickListener(new View.OnClickListener(){public void onClick(View v){prefs.edit().putBoolean("bundled_mythic_manual_suppressed",false).apply();ensureBundledMythicManualAsync();setStatus("Restaurando o manual integrado. A indexação só começará quando você solicitar.");}});b.addView(restoreBundled);}}int max=Math.min(manualVisibleLimit,list.size());
        for(int i=0;i<max;i++){final JSONObject m=list.get(i);LinearLayout row=card();LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);final CheckBox enabled=check("",m.optInt("enabled",1)==1);top.addView(enabled);top.addView(text(manualDisplayTitle(m),15,TEXT,true),new LinearLayout.LayoutParams(0,-2,1));row.addView(top);row.addView(text(m.optString("category")+" • "+m.optString("rule_profile")+" • "+humanSize(m.optLong("size_bytes")),12,MUTED,false));String status=m.optString("rag_status","not_indexed");int pages=Math.max(0,m.optInt("rag_page_count"));String statusLabel="ready".equals(status)?"✓ PRONTO • "+pages+" PÁGINAS":"preparing".equals(status)?"PREPARANDO CÓPIA LOCAL...":"indexing".equals(status)?"INDEXANDO LOCALMENTE...":"waiting_network".equals(status)?"DOWNLOAD PAUSADO — RETOMA SOZINHO":"waiting_drive".equals(status)?"AGUARDANDO GOOGLE DRIVE":"duplicate_skipped".equals(status)?"DUPLICADO — CÓPIA MENOR MANTIDA":"needs_ocr".equals(status)?"PDF SEM TEXTO EXTRAÍVEL":"disabled".equals(status)?"DESATIVADO":"error".equals(status)?"PAUSADO — TOQUE PARA RETOMAR":"AINDA NÃO INDEXADO";int statusColor="ready".equals(status)?GREEN:("error".equals(status)||"needs_ocr".equals(status)?RED:GOLD);row.addView(text(statusLabel,12,statusColor,true));String progress=m.optString("rag_progress");if(progress.length()>0)row.addView(text(progress,11,MUTED,false));String error=manualIndexErrorPtBr(m.optString("rag_error"));if(error.length()>0)row.addView(text(error,11,"error".equals(status)?RED:MUTED,false));Button index=smallButton("ready".equals(status)?"REINDEXAR LOCALMENTE":("error".equals(status)||"waiting_network".equals(status)||"needs_ocr".equals(status))?"TENTAR AGORA":"INDEXAR AGORA",PANEL2);index.setEnabled(!ragIndexingRunning&&enabled.isChecked()&&!"duplicate_skipped".equals(status));index.setOnClickListener(new View.OnClickListener(){public void onClick(View v){indexManual(m);}});row.addView(index);enabled.setOnClickListener(new View.OnClickListener(){public void onClick(View v){db.setManualEnabled(m.optLong("id"),enabled.isChecked());if(enabled.isChecked())indexManual(m);else removeManualFromRag(m);}});b.addView(row);}
        if(list.size()>max){Button more=button("CARREGAR MAIS "+Math.min(36,list.size()-max)+" MANUAIS",PANEL2);more.setOnClickListener(new View.OnClickListener(){public void onClick(View v){manualVisibleLimit+=36;showManuals(filter);}});b.addView(more);b.addView(text("Exibindo "+max+" de "+list.size()+" manuais para manter a navegação rápida.",12,MUTED,false));}
    }

    

    /** Registra as fontes auxiliares fornecidas para criação de NPCs. Os PDFs
     * continuam sob demanda: só são baixados/indexados quando o usuário manda. */
    private void ensureNpcSourceManualCatalog(){
        String[][] sources={
                {"1FCQ8y-GoqBBNsXTIPJ4AoocjtHKKOXDd","npc_The Game Master’s Book of NPC.pdf","16448444"},
                {"1mQhmqOMsXWEbMtLTS6sWRd_wFYurZYrT","npc_The Game Master’s Book of Random Encounters.pdf","73807032"},
                {"1_pGBtdH7UTKp5Tx_AKtQNRE6DdcfE06y","npc_statblock-compendium.pdf","12234945"},
                {"1yatdnp5mAZ8eTCFU2Q0oTUlt6ocF48Mv","npc_1000-memorable-npcs-for-any-roleplaying.pdf","17489897"}
        };long seen=System.currentTimeMillis();for(String[] source:sources)try{String[] classification=classifyManual(source[1]);db.upsertManualSynced(source[0],source[1],classification[0],classification[1],"application/pdf",Long.parseLong(source[2]),"2026-08-03T03:42:25Z","","Fontes de NPC • "+DEFAULT_NPC_SOURCE_FOLDER,"drive-npc-sources:1wLyyEr8kJZCajLyBzhK0ME1OnQ4BgKKv",seen);}catch(Exception error){AppLog.w("NpcSources","Não foi possível registrar "+source[1],error);}
    }


    private boolean hasManualFolderAccess(){return libraryConnections!=null?libraryConnections.hasPersistedReadPermission(LibraryConnectionManager.MANUALS):prefs!=null&&prefs.getString("manual_tree_uri","").trim().length()>0;}
    private boolean hasLibraryAccess(String source){return libraryConnections!=null&&libraryConnections.hasPersistedReadPermission(source);}
    private void selectBackupFolder(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);startActivityForResult(intent,REQ_BACKUP_FOLDER);}

    private void selectManualFolder(){
        Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);
        intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);
        try{startActivityForResult(intent,REQ_MANUAL_FOLDER);}catch(Exception e){toast("Não foi possível abrir o seletor de pastas: "+e.getMessage());}
    }

    private void syncManualFolder(){
        final String stored=prefs.getString("manual_tree_uri","").trim();
        if(stored.length()==0){selectManualFolder();return;}
        if(libraryConnections!=null&&!libraryConnections.hasPersistedReadPermission(LibraryConnectionManager.MANUALS)){libraryConnections.recordSyncFailure(LibraryConnectionManager.MANUALS,"Permissão persistente revogada.");selectManualFolder();return;}
        final Uri treeUri=Uri.parse(stored);
        if(libraryConnections!=null)libraryConnections.recordSyncStart(LibraryConnectionManager.MANUALS);
        setStatus("Verificando somente os PDFs de manuais; a pasta tokens será ignorada...");
        AppExecutors.io().execute(new Runnable(){public void run(){
            try{
                if(manualFolderScanner==null)manualFolderScanner=new SafFolderScanner(MainActivity.this);
                final int removedTokenPdfs=db.purgeManualsFromReservedTokenFolders();
                final List<JSONObject> files=manualFolderScanner.listManualPdfs(treeUri,null,null);
                final long seen=System.currentTimeMillis();final String sourceRoot="saf-manuals:"+stableFingerprint(stored);
                int accepted=0,added=0,changed=0;
                for(JSONObject file:files){
                    String title=file.optString("name","").trim();
                    if(title.length()==0)continue;
                    String mime=file.optString("mimeType","application/pdf");
                    if(!"application/pdf".equalsIgnoreCase(mime)&&!title.toLowerCase(Locale.US).endsWith(".pdf"))continue;
                    String documentId=file.optString("documentId",file.optString("sourceUri"));
                    String stableId="saf:"+Integer.toHexString((stored+"|"+documentId).hashCode())+":"+documentId;
                    String[] classification=classifyManual(title);
                    String path=file.optString("path",title);
                    int sync=db.upsertManualSynced(stableId,title,classification[0],classification[1],"application/pdf",file.optLong("size"),String.valueOf(file.optLong("modifiedTime")),file.optString("sourceUri"),"Pasta Android / Google Drive"+(path.length()>0?" • "+path:""),sourceRoot,seen);
                    if(sync==1)added++;else if(sync==2)changed++;
                    accepted++;
                }
                final int count=accepted,addedCount=added,changedCount=changed,missingCount=db.disableMissingManuals(sourceRoot,seen,"Pasta Android / Google Drive");
                prefs.edit().putInt("last_manual_tree_count",count).putLong("last_manual_tree_sync",System.currentTimeMillis()).apply();
                if(libraryConnections!=null)libraryConnections.recordSyncSuccess(LibraryConnectionManager.MANUALS,count,addedCount,changedCount,missingCount);
                ui.post(new Runnable(){public void run(){
                    if(count==0){
                        setStatus("A pasta foi vinculada, mas nenhum PDF foi encontrado.");
                        new AlertDialog.Builder(MainActivity.this).setTitle("Nenhum PDF encontrado").setMessage("Escolha a pasta que contém os manuais. Se ela estiver em ‘Compartilhados comigo’, adicione um atalho em ‘Meu Drive’ e selecione esse atalho pelo seletor do Android.").setNegativeButton("Fechar",null).setPositiveButton("ESCOLHER OUTRA PASTA",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){selectManualFolder();}}).show();
                    }else{
                        toast(count+" manuais encontrados • "+addedCount+" novo(s) • "+changedCount+" alterado(s) • "+missingCount+" ausente(s). A pasta tokens foi ignorada"+(removedTokenPdfs>0?" e "+removedTokenPdfs+" entrada(s) antiga(s) removida(s).":"."));
                        setStatus(count+" manuais sincronizados. Alterações invalidaram seus índices automaticamente; ausentes foram desativados. Toque em RETOMAR / INDEXAR TUDO para concluir.");
                        showManuals("");
                    }
                }});
            }catch(final Exception e){
                if(libraryConnections!=null)libraryConnections.recordSyncFailure(LibraryConnectionManager.MANUALS,e.getMessage()==null?e.toString():e.getMessage());
                ui.post(new Runnable(){public void run(){
                    String message=e.getMessage()==null?e.toString():e.getMessage();
                    setStatus("Não foi possível ler a pasta vinculada.");
                    new AlertDialog.Builder(MainActivity.this).setTitle("Acesso à pasta do Drive").setMessage(message+"\n\nSelecione novamente a pasta para renovar a permissão do Android.").setNegativeButton("Fechar",null).setPositiveButton("SELECIONAR PASTA",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){selectManualFolder();}}).show();
                }});
            }
        }});
    }

    private boolean isUnregisteredDriveClient(String message){
        String n=message==null?"":message.toLowerCase(Locale.US);
        return n.contains("unregisteredonapiconsole")||n.contains("unregistered on api console")||n.contains("developer_error")||n.contains("api console");
    }

    private void showDriveOAuthFallback(final String after,String rawMessage){
        pendingDriveSync=after==null?"":after;
        String detail=rawMessage==null?"":rawMessage.trim();
        new AlertDialog.Builder(this).setTitle("Conexão do Google Drive").setMessage("Esta compilação não está registrada no Google Cloud para o certificado usado no aparelho, por isso o login OAuth foi recusado"+(detail.length()>0?" ("+detail+")":"")+".\n\nO Braseiro pode acessar os mesmos arquivos sem login: o seletor oficial do Android concede acesso somente à pasta escolhida.").setNegativeButton("Cancelar",null).setPositiveButton("ESCOLHER PASTA NO DRIVE",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){if("tokenPdfs".equals(pendingDriveSync))selectTokenPdfFolder();else if("tokens".equals(pendingDriveSync))selectTokenImageFolder();else selectManualFolder();}}).show();
        setStatus("Use o seletor de pasta do Android; nenhum cadastro no Google Cloud é necessário.");
    }

    private void authorizeDrive(final String after){
        pendingDriveSync=after==null?"":after;
        setStatus("Abrindo seleção da conta Google...");
        try{
            if(accountManager==null)accountManager=AccountManager.get(this);
            Intent chooser=AccountManager.newChooseAccountIntent(null,null,new String[]{"com.google"},null,null,null,null);
            startActivityForResult(chooser,REQ_DRIVE_AUTH);
        }catch(Exception e){
            toast("Não foi possível abrir a seleção de conta: "+e.getMessage());
            setStatus("Falha ao abrir a conta Google.");
        }
    }

    private void requestDriveToken(final Account account){
        if(account==null){toast("Nenhuma conta Google foi selecionada.");setStatus("Google Drive não conectado.");return;}
        pendingDriveAccountName=account.name==null?"":account.name;
        pendingDriveAccountType=account.type==null?"com.google":account.type;
        setStatus("Solicitando autorização somente de leitura do Google Drive...");
        if(accountManager==null)accountManager=AccountManager.get(this);
        accountManager.getAuthToken(account,DRIVE_AUTH_TOKEN_TYPE,null,this,new AccountManagerCallback<Bundle>(){
            public void run(AccountManagerFuture<Bundle> future){
                try{
                    Bundle bundle=future.getResult();
                    Intent consent=bundle==null?null:(Intent)bundle.getParcelable(AccountManager.KEY_INTENT);
                    if(consent!=null){
                        startActivityForResult(consent,REQ_DRIVE_CONSENT);
                        return;
                    }
                    String token=bundle==null?null:bundle.getString(AccountManager.KEY_AUTHTOKEN);
                    acceptDriveAccessToken(token);
                }catch(final Exception e){
                    ui.post(new Runnable(){public void run(){
                        String message=e.getMessage()==null?e.toString():e.getMessage();
                        if(isUnregisteredDriveClient(message))showDriveOAuthFallback(pendingDriveSync,message);
                        else{toast("Falha ao autorizar o Drive: "+message);setStatus("Google Drive não conectado.");}
                    }});
                }
            }
        },ui);
    }

    private void acceptDriveAccessToken(String token){
        if(token==null||token.length()<20){
            toast("O Google não retornou acesso ao Drive. Confirme a conta e a autorização solicitada.");
            setStatus("Google Drive não conectado.");
            return;
        }
        drive.saveAccessToken(token);
        prefs.edit().putString("drive_account_name",pendingDriveAccountName).putString("drive_account_type",pendingDriveAccountType).apply();
        toast("Google Drive conectado à conta selecionada.");
        setStatus("Google Drive conectado.");
        String next=pendingDriveSync;pendingDriveSync="";
        if("tokens".equals(next))syncTokens();
        else if("tokenPdfs".equals(next))syncTokenPdfCatalog();
        else if("manuals".equals(next))syncDrive();
        else if("Config".equalsIgnoreCase(currentScreen))showSettings();
    }

    private void syncDrive(){
        if(hasManualFolderAccess()){syncManualFolder();return;}
        if(!drive.isConnected()){selectManualFolder();return;}
        setStatus("Lendo a pasta de manuais pela API legada do Drive...");
        final String folder=prefs.getString("drive_folder",DEFAULT_FOLDER);final String sourceRoot="drive-manuals:"+DriveService.extractFolderId(folder);
        drive.listFolderRecursive(folder,new DriveService.FilesCallback(){
            public void onSuccess(final List<JSONObject> files){
                long seen=System.currentTimeMillis();int accepted=0,added=0,changed=0;
                for(int i=0;i<files.size();i++){
                    JSONObject f=files.get(i);String mime=f.optString("mimeType");if(!"application/pdf".equals(mime))continue;
                    accepted++;String title=f.optString("name");String[] cls=classifyManual(title);
                    int sync=db.upsertManualSynced(f.optString("id"),title,cls[0],cls[1],mime,f.optLong("size"),f.optString("modifiedTime"),"","Google Drive API"+(f.optString("path").length()>0?" • "+f.optString("path"):""),sourceRoot,seen);
                    if(sync==1)added++;else if(sync==2)changed++;
                }
                final int count=accepted,addedCount=added,changedCount=changed,missingCount=db.disableMissingManuals(sourceRoot,seen,"Google Drive API");
                ui.post(new Runnable(){public void run(){setStatus(count+" manuais pela API • "+addedCount+" novo(s) • "+changedCount+" alterado(s) • "+missingCount+" ausente(s). Alterações já invalidaram os índices antigos; toque em RETOMAR / INDEXAR TUDO.");showManuals("");}});
            }
            public void onError(final String message){ui.post(new Runnable(){public void run(){
                if(isUnregisteredDriveClient(message)){drive.disconnect();showDriveOAuthFallback("manuals",message);}
                else if(message.toLowerCase(Locale.US).contains("expir")){drive.disconnect();selectManualFolder();}
                else{toast(message);setStatus("Falha ao sincronizar; selecione a pasta pelo Android.");}
            }});}
        });
    }

    private void indexManual(final JSONObject manual){
        final String worldAtStart=activeWorldProfile();if(!manualBelongsToWorld(manual,worldAtStart)){toast("Esse manual pertence a outro mundo e foi bloqueado.");return;}if(ragIndexingRunning){toast("O índice local já está trabalhando.");return;}if(manual.optString("local_uri").length()==0&&!drive.isConnected()){toast("Vincule novamente a pasta de manuais para acessar este PDF.");selectManualFolder();return;}
        ragIndexingRunning=true;ragIndexingWorld=worldAtStart;setStatus("Indexando localmente "+manualDisplayTitle(manual)+"...");
        AppExecutors.io().execute(new Runnable(){public void run(){try{android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND);}catch(Throwable ignored){Thread.currentThread().setPriority(Thread.MIN_PRIORITY);}final ArrayList<JSONObject> candidates=new ArrayList<JSONObject>();candidates.add(manual);String key=LocalManualIndexer.duplicateKey(manual.optString("title"));if(key.length()>=8){for(JSONObject other:filterManualsForWorld(db.listManuals(""),worldAtStart)){if(other.optLong("id")==manual.optLong("id")||other.optInt("enabled",1)!=1)continue;if(key.equals(LocalManualIndexer.duplicateKey(other.optString("title"))))candidates.add(other);}}Exception lastError=null;JSONObject winner=null;for(JSONObject candidate:candidates){if(!worldAtStart.equals(activeWorldProfile()))break;try{localManualIndexer.index(candidate,true,new LocalManualIndexer.Progress(){public void update(String message,int done,int total){postRagProgress(message);}});winner=candidate;lastError=null;break;}catch(Exception e){lastError=e;AppLog.w("ManualIndexer","Falha em uma cópia de "+manualDisplayTitle(candidate)+"; tentando duplicada quando existir.",e);}}if(winner!=null){if(key.length()>=8){for(JSONObject candidate:candidates){if(candidate.optLong("id")==winner.optLong("id"))continue;db.setManualRagProgress(candidate.optLong("id"),"duplicate_skipped","Duplicado coberto por "+manualDisplayTitle(winner)+" já indexado.","",LocalManualIndexer.STORE,candidate.optString("modified_time"),"",0,0,0,"local");}}ui.post(new Runnable(){public void run(){ragIndexingRunning=false;ragIndexingWorld="";toast("Manual pronto no índice local.");if(worldAtStart.equals(activeWorldProfile()))showManuals("");}});}else{final String failure=lastError==null?"Não foi possível concluir a indexação.":lastError.getMessage();ui.post(new Runnable(){public void run(){ragIndexingRunning=false;ragIndexingWorld="";toast(manualIndexErrorPtBr(failure));if(worldAtStart.equals(activeWorldProfile()))showManuals("");}});}}});
    }

