        List<JSONObject> pdfs=db.listTokenPdfs(filter,"Todos".equals(selectedGroup)?"Todos":selectedGroup);long cache=tokenPdfLibrary==null?0:tokenPdfLibrary.cacheBytes();b.addView(text(db.countTokenPdfs()+" PDFs CATALOGADOS • "+db.countPdfTokens()+" MINIATURAS INDEXADAS • CACHE "+humanSize(cache),15,GOLD,true));if(pdfs.size()==0)b.addView(empty(tree.length()==0?"Escolha a pasta tokens. Ela pode estar no Google Drive pelo seletor do Android.":"Toque em Atualizar Catálogo. Nenhum PDF será extraído nessa etapa."));int pdfMax=Math.min(tokenPdfVisibleLimit,pdfs.size());for(int i=0;i<pdfMax;i++){final JSONObject pdf=pdfs.get(i);LinearLayout row=card();row.addView(text(pdf.optString("label",pdf.optString("name")),16,TEXT,true));String detail=pdf.optString("category")+(pdf.optString("class_name").length()>0?" • "+pdf.optString("class_name"):"")+(pdf.optString("species").length()>0?" • "+pdf.optString("species"):"");row.addView(text(detail,12,GOLD,false));int pc=pdf.optInt("page_count",-1);row.addView(text(pdf.optString("name")+" • "+(pc>0?pc+" páginas":"páginas ainda não abertas")+" • "+humanSize(pdf.optLong("size_bytes")),11,MUTED,false));LinearLayout actions=new LinearLayout(this);Button open=smallButton("ABRIR",GREEN),grid=smallButton("AJUSTAR GRADE",PANEL2);open.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showTokenPdf(pdf.optLong("id"),0);}});grid.setOnClickListener(new View.OnClickListener(){public void onClick(View v){tokenPdfGridDialog(pdf,0);}});actions.addView(open);actions.addView(grid);row.addView(actions);b.addView(row);}if(pdfs.size()>pdfMax){Button morePdfs=button("CARREGAR MAIS "+Math.min(30,pdfs.size()-pdfMax)+" PDFs",PANEL2);morePdfs.setOnClickListener(new View.OnClickListener(){public void onClick(View v){tokenPdfVisibleLimit+=30;showTokens(filter,selectedGroup);}});b.addView(morePdfs);b.addView(text("Exibindo "+pdfMax+" de "+pdfs.size()+" PDFs para evitar travamentos.",12,MUTED,false));}

