    private String individualTokenTargetLabel(){
        try{if(pendingTokenNpcId.length()>0){JSONObject npc=db.getNpcMemory(Long.parseLong(pendingTokenNpcId));String name=npc.optString("name","NPC").trim();return "NPC • "+(name.length()>0?name:"NPC");}}catch(Exception ignored){AppLog.ignored("TokenIndividual","NPC pendente inválido.",ignored);pendingTokenNpcId="";}
        try{if(pendingTokenCharacterId.length()>0){JSONObject hero=db.getCharacter(Long.parseLong(pendingTokenCharacterId));String name=hero.optString("name","Herói").trim();return "Herói • "+(name.length()>0?name:"Herói");}}catch(Exception ignored){AppLog.ignored("TokenIndividual","Herói pendente inválido.",ignored);pendingTokenCharacterId="";}
        return "";
    }

    private void chooseIndividualDeviceToken(){
        if(pendingTokenCharacterId.length()>0||pendingTokenNpcId.length()>0){openFile("image/*",REQ_TOKEN,false);return;}
        final ArrayList<String> labels=new ArrayList<String>();final ArrayList<String> kinds=new ArrayList<String>();final ArrayList<Long> ids=new ArrayList<Long>();
        for(JSONObject hero:db.listCharacters()){long id=hero.optLong("id",0);if(id<=0)continue;String name=hero.optString("name","Herói").trim();labels.add("HERÓI • "+(name.length()>0?name:"Herói"));kinds.add("hero");ids.add(id);}
        JSONArray npcs=db.listNpcMemories(5000);for(int i=0;i<npcs.length();i++){JSONObject npc=npcs.optJSONObject(i);if(npc==null||npc.optInt("active",1)!=1)continue;long id=npc.optLong("id",0);if(id<=0)continue;String name=npc.optString("name","NPC").trim();labels.add("NPC • "+(name.length()>0?name:"NPC"));kinds.add("npc");ids.add(id);}
        if(labels.isEmpty()){toast("Crie um herói ou NPC antes de vincular um token individual.");return;}
        String[] options=labels.toArray(new String[labels.size()]);new AlertDialog.Builder(this).setTitle("Vincular token individual").setItems(options,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){if(which<0||which>=ids.size())return;if("npc".equals(kinds.get(which))){pendingTokenCharacterId="";pendingTokenNpcId=String.valueOf(ids.get(which));}else{pendingTokenNpcId="";pendingTokenCharacterId=String.valueOf(ids.get(which));}openFile("image/*",REQ_TOKEN,false);}}).setNegativeButton("Cancelar",null).show();
    }

    private void selectTokenPdfFolder(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);startActivityForResult(intent,REQ_TOKEN_PDF_FOLDER);}
    private void syncTokenPdfCatalog(){
        if(tokenPdfSyncRunning)return;
        final String stored=prefs.getString("token_pdf_tree_uri","").trim();
        if(stored.length()==0&&!drive.isConnected()){selectTokenPdfFolder();return;}
        if(stored.length()>0&&libraryConnections!=null&&!libraryConnections.hasPersistedReadPermission(LibraryConnectionManager.TOKEN_PDFS)){libraryConnections.recordSyncFailure(LibraryConnectionManager.TOKEN_PDFS,"Permissão persistente revogada.");selectTokenPdfFolder();return;}
        if(stored.length()>0&&libraryConnections!=null)libraryConnections.recordSyncStart(LibraryConnectionManager.TOKEN_PDFS);
        tokenPdfSyncRunning=true;setStatus(stored.length()>0?"Lendo a pasta de PDFs de tokens pelo Android...":"Lendo a biblioteca de tokens pela API Google...");
        AppExecutors.io().execute(new Runnable(){public void run(){
            try{
                Uri localTree=stored.length()==0?null:Uri.parse(stored);List<JSONObject> files=tokenPdfLibrary.listPdfs(localTree);long seen=System.currentTimeMillis();
                for(JSONObject f:files){
                    JSONObject oldPdf=db.getTokenPdfBySource(f.optString("sourceUri"));boolean changed=oldPdf.length()>0&&(oldPdf.optLong("size_bytes")!=f.optLong("size")||oldPdf.optLong("modified_time")!=f.optLong("modifiedTime"));
                    JSONObject cl=TokenClassifier.classifyPdf(f.optString("name"));long id=db.upsertTokenPdf(f.optString("sourceUri"),f.optString("documentId"),f.optString("name"),cl,f.optLong("size"),f.optLong("modifiedTime"),seen);
                    if(changed&&id>0){tokenPdfLibrary.invalidatePdf(id);deleteDirectory(new File(getCacheDir(),"pdf_token_library/thumbs/"+id));}
                }
                db.disableMissingTokenPdfs(seen);prefs.edit().putLong("last_token_pdf_sync",seen).apply();final int count=files.size();
                if(stored.length()>0&&libraryConnections!=null)libraryConnections.recordSyncSuccess(LibraryConnectionManager.TOKEN_PDFS,count,0,0,0);
                ui.post(new Runnable(){public void run(){tokenPdfSyncRunning=false;setStatus(count+" PDFs de tokens catalogados pela pasta vinculada.");toast(count+" PDFs encontrados em todas as subpastas acessíveis.");showTokens("","Todos");}});
            }catch(final Exception e){if(stored.length()>0&&libraryConnections!=null)libraryConnections.recordSyncFailure(LibraryConnectionManager.TOKEN_PDFS,e.getMessage()==null?e.toString():e.getMessage());ui.post(new Runnable(){public void run(){tokenPdfSyncRunning=false;String message=e.getMessage()==null?e.toString():e.getMessage();if(isUnregisteredDriveClient(message)){drive.disconnect();showDriveOAuthFallback("tokenPdfs",message);}else if(message.toLowerCase(Locale.US).contains("expir")){drive.disconnect();selectTokenPdfFolder();}else{toast("Tokens: "+message);setStatus("Falha ao catalogar PDFs; selecione a pasta novamente.");}}});}
        }});
    }

    private void showTokenPdf(final long pdfId,final int requestedPage){final JSONObject pdf=db.getTokenPdf(pdfId);if(pdf.length()==0){toast("PDF não encontrado no catálogo.");showTokens("","Todos");return;}ScrollView s=page(pdf.optString("label",pdf.optString("name")),"Página processada sob demanda. Toque em um token para visualizar ou vincular.");final LinearLayout b=body(s);LinearLayout nav=card();LinearLayout buttons=new LinearLayout(this);Button back=smallButton("VOLTAR",PANEL2),prev=smallButton("ANTERIOR",PANEL2),next=smallButton("PRÓXIMA",PANEL2),grid=smallButton("GRADE",GOLD);grid.setTextColor(Color.BLACK);back.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showTokens("",pdf.optString("group_key","Todos"));}});prev.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showTokenPdf(pdfId,Math.max(0,requestedPage-1));}});next.setOnClickListener(new View.OnClickListener(){public void onClick(View v){int pc=db.getTokenPdf(pdfId).optInt("page_count",-1);if(pc>0&&requestedPage+1>=pc){toast("Esta é a última página.");return;}showTokenPdf(pdfId,requestedPage+1);}});grid.setOnClickListener(new View.OnClickListener(){public void onClick(View v){tokenPdfGridDialog(db.getTokenPdf(pdfId),requestedPage);}});buttons.addView(back);buttons.addView(prev);buttons.addView(next);buttons.addView(grid);nav.addView(buttons);nav.addView(text("Página "+(requestedPage+1)+" • grade "+pdf.optInt("columns_count",5)+" × "+pdf.optInt("rows_count",9),13,MUTED,false));b.addView(nav);final LinearLayout tokenArea=card();tokenArea.addView(text("Preparando somente esta página...",15,GOLD,true));ProgressBar progress=new ProgressBar(this);tokenArea.addView(progress,new LinearLayout.LayoutParams(-1,dp(52)));b.addView(tokenArea);loadPdfTokenPage(pdfId,requestedPage,tokenArea);}

    private void loadPdfTokenPage(final long pdfId,final int pageNo,final LinearLayout target){AppExecutors.io().execute(new Runnable(){public void run(){try{JSONObject pdf=db.getTokenPdf(pdfId);Uri uri=Uri.parse(pdf.optString("source_uri"));int count=pdf.optInt("page_count",-1);if(count<0){count=tokenPdfLibrary.pageCount(pdfId,uri);db.updateTokenPdfPageCount(pdfId,count);}if(pageNo<0||pageNo>=count)throw new Exception("O PDF possui "+count+" páginas.");List<JSONObject> existing=db.listPdfPageTokens(pdfId,pageNo);boolean usable=!existing.isEmpty();if(usable)for(JSONObject t:existing)if(!new File(t.optString("thumb_path")).exists()){usable=false;break;}if(!usable){List<JSONObject> generated=tokenPdfLibrary.processPage(pdfId,uri,pageNo,pdf.optInt("columns_count",5),pdf.optInt("rows_count",9),pdf.optDouble("grid_left",pdf.optDouble("margin_x",.065)),pdf.optDouble("grid_top",pdf.optDouble("margin_y",.055)),pdf.optDouble("grid_right",1d-pdf.optDouble("margin_x",.065)),pdf.optDouble("grid_bottom",1d-pdf.optDouble("margin_y",.055)));db.replacePdfPageTokens(pdfId,pageNo,generated);existing=db.listPdfPageTokens(pdfId,pageNo);}final List<JSONObject> tokens=existing;final int pageCount=count;int cacheMb=prefs.getInt("token_cache_mb",500);tokenPdfLibrary.pruneCache(Math.max(100,cacheMb)*1024L*1024L);ui.post(new Runnable(){public void run(){renderPdfTokenGrid(pdfId,pageNo,pageCount,tokens,target);}});}catch(final Exception e){ui.post(new Runnable(){public void run(){target.removeAllViews();target.addView(text("Não foi possível abrir esta página: "+e.getMessage(),14,RED,true));target.addView(text("Use Ajustar Grade se o PDF abrir, mas os recortes não coincidirem com os círculos.",12,MUTED,false));}});}}});}

    private void renderPdfTokenGrid(final long pdfId,final int pageNo,int pageCount,List<JSONObject> tokens,LinearLayout target){target.removeAllViews();target.addView(text("Página "+(pageNo+1)+" de "+pageCount+" • "+tokens.size()+" recortes",15,GOLD,true));JSONObject pdf=db.getTokenPdf(pdfId);int columns=Math.max(1,pdf.optInt("columns_count",5));LinearLayout row=null;for(int i=0;i<tokens.size();i++){final JSONObject token=tokens.get(i);if(i%columns==0){row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER);target.addView(row,new LinearLayout.LayoutParams(-1,-2));}LinearLayout cell=new LinearLayout(this);cell.setOrientation(LinearLayout.VERTICAL);cell.setGravity(Gravity.CENTER);ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.CENTER_INSIDE);Bitmap bm=BitmapFactory.decodeFile(token.optString("thumb_path"));image.setImageBitmap(bm);image.setBackground(makeBg(INPUT_BG,INPUT_STROKE,8));image.setOnClickListener(new View.OnClickListener(){public void onClick(View v){previewPdfToken(pdfId,pageNo,token);}});cell.addView(image,new LinearLayout.LayoutParams(dp(62),dp(62)));TextView number=text(String.valueOf(token.optInt("token_index")+1),10,MUTED,false);number.setGravity(Gravity.CENTER);cell.addView(number,new LinearLayout.LayoutParams(dp(62),dp(22)));row.addView(cell,new LinearLayout.LayoutParams(0,dp(88),1));}}

    private void previewPdfToken(final long pdfId,final int pageNo,final JSONObject token){ImageView image=new ImageView(this);image.setAdjustViewBounds(true);image.setScaleType(ImageView.ScaleType.CENTER_INSIDE);image.setImageBitmap(BitmapFactory.decodeFile(token.optString("thumb_path")));new AlertDialog.Builder(this).setTitle("Token "+(token.optInt("token_index")+1)+" • página "+(pageNo+1)).setView(image).setNegativeButton("Fechar",null).setNeutralButton(token.optInt("favorite")==1?"Remover favorito":"Favoritar",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){db.setPdfTokenFavorite(token.optLong("id"),token.optInt("favorite")!=1);toast("Favoritos atualizados.");}}).setPositiveButton("Vincular ao herói",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){chooseHeroForPdfToken(pdfId,pageNo,token);}}).show();}

    private void chooseHeroForPdfToken(final long pdfId,final int pageNo,final JSONObject token){if(pendingTokenNpcId.length()>0){try{extractAndAssignPdfTokenToNpc(pdfId,pageNo,token,Long.parseLong(pendingTokenNpcId));}catch(Exception e){toast("NPC inválido.");}return;}final List<JSONObject> heroes=db.listCharacters();if(heroes.size()==0){toast("Crie um personagem primeiro.");navigate("Heróis");return;}if(pendingTokenCharacterId.length()>0){try{extractAndAssignPdfToken(pdfId,pageNo,token,Long.parseLong(pendingTokenCharacterId));}catch(Exception e){toast("Personagem inválido.");}return;}String[] names=new String[heroes.size()];for(int i=0;i<heroes.size();i++)names[i]=heroes.get(i).optString("name");final Spinner hero=spinner(names,names[0]);new AlertDialog.Builder(this).setTitle("Vincular token a qual personagem?").setView(hero).setNegativeButton("Cancelar",null).setPositiveButton("Vincular",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){extractAndAssignPdfToken(pdfId,pageNo,token,heroes.get(hero.getSelectedItemPosition()).optLong("id"));}}).show();}

    private void extractAndAssignPdfToken(final long pdfId,final int pageNo,final JSONObject token,final long characterId){setStatus("Criando o recorte em alta qualidade...");AppExecutors.io().execute(new Runnable(){public void run(){try{JSONObject pdf=db.getTokenPdf(pdfId);File file=tokenPdfLibrary.extractFullToken(pdfId,Uri.parse(pdf.optString("source_uri")),pageNo,token.optInt("token_index"),token.optDouble("crop_x"),token.optDouble("crop_y"),token.optDouble("crop_w"),token.optDouble("crop_h"));String uri=Uri.fromFile(file).toString();db.setPdfTokenFullPath(token.optLong("id"),file.getAbsolutePath(),true);db.setCharacterToken(characterId,uri);pendingTokenCharacterId="";ui.post(new Runnable(){public void run(){toast("Token vinculado ao personagem.");setStatus("Recorte salvo em alta qualidade.");returnToTokenLibrary();}});}catch(final Exception e){ui.post(new Runnable(){public void run(){toast("Token PDF: "+e.getMessage());setStatus("Falha ao criar recorte.");}});}}});}

