    private void focusMapOnCurrentPosition(){
        final MapBoardView target=mapView;if(target==null)return;
        final int[] attempts={0};final Runnable focus=new Runnable(){public void run(){if(target!=mapView||target.getWindowToken()==null)return;attempts[0]++;float zoom=Math.max(1.55f,(float)db.getMapState().optDouble("min_label_zoom",1.6));if(!target.focusCurrentPosition(zoom)&&attempts[0]<5)target.postDelayed(this,120L);}};
        target.post(focus);
    }

    private void searchMapLocation(final EditText field){
        String query=field==null?"":field.getText().toString().trim();JSONObject state=db.getMapState();String packageId=state.optString("map_package_id");
        if(packageId.length()==0){toast("O pacote completo do mapa ainda está sendo preparado.");return;}if(query.length()<2){toast("Digite pelo menos duas letras.");return;}
        final List<JSONObject> results=new ArrayList<JSONObject>();if(campaignPoiService!=null)for(JSONObject poi:campaignPoiService.findVisibleByQuery(query,30)){JSONObject copy=new JSONObject();try{copy=new JSONObject(poi.toString());copy.put("_campaign_poi",true);}catch(Exception ignored){}results.add(copy);}for(JSONObject canonical:db.findMapLocationsByQuery(packageId,query,30)){if(results.size()>=40)break;results.add(canonical);}if(results.isEmpty()){toast("Nenhum local encontrado no Atlas canônico nem nos POIs desta campanha.");return;}
        String[] labels=new String[results.size()];for(int i=0;i<results.size();i++){JSONObject loc=results.get(i);String region=loc.optString("region","");String bound=loc.optString("hex_id","").length()>0?" • "+loc.optString("hex_id"):" • posição não confirmada";labels[i]=loc.optString("name","Local")+(loc.optBoolean("_campaign_poi",false)?" — CAMPANHA":(region.length()>0?" — "+region:""))+bound;}
        new AlertDialog.Builder(this).setTitle("Resultados no mapa").setItems(labels,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){focusMapLocation(results.get(which));}}).setNegativeButton("Fechar",null).show();
    }
    private void focusMapLocation(JSONObject loc){
        if(loc!=null&&(loc.optBoolean("_campaign_poi",false)||loc.optString("poi_id","").length()>0)){String hex=loc.optString("hex_id","");boolean focused=hex.length()>0&&mapView!=null&&mapView.focusHexId(hex,1.25f);if(hex.length()>0&&mapView!=null)mapView.setDestination(hex);StringBuilder body=new StringBuilder("Camada: ").append(loc.optString("source","campaign").equals("procedural")?"PROCEDURAL descoberto":"CAMPAIGN").append("\nHex: ").append(hex).append("\nTipo: ").append(CampaignPoiService.displayType(loc.optString("type"))).append("\nEstado: ").append(loc.optString("status","active"));if(loc.optString("description","").length()>0)body.append("\n\n").append(loc.optString("description"));new AlertDialog.Builder(this).setTitle(loc.optString("name","Local")).setMessage(body.toString()).setPositiveButton("Fechar",null).show();if(focused)setStatus("Mapa centralizado em "+loc.optString("name","local")+".");return;}
        String hex=loc.optString("hex_id","");String raw=loc.optString("raw_json","{}");double x=Double.NaN,y=Double.NaN;String description="";String original="";
        try{JSONObject r=new JSONObject(raw);description=cleanJsonText(r.optString("description"),cleanJsonText(r.optString("descricao_linha_1"),""));original=cleanJsonText(r.optString("nameOriginal"),cleanJsonText(r.optString("nome_original"),""));JSONObject geometry=r.optJSONObject("geometry");JSONArray coordinates=geometry==null?null:geometry.optJSONArray("coordinates");if(coordinates!=null&&coordinates.length()>=2){x=coordinates.optDouble(0,Double.NaN);y=coordinates.optDouble(1,Double.NaN);}}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}
        boolean focused=false;if(!Double.isNaN(x)&&!Double.isNaN(y)&&mapView!=null)focused=mapView.focusMapPoint((float)x,(float)y,1.15f);else if(hex.length()>0&&mapView!=null)focused=mapView.focusHexId(hex,1.15f);
        if(hex.length()>0&&mapView!=null)mapView.setDestination(hex);StringBuilder body=new StringBuilder();if(original.length()>0&&!original.equalsIgnoreCase(loc.optString("name")))body.append("Nome original: ").append(original).append("\n");if(loc.optString("region").length()>0)body.append("Região: ").append(loc.optString("region")).append("\n");String placement=loc.optString("placement_status","").toLowerCase(Locale.US);if(hex.length()>0){body.append("Hex de referência: ").append(hex);if(placement.contains("approx"))body.append("\nPosição cartográfica aproximada do catálogo canônico; não é uma coordenada oficial exata.");else if(placement.contains("review")||placement.contains("unassigned"))body.append("\nReferência ainda sujeita a revisão; não será tratada como posição exata.");else body.append("\nHex confirmado no pacote cartográfico.");}else body.append("Este registro está no catálogo e pode ser consultado pelo Mestre, mas sua posição ainda não foi confirmada no mapa. O aplicativo não inventará um destino.");if(description.length()>0)body.append("\n\n").append(description);new AlertDialog.Builder(this).setTitle(loc.optString("name","Local")).setMessage(body.toString()).setPositiveButton("Fechar",null).show();if(focused)setStatus("Mapa centralizado em "+loc.optString("name","local")+".");
    }
    private float mapDistanceBetweenHexes(String from,String to,JSONObject state){MapManifestGeometry g=mapGeometryFromState(state);float d=g==null?0f:g.distanceKm(from,to);return d>0?d:mapHexScaleKm(state);}
    private float mapDistanceToLocation(String from,JSONObject target,MapManifestGeometry geometry){if(geometry==null||target==null)return 0f;try{JSONObject raw=new JSONObject(target.optString("raw_json","{}"));JSONObject g=raw.optJSONObject("geometry");JSONArray c=g==null?null:g.optJSONArray("coordinates");if(c!=null&&c.length()>=2)return geometry.distanceKmFromHexToPoint(from,(float)c.optDouble(0),(float)c.optDouble(1));}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}return geometry.distanceKm(from,target.optString("hex_id"));}

    private String normalizeGridName(String value){if("Hexagonal".equals(value))return "Hexagonal flat-top";if(value!=null&&value.toLowerCase(Locale.US).contains("point"))return "Hexagonal pointy-top";if(value!=null&&value.toLowerCase(Locale.US).contains("hex"))return "Hexagonal flat-top";return value==null?"Quadrada":value;}

