    private AlertDialog showReadableAlert(AlertDialog.Builder builder){
        final AlertDialog dialog=builder.create();dialog.setOnShowListener(new DialogInterface.OnShowListener(){public void onShow(DialogInterface ignored){
            Window w=dialog.getWindow();if(w!=null){w.setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(PANEL));w.addFlags(android.view.WindowManager.LayoutParams.FLAG_DIM_BEHIND);android.view.WindowManager.LayoutParams lp=w.getAttributes();lp.dimAmount=.86f;w.setAttributes(lp);}
            TextView message=dialog.findViewById(android.R.id.message);if(message!=null){message.setTextColor(TEXT);message.setTextSize(14);message.setLineSpacing(0,1.18f);}
            Button positive=dialog.getButton(AlertDialog.BUTTON_POSITIVE),negative=dialog.getButton(AlertDialog.BUTTON_NEGATIVE),neutral=dialog.getButton(AlertDialog.BUTTON_NEUTRAL);if(positive!=null)positive.setTextColor(GOLD);if(negative!=null)negative.setTextColor(GOLD);if(neutral!=null)neutral.setTextColor(GOLD);
        }});dialog.show();return dialog;
    }

    private void runSystemDiagnostics5(){
        setStatus("Diagnóstico 5.0: verificando banco, regras, Atlas, Mestre, combate e responsividade…");
        AppExecutors.io().execute(new Runnable(){public void run(){final JSONObject report=SystemDiagnostics5.run(MainActivity.this,db,charonLatencyTelemetry,uiResponsivenessMonitor);ui.post(new Runnable(){public void run(){pendingDiagnosticJson=report.toString();String summary=report.optInt("passed",0)+"/"+report.optInt("total",0)+" verificações aprovadas";setStatus("Diagnóstico 5.0: "+summary+".");showReadableAlert(new AlertDialog.Builder(MainActivity.this).setTitle(report.optBoolean("ok",false)?"Diagnóstico 5.0 aprovado":"Diagnóstico 5.0 — atenção").setMessage(summary+"\n\n"+humanDiagnostic5(report)).setNegativeButton("Fechar",null).setPositiveButton("VER JSON",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){showReadableAlert(new AlertDialog.Builder(MainActivity.this).setTitle("Diagnóstico técnico 5.0").setMessage(report.toString()).setPositiveButton("Fechar",null));}}));}});}});
    }
    private String humanDiagnostic5(JSONObject report){StringBuilder b=new StringBuilder();JSONArray checks=report.optJSONArray("checks");if(checks!=null)for(int i=0;i<checks.length();i++){JSONObject c=checks.optJSONObject(i);if(c==null)continue;b.append(c.optBoolean("ok",false)?"✓ ":"✗ ").append(c.optString("name","Verificação"));if(c.has("count"))b.append(" — ").append(c.optInt("count"));if(c.has("free_mb"))b.append(" — ").append(c.optLong("free_mb")).append(" MB livres");b.append('\n');}JSONObject latency=report.optJSONObject("charon_latency");if(latency!=null&&latency.optLong("last_total_ms",-1)>=0)b.append("\nCharon — última primeira fala: ").append(latency.optLong("last_total_ms")).append(" ms.");JSONObject uiDiag=report.optJSONObject("ui_responsiveness");if(uiDiag!=null)b.append("\nAtrasos de UI detectados: ").append(uiDiag.optInt("lag_count",0)).append("; maior: ").append(uiDiag.optLong("max_lag_ms",0)).append(" ms.");return b.toString().trim();}
    private void runBackupRoundTrip5(){
        setStatus("Backup 5.0: exportando e restaurando em banco temporário…");
        AppExecutors.io().execute(new Runnable(){public void run(){final JSONObject report=BackupRoundTripVerifier.verify(MainActivity.this,db);ui.post(new Runnable(){public void run(){setStatus(report.optBoolean("ok",false)?"Backup 5.0 passou no round-trip.":"Backup 5.0 encontrou divergência; campanha original não foi alterada.");showReadableAlert(new AlertDialog.Builder(MainActivity.this).setTitle(report.optBoolean("ok",false)?"Round-trip aprovado":"Round-trip requer atenção").setMessage(report.optBoolean("ok",false)?"A campanha foi exportada, restaurada em um banco temporário e o conteúdo lógico conferiu.":("A campanha original não foi modificada. Detalhe: "+report.optString("error","o conteúdo lógico antes/depois divergiu."))).setNegativeButton("Fechar",null).setPositiveButton("VER RELATÓRIO",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){showReadableAlert(new AlertDialog.Builder(MainActivity.this).setTitle("Backup 5.0").setMessage(report.toString()).setPositiveButton("Fechar",null));}}));}});}});
    }

    private void runReleaseReadinessAudit(){
        if(releaseReadiness==null){toast("Auditoria ainda não inicializada.");return;}
        setStatus("Executando auditoria final sem alterar a campanha…");
        AppExecutors.io().execute(new Runnable(){public void run(){final JSONObject report=releaseReadiness.audit();ui.post(new Runnable(){public void run(){try{pendingDiagnosticJson=report.toString(2);showReadableAlert(new AlertDialog.Builder(MainActivity.this).setTitle("Auditoria final "+APP_VERSION).setMessage(report.optString("summary")+"\n\n"+report.optString("human_report")).setNegativeButton("Fechar",null).setPositiveButton("VER JSON",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){showReadableAlert(new AlertDialog.Builder(MainActivity.this).setTitle("Relatório técnico").setMessage(pendingDiagnosticJson).setPositiveButton("Fechar",null));}}));setStatus(report.optString("summary"));}catch(Exception e){toast("Auditoria: "+e.getMessage());}}});}});
    }

    private void showAuditDialog(){
        LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(dp(10),dp(6),dp(10),dp(18));List<JSONObject> events=db.listAuditEvents(150);
        if(events.isEmpty())list.addView(text("Nenhum evento registrado.",14,MUTED,false));
        for(JSONObject event:events){LinearLayout item=card();item.addView(text(event.optString("title"),14,GOLD,true));item.addView(text(event.optString("category").toUpperCase(Locale.US)+" • "+formatDate(event.optLong("created_at"))+(event.optInt("reversible")==1?" • reversível por snapshot":""),11,MUTED,false));if(event.optString("summary").length()>0)item.addView(text(event.optString("summary"),13,TEXT,false));list.addView(item);}
        ScrollView scroll=new ScrollView(this);scroll.addView(list);new AlertDialog.Builder(this).setTitle("Histórico e auditoria").setView(scroll).setPositiveButton("Fechar",null).show();
    }

    private JSONObject mapCoordinateDiagnostic(){
        JSONObject out=new JSONObject();try{
            JSONObject state=db.getMapState();String manifest=state.optString("manifest_json",prefs.getString("map_manifest_json",""));
            out.put("manifest_loaded",manifest.length()>0).put("generic_grid_locked",manifest.length()>0);
            if(manifest.length()==0){out.put("summary","sem manifesto explícito");return out;}
            MapManifestGeometry geometry=MapManifestGeometry.parse(manifest);
            out.put("logical_width",geometry.getImageWidth()).put("logical_height",geometry.getImageHeight()).put("orientation",geometry.getOrientation()).put("hex_count",geometry.size()).put("explicit_centers",geometry.hasExplicitCenters()).put("hex_width",geometry.getHexWidth()).put("hex_height",geometry.getHexHeight()).put("step_x",geometry.getStepX()).put("step_y",geometry.getStepY());
            boolean runtimeRoundTrip=true;
            if(mapView!=null){
                out.put("decoded_bitmap_scale_x",mapView.getDecodedBitmapScaleX()).put("decoded_bitmap_scale_y",mapView.getDecodedBitmapScaleY());
                float[][] points={{1f,1f},{geometry.getImageWidth()/2f,geometry.getImageHeight()/2f},{Math.max(1f,geometry.getImageWidth()-1f),Math.max(1f,geometry.getImageHeight()-1f)}};
                float[] zooms={1f,2f,4f};
                for(float zoom:zooms)for(float[] point:points)runtimeRoundTrip&=mapView.validateCoordinateRoundTripAtScale(point[0],point[1],zoom,.02f);
            }
            out.put("round_trip_100_200_400",runtimeRoundTrip);
            String current=state.optString("current_hex_id");MapManifestGeometry.ManifestHex h=geometry.byId(current);
            if(h!=null)out.put("current_hex",current).put("current_center_x",h.centerX).put("current_center_y",h.centerY);
            out.put("summary",Math.round(geometry.getImageWidth())+"×"+Math.round(geometry.getImageHeight())+" lógico • "+geometry.size()+" centros • toque/overlay "+(runtimeRoundTrip?"coerentes":"requerem atenção"));
        }catch(Exception e){try{out.put("summary","erro: "+e.getMessage()).put("error",e.getMessage());}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}}return out;
    }

    private void showMasterConnectionAudit(){
        JSONObject audit=masterGameContext.auditConnections();if(audit==null)audit=new JSONObject();
        StringBuilder body=new StringBuilder();java.util.Iterator<String> keys=audit.keys();while(keys.hasNext()){String key=keys.next();if("complete".equals(key))continue;body.append(audit.optBoolean(key)?"✓ ":"⚠ ").append(masterAuditLabel(key)).append('\n');}
        body.append("\nResultado: ").append(audit.optBoolean("complete")?"o Mestre lê o estado estrutural de todas as áreas e devolve atualizações persistentes.":"há pelo menos uma ligação estrutural ausente; exporte o diagnóstico para identificar.");
        new AlertDialog.Builder(this).setTitle("Conexões do Mestre IA").setMessage(body.toString()).setPositiveButton("Fechar",null).show();
    }

    private String masterAuditLabel(String key){
        if("campaign_connected".equals(key))return "campanha";if("rules_connected".equals(key))return "perfil de regras";if("heroes_connected".equals(key))return "todos os heróis";if("active_party_connected".equals(key))return "grupo ativo";if("inventory_and_sheet_connected".equals(key))return "fichas, inventário e recursos";if("character_tokens_connected".equals(key))return "tokens dos heróis";if("npc_memory_connected".equals(key))return "memória persistente de NPCs";if("npc_tokens_connected".equals(key))return "tokens dos NPCs";if("scene_connected".equals(key))return "estado da cena";if("scene_npc_link_connected".equals(key))return "elenco da cena ↔ memória de NPCs";if("map_connected".equals(key))return "mapa, hex atual, névoa e rota";if("combat_connected".equals(key))return "combate";if("journal_connected".equals(key))return "diário";if("dice_connected".equals(key))return "dados";if("audit_connected".equals(key))return "auditoria";if("audio_connected".equals(key))return "motor de áudio";if("narrator_bus_connected".equals(key))return "barramento operacional usado em cada cena";if("full_sheets_in_narrator_bus".equals(key))return "fichas completas no contexto do Narrador";if("inventory_and_spells_in_narrator_bus".equals(key))return "inventário e magias no contexto do Narrador";if("map_bidirectional_connected".equals(key))return "mapa com leitura e escrita revisada";if("tactical_bidirectional_connected".equals(key))return "tabuleiro com leitura e escrita revisada";if("journal_bidirectional_connected".equals(key))return "diário com leitura e escrita revisada";if("living_world_runtime_connected".equals(key))return "Mundo Vivo no barramento de execução";if("pending_review_connected".equals(key))return "consequências pendentes para revisão";if("mechanical_guard_connected".equals(key))return "barreira mecânica verificada ou bloqueada";return key.replace('_',' ');
    }

    private String taskStateSummary(JSONObject root){JSONArray tasks=root==null?null:root.optJSONArray("tasks");if(tasks==null||tasks.length()==0)return "nenhuma registrada";JSONObject last=tasks.optJSONObject(tasks.length()-1);return last==null?"nenhuma registrada":last.optString("label","tarefa")+" — "+last.optString("status","desconhecido");}

    private void showTaskStateDialog(){LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(dp(10),dp(6),dp(10),dp(18));JSONArray tasks=taskQueue.state().optJSONArray("tasks");if(tasks==null||tasks.length()==0)list.addView(text("Nenhuma importação ou indexação registrada.",13,MUTED,false));else for(int i=tasks.length()-1;i>=0;i--){JSONObject task=tasks.optJSONObject(i);if(task==null)continue;LinearLayout item=card();item.addView(text(task.optString("label","Tarefa"),14,GOLD,true));item.addView(text(task.optString("status").toUpperCase(Locale.US)+" • "+task.optInt("done")+"/"+task.optInt("total")+"\n"+task.optString("message")+"\n"+formatDate(task.optLong("updated_at")),12,TEXT,false));list.addView(item);}ScrollView scroll=new ScrollView(this);scroll.addView(list);new AlertDialog.Builder(this).setTitle("Tarefas e checkpoints").setView(scroll).setPositiveButton("Fechar",null).show();}

