    private void showVisualTokenCalibrator(final JSONObject pdf,final int pageNo,final Bitmap preview){
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(10),dp(6),dp(10),0);
        form.addView(text("Arraste os quatro pontos vermelhos. Toque em SALVAR E REPROCESSAR; a calibração fica gravada para este PDF e continua após sair da aba.",13,MUTED,false));
        final TokenGridCalibrationView calibrator=new TokenGridCalibrationView(this);calibrator.setBitmap(preview);calibrator.setBounds(pdf.optDouble("grid_left",pdf.optDouble("margin_x",.065)),pdf.optDouble("grid_top",pdf.optDouble("margin_y",.055)),pdf.optDouble("grid_right",1d-pdf.optDouble("margin_x",.065)),pdf.optDouble("grid_bottom",1d-pdf.optDouble("margin_y",.055)));form.addView(calibrator,new LinearLayout.LayoutParams(-1,dp(430)));
        LinearLayout counts=new LinearLayout(this);counts.setOrientation(LinearLayout.HORIZONTAL);final EditText columns=input("Colunas",String.valueOf(pdf.optInt("columns_count",5)),false);columns.setInputType(InputType.TYPE_CLASS_NUMBER);final EditText rows=input("Linhas",String.valueOf(pdf.optInt("rows_count",9)),false);rows.setInputType(InputType.TYPE_CLASS_NUMBER);counts.addView(columns,new LinearLayout.LayoutParams(0,-2,1));counts.addView(rows,new LinearLayout.LayoutParams(0,-2,1));form.addView(counts);
        View.OnFocusChangeListener refresh=new View.OnFocusChangeListener(){public void onFocusChange(View v,boolean has){if(!has)calibrator.setGrid(Math.max(1,num(columns,5)),Math.max(1,num(rows,9)));}};columns.setOnFocusChangeListener(refresh);rows.setOnFocusChangeListener(refresh);calibrator.setGrid(pdf.optInt("columns_count",5),pdf.optInt("rows_count",9));
        new AlertDialog.Builder(this).setTitle("Recorte visual — página "+(pageNo+1)).setView(form).setNegativeButton("Cancelar",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){preview.recycle();}}).setPositiveButton("SALVAR E REPROCESSAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){int c=Math.max(1,num(columns,5)),r=Math.max(1,num(rows,9));db.updateTokenPdfLayoutBounds(pdf.optLong("id"),c,r,calibrator.getGridLeft(),calibrator.getGridTop(),calibrator.getGridRight(),calibrator.getGridBottom());deleteDirectory(new File(getCacheDir(),"pdf_token_library/thumbs/"+pdf.optLong("id")));preview.recycle();toast("Calibração salva para este PDF.");showTokenPdf(pdf.optLong("id"),pageNo);}}).show();
    }

    private boolean persistSelectedTree(String source,Intent data,boolean requireWrite){
        if(data==null||data.getData()==null)return false;
        try{
            Uri tree=data.getData();int flags=data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);
            if(requireWrite&&(flags&Intent.FLAG_GRANT_WRITE_URI_PERMISSION)==0)throw new Exception("O provedor não concedeu permissão de gravação para esta pasta.");
            if(libraryConnections==null)libraryConnections=new LibraryConnectionManager(this);
            libraryConnections.saveTree(source,tree,flags);
            return true;
        }catch(Exception error){if(libraryConnections!=null)libraryConnections.recordSyncFailure(source,error.getMessage());toast("Não foi possível manter acesso à pasta: "+String.valueOf(error.getMessage()));return false;}
    }

    protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==REQ_MANUAL_FOLDER){
        if(result!=RESULT_OK||data==null||data.getData()==null){toast("Seleção da pasta de manuais cancelada.");return;}
        if(persistSelectedTree(LibraryConnectionManager.MANUALS,data,false)){prefs.edit().remove("drive_access_token").apply();drive.disconnect();toast("Pasta de manuais vinculada pelo Android.");syncManualFolder();}
        return;
    }if(request==REQ_DRIVE_AUTH){
        if(result!=RESULT_OK||data==null){
            toast("Seleção da conta Google cancelada.");
            setStatus("Google Drive não conectado.");
            return;
        }
        String name=data.getStringExtra(AccountManager.KEY_ACCOUNT_NAME);
        String type=data.getStringExtra(AccountManager.KEY_ACCOUNT_TYPE);
        if(name==null||name.trim().length()==0){
            toast("A conta Google não foi retornada pelo Android.");
            setStatus("Google Drive não conectado.");
            return;
        }
        requestDriveToken(new Account(name,type==null||type.length()==0?"com.google":type));
        return;
    }
    if(request==REQ_DRIVE_CONSENT){
        if(result!=RESULT_OK){
            toast("Autorização do Google Drive cancelada.");
            setStatus("Google Drive não conectado.");
            return;
        }
        String name=pendingDriveAccountName.length()>0?pendingDriveAccountName:prefs.getString("drive_account_name","");
        String type=pendingDriveAccountType.length()>0?pendingDriveAccountType:prefs.getString("drive_account_type","com.google");
        if(name.length()==0){toast("A conta Google precisa ser selecionada novamente.");authorizeDrive(pendingDriveSync);return;}
        requestDriveToken(new Account(name,type));
        return;
    }
if(request==REQ_TOKEN_IMAGE_FOLDER){if(result!=RESULT_OK||data==null||data.getData()==null){toast("Seleção da pasta de imagens cancelada.");return;}if(persistSelectedTree(LibraryConnectionManager.TOKEN_IMAGES,data,false)){toast("Pasta de imagens vinculada pelo Android.");syncTokens();}return;}if(request==REQ_AUDIO_FOLDER){if(result!=RESULT_OK||data==null||data.getData()==null){toast("Seleção da pasta de áudio cancelada.");return;}if(persistSelectedTree(LibraryConnectionManager.AUDIO,data,false))syncAudioLibrary();return;}if(request==REQ_AUDIO_KEYWORDS){if(result!=RESULT_OK||data==null)return;final Intent keywordData=data;setStatus("Lendo biblioteca_sons.json...");taskQueue.submit("audio-catalog-"+System.currentTimeMillis(),"Importar biblioteca_sons.json",new ResilientTaskQueue.Work(){public void run(ResilientTaskQueue.Progress progress)throws Exception{progress.update(0,1,"Validando nomes e palavras-chave");final int count=smartAudio.importKeywordIntent(keywordData);progress.update(1,1,count+" áudios catalogados");prefs.edit().putInt("last_audio_keyword_count",count).apply();}},new ResilientTaskQueue.Callback(){public void onSuccess(){ui.post(new Runnable(){public void run(){int count=prefs.getInt("last_audio_keyword_count",0);toast(count+" áudios ligados ao catálogo JSON.");setStatus("biblioteca_sons.json aplicado. Atualize o índice da pasta para conferir os arquivos.");showAudio();}});}public void onError(final String message){ui.post(new Runnable(){public void run(){toast("biblioteca_sons.json: "+message);setStatus("Falha ao importar o catálogo de sons.");}});}});return;}if(request==REQ_TOKEN_PDF_FOLDER){if(result!=RESULT_OK||data==null||data.getData()==null){toast("Seleção da pasta tokens cancelada.");return;}if(persistSelectedTree(LibraryConnectionManager.TOKEN_PDFS,data,false)){toast("Pasta de PDFs de tokens vinculada.");syncTokenPdfCatalog();}return;}if(request==REQ_BACKUP_FOLDER){if(result!=RESULT_OK||data==null||data.getData()==null){toast("Seleção da pasta de backup cancelada.");return;}if(persistSelectedTree(LibraryConnectionManager.BACKUPS,data,true)){prefs.edit().putBoolean("automatic_drive_backup",true).apply();toast("Pasta de backup automático vinculada.");if(maintenance!=null)maintenance.runMaintenance("Pasta de backup vinculada",true);showSettings();}return;}if((request==REQ_EXPORT_CHARACTER||request==REQ_IMPORT_CHARACTER)&&(result!=RESULT_OK||data==null||data.getData()==null)){pendingCharacterExport=new JSONObject();toast("Operação de ficha JSON cancelada.");return;}if(request==REQ_EXPORT_JOURNAL_PDF&&(result!=RESULT_OK||data==null||data.getData()==null)){if(pendingAdventurePdf!=null)pendingAdventurePdf.delete();pendingAdventurePdf=null;pendingAdventurePdfKind="livro";toast("Exportação do PDF cancelada.");return;}if(result!=RESULT_OK||data==null)return;try{
        if(request==REQ_MAP_PACKAGE&&data.getData()!=null){safety.beforeDestructiveChange("importar pacote de mapa");Uri zip=data.getData();persist(zip,data);importMapPackage(zip);}
        else if(request==REQ_MAP&&data.getData()!=null){safety.beforeDestructiveChange("substituir imagem do mapa");Uri uri=data.getData();persist(uri,data);JSONObject st=db.getMapState();db.saveMapPackageState(uri.toString(),"",st.optString("manifest_json"),"","",false,"{}",st.optString("grid_type","Quadrada"),(float)st.optDouble("grid_size",64),st.optInt("fog_enabled")==1,.5f,.5f,0,0,0);db.addAuditEvent("mapa","Imagem do mapa substituída",displayName(uri),"{}",db.getMapState().toString(),true);showMap();}
        else if(request==REQ_MAP_OVERLAY&&data.getData()!=null){Uri overlayUri=data.getData();persist(overlayUri,data);MapBoardView probe=mapView!=null?mapView:new MapBoardView(this);JSONObject st=db.getMapState();if(st.optString("image_uri").length()>0)probe.load(Uri.parse(st.optString("image_uri")));probe.loadOverlay(overlayUri);db.saveMapPackageState(st.optString("image_uri"),overlayUri.toString(),st.optString("manifest_json"),st.optString("map_package_id"),st.optString("current_hex_id"),true,st.optString("reveals_json","{}"),st.optString("grid_type","Quadrada"),(float)st.optDouble("grid_size",64),st.optInt("fog_enabled")==1,(float)st.optDouble("token_x",.5),(float)st.optDouble("token_y",.5),(float)st.optDouble("scale",1),(float)st.optDouble("offset_x",0),(float)st.optDouble("offset_y",0));toast("Overlay de IDs vinculado.");showMap();}
        else if(request==REQ_AUDIO_AMBIENCE&&data.getData()!=null){persist(data.getData(),data);if(audio!=null)audio.playAmbience(data.getData());else toast("O motor de áudio ainda está iniciando.");}
        else if(request==REQ_AUDIO_MUSIC&&data.getData()!=null){persist(data.getData(),data);if(audio!=null)audio.playMusic(data.getData());else toast("O motor de áudio ainda está iniciando.");}
        else if(request==REQ_AUDIO_SFX&&data.getData()!=null){persist(data.getData(),data);if(smartAudio!=null)smartAudio.playManualSfx(data.getData(),displayName(data.getData()));else toast("A biblioteca de sons ainda está iniciando.");}
        else if(request==REQ_MAP_MANIFEST&&data.getData()!=null){safety.beforeDestructiveChange("substituir manifesto do mapa");persist(data.getData(),data);InputStream min=getContentResolver().openInputStream(data.getData());String json=readAll(min);min.close();MapBoardView probe=mapView!=null?mapView:new MapBoardView(this);JSONObject st=db.getMapState();if(st.optString("image_uri").length()>0)probe.load(Uri.parse(st.optString("image_uri")));String summary=probe.applyManifest(json);prefs.edit().putString("map_manifest_json",json).apply();db.saveMapPackageState(st.optString("image_uri"),st.optString("overlay_uri"),json,"",probe.getCurrentHexId(),st.optInt("overlay_visible",1)==1,st.optString("reveals_json","{}"),probe.getManifestGridType(),probe.getManifestGridSize(),st.optInt("fog_enabled")==1,(float)st.optDouble("token_x",.5),(float)st.optDouble("token_y",.5),(float)st.optDouble("scale",1),(float)st.optDouble("offset_x",0),(float)st.optDouble("offset_y",0));db.addAuditEvent("mapa","Manifesto importado",summary,"{}",json,true);toast("Manifesto importado: "+summary);showMap();}
        else if(request==REQ_EXPORT_MAP_CORRECTIONS&&data.getData()!=null){JSONObject st=db.getMapState();OutputStream out=getContentResolver().openOutputStream(data.getData());out.write(db.exportMapCorrections(st.optString("map_package_id")).toString(2).getBytes("UTF-8"));out.close();toast("Revisões do mapa exportadas.");setStatus("JSON de revisões salvo.");}
        else if(request==REQ_IMPORT_MAP_CORRECTIONS&&data.getData()!=null){InputStream in=getContentResolver().openInputStream(data.getData());String json=readAll(in);in.close();JSONObject parsed=new JSONObject(json);safety.beforeDestructiveChange("importar revisões do mapa");JSONObject st=db.getMapState();int count=db.importMapCorrections(st.optString("map_package_id"),parsed);db.addAuditEvent("mapa","Revisões importadas",count+" alterações","{}",parsed.toString(),true);toast(count+" revisões importadas.");setStatus("Revisões aplicadas ao mapa ativo.");showMap();}
        else if(request==REQ_EXPORT_CAMPAIGN_POIS&&data.getData()!=null){OutputStream out=getContentResolver().openOutputStream(data.getData());if(out==null)throw new Exception("Não foi possível criar campaign_pois.json.");out.write(campaignPoiService.exportJson().toString(2).getBytes("UTF-8"));out.close();toast("POIs da campanha exportados sem alterar o Atlas canônico.");}
        else if(request==REQ_IMPORT_CAMPAIGN_POIS&&data.getData()!=null){InputStream in=getContentResolver().openInputStream(data.getData());if(in==null)throw new Exception("Não foi possível abrir o JSON de POIs.");String json=readAll(in);in.close();int count=campaignPoiService.importJson(new JSONObject(json));refreshCampaignPoiMarkers();toast(count+" POI(s) importado(s) para a campanha. O catálogo oficial permaneceu intacto.");if("Mapa".equals(currentScreen))showMap();}
        else if(request==REQ_IMPORT_MANUALS){ArrayList<Uri> uris=new ArrayList<Uri>();if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)uris.add(data.getData());for(int i=0;i<uris.size();i++){Uri u=uris.get(i);persist(u,data);String title=displayName(u);String[] cl=classifyManual(title);long localSize=sizeOf(u);db.upsertManual("local:"+u.toString().hashCode(),title,cl[0],cl[1],true,"application/pdf",localSize,String.valueOf(localSize),u.toString(),"Arquivo local / Drive provider");}showManuals("");setStatus(uris.size()+" PDF(s) importado(s). Toque em RETOMAR / INDEXAR TUDO para preparar o índice local.");}
        else if(request==REQ_EXPORT_BACKUP&&data.getData()!=null){OutputStream out=getContentResolver().openOutputStream(data.getData());out.write(db.exportAll().toString(2).getBytes("UTF-8"));out.close();toast("Backup exportado.");}
        else if(request==REQ_IMPORT_BACKUP&&data.getData()!=null){InputStream in=getContentResolver().openInputStream(data.getData());String json=readAll(in);in.close();JSONObject backupJson=new JSONObject(json);BackupContractValidator.requireValid(backupJson);safety.beforeDestructiveChange("importar backup externo");db.importAll(backupJson);db.addAuditEvent("segurança","Backup externo restaurado",displayName(data.getData()),"{}",backupJson.optJSONObject("campaign").toString(),true);loadStoryState();ensureBundledMapForProfileAsync(activeWorldProfile());toast("Campanha restaurada e validada. Bibliotecas externas foram preservadas.");navigate("Aventura");}
        else if(request==REQ_EXPORT_DIAGNOSTIC&&data.getData()!=null){OutputStream out=getContentResolver().openOutputStream(data.getData());if(out==null)throw new Exception("Não foi possível criar o diagnóstico.");out.write(pendingDiagnosticJson.getBytes("UTF-8"));out.close();pendingDiagnosticJson="";toast("Diagnóstico exportado.");}
        else if(request==REQ_EXPORT_JOURNAL_PDF&&data.getData()!=null){exportPreparedPdfToUri(data.getData());return;}
        else if(request==REQ_EXPORT_CHARACTER&&data.getData()!=null){if(pendingCharacterExport.length()==0)throw new Exception("Nenhuma ficha foi preparada para exportação.");OutputStream out=getContentResolver().openOutputStream(data.getData());if(out==null)throw new Exception("Não foi possível criar o arquivo JSON.");out.write(pendingCharacterExport.toString(2).getBytes("UTF-8"));out.close();pendingCharacterExport=new JSONObject();toast("Ficha JSON exportada com todos os campos.");setStatus("Ficha de herói salva em JSON.");}
        else if(request==REQ_IMPORT_CHARACTER&&data.getData()!=null){Uri uri=data.getData();long size=sizeOf(uri);if(size>2L*1024L*1024L)throw new Exception("O JSON excede o limite de 2 MB para uma ficha.");InputStream in=getContentResolver().openInputStream(uri);if(in==null)throw new Exception("Não foi possível abrir o JSON.");String json=readAll(in);in.close();JSONObject imported=decodeCharacterJson(json);characterDialog(null,imported);toast("Ficha PF2e aberta como novo herói. Revise antes de salvar.");setStatus("Ficha JSON Pathfinder 2e importada sem sobrescrever personagens existentes.");}
        else if(request==REQ_TOKEN&&data.getData()!=null){importSelectedTokenAsync(data.getData());return;}
    }catch(Exception e){toast("Erro: "+e.getMessage());}}

    private void exportPreparedPdfToUri(final Uri destination){
        final File source=pendingAdventurePdf;final String kind=pendingAdventurePdfKind;if(source==null||!source.exists()){toast("O PDF temporário não está mais disponível.");return;}setStatus("Salvando PDF em segundo plano…");AppExecutors.io().execute(new Runnable(){public void run(){String error="";try(InputStream in=new FileInputStream(source);OutputStream out=getContentResolver().openOutputStream(destination)){if(out==null)throw new Exception("Não foi possível criar o PDF escolhido.");byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))>0)out.write(buffer,0,n);out.flush();source.delete();db.addAuditEvent("diário","bardo".equals(kind)?"Crônica de bardo exportada":"Livro da aventura exportado",displayName(destination),"{}","{}",false);}catch(Exception e){error=String.valueOf(e.getMessage());}final String failure=error;ui.post(new Runnable(){public void run(){if(failure.length()>0){toast("PDF: "+failure);setStatus("Falha ao salvar o PDF.");return;}pendingAdventurePdf=null;pendingAdventurePdfKind="livro";toast("bardo".equals(kind)?"Crônica de bardo exportada em PDF.":"Livro da aventura exportado em PDF.");setStatus("PDF exportado.");}});}});
    }

    private void importSelectedTokenAsync(final Uri source){
        final boolean npcTarget=pendingTokenNpcId.length()>0;final String npcIdText=pendingTokenNpcId,characterIdText=pendingTokenCharacterId;setStatus("Copiando e validando o token em segundo plano…");AppExecutors.io().execute(new Runnable(){public void run(){String error="";try{if(npcTarget){long npcId=Long.parseLong(npcIdText);Uri stored=storeNpcAvatar(source,npcId);if(stored==null)throw new Exception("A imagem não pôde ser copiada com segurança.");db.setNpcToken(npcId,stored.toString());}else if(characterIdText.length()>0){long characterId=Long.parseLong(characterIdText);Uri stored=storeCharacterAvatar(source,characterId);if(stored==null)throw new Exception("A imagem não pôde ser copiada com segurança.");db.setCharacterToken(characterId,stored.toString());}else throw new Exception("Nenhum personagem ou NPC foi selecionado.");}catch(Exception e){AppLog.e("TokenImport","Falha no token individual.",e);error=String.valueOf(e.getMessage());}final String failure=error;ui.post(new Runnable(){public void run(){if(failure.length()>0)toast((npcTarget?"Token do NPC: ":"Avatar: ")+failure);else toast(npcTarget?"Token do NPC validado e salvo no aparelho.":"Avatar validado e salvo no aparelho.");if(npcTarget)returnToNpcMemory();else returnToTokenLibrary();}});}});
    }

