    private void handleIncomingIntent(Intent intent){
        String action=intent==null?"":intent.getAction();
        if(PendingImageImportStore.ACTION_CONSUME.equals(action)){
            String token=intent.getStringExtra(PendingImageImportStore.EXTRA_TOKEN);
            String error=intent.getStringExtra(PendingImageImportStore.EXTRA_ERROR);
            consumeIncomingIntent(intent);
            if(error!=null&&error.trim().length()>0){setStatus("A imagem recebida não foi importada.");toast(error);return;}
            Uri stored=PendingImageImportStore.claim(this,token);
            if(stored!=null){applyReceivedImage(stored);return;}
        }
        // Recupera uma cópia que tenha sido concluída antes de o processo ou a
        // Activity anterior serem encerrados.
        if(!Intent.ACTION_SEND.equals(action)){Uri recovered=PendingImageImportStore.claim(this,"");if(recovered!=null){applyReceivedImage(recovered);return;}}
        if(intent==null)return;
        String type=intent.getType();if(!Intent.ACTION_SEND.equals(action)||type==null||!type.startsWith("image/"))return;
        final Uri source=incomingImageUri(intent);consumeIncomingIntent(intent);if(source==null)return;
        // Compatibilidade com remetentes que contornam a Activity dedicada.
        setStatus("Validando e salvando a imagem recebida…");AppExecutors.io().execute(new Runnable(){public void run(){try{final Uri stored=ImageStorageManager.importImage(MainActivity.this,source,"scene_images","shared_scene",12);ui.post(new Runnable(){public void run(){applyReceivedImage(stored);}});}catch(final Exception e){AppLog.e("ImageImport","Imagem compartilhada rejeitada.",e);ui.post(new Runnable(){public void run(){setStatus("A imagem recebida não foi importada.");toast(e.getMessage()==null?"Imagem inválida.":e.getMessage());}});}}});
    }
    private Uri incomingImageUri(Intent intent){if(intent==null)return null;Uri source=null;if(Build.VERSION.SDK_INT>=33)source=intent.getParcelableExtra(Intent.EXTRA_STREAM,Uri.class);else source=(Uri)intent.getParcelableExtra(Intent.EXTRA_STREAM);if(source==null&&intent.getClipData()!=null&&intent.getClipData().getItemCount()>0)source=intent.getClipData().getItemAt(0).getUri();return source;}
    private void consumeIncomingIntent(Intent intent){if(intent!=null){intent.setAction(null);intent.removeExtra(Intent.EXTRA_STREAM);intent.removeExtra(PendingImageImportStore.EXTRA_TOKEN);intent.removeExtra(PendingImageImportStore.EXTRA_ERROR);intent.setClipData(null);}setIntent(new Intent(this,MainActivity.class));}
    private void applyReceivedImage(Uri stored){
        String target=prefs.getString(PREF_PENDING_IMAGE_TARGET,"scene");
        if("npc".equals(target)){applyReceivedNpcImage(stored);return;}
        if("character".equals(target)){applyReceivedCharacterImage(stored);return;}
        applyReceivedSceneImage(stored);
    }
    private void applyReceivedCharacterImage(Uri stored){
        if(stored==null||!ImageStorageManager.isReadable(this,stored)){setStatus("A imagem recebida não está mais disponível.");return;}
        final long characterId=prefs.getLong(PREF_PENDING_CHARACTER_ID,0L);
        final JSONObject character=characterId>0?db.getCharacter(characterId):new JSONObject();
        if(character.length()==0){setStatus("O personagem associado à imagem não existe mais.");clearPendingImageTarget();toast("Imagem não vinculada à cena.");return;}
        final Uri source=stored;final String name=character.optString("name","Personagem");
        setStatus("Salvando token de "+name+"…");
        AppExecutors.io().execute(new Runnable(){public void run(){try{
            final Uri avatar=ImageStorageManager.importImage(MainActivity.this,source,"hero_avatars","hero_"+characterId+"_gemini",80);
            db.setCharacterToken(characterId,avatar.toString());
            ui.post(new Runnable(){public void run(){pendingTokenCharacterId="";clearPendingImageTarget();screenCache.remove("Personagens");screenCache.remove("Combate");screenCache.remove("Mestre IA");setStatus("Imagem salva exclusivamente como token de "+name+".");toast("Token de "+name+" atualizado.");if("Personagens".equals(currentScreen))showHeroes();}});
        }catch(final Exception error){AppLog.e("CharacterPortrait","Falha ao persistir token recebido.",error);ui.post(new Runnable(){public void run(){setStatus("A imagem do personagem não pôde ser salva.");toast(String.valueOf(error.getMessage()));}});}}});
    }
    private void applyReceivedNpcImage(Uri stored){
        if(stored==null||!ImageStorageManager.isReadable(this,stored)){setStatus("A cópia recebida não está mais disponível.");return;}long npcId=prefs.getLong(PREF_PENDING_NPC_ID,0L);String npcName=prefs.getString(PREF_PENDING_NPC_NAME,"");JSONObject npc=npcId>0?db.getNpcMemory(npcId):db.findNpcMemoryByName(npcName);if(npc.length()==0){setStatus("O NPC associado ao retrato não existe mais nesta campanha.");clearPendingImageTarget();return;}final long resolvedId=npc.optLong("id",npcId);final String resolvedName=npc.optString("name",npcName);final Uri source=stored;setStatus("Salvando retrato persistente de "+resolvedName+"…");AppExecutors.io().execute(new Runnable(){public void run(){try{final Uri portrait=ImageStorageManager.importImage(MainActivity.this,source,"npc_avatars","npc_"+resolvedId+"_portrait",80);db.setNpcToken(resolvedId,portrait.toString());ui.post(new Runnable(){public void run(){applyNpcPortraitToScene(resolvedName,portrait.toString());clearPendingImageTarget();setStatus("Retrato salvo exclusivamente para "+resolvedName+".");showNpcPortraitFullscreen(resolvedName,portrait);}});}catch(final Exception error){AppLog.e("NpcPortrait","Falha ao persistir retrato recebido.",error);ui.post(new Runnable(){public void run(){setStatus("O retrato recebido não pôde ser salvo.");toast(String.valueOf(error.getMessage()));}});}}});}
    private void clearPendingImageTarget(){prefs.edit().remove(PREF_PENDING_IMAGE_TARGET).remove(PREF_PENDING_IMAGE_FINGERPRINT).remove(PREF_PENDING_CHARACTER_ID).remove(PREF_PENDING_NPC_ID).remove(PREF_PENDING_NPC_NAME).remove(PREF_PENDING_NPC_PROMPT).apply();}
    private void applyReceivedSceneImage(Uri stored){if(stored==null||!ImageStorageManager.isReadable(this,stored)){setStatus("A cópia recebida não está mais disponível.");return;}String current=currentSceneVisualFingerprint(),pending=prefs.getString(PREF_PENDING_IMAGE_FINGERPRINT,"");if(pending.length()>0&&!pending.equals(current)){setStatus("A imagem recebida pertence a uma cena anterior e não foi vinculada.");toast("A cena mudou depois que o Gemini foi aberto. Gere ou compartilhe novamente a imagem atual.");prefs.edit().remove(PREF_PENDING_IMAGE_FINGERPRINT).apply();return;}sharedImageUri=stored;prefs.edit().putString(PREF_SCENE_IMAGE_URI,stored.toString()).putString(PREF_SCENE_IMAGE_FINGERPRINT,current).putInt("scene_image_aspect_w",9).putInt("scene_image_aspect_h",16).remove("scene_image_fill").remove(PREF_PENDING_IMAGE_FINGERPRINT).remove(PREF_PENDING_IMAGE_TARGET).apply();navigate("Mestre IA");displaySceneImage(stored);setStatus("Imagem recebida, validada, salva e vinculada à cena atual.");toast("Imagem adicionada à cena atual.");}
    private void addSceneImageCard(LinearLayout parent){
        final LinearLayout imageCard=card();
        LinearLayout header=new LinearLayout(this);header.setOrientation(LinearLayout.HORIZONTAL);header.setGravity(Gravity.CENTER_VERTICAL);
        header.addView(text("IMAGEM DA CENA",13,GOLD,true),new LinearLayout.LayoutParams(0,-2,1));
        if(sharedImageUri!=null){
            Button open=smallButton("ABRIR",PANEL2);open.setTextSize(9);open.setContentDescription("Abrir a imagem vertical da cena em tela cheia");open.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showSceneImageFullscreen();}});
            header.addView(open,new LinearLayout.LayoutParams(dp(72),dp(40)));
        }
        imageCard.addView(header);
        sceneImage=new ImageView(this);sceneImage.setAdjustViewBounds(false);sceneImage.setBackground(makeBg(PANEL2,CARD_STROKE,12));sceneImage.setClipToOutline(true);sceneImage.setContentDescription("Imagem vertical 9 por 16 da cena atual. Toque para abrir em tela cheia.");applySceneImageScale();
        sceneImage.setOnClickListener(new View.OnClickListener(){public void onClick(View v){if(sharedImageUri!=null)showSceneImageFullscreen();}});
        if(sharedImageUri!=null){displaySceneImage(sharedImageUri);imageCard.addView(sceneImage,sceneImagePreviewLayoutParams());}
        else{sceneImage.setImageBitmap(null);imageCard.addView(sceneImage,new LinearLayout.LayoutParams(-1,dp(130)));}
        if(sharedImageUri==null){TextView no=text("Gere a cena pelo Gemini em proporção vertical 9:16 usando somente o prompt visual limpo.",13,MUTED,false);no.setGravity(Gravity.CENTER);imageCard.addView(no);}
        else{TextView caption=text("Imagem 9:16 recebida, salva e vinculada a esta cena. Toque para visualizar em tela cheia.",11,MUTED,false);caption.setGravity(Gravity.CENTER_HORIZONTAL);imageCard.addView(caption);}
        parent.addView(imageCard);
    }

    private LinearLayout.LayoutParams sceneImagePreviewLayoutParams(){
        int viewport=getResources().getDisplayMetrics().widthPixels;
        int available=Math.max(dp(180),viewport-dp(64));
        int width=SceneImageLayoutPolicy.previewWidth(available,dp(320),dp(180));
        int height=SceneImageLayoutPolicy.heightForWidth(width);
        LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(width,height);
        params.gravity=Gravity.CENTER_HORIZONTAL;params.topMargin=dp(6);params.bottomMargin=dp(6);
        return params;
    }

    private void applySceneImageScale(){if(sceneImage!=null)sceneImage.setScaleType(ImageView.ScaleType.CENTER_CROP);}

    private void showSceneImageFullscreen(){
        if(sharedImageUri==null){toast("Nenhuma imagem vinculada à cena.");return;}
        try{
            final ImageView full=new ImageView(this);full.setBackgroundColor(Color.BLACK);full.setScaleType(ImageView.ScaleType.FIT_CENTER);full.setAdjustViewBounds(true);full.setImageBitmap(ImageStorageManager.decodeSampled(this,sharedImageUri,2048,2048));full.setPadding(dp(4),dp(4),dp(4),dp(4));
            final AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Imagem completa da cena").setView(full).setNegativeButton("Fechar",null).setNeutralButton("Alternar enquadramento",null).create();
            dialog.setOnShowListener(new DialogInterface.OnShowListener(){public void onShow(DialogInterface d){Window w=dialog.getWindow();if(w!=null)w.setLayout(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.MATCH_PARENT);dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(new View.OnClickListener(){public void onClick(View v){full.setScaleType(full.getScaleType()==ImageView.ScaleType.FIT_CENTER?ImageView.ScaleType.CENTER_CROP:ImageView.ScaleType.FIT_CENTER);}});}});dialog.show();
        }catch(Throwable error){AppLog.e("SceneImage","Falha ao abrir a imagem completa.",error);toast("Não foi possível abrir a imagem completa.");}
    }

    private void displaySceneImage(final Uri uri){if(sceneImage==null||uri==null)return;final long generation=++sceneImageDecodeGeneration;AppExecutors.io().execute(new Runnable(){public void run(){try{final android.graphics.Bitmap bitmap=ImageStorageManager.decodeSampled(MainActivity.this,uri,1080,1920);ui.post(new Runnable(){public void run(){if(generation!=sceneImageDecodeGeneration||sceneImage==null){if(bitmap!=null)bitmap.recycle();return;}sceneImage.setImageBitmap(bitmap);applySceneImageScale();}});}catch(final Throwable e){AppLog.e("SceneImage","Falha ao exibir imagem da cena.",e);ui.post(new Runnable(){public void run(){if(generation!=sceneImageDecodeGeneration)return;try{if(sceneImage!=null)sceneImage.setImageDrawable(null);}catch(Throwable ignored){AppLog.ignored("SceneImage","Falha ao limpar imagem inválida.",ignored);}if(prefs!=null)clearSceneImageReference();sharedImageUri=null;}});}}});}

    private void openFile(String type,int req,boolean multiple){Intent x=new Intent(Intent.ACTION_OPEN_DOCUMENT);x.addCategory(Intent.CATEGORY_OPENABLE);x.setType(type);x.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,multiple);x.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(x,req);}
    private void persist(Uri uri,Intent data){try{int flags=data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);getContentResolver().takePersistableUriPermission(uri,flags);}catch(Exception ignored){AppLog.ignored("MainActivity","Falha tolerada; a execução continuou.",ignored);}}
    private void beginCharacterExport(JSONObject source,boolean active){try{JSONObject sheet=new JSONObject(source==null?"{}":source.toString());sheet.put("active",active);JSONObject envelope=new JSONObject();envelope.put("format","braseiro-character-sheet");envelope.put("format_version",2);envelope.put("app_version",APP_VERSION);envelope.put("rules_profile","pathfinder_2e");envelope.put("system_id","pathfinder_2e");envelope.put("language","pt-BR");envelope.put("exported_at",dateNow());envelope.put("character",sheet);pendingCharacterExport=envelope;String name=sheet.optString("name","heroi").trim();String safe=java.text.Normalizer.normalize(name,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","").replaceAll("[^A-Za-z0-9_-]+","_").replaceAll("^_+|_+$","");if(safe.length()==0)safe="heroi";Intent x=new Intent(Intent.ACTION_CREATE_DOCUMENT);x.addCategory(Intent.CATEGORY_OPENABLE);x.setType("application/json");x.putExtra(Intent.EXTRA_TITLE,"Ficha_"+safe+".json");x.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION);startActivityForResult(x,REQ_EXPORT_CHARACTER);}catch(Exception e){pendingCharacterExport=new JSONObject();toast("Não foi possível preparar a ficha: "+e.getMessage());}}
    private void startCharacterImport(){openFile("application/json",REQ_IMPORT_CHARACTER,false);}
    private JSONObject decodeCharacterJson(String json)throws Exception{
        if(json==null||json.trim().length()==0)throw new Exception("O arquivo está vazio.");
        JSONObject root=new JSONObject(json);String format=root.optString("format");if(format.length()>0&&!"braseiro-character-sheet".equals(format))throw new Exception("Este JSON não é uma ficha individual do Braseiro.");JSONObject sheet=root.optJSONObject("character");if(sheet==null)sheet=root;if(!sheet.has("name")||!sheet.has("class_name"))throw new Exception("A ficha precisa conter name e class_name.");JSONObject clean=new JSONObject(sheet.toString());clean.remove("id");clean.remove("token_uri");String system=clean.optString("system",root.optString("rules_profile","")).trim().toLowerCase(Locale.US);if(system.length()>0&&!(system.equals("pathfinder_2e")||system.equals("pf2")||system.contains("pathfinder 2")))throw new Exception("Ficha de outro sistema bloqueada. Este aplicativo aceita somente Pathfinder 2e.");clean.put("system","pathfinder_2e");clean.put("rules_profile","Pathfinder 2e Remaster");if(!clean.has("ancestry")&&clean.has("species"))clean.put("ancestry",clean.optString("species"));if(!clean.has("species")&&clean.has("ancestry"))clean.put("species",clean.optString("ancestry"));return clean;
    }


    

