    private void ensureBundledMythicManualAsync(){
        if(prefs!=null&&prefs.getBoolean("bundled_mythic_manual_suppressed",false))return;
        AppExecutors.io().execute(new Runnable(){public void run(){try{
            File dir=new File(getFilesDir(),"bundled_manuals");if(!dir.exists())dir.mkdirs();File pdf=new File(dir,"Mythic_2e.pdf");
            if(!pdf.exists()||pdf.length()<1000000){InputStream in=getAssets().open("manuals/Mythic 2e.pdf");FileOutputStream out=new FileOutputStream(pdf);byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))>0)out.write(buffer,0,n);in.close();out.close();}
            if(prefs!=null&&prefs.getBoolean("bundled_mythic_manual_suppressed",false))return;
            db.upsertManual("bundled:mythic-2e","Mythic 2e","Ferramenta narrativa / Oráculos","Sistema neutro",true,"application/pdf",pdf.length(),"2.4.1",Uri.fromFile(pdf).toString(),"Incluído no app; tabelas locais com páginas verificáveis; interpretação em PT-BR");
            ui.post(new Runnable(){public void run(){setStatus("Mythic 2e disponível. A indexação só começa quando você solicitar na aba Manuais.");if("Manuais".equals(currentScreen))showManuals(manualVisibleFilter);}});
        }catch(Exception e){AppLog.w("ManualBundled","Não foi possível preparar o PDF integrado.",e);}}});
    }

