    private Spinner spinner(String[] items,String selected){Spinner s=new Spinner(this);ArrayAdapter<String> a=new ArrayAdapter<String>(this,android.R.layout.simple_spinner_item,items){public View getView(int position,View convertView,ViewGroup parent){TextView v=(TextView)super.getView(position,convertView,parent);v.setTextColor(TEXT);v.setTextSize(15);v.setTypeface(Typeface.SERIF);v.setPadding(dp(10),dp(10),dp(10),dp(10));return v;}public View getDropDownView(int position,View convertView,ViewGroup parent){TextView v=(TextView)super.getDropDownView(position,convertView,parent);v.setTextColor(TEXT);v.setTextSize(15);v.setTypeface(Typeface.SERIF);v.setBackgroundColor(PANEL);v.setPadding(dp(14),dp(12),dp(14),dp(12));return v;}};a.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);s.setAdapter(a);for(int i=0;i<items.length;i++)if(items[i].equals(selected)){s.setSelection(i);break;}s.setBackground(makeBg(INPUT_BG,INPUT_STROKE,8));s.setPadding(dp(8),0,dp(8),0);return s;}
