    private void showKingmakerUpgradeDialog(final JSONObject town,final JSONObject old){
        final List<String> targets=new ArrayList<String>(),labels=new ArrayList<String>();
        String[] all={"academy","military_academy","university","garrison","castle","palace","luxury_store","marketplace","magic_shop","occult_shop","theater","opera_house","guildhall","hospital","houses","mansion","orphanage","noble_villa","menagerie","temple","cathedral","tavern_popular","tavern_luxury","tavern_world_class","waterfront","wall_stone"};
        for(String target:all)if(KingmakerStructureSemantics.canUpgrade(old.optString("structure_key"),target)){targets.add(target);labels.add(kingmakerRules.structure(target).optString("name",target));}
        if(targets.isEmpty()){toast("Esta estrutura não tem upgrade no manual.");return;}
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),dp(16));
        form.addView(text("O pagamento usa o custo efetivo do exemplar. A estrutura antiga funciona até a conclusão. O upgrade ocupa o mesmo bloco; uma falha pode ser retomada no próximo turno sem repagar.",13,TEXT,false));
        final Spinner targetChoice=spinner(labels.toArray(new String[0]),labels.get(0));form.addView(cardWithLabel("UPGRADE",targetChoice));
        final EditText lots=labeledField(form,"Lotes finais (vazio escolhe no mesmo bloco)","",false),focus=labeledField(form,"Foco comercial (Guildhall)","",false),roll=labeledField(form,"d20",String.valueOf(new Random().nextInt(20)+1),false),skill=labeledField(form,"Perícia (vazio usa a padrão da estrutura)","",false),notes=labeledField(form,"Notas","",true);roll.setInputType(InputType.TYPE_CLASS_NUMBER);
        new AlertDialog.Builder(this).setTitle("Melhorar "+old.optString("name")).setView(scrollableDialogView(form)).setNegativeButton("Cancelar",null).setNeutralButton("PAGAMENTO HISTÓRICO",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){showKingmakerHistoricalPayment(town,old);}}).setPositiveButton("RESOLVER UPGRADE",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{
            String target=targets.get(targetChoice.getSelectedItemPosition());JSONObject def=kingmakerRules.structure(target),options=new JSONObject().put("trade_focus",value(focus));
            if(value(lots).length()>0)options.put("lot_placement",new JSONObject().put("lots",parseDiceList(value(lots),4,4)));
            String chosen=value(skill);if(chosen.length()==0)chosen=def.optString("construction_skill",def.optString("skill_key","engineering"));
            JSONObject result=kingmakerRepository.resolveStructureUpgrade(town.optString("settlement_key"),old.optString("structure_key"),target,num(roll,0),chosen,options,value(notes));showKingmaker();toast("Upgrade: "+result.optString("status"));
        }catch(Exception e){toast("Upgrade: "+e.getMessage());}}}).show();
    }
    private void showKingmakerHistoricalPayment(final JSONObject town,final JSONObject old){
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),dp(16));form.addView(text("Informe valores realmente pagos após devoluções. Construção gratuita: todos zero. Este registro não altera os recursos atuais.",13,TEXT,false));
        final EditText rp=labeledField(form,"RP pagos","",false),wood=labeledField(form,"Madeira paga","",false),stone=labeledField(form,"Pedra paga","",false),ore=labeledField(form,"Minério pago","",false),lux=labeledField(form,"Luxos pagos","",false),evidence=labeledField(form,"Fonte / registro que comprova o pagamento","",true);
        new AlertDialog.Builder(this).setTitle("Pagamento do exemplar #"+old.optInt("count")).setView(scrollableDialogView(form)).setNegativeButton("Cancelar",null).setPositiveButton("REGISTRAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{
            for(EditText field:new EditText[]{rp,wood,stone,ore,lux})if(value(field).length()==0)throw new IllegalArgumentException("Preencha todos os custos, inclusive zeros.");
            kingmakerRepository.declareHistoricalConstructionPayment(town.optString("settlement_key"),old.optString("structure_key"),new JSONObject().put("resource_points",num(rp,-1)).put("lumber",num(wood,-1)).put("stone",num(stone,-1)).put("ore",num(ore,-1)).put("luxuries",num(lux,-1)),value(evidence));showKingmakerUpgradeDialog(town,old);
        }catch(Exception e){toast("Pagamento histórico: "+e.getMessage());}}}).show();
    }


    private void showKingmakerCampaignJournal(){
        final List<JSONObject> rows=new ArrayList<JSONObject>();final List<String> labels=new ArrayList<String>();
        for(JSONObject q:kingmakerRepository.campaignJournal())if(KingmakerCampaignGate.official(q)&&!KingmakerCampaignGate.retiredQuest(q)){rows.add(q);String k=KingmakerCampaignGate.questKey(q);labels.add((k.startsWith("q_cg_")?"Companheiro":KingmakerCampaignGate.officialTitle(KingmakerCampaignGate.officialChapterForQuest(q)))+" • "+q.optString("title")+" • "+q.optString("status"));}
        new AlertDialog.Builder(this).setTitle("Diário da Campanha").setItems(labels.toArray(new String[0]),new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){showKingmakerQuestObjectives(rows.get(which));}}).setPositiveButton("AÇÕES NA MANSÃO",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){new AlertDialog.Builder(MainActivity.this).setTitle("Mansão Aldori").setItems(new String[]{"Fumaça e incêndios A16/A17","Tesouros A4/A7 e Jamandi"},new DialogInterface.OnClickListener(){public void onClick(DialogInterface menu,int which){if(which==0)showKingmakerManorFire();else showKingmakerManorTreasury();}}).setNegativeButton("Voltar",null).show();}}).setNegativeButton("Voltar",null).setNeutralButton("MAPAS DA MANSÃO",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){showKingmakerManorMaps();}}).show();
    }
    private void showKingmakerQuestObjectives(final JSONObject q){
        final JSONArray objectives=KingmakerCampaignGate.objectives(q);final List<String> labels=new ArrayList<String>();
        for(int n=0;n<objectives.length();n++){JSONObject o=objectives.optJSONObject(n);labels.add((o.optBoolean("completed")||"waived".equals(o.optString("status"))?"✓ ":"○ ")+o.optString("description",o.optString("desc")));}
        new AlertDialog.Builder(this).setTitle(q.optString("title")).setItems(labels.toArray(new String[0]),new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){showKingmakerObjectiveOutcome(q,objectives.optJSONObject(which));}}).setNegativeButton("Voltar",null).setPositiveButton("CONCLUIR MISSÃO",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{kingmakerRepository.finishCampaignQuest(q.optLong("id"));showKingmakerCampaignJournal();}catch(Exception e){toast(e.getMessage());}}}).show();
    }
    private void showKingmakerObjectiveOutcome(final JSONObject q,final JSONObject objective){
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),dp(16));form.addView(text(objective.optString("description",objective.optString("desc")),14,TEXT,false));
        final Spinner result=spinner(new String[]{"Objetivo cumprido","Dispensado por decisão / ramificação"},"Objetivo cumprido");form.addView(cardWithLabel("RESULTADO",result));final EditText evidence=labeledField(form,"O que ocorreu na cena / decisão tomada",objective.optString("resolution_notes"),true);
        new AlertDialog.Builder(this).setTitle("Resolver objetivo").setView(scrollableDialogView(form)).setNegativeButton("Cancelar",null).setPositiveButton("REGISTRAR",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{JSONObject fresh=kingmakerRepository.recordCampaignObjective(q.optLong("id"),objective.optString("id"),result.getSelectedItemPosition()==1,value(evidence));showKingmakerQuestObjectives(fresh);}catch(Exception e){toast(e.getMessage());}}}).show();
    }


    private void showKingmakerManorMaps(){
        new AlertDialog.Builder(this).setTitle("Mansão Aldori • mapas oficiais").setItems(new String[]{"Ala leste • A1–A13","Ala oeste • A14–A24"},new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){
            android.webkit.WebView map=new android.webkit.WebView(MainActivity.this);map.getSettings().setJavaScriptEnabled(false);map.getSettings().setBuiltInZoomControls(true);map.getSettings().setDisplayZoomControls(false);map.getSettings().setUseWideViewPort(true);map.getSettings().setLoadWithOverviewMode(true);map.setMinimumHeight(dp(450));
            String asset=which==0?"manor_east_primary.jpg":"manor_west_primary.jpg";
            map.loadDataWithBaseURL("file:///android_asset/pathfinder/kingmaker/maps/","<html><head><meta name='viewport' content='width=device-width, initial-scale=1'></head><body style='margin:0;background:#fff'><img style='width:100%' src='"+asset+"'></body></html>","text/html","UTF-8",null);
            new AlertDialog.Builder(MainActivity.this).setTitle(which==0?"Ala leste • quadrado = 1,5 m":"Ala oeste • quadrado = 1,5 m").setView(map).setPositiveButton("FECHAR",null).show();
        }}).setNegativeButton("Voltar",null).show();
    }


    private void showKingmakerManorFire(){
        final List<JSONObject> heroes=db.listActiveCharacters();if(heroes.isEmpty()){toast("Não há personagens ativos.");return;}
        String[] labels=new String[heroes.size()];for(int n=0;n<labels.length;n++)labels[n]=heroes.get(n).optString("name");
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),dp(16));
        JSONObject current=kingmakerRepository.manorFireState();JSONArray currentRooms=current.optJSONArray("rooms");StringBuilder status=new StringBuilder();for(int n=0;n<5;n++){JSONObject state=currentRooms==null?new JSONObject():currentRooms.optJSONObject(n);if(state==null)state=new JSONObject();status.append("Quarto ").append(n+1).append(": ").append(state.optInt("points")).append("/4").append(state.optBoolean("window_broken")?" • janela aberta":"").append("\n");}form.addView(text(status.toString()+"Fumaça: CD "+KingmakerCampaignGate.manorSmokeDc(current)+(current.optBoolean("xp_awarded")?" • 30 XP já concedidos":""),13,TEXT,false));
        form.addView(text("Cinco quartos A17, numerados de cima para baixo no mapa. Cada incêndio precisa de 4 pontos. Três janelas abertas reduzem a fumaça; apagar todos rende 30 XP a cada personagem.",13,TEXT,false));
        final Spinner hero=spinner(labels,labels[0]),room=spinner(new String[]{"1","2","3","4","5"},"1"),action=spinner(new String[]{"Combater incêndio","Quebrar janela","Resistir à fumaça","Dano de fogo ao terminar turno","Respiração ao terminar turno","Teste de sufocamento","Levar para ar livre"},"Combater incêndio"),skill=spinner(new String[]{"Atletismo","Acrobacia","Sobrevivência"},"Atletismo");form.addView(cardWithLabel("PERSONAGEM",hero));form.addView(cardWithLabel("QUARTO A17",room));form.addView(cardWithLabel("AÇÃO",action));form.addView(cardWithLabel("PERÍCIA PARA COMBATER INCÊNDIO",skill));
        final CheckBox exertion=check("Ataquei ou conjurei neste turno",false),spoke=check("Falei neste turno (inclui magia verbal)",false);form.addView(exertion);form.addView(spoke);final EditText criticalLosses=labeledField(form,"Acertos críticos sofridos + falhas críticas em salvamentos com dano neste turno","0",false);criticalLosses.setInputType(InputType.TYPE_CLASS_NUMBER);final CheckBox water=check("Uso de água ao combater o incêndio",false),breath=check("Estou prendendo a respiração",false);form.addView(water);form.addView(breath);final EditText roll=labeledField(form,"d20",String.valueOf(new Random().nextInt(20)+1),false);roll.setInputType(InputType.TYPE_CLASS_NUMBER);
        final String actionId=java.util.UUID.randomUUID().toString();
        new AlertDialog.Builder(this).setTitle("Fumaça e incêndios da mansão").setView(scrollableDialogView(form)).setNegativeButton("Cancelar",null).setPositiveButton("RESOLVER",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{
            String[] keys={"fight_fire","break_window","smoke","fire_damage","breathing_end_turn","suffocation_save","fresh_air"};JSONObject params=new JSONObject().put("action_id",actionId).put("character_id",heroes.get(hero.getSelectedItemPosition()).optLong("id")).put("room",room.getSelectedItemPosition()+1).put("action",keys[action.getSelectedItemPosition()]).put("skill",String.valueOf(skill.getSelectedItem())).put("natural_roll",num(roll,0)).put("water",water.isChecked()).put("holding_breath",breath.isChecked()).put("damage_rolls",new JSONArray().put(new Random().nextInt(6)+1).put(new Random().nextInt(6)+1)).put("suffocation_d4",new Random().nextInt(4)+1);
            params.put("attacked_or_cast",exertion.isChecked()).put("spoke",spoke.isChecked()).put("critical_air_losses",num(criticalLosses,0));if("suffocation_save".equals(params.optString("action"))){JSONObject c=db.queryOne("SELECT * FROM combatants WHERE world_profile=? AND is_player=1 AND source_kind='character' AND source_id=?",new String[]{db.getActiveMapProfile(),String.valueOf(params.optLong("character_id"))});JSONObject r=parseLooseJson(c.optString("resources_json","{}"));int count=r.optInt("manor_suffocation_checks",0)+1;if(count<1||count>101)throw new IllegalStateException("Contagem de sufocamento inválida.");JSONArray dice=new JSONArray();for(int n=0;n<count;n++)dice.put(new Random().nextInt(10)+1);params.put("suffocation_rolls",dice);}JSONObject result=kingmakerRepository.resolveManorFireAction(params);toast(result.optString("description","Ação registrada."));showKingmakerManorFire();
        }catch(Exception e){toast(e.getMessage());}}}).show();
    }


    private void showKingmakerManorTreasury(){
        final List<JSONObject> heroes=db.listActiveCharacters();if(heroes.isEmpty()){toast("Não há personagens ativos.");return;}String[] names=new String[heroes.size()];for(int n=0;n<names.length;n++)names[n]=heroes.get(n).optString("name");
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(12),0,dp(12),dp(16));JSONObject state=kingmakerRepository.manorTreasuryState();form.addView(text("A4: compartimento "+(state.optBoolean("a4_discovered")?"encontrado":"oculto")+" • "+(state.optBoolean("a4_looted")?"conteúdo recolhido":"conteúdo disponível após descoberta")+"\nA7: "+(state.optBoolean("a7_unlocked")?"baú aberto":state.optInt("lock_successes")+"/3 sucessos na fechadura")+" • "+(state.optBoolean("a7_looted")?"tesouro recolhido":"tesouro no baú")+"\nOuro do baú: "+state.optInt("gold_held")+" PO"+(state.optBoolean("gold_demanded")?" • Jamandi exige devolução":""),13,TEXT,false));
        final Spinner hero=spinner(names,names[0]),action=spinner(new String[]{"Procurar compartimento A4","Recolher poções e chave A4","Abrir baú A7 com a chave","Abrir fechadura A7 (2 ações)","Recolher tesouro A7","Admitir e devolver ouro","Mentir a Jamandi","Armas reconhecidas por Jamandi","Devolver o ouro exigido","Recusar devolução"},"Procurar compartimento A4");form.addView(cardWithLabel("PERSONAGEM",hero));form.addView(cardWithLabel("DECISÃO",action));final EditText roll=labeledField(form,"d20",String.valueOf(new Random().nextInt(20)+1),false);roll.setInputType(InputType.TYPE_CLASS_NUMBER);final String actionId=java.util.UUID.randomUUID().toString();
        new AlertDialog.Builder(this).setTitle("Tesouros e consequências da mansão").setView(scrollableDialogView(form)).setNegativeButton("Voltar",null).setPositiveButton("RESOLVER",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){try{String[] keys={"search_a4","loot_a4","unlock_key","pick_lock","loot_a7","admit_return","lie","weapons_seen","return_gold","refuse"};JSONObject outcome=kingmakerRepository.resolveManorTreasuryAction(new JSONObject().put("action_id",actionId).put("character_id",heroes.get(hero.getSelectedItemPosition()).optLong("id")).put("action",keys[action.getSelectedItemPosition()]).put("natural_roll",num(roll,0)));toast(outcome.optString("description"));showKingmakerManorTreasury();}catch(Exception e){toast(e.getMessage());}}}).show();
    }

